export const tddnSentences: Sentence[] = [
  {"id":"s_work_tddn_1_1","chapterId":"ch_work_tddn_1","text":"●自序","sortOrder":1},
  {"id":"s_work_tddn_1_2","chapterId":"ch_work_tddn_1","text":"餘世為齊人，居歷山下，或居華不註之陽。五世祖同州府君而上，种學績文，代有聞人。曾大父扈跸南來，受高皇帝特知，遍歷三院，径跻中司。泰、禧之間，大父從屬車，外大父掌帝製。朝野之故，耳聞目接，歲編日紀，可信不誣。我先君博極群書，習聞台閣舊事，每對客語，音吐洪畅，纚纚不得休。坐人傾耸敬叹，知為故家文獻也。餘龆侍膝下，竊剽緒餘，已有叙次。意嘗疑某事與世俗之言殊，某事與國史之論異。他日，過庭质之，先子出曾大父、大父手泽數十大帙示之曰：\"某事然也。\"又出外大父日錄及諸老雜書示之曰：\"某事與若祖所記同，然也。其世俗之言殊，傳訛也；國史之論異，私意也。小子識之。\"又曰：\"定、哀多微詞，有所辟也。牛、李有異議，有所党也。愛憎一衰，論議乃公。國史凡幾修，是非凡幾易，而吾家乘不可删也，小子識之。\"氵存遭多故，遺編鉅帙，悉皆散亡。老病日至，忽忽漫不省憶為大恨。閒居追念得一二於十百，懼复墜逸為先人羞。乃參之史傳諸書，博以近聞脞說，務求事之實，不計言之野也。異時展餘卷者，噱曰：\"野哉言乎，子真齊人也。\"餘對曰：\"客知言哉！餘故齊，欲不齊不可。雖然，餘何言哉？何言，亦言也，無所言也，無所不言，乌乎言。\"客大笑，吾因以名其書。歷山周密公謹父書。","sortOrder":2},
  {"id":"s_work_tddn_2_1","chapterId":"ch_work_tddn_2","text":"●卷一","sortOrder":1},
  {"id":"s_work_tddn_2_2","chapterId":"ch_work_tddn_2","text":"○孝宗聖政","sortOrder":2},
  {"id":"s_work_tddn_2_3","chapterId":"ch_work_tddn_2","text":"阜陵天縱睿聖，英武果斷，古今之所鮮俪。聖政彰彰者，備載金匮玉牒之書，嘗得以竊窥之矣。其或一時史臣有所避忌，采訪遺落，失於紀載者，不一而足。茲以先世見聞，及當時諸公之所記錄數事，謹書於此。庶乎美盛德之形容，備良史之采錄雲。","sortOrder":3},
  {"id":"s_work_tddn_2_4","chapterId":"ch_work_tddn_2","text":"帝嘗禁諸司官非時會合，以其族談不修職業故也。李安國為郎官，一日，有荐術士至，部中同省，因會集言命。翼日，御批問故，同省窘甚，鹹欲飾辭自解。安國獨曰：\"以實告，其過小；為欺，其罪大。\"因援魯肅簡市飲故事，引咎以聞，同省從之。既而事寢不行，越三日，李遂除吏部侍郎。","sortOrder":4},
  {"id":"s_work_tddn_2_5","chapterId":"ch_work_tddn_2","text":"李處全嘗論匠監韓玉，玉乃廟堂客也。凡三疏。而玉亦以處全請托私書為言。上既重违台論，且以忌器，遂令玉補外，既而與祠。而玉留北闕，作書投匦，訴匠簿張權谮己。密院不敢納，遂潛入關，伏闕投之。上就書批雲：\"韓玉曾任卿監，理當靖共，乃敢伏闕，妄有陳訴，鼓惑眾聽，漸不可長，可送潭州居住。\"女真使乌林答天錫到闕，要上降榻問金主起居。贍軍酒官丁逢上書乞斬之，即日引對，遂極論前侍御李處全及故諫議大夫单時貪污事。即與改命入官，升擢差遣。","sortOrder":5},
  {"id":"s_work_tddn_2_6","chapterId":"ch_work_tddn_2","text":"舊法，未經任人，不許堂差。時相欲示私恩，則取部闕而堂除之。上知其故，遂令根刷姓名進呈。降旨雲：\"宰執當守法度，以正百官。梁克家违戾差過員數最多，候服阕日落職；曾懷可降觀文殿學士。","sortOrder":6},
  {"id":"s_work_tddn_2_7","chapterId":"ch_work_tddn_2","text":"丁娄明之子，常任明州ヘ。以舊學之故，力附曾觌。其後，魏王出判明州，尤昵近之。既而入奏，與之求貼職。上批答雲：\"朕於吾子無所愛。第爵祿天下之公器，不可私也。\"未幾，台臣論罢之。","sortOrder":7},
  {"id":"s_work_tddn_2_8","chapterId":"ch_work_tddn_2","text":"程泰之以天官兼經筵，進講《禹貢》，闕文疑義，疏說甚詳，且多引外國幽奧地理。上頗厭之，宣諭宰執雲：\"《六經》斷簡，闕疑可也，何必強為之說？且地理既非親歷，雖聖賢有所不知，朕殊不晓其說。想其治铨曹亦如此也。\"既而補外。","sortOrder":8},
  {"id":"s_work_tddn_2_9","chapterId":"ch_work_tddn_2","text":"庚子九月，上宣諭宰執雲：\"已指揮閣門，令今後常朝，宰臣免宣名，他朝會則否。\"且雲：\"朕記得老蘇議論，贊儀之臣，呼名如胥吏，非禮貌之意也。\"上一日與宰執言：\"伯圭不甚教子，各使之治生，何以為清白之傳？且其下尚有三弟，若皆作郡，則近地州郡皆自家占了，何以用人？莫若以高爵厚祿，使之就閒可也。\"趙丞相贊曰：\"凡好事，古所難者，盡出陛下之意，臣等略無萬一可以補助。\"後秀邸諸子弟，悉歸班焉。","sortOrder":9},
  {"id":"s_work_tddn_2_10","chapterId":"ch_work_tddn_2","text":"辛丑六月，臨安士人以不預補试，群詣台諫宅陳詞。台諫畏其势，以好語諭之。是夜，集吏部侍郎鄭丙之門，詬骂無禮。或疑京尹王宣子怒丙，激使然也。鄭遂徙家避之。次日入奏，待罪乞去。上已密知其故，遂批出：\"鄭丙無罪可待。令臨安府將為首作鬧人重作行遣。\"既而宣子頗回護之，上怒雲：\"設使鄭丙容私，自當訟之朝廷，安可無禮如此。若不得為首人，王佐亦當坐罪。\"且令宰執宣諭。宣子越一日奏，勘到作鬧士人府學生員丁如植為首，其次許斗權、羅。御批併編管鄰州，如植仍杖八十科斷。","sortOrder":10},
  {"id":"s_work_tddn_2_11","chapterId":"ch_work_tddn_2","text":"嘗秋旱，上問執政：\"祷雨於天地宗廟社稷，合用牲否？\"周益公奏：\"止用酒脯、幣帛。\"上曰：\"《雲漢》詩雲：'靡神不舉，靡愛斯牲。'則是合用牲矣。可更與禮官等考订之。\"","sortOrder":11},
  {"id":"s_work_tddn_2_12","chapterId":"ch_work_tddn_2","text":"淳熙九年，明堂大禮，以曾觌為滷簿使，李彦穎頓遞使。習儀之际，曾以李為參預，漫爾遜之居前。李以五使有序，毅然不敢當者久之。在列悉以顧忌，皆不敢有所决擇。太常寺禮直官某人者，忽進曰：\"參政、宰執也，觀瞻所系，开府之遜良是。\"径揖李以前。時曾方有盛眷，翌日入其事。上默然久之曰：\"朕幾誤矣！\"即日批出：\"李彦穎改充滷簿使，伯圭充頓遞使，禮直官某人，特轉一官。\"其改過不吝，蓋如此雲。","sortOrder":12},
  {"id":"s_work_tddn_2_13","chapterId":"ch_work_tddn_2","text":"淳熙中，張說頗用事，為都承旨。一日，奏欲置酒延眾侍從。上許之，且曰：\"當致酒肴為汝助。\"說拜謝。退而約客，客至期畢集，獨兵部侍郎陳良祐不至，說殊不平。已而，中使以上樽珍膳至，說為表謝，因附奏：\"臣嘗奉旨而後敢集客，陳良祐獨不至，是违聖意也。\"既奏，上忽顧小黃門言：\"張說會未散否？\"對曰：\"彼既取旨召客，當必卜夜。\"乃命再賜。說大喜，复附奏：\"臣再三速良祐，迄不肯來。\"夜漏將止，忽報中批陳良祐除諫議大夫。坐客方盡歡，聞之，怃然而罢。其用人也又如此。","sortOrder":13},
  {"id":"s_work_tddn_2_14","chapterId":"ch_work_tddn_2","text":"上聖孝出於天性。居高宗丧，百日後，尚食進素膳，毀瘠特甚。吳夫人者，潛邸舊人也，屢以過損為言，上堅不從。一日，密諭尚食內侍雲：\"官家食素多時，甚覺清瘦，汝辈可自作商量。\"於是密令苑中，以雞汁等雜之素饌中以進。上食之覺異，詢所以然。內侍恐甚，以實告。上大怒，即欲見之施行。皇太後聞之，亟過宮力解之。乃出吳夫人於外，內侍等罢職有差。","sortOrder":14},
  {"id":"s_work_tddn_2_15","chapterId":"ch_work_tddn_2","text":"○溫泉寒火","sortOrder":15},
  {"id":"s_work_tddn_2_16","chapterId":"ch_work_tddn_2","text":"邵康節曰：\"世有溫泉，而無寒火。\"昭德晁氏解雲：\"陰能順陽，而陽不能順陰也。水為火爨，則沸而熟物；火為水沃，則滅矣。\"晉紀瞻舉秀才，陆機策之曰：\"陰陽不調，則大數不得不否；一氣偏废，則萬物不能獨成。今有溫泉，而無寒火，其故何也？\"白虎殿諸儒講論，班固纂為《白虎通》，《五行篇》亦曰：\"有溫水，無寒火。\"","sortOrder":16},
  {"id":"s_work_tddn_2_17","chapterId":"ch_work_tddn_2","text":"然今湯泉，往往有之。如驪山、尉氏、骆穀、汝水、黃山、佛跡、匡庐、閩中等處，皆表表在人耳目。坡詩雲：\"自怜耳目隘，未测陰陽故。鬱攸火山烈，沸湯泉註。安能長魚鱉，仅可尋狐兔。\"朱氏晦庵詩雲：\"誰然丹黃焰，爨此玉池水。\"蓋或為溫泉之下，必有硫黃、礬石故耳。獨未見所謂寒火。按《西京雜記》載董仲舒曰：\"水極陰而有溫泉，火至陽而有涼焰。\"又《抱朴子》曰：\"水主純冷，而有溫穀之湯泉；火體宜炽，而有萧丘之寒焰。\"又劉子《從化篇》曰：\"水性宜冷，而有華陽溫泉，猶曰泉冷，冷者多也。火性宜熱，而有萧丘寒焰，猶曰火熱，熱者多也。\"然則寒火亦有之矣，特以耳目所未及，故以為無耳。","sortOrder":17},
  {"id":"s_work_tddn_2_18","chapterId":"ch_work_tddn_2","text":"○段幹木","sortOrder":18},
  {"id":"s_work_tddn_2_19","chapterId":"ch_work_tddn_2","text":"《唐書·宗室世系表叙》雲：\"李耳，字伯陽，一字聃。其後有李宗者，魏封於段，為幹木大夫。\"按《史記》，聃之子宗，為魏將，封於段幹。《抱朴子》亦雲：\"伯陽有子名宗，仕魏有功，封於段幹。\"審此，段幹乃邑名耳。然《孟子》有段幹木，《列子》有段幹生，《史記·魏世家》有段幹子，《田敬仲世家》有段幹朋，《戰國策》有段幹纶、段幹崇、段幹越人。意者，因邑以為姓；故木與朋，纶與崇、越人，皆其名，而子與生，則男子之通稱耳。《風俗通·姓氏註》以為姓段名幹木，恐或失之。","sortOrder":19},
  {"id":"s_work_tddn_2_20","chapterId":"ch_work_tddn_2","text":"蓋戰國時，自有段規。疑段與段幹自別。若如《唐史》之說，則段幹木姓李名宗，為魏將有功，封於段幹。若如史遷、葛洪之言，則段幹木之賢，魏侯所以師而敬之者，恐別一入耳。姑書其說，以俟博識者订之。","sortOrder":20},
  {"id":"s_work_tddn_2_21","chapterId":"ch_work_tddn_2","text":"○表答用先世語","sortOrder":21},
  {"id":"s_work_tddn_2_22","chapterId":"ch_work_tddn_2","text":"文正范公《嶽陽樓記》有雲：\"先天下之忧而忧，後天下之樂而樂。\"其後東坡行忠宣公辭免批答，径用此語雲：\"吾聞之乃烈考曰：'君子先天下之忧而忧，後天下之樂而樂。'雖聖人复起，不易斯言。卿將書之紳，銘之盤盂，以為一言而可以終身行之者欤！則今茲爰立之命，乃所以委重投艱而已，又何辭乎？\"其後忠宣上遺表，亦用之雲：\"蓋嘗先天下之忧，期不負聖人之學。此先臣所以教子，而微臣所以事君。\"此又述批答之意，亦前所未見也。","sortOrder":22},
  {"id":"s_work_tddn_2_23","chapterId":"ch_work_tddn_2","text":"○蜜章密章","sortOrder":23},
  {"id":"s_work_tddn_2_24","chapterId":"ch_work_tddn_2","text":"密章二字，見《晉書》山涛等傳，然其義殊不能深晓。自唐以來，文士多用之。近世若洪舜俞行《乔行簡赠祖母製》，亦雲：\"欲報食飴之德，可稽製蜜之章。\"蜜字皆從虫。相傳謂赠典既不刻印，而以蠟為之。蜜即蠟，所以謂之蜜章。然劉禹錫為《杜司徒謝追赠表》雲：\"紫書忽降於九重，密印加榮於後夜。\"《李國長神道碑》雲：\"煌煌密章，肅肅終言。\"《王崇述神道碑》雲：\"没代流慶，密章下贲。\"宋祁《孫謚議》雲：\"密章加等，昭飾下泉。\"又《祭文》雲：\"恤恩告第，蹄書密章。\"密字乃併從山，莫知其義為孰是。豈古字可通用乎？或他別有所出也。","sortOrder":24},
  {"id":"s_work_tddn_2_25","chapterId":"ch_work_tddn_2","text":"○三蘇不取孔明","sortOrder":25},
  {"id":"s_work_tddn_2_26","chapterId":"ch_work_tddn_2","text":"老泉《權書·強弱篇》雲：\"管仲曰：'攻堅則瑕者堅，攻瑕則堅者瑕。'呜呼！不從其瑕而攻之，天下皆強敵也。漢高帝所忧在項籍，而先取九江、取魏、取代、取趙、取齊、然後取籍。秦之忧在六國，蜀最僻、最小，最先取；楚最強，最後取。諸葛孔明一出其兵，乃與魏氏角，其亡宜也。\"又論曰：\"古之取天下者，常先圖所守。諸葛孔明弃荆州取西蜀，吾知其無能為也。\"","sortOrder":26},
  {"id":"s_work_tddn_2_27","chapterId":"ch_work_tddn_2","text":"東坡論曰：\"取之以仁義，守之以仁義者，周也；取之以诈力，守之以诈力者，秦也。以秦之所以取取之，以周之所以守守之者，漢也。仁義诈力雜用以取天下者，此孔明之所以失也。孔明之所恃以勝者，獨以其區區之忠信，有以激天下之心耳。劉表之丧，先主在荆州，孔明欲袭殺其孤，先主不忍也。其後，劉璋以好逆之至蜀，不數月，扼其吭、拊其背而奪之國，此其與曹操異者幾希矣！乃治兵振旅，為仁義之師，長驅東向，而欲天下向應，蓋亦難矣。\"","sortOrder":27},
  {"id":"s_work_tddn_2_28","chapterId":"ch_work_tddn_2","text":"潁濱論曰：\"劉備弃荆州而入蜀，則非其地；用諸葛孔明治國之才，而當紛紛之冲，則非其將；不忍忿忿之氣以攻人，則是其氣不足尚也。\"其說蓋用陳寿所謂\"應变將略，非其所長\"之語耳。雖然，孔明豈可少哉！","sortOrder":28},
  {"id":"s_work_tddn_2_29","chapterId":"ch_work_tddn_2","text":"○詩用史論","sortOrder":29},
  {"id":"s_work_tddn_2_30","chapterId":"ch_work_tddn_2","text":"劉貢父《詠史》詩雲：\"自古邊功緣底事，多因嬖幸欲封侯，不如直與黃金印，惜取沙場萬髑髏。\"其意蓋指當時王韶、李憲辈耳。而其說則出於溫公論李廣利曰：\"武帝欲侯寵姬李氏，而使廣利將兵伐宛。其意以為非有功不侯，不欲負高帝之約也。夫軍旅大事，國之安危，民之生死系焉。苟為不擇賢愚，欲徼幸咫尺之功，藉以為名，而私其所愛，不若無功而侯之為愈也。然則武帝有見於封國，無見於置將，謂之能守先帝之約，臣曰過矣！\"蓋全用之。","sortOrder":30},
  {"id":"s_work_tddn_2_31","chapterId":"ch_work_tddn_2","text":"然胡明仲論留侯則雲：\"善乎，子房之能納說也。不先事而強聒，不後事而失機。不問則不言，有言則必當其可。故聽之易，而用不難也。評者曰：'漢業存亡在俯仰間，而留侯於此每從容焉。諸侯失固陵之期，始分信、越之地；复道見沙中之聚，始言雍齒之侯。'善言子房矣。\"此論全用荆公詩：\"漢業存亡俯仰中，留侯於此每從容，固陵始議韓、彭地，复道方圖雍齒封。\"此則史論用詩也。","sortOrder":31},
  {"id":"s_work_tddn_2_32","chapterId":"ch_work_tddn_2","text":"近世劉潛夫詩雲：\"身屬嫖姚性命輕，君看一蚁尚貪生。無因唤取談兵者，來此桥邊聽哭聲。\"而東坡《諫用兵之疏》雲：\"且夫戰勝之後，陛下可得而知者，凯旋捷奏，拜表稱贺，赫然耳目之觀矣。至於遠方之民，肝腦涂於白刃，筋骨絕於饋餉，流離破產，鬻賣男女，薰眼折臂，自經之状，陛下必不得而見也。慈父孝子，孤臣寡婦之哭聲，陛下必不得而聞也。\"其意亦出此。","sortOrder":32},
  {"id":"s_work_tddn_2_33","chapterId":"ch_work_tddn_2","text":"冯必大詩雲：\"亭長何曾識帝王，入關便解約三章。只消一勺清冷水，冷却秦鍋百沸湯。\"亦用黃公度《漢高祖論》曰：\"傷弓之鳥驚曲木，挽萬石之弓以射之，寧無所懼；奔渴之牛急濁泥，飲以清冷之水，寧無所喜。項驚天下以弓，而帝飲天下以水。\"","sortOrder":33},
  {"id":"s_work_tddn_2_34","chapterId":"ch_work_tddn_2","text":"葉紹翁詩雲：\"殿號長秋花寂寂，台名思子草茫茫；尚無人世团樂，枉認蓬萊作帝乡。\"亦出於林少穎《武帝論》雲：\"武帝好長生不死之術，聚方士於京師，由是祷祠之俗興，以成巫蠱之禍。陽邑、朱昌二公主俱以此誅，而皇後、太子亦皆不免。其始也，欲求長生不死之術而不可得，徒使败亡之禍橫及骨肉，可笑也。\"","sortOrder":34},
  {"id":"s_work_tddn_2_35","chapterId":"ch_work_tddn_2","text":"錢舜選詩雲：\"項羽天資自不仁，那堪亚父作謀臣。鸿門若遂樽前計，又一商君又一秦。\"亦祖陳傅良之論羽雲：\"羽之戮子婴、弒義帝、斬彭生，坑秦二十萬眾，亚父獨不當试晓之邪？使楚果亡漢，則羽又一秦，增又一商鞅也。\"此類甚多，不暇枚舉，豈所謂脱胎者耶？","sortOrder":35},
  {"id":"s_work_tddn_2_36","chapterId":"ch_work_tddn_2","text":"○漢租最輕","sortOrder":36},
  {"id":"s_work_tddn_2_37","chapterId":"ch_work_tddn_2","text":"自井田之法废，賦名日繁，民幾不聊生。餘嘗夷考，在昔獨兩漢為最輕，非惟後世不可及，雖三代亦所不及焉。自高、惠以來，十五稅一。文帝再行賜半租之令，二年、十二年，至十三年，乃盡除而不收。景帝元年，亦嘗賜半租，至明年，乃三十而稅一，即所謂半租耳。蓋先是十五稅一，則三十合征其二，今乃止稅其一，乃所謂半租之製也。自是之後，守之不易。故光武詔曰：\"頃者，師旅未解，故行什一之稅。今糧储差積，其令三十稅一，如舊製。\"是知三十稅一，漢家經常之製也。","sortOrder":37},
  {"id":"s_work_tddn_2_38","chapterId":"ch_work_tddn_2","text":"以武帝南征北伐，東巡西幸，奢靡無度，大司農告竭。當時言利者析秋毫，至於賣爵、更幣、算車船、租六畜、告缗、均输、鹽鐵、榷酤，凡可以佐用者，一孔不遺。獨於田租，不敢增益。","sortOrder":38},
  {"id":"s_work_tddn_2_39","chapterId":"ch_work_tddn_2","text":"雖至季世，此意未泯。田有灾害，吏趣其租，於定國以是報罢；用度不足，奏請增賦，翟方進以是受责。重之以灾傷免租（始元二，本始三，建始元、元康二，初元元，鸿嘉四）。初郡無稅（《食货志》），行軍勞苦者給复（高二年），陂、湖、園、池假貧民者勿租賦（初元元年）。又至於即位免，祥瑞免，行幸免（文帝三。武帝元封元、四年、五年，永始四，天漢三，宣帝神爵元，元帝初元四），民資不滿三萬免（平帝元始二年）。而逋租之民，又時貸焉，何與民之多耶！此三代而下，享國所以獨久者，蓋有以也。","sortOrder":39},
  {"id":"s_work_tddn_2_40","chapterId":"ch_work_tddn_2","text":"○真西山","sortOrder":40},
  {"id":"s_work_tddn_2_41","chapterId":"ch_work_tddn_2","text":"真文忠公，建寧府浦城縣人，起自白屋。先是，有道人於山間結庵，煉丹將成。忽一日入定，語童子曰：\"我去後，或十日、五日即還，謹勿輕動我屋子。\"後數日，忽有扣門者，童子語以師出未還。其人曰：\"我知汝師久矣。今已為冥司所錄，不可歸。留之無益，徒臭腐耳。\"童子村朴，不悟為魔，遂舉而焚之。道者旋歸，已無及。繞庵呼號雲：\"我在何處？\"如此月餘不絕聲，乡落為之不安。適有老僧聞其說，厲聲答之曰：\"你說尋'我'，你却是誰？\"於是其聲乃絕。時真母方娠，忽見道者入室，遂產西山。幼，穎悟絕人。家貧，無從得書，往往假之他人及剽學里儒，為舉子業。未幾登第，初任為延平郡掾。時倪文節喜奖借後進，且知其才，意欲以詞科衣鉢傳之。每假以私淑之文，辄一二日即歸，若手未觸者。文節殊不平曰：\"老夫固不學，然賢者亦何所見，遽不觀耶？\"西山悚然對曰：\"先生善誘，後學何敢自弃？其書皆嘗竊觀，特不敢久留耳。\"文節謾扣一二，皆能成誦，文節始大驚喜。於是與之延譽於朝，而繼中詞科，遂為世儒宗焉。","sortOrder":41},
  {"id":"s_work_tddn_2_42","chapterId":"ch_work_tddn_2","text":"○書史載箕子比幹不同","sortOrder":42},
  {"id":"s_work_tddn_2_43","chapterId":"ch_work_tddn_2","text":"《書·微子·篇》曰：\"父師、少師，殷其弗或亂正四方。\"孔註：\"父師、太師、三公，箕子也。少師、孤卿，比幹也。\"《史記·殷紀》乃雲：\"紂淫亂不止，微子數諫不聽，與太師、少師謀，遂去。比幹曰：'為人臣者，不得不以死爭。'乃強諫。紂剖比幹心，箕子懼，乃佯狂為奴，紂又囚之。殷之太師、少師乃持其祭器奔周。\"《周紀》又雲：\"紂殺比幹，囚箕子，太師疵、少師強，抱其樂器奔周。\"又《宋世家》：\"微子數諫，紂弗聽，欲死之，及去，未能自决，乃問於太師、少師。箕子披發，佯狂為奴。比幹諫，紂剖其心。太師、少師乃勸微子去，遂行。\"註但雲時比幹已死，而雲少師者似誤。蓋三處皆以太師、少師，非箕子、比幹。獨《周紀》明言，太師名疵，少師名強。《漢·古今人物表》，亦有太師疵，少師強，殊與孔註不合。然二子同武帝時人，何以見異而言不同欤？及蘇子由作《古史》，乃用安國之說，劉道原作《通鑒外紀》，則又從《史記》之言，二公必各有所見故耳。","sortOrder":43},
  {"id":"s_work_tddn_2_44","chapterId":"ch_work_tddn_2","text":"○梓人掄材","sortOrder":44},
  {"id":"s_work_tddn_2_45","chapterId":"ch_work_tddn_2","text":"梓人掄材，往往截長為短，斫大為小，略無顧惜之意，心每惡之。因觀《建隆遺事》，載太祖時，以寢殿梁損，須大木換易。三司奏聞，恐他木不堪，乞以模枋一條截用（模枋者，以人立木之兩傍，但可手模，不可得見，其大可知）。上批曰：\"截你爺頭，截你娘頭，別尋進來。\"於是止。","sortOrder":45},
  {"id":"s_work_tddn_2_46","chapterId":"ch_work_tddn_2","text":"嘉祐中，修三司，敕內一項雲：\"敢以大截小，長截短，併以违製論。\"即此敕也。大哉王言，豈區區靳一木哉？是亦用人之術耳！","sortOrder":46},
  {"id":"s_work_tddn_2_47","chapterId":"ch_work_tddn_2","text":"元丰中，趙伯山為將作監。太後出金帛，建上清储祥宮，內侍陳衍主其役，請輟將作镇库模枋，截充殿梁，伯山執不與，且援引建隆詔旨，惟大慶、文德殿換梁方許用，乃已。《邵氏聞見錄》乃以為晉邸內臣奏請，且文其辭雲：\"破大為小，何若斬汝之頭乎？\"失其實矣。","sortOrder":47},
  {"id":"s_work_tddn_2_48","chapterId":"ch_work_tddn_2","text":"○林夏","sortOrder":48},
  {"id":"s_work_tddn_2_49","chapterId":"ch_work_tddn_2","text":"林复字端陽，括蒼人。學問材具，皆有過人者，特险隘忍酷，略不容物。紹熙中，為臨安推官。有告監文思院常良孫贓墨事，朝廷下之臨安獄，久不得其情。上意謂京尹左右之，尹不自安。复乃挺身白尹，乞任其事。訖就煅煉成罪，當流海外，因寓客舶以往。中途遇盜，無以應其求。盜取常手足釘著兩船舷，船开，分其尸為二焉。林竟以勞改官，不數年為郎，出知惠州。","sortOrder":49},
  {"id":"s_work_tddn_2_50","chapterId":"ch_work_tddn_2","text":"時，常有姻家當得郡，憤其冤，欲報之，遂力請繼其後，林弗知也。既知惠，適有訴林在郡日，以鸩殺人，具有其實。御使徐安國亦按其家，有僭擬等物。於是有旨令大理丞陳朴追逮，隨所至置獄鞫問。及至潮陽，遇諸道間。搜其行李，得朱椅、黃帷等物，蓋林好祠醮所用者，乃就鞫於僧寺中。林知必不免，願一見家人訣別。既入室，亟探囊中藥，投酒中飲之。有頃，流血滿地，家人號泣，使者入视，則仰藥死矣，因具以复命。然其所服，乃草鳥末及他一草藥耳。至三日，乃蘇，即亡命入廣，其家以空柩歸葬。","sortOrder":50},
  {"id":"s_work_tddn_2_51","chapterId":"ch_work_tddn_2","text":"始就逮時，僮仆鳥散，行囊旁午道中。大姓潘氏者，為收斂歸之，了無所失。其家與之音問相聞者累年，至嘉定末始絕，竟佚其罰雲。","sortOrder":51},
  {"id":"s_work_tddn_2_52","chapterId":"ch_work_tddn_2","text":"此陳造周士所記，得之括医吳嗣英，甚詳。《夷堅志》亦為所罔，以為真死，殊可笑也。","sortOrder":52},
  {"id":"s_work_tddn_2_53","chapterId":"ch_work_tddn_2","text":"○汪端明","sortOrder":53},
  {"id":"s_work_tddn_2_54","chapterId":"ch_work_tddn_2","text":"汪聖錫應辰端明，本玉山縣弓手子。喻樗子材為尉，嘗授諸子學。有兵在侧，言某兒頗知讀書，可使侍筆砚。呼视之，状貌伟然，不類常兒。問：\"能屬對否？\"曰：\"能。\"曰：\"馬蹄踏破青青草。\"應聲曰：\"龍爪拿开白白雲。\"喻大驚異，曰：\"他日必為伟器。\"留授之學，且許妻以子。後從張橫浦遊，學益進。年十八，魁天下。天資強敏，記問絕人。其帥福州，吏聞其名，欲嘗之。始謁廟，有嫗持牒立道左，命取视之，累千百言，皆枝赘不根。即好諭曰：\"事不可行也。\"嫗呼曰：\"乞詳状。\"公笑曰：\"爾謂吾不詳耶？\"駐車還其牒，誦之不差一字。吏民以為神，相戒不敢犯。","sortOrder":54},
  {"id":"s_work_tddn_2_55","chapterId":"ch_work_tddn_2","text":"公以忠言直道，受知寿皇。自蜀還，為天官兼學士，向柄用矣。近習多不悅之，朝夕伺間。一日，內宿召對，天顏甚喜，曰：\"欲與卿款語。\"方命坐賜茶，汪奏：\"臣適有白事。\"上欣然問：\"何事？\"時德寿宮建房廊於市廛，董役者不識事體，凡門阖辄題德寿宮字，下至委巷廁溷皆然。汪以為非所以示四方，袖出札子極言之。且謂：\"陛下方以天下養，有司無状，亵慢如此。天下後世，將以陛下為薄於奉親，而使之規規然營間架之利，為聖孝之累不小。\"上事德寿謹，汪言頗過激。聞之，变色曰：\"朕雖不孝，殆未至是。\"汪曰：\"臣愛陛下切至，不欲使陛下負此名，故及此。\"上終不怿。奏畢，請退，上頷之，不复賜坐，自是眷顧頗衰。","sortOrder":55},
  {"id":"s_work_tddn_2_56","chapterId":"ch_work_tddn_2","text":"會德寿宮市蜀燈籠錦，詔求之，不獲。他日，上詣宮言其故，太上曰：\"比已得之。\"上問所從來，曰：\"汪應辰家物也。\"上還，即詔應辰與郡。蓋近習揣上意，因事中傷（一作之），君臣之际，難哉！","sortOrder":56},
  {"id":"s_work_tddn_2_57","chapterId":"ch_work_tddn_2","text":"○張定叟失出","sortOrder":57},
  {"id":"s_work_tddn_2_58","chapterId":"ch_work_tddn_2","text":"建康溧陽市民，同日殺人，皆系獄。獄具，以囚上府，亦同日就道。二囚時相與語，監者不虞也。夕宿邸舍，甲謂乙曰：\"吾二人事已至此，死固其分。顧事適同日，計亦有可為者。我有老母，貧不能自活。君到府，第稱冤，悉以諉我，我當兼任之。等死耳，幸而脱，君家素溫，為我養母終其身，則吾死為不徒死矣。\"乙欣然許之。","sortOrder":58},
  {"id":"s_work_tddn_2_59","chapterId":"ch_work_tddn_2","text":"時張定叟以尚書知府事，號稱嚴明。囚既至，皆呼使前問之。及乙，則曰：\"某實不殺某人，殺之者亦甲也。\"張駭異，使竟其說，曰：\"甲已殺某人，既逸出，其家不知為甲所殺也。平日與某有隙，遂以聞於官。已而甲又殺某人，乃就捕。某非不自明，官暗而吏赇，故冤不得直也。\"張以問甲，甲對如乙言，立破械縱之，一縣大驚。甲既論死，官吏皆坐失入抵罪，而張終不悟。甚哉！獄之難明也。","sortOrder":59},
  {"id":"s_work_tddn_2_60","chapterId":"ch_work_tddn_2","text":"○放翁鐘情前室","sortOrder":60},
  {"id":"s_work_tddn_2_61","chapterId":"ch_work_tddn_2","text":"陆務觀初娶唐氏，閎之女也，於其母夫人為姑侄。伉俪相得，而弗獲於其姑。既出，而未忍絕之，則為別馆，時時往焉。姑知而掩之，雖先知挈去，然事不得隱，竟絕之，亦人倫之变也。","sortOrder":61},
  {"id":"s_work_tddn_2_62","chapterId":"ch_work_tddn_2","text":"唐後改適同郡宗子士程。嘗以春日出遊，相遇於禹跡寺南之沈氏園。唐以語趙，遣致酒肴，翁怅然久之，為賦《釵頭鳳》一詞，題園壁間雲：\"紅酥手，黃藤酒，滿城春色宮牆柳。東風惡，歡情薄，一懷愁緒，幾年離索。错！错！错！春如舊，人空瘦，淚痕紅鲛绡透。桃花落，閒池閣，山盟雖在，錦書難托。莫！莫！莫！\"實紹興乙亥歲也。","sortOrder":62},
  {"id":"s_work_tddn_2_63","chapterId":"ch_work_tddn_2","text":"翁居鑒湖之三山，晚歲每入城，必登寺眺望，不能勝情。嘗賦二絕雲：\"夢斷香銷四十年，沈園柳老不飛綿。此身行作稽山土，猶弔遺蹤一怅然。\"又雲：\"城上斜陽畫角哀，沈園無复舊池台。傷心桥下春波绿，曾是驚鸿照影來。\"蓋慶元己未歲也。","sortOrder":63},
  {"id":"s_work_tddn_2_64","chapterId":"ch_work_tddn_2","text":"未久，唐氏死。至紹熙壬子歲，复有詩。序雲：\"禹跡寺南，有沈氏小園。四十年前，嘗題小詞一阕壁間。偶复一到，而園已三易主，讀之怅然。\"詩雲：\"楓葉初丹槲葉黃，河陽愁鬢怯新霜。林亭感舊空回首，泉路凭誰說斷腸。坏壁辭題尘漠漠，斷雲幽夢事茫茫。年來妄念消除盡，回向蒲龛一炷香。\"","sortOrder":64},
  {"id":"s_work_tddn_2_65","chapterId":"ch_work_tddn_2","text":"又至开禧乙丑歲暮，夜夢遊沈氏園，又兩絕句雲：\"路近城南已怕行，沈家園里更傷情。香穿客袖梅花在，绿蘸寺桥春水生。\"\"城南小陌又逢春，只見梅花不見人。玉骨久成泉下土，墨痕猶鎖壁間尘。\"","sortOrder":65},
  {"id":"s_work_tddn_2_66","chapterId":"ch_work_tddn_2","text":"沈園後屬許氏，又為汪之道宅雲。","sortOrder":66},
  {"id":"s_work_tddn_3_1","chapterId":"ch_work_tddn_3","text":"●卷二","sortOrder":1},
  {"id":"s_work_tddn_3_2","chapterId":"ch_work_tddn_3","text":"○張魏公三戰本末略","sortOrder":2},
  {"id":"s_work_tddn_3_3","chapterId":"ch_work_tddn_3","text":"△富平之戰","sortOrder":3},
  {"id":"s_work_tddn_3_4","chapterId":"ch_work_tddn_3","text":"建炎三年五月，以張浚為川陝宣撫處置使，許便宜黜陟。初，上問大計，浚請身任西事，置司秦州，別遣大臣與韓世忠镇淮東，令呂颐浩扈跸來武昌，從以張俊、劉光世，以相首尾。浚發行在，王彦統八字軍從之。浚以御營司提舉事務曲端屢挫敵，欲仗其威聲，乃承製拜為威武大將軍、本司都統製。浚抵秦州置司，節製五路諸帥。","sortOrder":4},
  {"id":"s_work_tddn_3_5","chapterId":"ch_work_tddn_3","text":"四年春，金帥娄室破陝州，李彦仙死之。既而與其副撤離歇及黑峰等，寇州。曲端拒之，兩戰皆捷。至白店原，寇引眾來犯，又為端所败。既而寇势复振，獻策者多以击之為便。浚於是欲謀大舉，召端問之。端曰：\"平原易野，賊便於冲突。而我師未習戰，須教士數年，然後可以大舉。\"复謀之吳，以宜守要害，以待其弊，然後可以徐圖。浚曰：\"吾寧不知此？顧今東南之事方急，不得不為是爾。\"","sortOrder":5},
  {"id":"s_work_tddn_3_6","chapterId":"ch_work_tddn_3","text":"浚以端沮大議，意已不平；而王庶與端有龍坊之憾，因谮之曰：\"端有反心久矣，盍早圖之。\"浚乃罢端兵柄，遷之秦州獄。其部將張中孚、李彦琪，併諸州羁管。時陝西軍民，皆恃端為命。及為庶谮，無罪而貶，軍情大不悅。《西事記》雲：\"張浚之至陝西，易置諸路帥臣，權势震赫。是時五路未破，士馬強盛。加以西蜀之富，而貸其賦五年，金銀糧帛之資，不絕於道，所在山積。浚為人，忠有餘而才不足；雖有志，而昧於用人，短於用兵。曲端心常少浚，故奪其兵废之，西人為之失望。\"","sortOrder":6},
  {"id":"s_work_tddn_3_7","chapterId":"ch_work_tddn_3","text":"浚於是决策治兵，移檄河東問罪。兀術聞变，自京西星馳至陝右，與娄室等會。而浚亦合五路兵四十萬，馬十一萬，會戰於耀州。以熙河經略劉錫為都統製，與涇原經略劉倚、秦鳳經略孫渥、環慶經略趙哲，各帥所部兵以從。吳、郭浩，極言虜鋒方銳，且當分守其地，犄角相援，待其弊乃可乘。浚不從。","sortOrder":7},
  {"id":"s_work_tddn_3_8","chapterId":"ch_work_tddn_3","text":"軍行至富平縣，吳曰：\"兵以利動，今地势不利，未見其可也。\"將戰，乃诈立前軍都統曲端旗以懼敵。娄室曰：\"聞曲將軍已得罪，必绐我也。\"遂擁兵骤至，直击環慶軍。趙哲離所部未至，哲軍遂驚遁，而諸軍悉從之，大潰，陝西為之大震。","sortOrder":8},
  {"id":"s_work_tddn_3_9","chapterId":"ch_work_tddn_3","text":"浚聞軍潰，自州退保河池縣，又退保興州。遂歸罪趙哲，斬之，责劉錫合州安置，陝西兵皆散歸本路。收秦鳳餘兵，閉大散關。關師古收涇原餘兵保岷、巩，孫渥收涇原餘兵於階、成、鳳三州。未幾，大散關复不守。浚時止有親兵千餘人，又退保阆州。或建策徙治夔州，劉子羽以為不可。遂檄吳，郭浩據和尚原，而敵复至，於是下令徙治潼州。軍士皆憤，取其榜裂之，乃止。","sortOrder":9},
  {"id":"s_work_tddn_3_10","chapterId":"ch_work_tddn_3","text":"《西事記》雲：\"張浚之戰於富平也，金人初亦畏之。而浚銳於進取，幕下之士多蜀人，南人不練軍事，欲亟决勝負於一舉，以至於败。遂走興元，又走阆中。陝西諸郡，不殘於金人者，亦皆為潰兵所破矣。\"","sortOrder":10},
  {"id":"s_work_tddn_3_11","chapterId":"ch_work_tddn_3","text":"既而張中孚、李彦琪、趙彬，相繼降敵，遂犯秦州，又犯熙河，又围慶州，於是五路悉陷。浚以三人皆曲端心腹，疑端必知其情，王庶复谮端不已。時西人多上書為端訴冤者，浚亦忌其得眾心，乃殺之於秦州獄，時人莫不冤之，軍情於是愈沮矣。","sortOrder":11},
  {"id":"s_work_tddn_3_12","chapterId":"ch_work_tddn_3","text":"紹興元年，浚以關陝失律，上章待罪，朝野無敢言其事者。至四年二月，浚還朝，侍御史辛炳始言浚被命宣撫，輕失五路，坐困四川。用劉子羽辈小人，而無辜殺曲端、趙哲；以至設秘閣以崇儒，擬上方以鑄印；及既败之後，被召不肯出蜀等罪。遂罢為資政殿大學士，提舉洞霄宮。尋又詔落職，福州居住。","sortOrder":12},
  {"id":"s_work_tddn_3_13","chapterId":"ch_work_tddn_3","text":"《秀水閒居錄》雲：\"魏公出使陝、蜀，便宜除官至節度使、雜學士，權出人主右。竭蜀之财，悉陝之兵凡三十萬餘，與敵角，一戰盡覆。用其屬劉子羽謀，歸罪其將趙哲、曲端，併誅之。將士由是怒怨俱叛，浚仅以身免，奔還阆中，關、陝之陷自此始。至今言败績之大者，必曰富平之役。追還薄譴，俾居福州而已。\"其後，川陝宣撫處置副使王似、盧法原，乃分陝、蜀之地，责守於諸將。自秦鳳至洋州，命吳主之，屯和尚原。金房至巴達，王彦主之，屯通州。文龍至威茂，劉鑄主之，屯巴西。洮岷至階成，關師古主之，屯武都。既而師古戰败降賊，自此遂失洮岷之地，獨存階成而已。","sortOrder":13},
  {"id":"s_work_tddn_3_14","chapterId":"ch_work_tddn_3","text":"△淮西之变","sortOrder":14},
  {"id":"s_work_tddn_3_15","chapterId":"ch_work_tddn_3","text":"紹興七年三月，浚奏劉光世在淮西，軍無紀律，罢為少師、萬寿觀使，以其兵隸都督府。命參謀、兵部尚書呂祉往庐州節製，且以王德為都統製，郦琼副之。琼與靳赛，皆故群盜，與王德素不相能。德，威聲素著，軍中號為王夜叉。都承旨張宗元，深以為不可，謂浚曰：\"琼等畏德如虎，今乃使臨其上，是速其叛也。\"浚不謂然。复謀之嶽飛曰：\"王德，淮西軍所服，浚欲以為都統製，而命呂祉為督府參謀領之，如何？\"飛曰：\"德與琼素不相下，一旦使揠之在上，势所必爭。呂尚書雖通才，然書生不習軍事，恐不足以服之。\"浚曰：\"張宣撫何如？\"飛曰：\"暴而寡謀，且琼辈素不服。\"浚曰：\"然則楊沂中耳。\"飛曰：\"沂中视德等耳，豈能馭之？\"浚艴然曰：\"浚固知非太尉不可。\"飛曰：\"都督以正問飛，飛不敢不盡其愚，豈以得兵為念哉！即日乞解兵柄，持餘服。而浚訖行之，琼辈懼不敢喘。","sortOrder":15},
  {"id":"s_work_tddn_3_16","chapterId":"ch_work_tddn_3","text":"及德视事教場，諸將執挝用軍禮謁拜。琼登而言曰：\"尋常伏事太尉不周，今日乞做一床錦被遮蓋。\"德素獷勇自任，竟不解出一語慰撫之，遂索馬去。於是琼辈愈懼，相與連衔上章，乞回避之。","sortOrder":16},
  {"id":"s_work_tddn_3_17","chapterId":"ch_work_tddn_3","text":"張宗元知其事，复語浚曰：\"業已爾，今獨有終任德，或可以镇，不然，变且生矣。\"浚不以為然，遂奏召德還。以張俊為淮西宣撫使，駐盱眙；楊沂中為淮西製置使，劉副之，併駐庐州。且命郦琼以所部兵赴行在，意將以奪其軍而誅之。宗元聽製於文德殿下，語人曰：\"是速琼等叛耳。\"會祉复密奏罢琼兵柄，書吏朱照漏語於琼，於是叛謀始决。及金字牌飛報，呂方坐廳事，聞有大聲如〈骨孝〉箭辟歷，自戟門隨牌而至，啟视之，乃三使除書也。呂拍案叹曰：\"庞涓死此树下。\"即時亂作，遂縛呂祉，及殺中軍統製張景、鈴轄乔仲福、劉永衡、前知庐州趙康直、釋知庐州趙不群，以其所部七萬人悉叛歸劉豫。至淮岸，遂殺祉及康直，釋不群使還。浚乃亟遣張宗元使招之，已不及矣。","sortOrder":17},
  {"id":"s_work_tddn_3_18","chapterId":"ch_work_tddn_3","text":"浚遂上章引咎，台臣交章論列，謂：\"浚輕而寡謀，愚而自用。德不足以服人，而惟恃其權；誠不足以用眾，而专任其數。若喜而怒，若怒而喜；雖本無疑貳者，皆使之有疑貳之心。予而陰奪，奪而陰予；雖本無怨望者，皆使之有怨望之意。無事，則張威恃势，使上下有暌隔之情；有急，則甘言美辭，使將士有輕侮之意。郦琼以此懷疑，以數萬眾叛去。然浚平日视民如草菅，用财如粪土。竭民膏血而用之軍中者，曾何補哉？陛下尚欲觀其後效，臣謂浚之才，止如是而已。\"時司諫王縉，則以罪在劉光世，參政張守期為力求未减。都官郎官趙令衿，則乞留浚，陳公辅則謂不可因將帥而罢宰相，於是罢為觀文殿大學士，提舉太平觀。其後，言者不已，遂詔落職。既而御批\"張浚散官，安置嶺表\"。趙鼎力扌求解之，改秘書少監，分司西京，且為出言官於外。","sortOrder":18},
  {"id":"s_work_tddn_3_19","chapterId":"ch_work_tddn_3","text":"《退朝錄》曰：\"紹興二十年，浚复上疏論邊事。高宗為湯丞相雲：'張浚用兵，不獨朕知之，天下皆知之，如富平之败，淮西之師，其效可見矣。今复論兵，極為生事。'於是复有永州之命。\"","sortOrder":19},
  {"id":"s_work_tddn_3_20","chapterId":"ch_work_tddn_3","text":"《揮麈錄》雲：\"淮西軍叛後，冯楫啟上曰：'如張浚者，當再以戎機付之，庶收後效。'高宗正色曰：'朕寧至覆國，不用此人矣。'遂終高宗朝，不复再用。\"","sortOrder":20},
  {"id":"s_work_tddn_3_21","chapterId":"ch_work_tddn_3","text":"△符離之師","sortOrder":21},
  {"id":"s_work_tddn_3_22","chapterId":"ch_work_tddn_3","text":"孝宗隆興元年正月，以張浚為枢密使，仍都督江淮軍馬，五月，兼都督荆、襄。浚既入見，屢奏欲先取山東。時顯官名士如王大寶、胡铨、王十朋、汪應辰、陳良翰等，皆魏公門人，交贊其謀。左仆射史浩獨不以為然，曰：\"宿師於外，守備先虛。我能出兵山東，以牵製川、陝，彼獨不能驚動兩淮、荆、襄，以解山東之急邪？惟當固守要害，為不可勝之計。必俟兩淮無致敵之慮，然後可前。若乃順諸將之虛勇，收無用之空城，寇去則論賞於朝，寇至則仅保山寨，顧何益乎？\"繼而主管殿前司公事李顯忠，建康都統製邵宏淵，亦奏乞引兵進取。浩曰：\"二將辄自乞戰，豈督府命令有不行邪？\"督府准遣李椿以書遺浚子┉曰：\"复仇讨賊，天下之大義也。然必正名定分，養威觀衅，而後可圖。今議不出於督府，而出於諸將，則已為舆尸之凶矣。况藩篱不固，储備不丰，將多而非才，兵弱而未練，節製未允，議論不定，彼逸我勞，雖或有獲，得地不守，未足多也。\"武鋒軍都統製陳敏曰：\"盛夏興師，恐非其時。兼聞金重兵皆在大梁，必有嚴備。萬一深入，我客彼主。千里爭力，人疲馬倦，勞逸既異，勝負之势先形矣。願少缓之。\"浚皆不聽。","sortOrder":22},
  {"id":"s_work_tddn_3_23","chapterId":"ch_work_tddn_3","text":"韓元吉以長書投浚，言和、戰、守三事。略雲：\"和固下策，然今日之和，與前日之和異。至於决戰，夫豈易言？今舊兵憊而未蘇，新兵弱而未練，所恃者一二大將；大將之權謀智略既不外見，有前败於尉桥矣，有近衄於順昌矣，况渡淮而北，千里而攻人哉！非韓信、樂毅不可也。若是，則守且有餘。然彼复來攻，何得不戰？戰而勝也，江淮可守；戰而不勝，江淮固在，其誰守之？故愚願朝廷以和為疑之之策，以守為自強之計，以戰為後日之圖。自亮賊之陨，彼嘗先遣使於我矣，又一再遺我書矣，其信其诈，固未可知，而在我亦當以信與诈之間待之。蓋未有夷狄欲息兵，而中國反欲用兵者。\"雲雲。參贊軍事唐文若、陳俊卿，皆以為不若養威觀衅，俟萬全而後動。亦不從。遂乞即日降詔幸建康，以成北伐之功。史浩曰：\"古人不以賊遺君父，必俟乘舆臨江而後成功，則安用都督哉？\"上以問浩，浩陳三說雲：\"若下詔親征，則無故招致敵兵寇邊，何以應之？若巡邊犒師，則德寿去年一出，州縣供亿重費之外，朝廷自用缗錢千四百萬，今何以繼？若曰移跸，欲奉德寿以行，則未有行宮；若陛下自行，萬一金有一騎冲突，行都骚動，何以處之？\"孝宗大悟，謂浚曰：\"都督先往行邊，俟有功緒，朕亦不憚一行。\"浚怒曰：\"陛下當以馬上成功，豈可懷安以失事機。\"及退朝，浩謂浚曰：\"帝王之兵，當出萬全，豈可嘗试而圖僥幸？主上承二百年基業之托，漢高祖起於亭長败亡之餘，乌可比哉？\"","sortOrder":23},
  {"id":"s_work_tddn_3_24","chapterId":"ch_work_tddn_3","text":"尋复論辨於殿上，浚曰：\"中原久陷，今不取，豪杰必起而取之。\"浩曰：\"中原必無豪杰，若有之，何不起而亡金？\"浚曰：\"彼民間無寸鐵，不能自起，待我兵至，而為內應。\"浩曰：\"勝、廣能以Θ棘矜亡秦，彼必待我兵至，非豪杰矣。若有豪杰而不能起，則是金猶有法製維持之，未可以遽取也。今不思，將貽後悔。\"又上疏力諫曰：\"靖康之禍，忠臣孝子，孰不痛心疾首？思欲喋血朔庭，以雪大恥。恭想宸衷，寢膳不忘。然邇安可以服遠。若大臣未附，百姓不信，而遽為此舉，安保其必勝乎？苟戰而捷，則一舉而空虜庭，豈不快吾所欲？若其不捷，則重辱社稷，以資外侮，陛下能安於九重乎？上皇能安於天下之養乎？此臣之所以食不甘味，而寢不安席也。浚，老臣，慮宜及此。而溺於幕下新進之謀，眩於北人誑惑之說，是以有請耳。德寿豈無報复之心？時張、韓、劉、嶽，各擁大兵，皆西北戰士，燕、蓟良馬；然與之角勝負於五十載之間，猶不能复尺寸之地。今欲以李顯忠之輕率，邵宏淵之寡謀，而欲取勝，不亦難哉。惟當練士卒、備器械、固邊圉、蓄财賦、宽民力，十年而後用之，則進有辟國复仇之功，退無勞師費财之患，此臣素志天下大計也。\"","sortOrder":24},
  {"id":"s_work_tddn_3_25","chapterId":"ch_work_tddn_3","text":"既而督府乏用，欲取之民，浩曰：\"未施德於民，遽重征之，恐賊未必滅，民貧先自為盜。必欲取民，臣當丐退。\"上為給虛告五百道，且以一年歲幣銀二十五萬兩添給軍費。浩复從容為浚言：\"兵少而不精，二將不可恃。且今二十萬人，留屯江淮者幾何？曰十萬。复為計其守舟運糧之人，則各二萬，則戰卒才六萬耳。彼其畏是哉！况淄、青、齊、鄆等郡，雖盡克复，亦未傷彼。彼或以重兵犯兩淮，荆、襄為之牵製，則江上危如累卵矣。都督於是在山東乎？在江上乎？\"如此詰難者凡五日。又委曲勸之曰：\"平日願執鞭而不可得，幸同事任，而數數議論不同，不惟為社稷生靈計，亦為相公計。明公以大仇未复，决意用兵，此實忠義之心。然不觀時势而遽為之，是徒慕复仇之名耳。誠欲建立功業，宜假以數年，先為不可勝之計，以待敵之可勝，乃上計也。明公四十年名望，如此一旦失利，當如何哉？\"浚曰：\"丞相之言是也。雖然，浚老矣。\"浩曰：\"晉滅吳，杜征南之功也，而當時歸功於羊太傅，以規模出於祜也。明公能先立規模，使後人藉是有功，是亦明公之功，何必身為之？\"浚默然。","sortOrder":25},
  {"id":"s_work_tddn_3_26","chapterId":"ch_work_tddn_3","text":"明日內引，浚奏曰：\"史浩意不可回也。恐失機會，惟陛下英斷。\"於是不由三省、密院，径檄諸將出師矣。德寿知之，謂寿皇曰：\"毋信張浚虛名，將來必誤大計。他专把國家名器财物做人情耳。\"已而，浩於省中忽得宏淵等遵禀出軍状，始知其故。浩語陳康伯曰：\"吾屬俱兼右府，而出兵不得與聞，則焉用彼相哉！\"浩遂力請罢歸，乃出知紹興府。臨辭，复曰：\"願陛下審度事势，若一失之後，恐終不得复望中原矣。\"","sortOrder":26},
  {"id":"s_work_tddn_3_27","chapterId":"ch_work_tddn_3","text":"浚至扬州，合江淮兵八萬人，實可用者六萬，分隸諸將，號二十萬。以李顯忠為淮東招撫使，出定遠，宏淵為副使，出盱眙，浚自渡淮视師。顯忠复靈壁縣，败萧琦。宏淵至虹縣，金拒之，會顯忠亦至，遂复虹縣。知泗州蒲察徒穆、同知大周仁併降。二將遂乘勝進，克宿州。捷奏，顯忠進开府儀同三司、淮南京畿京東河北招讨使，宏淵進檢校少保、寧遠軍節度使、招讨副使。是時，顯忠名出宏淵右。","sortOrder":27},
  {"id":"s_work_tddn_3_28","chapterId":"ch_work_tddn_3","text":"時符離府軍中，尚有金三千餘兩，銀四萬餘兩，絹一萬二千匹，錢五萬缗，米、豆共糧六萬餘石，布袋十七萬條，衣絛、棗、羊、少各一库，酒三库。乃縱親信部曲，恣其搬取，所餘者，始以犒軍人，三兵共一缗。士卒怨怒曰：\"得宿州，賞三百，得南京，須得四百。\"既而复出戰，悉弃錢溝壑。由是軍情憤詈，人無斗志。","sortOrder":28},
  {"id":"s_work_tddn_3_29","chapterId":"ch_work_tddn_3","text":"浚乃移書，令宏淵聽顯忠節製，宏淵不悅。已而复令顯忠、宏淵同節製，於是悉無體統矣。孝宗聞之，手書與浚曰：\"近日邊報，中外鼓舞，十年來無此克捷。以盛夏人疲，急召李顯忠等還師。\"未達間，忽報金人副元帥紇石烈志寧大軍且至，遇夜，軍馬未整，中軍統製周宏先率軍逃歸，繼逃歸者，宏淵之子世雄，統製左士淵，二將皆不能製。於是顯忠、宏淵大軍併丁夫等十三萬眾，一夕大潰，器甲資糧，委弃殆盡。士卒皆奋空拳，掉臂南奔，蹂踐飢困而死者，不可勝計。二將逃竄，莫知所在。","sortOrder":29},
  {"id":"s_work_tddn_3_30","chapterId":"ch_work_tddn_3","text":"浚時在盱眙，去宿尚四百里。傳言金且至，遂亟渡淮入泗州，已而复退維扬。窘懼無策，遂解所佩魚，假添差太平州通判張蘊古為朝議大夫，令使金求和。僚吏力止之，以為不可。乃奏乞致仕，又乞遣使求和。孝宗怒曰：\"方败而求和，是何舉措！\"於是下詔罪己，有雲：\"朕明不足以見萬里之情，智不足以擇三軍之帥，號令既乖，進退失律。\"又雲：\"素服而哭崤陵之師，敢废穆公之誓；嘗胆而雪會稽之恥，當懷勾踐之圖。\"張浚降特進江淮東西路宣撫使，官屬各奪二官。邵宏淵降五官，又责靖州团練副使，南安軍安置。李顯忠责授清遠軍節度副使，筠州安置，又再责萊州团練使，潭州安置。弃軍諸將，遞降貶竄有差。既而置宣撫司，便宜行事。未幾，复以浚都督江淮軍馬，既而又复入為右仆射，仍領都督。二年三月，复詔浚淮上视師。浚复謀大舉，上不從。四月，召還。罢江淮都督府，浚亦罢相。","sortOrder":30},
  {"id":"s_work_tddn_3_31","chapterId":"ch_work_tddn_3","text":"及和議將成，浚堅持以為不可。湯思退乃白上以張蘊古求和事，由是浚議遂黜。既而，金紇石烈志寧遣書議和，有雲：\"乃者，出師诡道，袭我靈壁、虹縣，以十餘萬，竊取二小邑。主將氣盈，率眾直抵符離，帥府以應兵進讨。凭仗天威，以全製勝，所殺過當，餘眾潰去。計其得丧，孰少孰多。若以符離之役，尚為兵少致败，則請空國之眾，以迎我師。\"雲雲。是歲八月，浚薨。","sortOrder":31},
  {"id":"s_work_tddn_3_32","chapterId":"ch_work_tddn_3","text":"《趙鼎傳》雲：\"鼎再相，已逾月，或以未有施設為言。鼎謂今日事，如久病虛弱之人，再有所傷，元氣必耗，惟當靜以镇之。張德遠非不欲有所為，其效可見，亦足以戒矣。時議回臨安，鼎奏恐回跸之後，中外謂朝廷無恢复之意。上曰：'張浚措置三年，竭民力，耗國用，何嘗得尺寸地，此論不足恤也'。\"","sortOrder":32},
  {"id":"s_work_tddn_3_33","chapterId":"ch_work_tddn_3","text":"《劉氏日記》雲：\"孝宗初立，張魏公用事，獨付以恢复之任，公當之不辭，朝廷莫敢违。魏公素輕銳，是時皆以必败待之，特不敢言耳。及辟查、冯方為屬，此二人尤輕銳，朝廷患之，遂以陳俊卿、唐文若參其軍事，蓋此二人厚重詳審故耳。周益公時為中書舍人，文若來別，益公握文若手，使戒魏公不可輕舉。後魏公知之，極憾益公，然卒以輕舉败事。\"","sortOrder":33},
  {"id":"s_work_tddn_3_34","chapterId":"ch_work_tddn_3","text":"《何氏備史》雲：\"張魏公素輕銳好名，士之稍有虛名者，無不牢籠。揮金如土，视官爵如等閒。士之好功名富貴者，無不趨其門。且其子南軒，以道學倡名，父子為當時宗主。在朝顯官，皆其門人，悉自诡為君子。稍有指其非者，則目之為小人。紹興元年，合關、陝五路兵三十餘萬，一旦盡覆，朝廷無一人敢言其罪。直至四年，辛炳始言之，亦不過落職，福州居住而已。淮西郦琼之叛，是時公論沸騰，言路不得已，遂疏其罪，既而併逐言者於外。及符離之败，國家平日所積兵财，扫地無餘，反以殺傷相等為辭，行賞轉官無虛日。隆興初年，大政事莫如符離之事，而實錄、時政紀，併無一字及之，公論安在哉？使魏公未死，和議必不成，其禍將有不可勝言者矣。\"","sortOrder":34},
  {"id":"s_work_tddn_3_35","chapterId":"ch_work_tddn_3","text":"《涧上閒談》雲：\"近世修史，本之實錄、時政紀等，參之諸家傳記、野史及銘志、行状之類。野史各有私好惡，固難盡信；若志状，則全是本家子孫門人掩惡溢美之辭，又可盡信乎？與其取志状之虛言，反不若取野史、傳記之或可信者耳。且以近修四朝史言之，如《張魏公列傳》所書嘉禾刺客，乃是附會雜史張元遣刺韓忠獻事。又載遣蠟書疑郦琼之語，亦是《潘遠紀聞》嶽武穆秦州叛卒事。至雲符離軍潰，公方鼻息如雷，此是心學。雖亦取《萊公紀事》中意，然方當大軍悉潰，亦安在其為心學哉！其說皆淺近易見，乃略不審其是非，登之信史，傳之千萬世，可乎？\"","sortOrder":35},
  {"id":"s_work_tddn_4_1","chapterId":"ch_work_tddn_4","text":"●卷三","sortOrder":1},
  {"id":"s_work_tddn_4_2","chapterId":"ch_work_tddn_4","text":"○紹熙內禪","sortOrder":2},
  {"id":"s_work_tddn_4_3","chapterId":"ch_work_tddn_4","text":"紹熙二年辛亥，十一月壬申，光宗初祀圜丘。先是，貴妃黃氏有寵，慈懿李後妒之。至是，上宿斋宮，乘間殺之，以暴卒聞，上不勝駭憤。及行禮，值大風雨，黃壇燈燭盡滅，不成禮而罢。上以為獲罪於天，且憚寿皇譴怒，忧懼不寧，遂得心疾，歸臥青城殿。寿皇知其事，輕舆径至幄殿，欲慰勉之。直上寐，戒左右使勿言。既寤，小黃門奏知寿皇在此，上矍然驚起，下榻叩頭請罪。寿皇再三开諭，終不怿。自是喜怒不常，不复视朝矣。至三年二月，疾稍平，詣重華宮起居。","sortOrder":3},
  {"id":"s_work_tddn_4_4","chapterId":"ch_work_tddn_4","text":"四年九月重陽節，以疾不過宮。宰執、侍從，兩省百僚及諸生，皆有疏乞過宮。甲申，上將朝重華，百官班立以俟。上已出，至御屏，李後挽上回曰：\"天色冷，官家且進一杯酒。\"百僚、侍衛皆失色。時陳傅良為中書舍人，遂趨上引裾，請毋再入，隨上至御屏後。李後叱之曰：\"这里甚去處？你秀才们要斫了驢頭。\"傅良遂大恸於殿下。李後遣人問曰：\"此是何理？\"傅良對曰：\"子諫父不聽，則號泣隨之。\"後益怒，遂傳旨：\"已降過宮指揮，更不施行。\"於是臣僚士庶紛紛之議競起矣。","sortOrder":4},
  {"id":"s_work_tddn_4_5","chapterId":"ch_work_tddn_4","text":"十月，會慶節，王部尚書趙彦逾等上疏重華，乞會慶聖節，先期諭旨，勿先過宮。寿皇御筆：\"朕自秋涼以來，思與皇帝相見。所有卿等奏札，已令進御前矣。\"庚申，詔過宮，又不果出。至戊寅，上始朝重華，都人皆大喜。先是，丞相留正，以論薑特立，待罪范村，凡一百四十日，至此方召還。","sortOrder":5},
  {"id":"s_work_tddn_4_6","chapterId":"ch_work_tddn_4","text":"五年正月，寿皇始不豫。上以疾，不能問安嘗藥。臣僚劾內侍陳源、楊舜卿、林亿年，以離間兩宮，請罢逐。及寿皇疾甚，留正請上侍疾，挽裾隨至福寧殿，泣而出。既而宰執以所請不從，乞出。光宗傳旨，令宰執盡出，於是俱至浙江亭待罪。知閣韓胄奏請自往宣押入城，於是宰執各還第。（國史《趙汝愚傳》雲：\"孝宗令嗣秀王傳意，令宰執复入，非實。\"）复請過宮，許之，至期，過午，有旨放仗。當是時，諸公引裾恸哭，朝士日相聚於道宮佛寺集議，百司皂隸，造謗伪傳，學舍草茅，爭相伏闕。劉過改之一書，至有\"生靈涂炭，社稷丘墟\"之語。且有詩雲：\"從教血染長安市，一枕清風臥釣磯。\"扰扰紛紛，無所不至。大抵當時執政無承平諸公識度，不能以上疾状昭示天下，镇靜浮言。而朝紳學士，率多賣直釣名之人，遂使上蒙疑負謗，日甚一日。","sortOrder":6},
  {"id":"s_work_tddn_4_7","chapterId":"ch_work_tddn_4","text":"至六月九日戊戌，寿皇崩於重華殿。本宮提舉關禮等，詣宰執第，告上大漸。丞相留正、枢密趙汝愚、參政陳癸、同知餘端禮，力請過宮，俟至晚，又不果出。先是，孝宗未服藥，黃裳等嘗請過宮，以笏拦光宗雲：\"寿皇已服藥矣，便請陛下升輦。\"已而無它。至是，亦以為妄，不复信。十三日，寿皇大殓，車駕不至，無與成服，人情忧懼。留正等遂奏請憲聖代行祭奠之禮，以安人心。往反數四，始得太皇聖旨：\"皇帝以疾，聽就內中成服，太皇太後代行祭奠之禮，宰相百官就重華宮成服。\"正等遂遵行之。然中外人情汹汹，以禍在旦夕。近習富室，競輦金帛藏匿村落。而朝士中如項安世等，遁去者數人。如李詳等，搬家歸乡者甚眾。侍從至欲相率出城。於是留正等連疏乞立太子，以重國本。二十四日晚，御批雲：\"甚好。\"次日，宰執擬立太子指揮進入。御筆批：\"依付學士院降詔。\"是晚，又御批雲：\"歷事歲久，念欲退閒。\"留正見之懼。以為初止請立太子，今乃有退閒之語，何邪？會次日朝臨，仆於殿庭傷足，正疑為不祥。先是，正嘗從善軌革者問命，有兔伏草、雞自焚之象。及此，謂所知曰：\"上卯生，吾酉生，前語验矣。\"遂力請罢免，出城俟命。","sortOrder":7},
  {"id":"s_work_tddn_4_8","chapterId":"ch_work_tddn_4","text":"工部尚書趙彦逾，時為山陵按行使。臨欲渡江，因別汝愚曰：\"近事危急如此，知院乃同姓之卿，豈容坐视？當思救之之策可也。\"汝愚默然久之，曰：\"今有何策？事急時，持刀去朝天門，叫幾聲，自割殺耳。\"彦逾曰：\"與其如此死，不若如是死。\"且雲：\"聞上有御筆八字，果否？\"汝愚曰：\"留丞相丁寧莫說。今事急矣！與尚書說亦不妨。\"彦逾曰：\"既有此御筆，何以不便立嘉王？\"汝愚驚曰：\"向嘗有立储之請，尚恐上怒。此事誰敢擔當？且看慈福、寿成兩宮之意如何？\"彦逾曰：\"留丞相以足跌求去，天付此一段事業與知院，豈可持疑？礻覃祭在近，便可舉行。\"汝愚曰：\"此是大事，恐未易仓卒，亦須擇一好日。\"遂取官歷檢视，適是日甲子吉。彦逾曰：\"帝王即位，即是好日。兼官歷又吉，何疑？事不容缓，宜亟行之，亦順事也。\"因勸與殿帥郭杲同議。汝愚遂遣范仲壬及詹體仁諭意，杲皆不答，汝愚大恐。彦逾曰：\"某嘗有德於杲。\"遂馳告之曰：\"近日外議Е洞，太尉知否？\"杲曰：\"然則奈何？\"彦逾遂以內禪事語之，曰：\"某與趙枢密，第能謀之耳。太尉為國虎臣，此事全在太尉。\"杲猶未語，彦逾曰：\"太尉所慮者，百口之家耳。今某盡誠以告，太尉不答，豈太尉別有謀乎？杲矍然而起曰：\"敢不效使令。\"遂與區處發軍坐甲等事。還報汝愚，議遂定。乃謀可白事於慈福宮者。始擬吳琚，琚，憲聖侄也。琚辭。或雲：\"已白憲聖，不許。\"繼用吳環，環亦辭。於是令徐誼、葉適因閣門蔡必勝諭意於知閣門事韓胄。胄母，憲聖女弟也，其妻又憲聖女侄，最為親近。胄慨然曰：\"某世受國恩，托在肺腑，願得效力。\"於是往見慈福宮提舉張宗尹曰：\"事势如此，我辈死無日矣。\"宗尹曰：\"今當如何？\"遂告以內禪事，且雲：\"須得太皇主張方可。\"宗尹遂許為奏知。次日未報，胄懼，遂親往慈福宮。適值憲聖感風不出，胄亦窘，立殿庑垂涕。重華宮提舉關禮適至，邀問之，胄不敢言，因指天為誓，胄遂具述其事。禮曰：\"即當奏知，少俟可也。\"禮入見，垂涕。憲聖問曰：\"汝有何苦？\"曰：\"小臣無事，天下可忧耳。\"憲聖蹙額不言。禮曰：\"聖人讀萬卷書，曾見有如此時節，可保無虞否？\"憲聖曰：\"此豈汝所知。\"禮曰：\"此事，人人知之。丞相已去，所賴二三執政，旦夕亦且去矣，中外將誰賴乎？\"言與淚俱。憲聖驚曰：\"事將奈何？\"禮曰：\"今宰執令韓胄在外，欲奏內禪事。望聖人三思，早定大計。\"憲聖不語，久之，曰：\"我前日略曾見吳琚說來，若事順，須是做教好。\"且許來早於梓宮前垂帘，引執政面對。禮遂傳旨胄，胄乃复命於汝愚。始往報陳癸、餘端禮及郭杲。併步帥阎仲。關禮使其姻党閣門舍人傅昌朝，密製黃袍。","sortOrder":8},
  {"id":"s_work_tddn_4_9","chapterId":"ch_work_tddn_4","text":"先是，嘉王數日謁告。執政諭宮僚彭龟年等曰：\"礻覃祭重事，王不可不入。\"七月四日甲子，礻覃祭。群臣入，王亦入。執政率百僚詣大行前，奏請太皇。頃之，垂帘。有旨令韓胄同執政奏事。汝愚等再拜，詣帘前奏曰：\"皇帝以疾，至今未能執丧。臣等累入札，乞立皇子嘉王為皇太子，以系人心。皇帝批出'甚好'，繼又批'歷事歲久，念欲退閒'。取太皇太後旨處分。\"憲聖曰：\"皇帝既有御筆，相公自當奉行。\"汝愚等奏曰：\"此事甚大，須降一指揮方可。\"憲聖曰：\"好！好！\"汝愚遂袖出所擬指揮以進，曰：\"皇帝以疾，未能執丧。曾有御筆，自欲退閒。皇子嘉王，可即皇帝位。尊皇帝為太上皇帝，皇後為太上皇後。\"憲聖覽訖曰：\"甚好。\"汝愚等再拜奏曰：\"凡事全望太皇太後主張。\"憲聖首肯，遂乞令都知楊舜卿提舉寿康宮，以任其责。遂召之帘前面付之。汝愚即幾筵殿前宣布聖旨及詔書訖，關禮、張宗尹扶掖太子入帘。太皇面諭再三，太子固辭，曰：\"恐負不孝之罪。\"俯伏涕泣。太皇命胄入帘，授以黃袍，令扶嗣君往即皇帝位。關禮、張宗尹共掖嗣君至素幄，傳太皇聖旨，令汝愚等勸請。汝愚等奏曰：\"天子當以安社稷定國家為孝。今中外人人忧亂，萬一变生，置太上於何地，尚得為孝乎？\"眾扶上披黃袍，上猶却立，眾扶上就座，汝愚等率百官再拜，皇帝立受。汝愚等遂傳宣殿帥郭杲、阎仲，同韓胄一班起居，內侍扶导上詣太皇帘前行謝禮，次詣梓宮前行礻覃祭禮。畢，御史台閣門集百官，禁衛立班起居。翌日，胄侍上詣光宗問起居，光宗問：\"是誰？\"胄對曰：\"嗣皇帝。\"光宗瞪视曰：\"吾兒邪？\"","sortOrder":9},
  {"id":"s_work_tddn_4_10","chapterId":"ch_work_tddn_4","text":"先是，汝愚諭殿帥郭杲，以軍五百至祥禧殿門祈請御寶。杲入，索於職掌內侍羊る、劉慶祖。二人私議曰：\"今外議汹汹如此，萬一玺入其手，或以它授，豈不利害？\"於是封識空函授杲。二取玺，從間道詣德寿宮，納之憲聖。及汝愚开函奉玺之际，憲聖方自內付玺與之。（《四朝聞見錄》雲：\"寧宗次日謁光宗，慈懿方自臥內取玺與之。\"按御玺重寶，安得即位後方取？兼玺玉各有職掌，安得置之臥內？恐非實。）","sortOrder":10},
  {"id":"s_work_tddn_4_11","chapterId":"ch_work_tddn_4","text":"先是，襄陽歸正人陳應祥等，誘聚亡命，謀以七月望日為寿皇發丧為亂。前一夕登極赦至，其徒告之而败。","sortOrder":11},
  {"id":"s_work_tddn_4_12","chapterId":"ch_work_tddn_4","text":"汝愚遂奏乞召還留正，以辅初政，而御史張叔椿則劾以弃國之罪，遂遷叔椿為吏部侍郎。正乃复入拜左相，汝愚為右相。汝愚曰：\"同姓之卿，不幸處君臣之变，敢言功乎？\"辭不拜。乃以特進為枢密使。及孝宗將攒，汝愚建議欲卜山陵，與正異議，遂出正判建康府，汝愚遂拜右相。先是，汝愚許胄以事成日授節鉞，彦逾執政。既而推定策恩，汝愚乃謂彦逾曰：\"我辈宗臣，不當言功。\"仅除郭杲節度使，彦逾為端明殿學士，出為四川製置、知成都府，胄遷觀察使、枢密都承旨。（元系防御使、知閣門事，至是，仅遷一級。）於是二人憤曰：\"此事皆吾二人之力，汝愚不過蒙成耳。今既自據相位，以专其功，乃置吾辈度外邪！\"於是始有逐汝愚之謀矣。汝愚覺之，以朱熹有重名，遂自長沙召入為待製，侍經筵，及收召李祥、楊簡、呂祖俭等道學諸君子以自壮。然宮中及一時之議，皆歸功於胄，自是出入宮掖，居中用事。且嗾伶人刻木為熹等像，峨冠大袖，講說性理，為戲於禁中。","sortOrder":12},
  {"id":"s_work_tddn_4_13","chapterId":"ch_work_tddn_4","text":"熹與龟年等，屢白汝愚曰：\"胄怨望殊甚。宜以厚賞酬其勞，處以大藩，出之於外。勿使預政，以防後患。\"汝愚不納，曰：\"彼嘗自言不愛官職，何慮之有？既而熹進對，面陳胄之奸。繼而正言黃度欲論之而謀泄，以內批斥去。熹又因進講極論之，聲色頗厲。上怒，遂批出，除熹宮觀。汝愚請見，乃以內批袖還上，繼而求去，皆不許。於是彭龟年奏：\"陛下逐朱熹太暴。\"且言：\"胄竊弄威權，為中外所附，必貽大患。\"寧宗欲兩罢之，汝愚欲兩留之。既而龟年與郡，胄势由是益張。會彦逾帥蜀，陛辭日，盡疏當時道學諸賢姓名，指為汝愚之党，而寧宗亦疑之矣。","sortOrder":13},
  {"id":"s_work_tddn_4_14","chapterId":"ch_work_tddn_4","text":"知閣劉弼謂胄曰：\"趙丞相欲专此大功，日引虛名之士以植党，君豈但不得節鉞，將恐不免嶺海之禍。\"胄恐甚。會汝愚欲除劉光祖為侍御史，胄知其欲击己。而上方令近臣舉御史，於是以御筆除大理簿劉德秀為御史，楊大法為殿院。又罢吳獵，以劉三杰代之，於是言路皆韓党矣。","sortOrder":14},
  {"id":"s_work_tddn_4_15","chapterId":"ch_work_tddn_4","text":"先是，汝愚嘗雲：\"夢孝宗授以湯鼎，背負白龍升天。\"又沈有开嘗在汝愚坐曰：\"外間傳嘉王出判福州，許國公判明州，三軍士庶，已推戴相公矣。\"又徐誼語人曰：\"但得趙家一塊肉足矣。\"蓋指魏王之子，徐國公柄也。樓鑰行辭免批答，有\"親為伯父，固非同姓之卿\"之語。太學生上書，乞尊汝愚為伯父。周成子言\"郎君不令\"。田澹謂\"寧宗非光宗子\"。其說非一端。於是右正言李沐首疏其事，劾汝愚以\"同姓居相位，非祖宗典故。方太上聖體不康之時，欲行周公故事。倚虛聲，植私党，以定策自居，专功自恣\"等事。遂罢汝愚相位，出知福州。既而台臣合奏，罢郡與祠。於是祭酒李祥、博士楊簡，府丞呂祖俭等有疏，太學生周端朝等六人共一書，訴汝愚有大功，不當去位，皆被黜謫。未幾，何澹、胡疏：\"汝愚倡引伪徒，謀為不軌。乘龍授鼎，假夢為符。\"且言\"與徐誼辈造謀，欲衛送太上過越，為紹熙皇帝\"等事。遂责汝愚永州安置。至衡州而卒。朱熹為之註《離骚》以寄意焉。敖陶孫題詩於闕門，有\"一死固知公所欠，孤忠賴有史長存\"之句。","sortOrder":15},
  {"id":"s_work_tddn_4_16","chapterId":"ch_work_tddn_4","text":"其後葉翥、汪義端交論伪學，而劉三杰以伪党為逆党，凡得罪者五十九人。省部籍記姓名，降詔禁伪學。而直省吏蔡璉，告汝愚定策時異謀，賓客所言凡七十紙。欲逮彭龟年、曾三聘、徐誼、沈有开下大理獄，賴范仲藝等力解之乃已。既而胄遷太傅，封平原郡王。自此，十年专政，肇开兵端，身殒國危。在胄固不足责，而當時諸君子馭之亦失其道，有以致之也。","sortOrder":16},
  {"id":"s_work_tddn_4_17","chapterId":"ch_work_tddn_4","text":"○誅韓本末","sortOrder":17},
  {"id":"s_work_tddn_4_18","chapterId":"ch_work_tddn_4","text":"嘉泰元年五月，監太平惠民局夏允中，請用文彦博故事，以胄為平章軍國重事。胄恐，乞致仕，免允中官。","sortOrder":18},
  {"id":"s_work_tddn_4_19","chapterId":"ch_work_tddn_4","text":"二年十二月，拜胄為太師，立貴妃楊氏為皇後。初，恭淑後既崩，椒房虛位，楊貴妃、曹美人皆有寵。胄畏楊權數，以曹柔順，勸上立之，上意向楊，胄不能奪也。太學生王夢龍，為後兄次山客。監雜賣場趙汝谠與夢龍為外兄弟，知其事。於是以胄之謀告次山，次山以白後，後由是怨之，始有謀胄之意矣。三年，金國盜起，氵存飢，懼我乘隙用兵，於是沿邊聚糧增戍，且禁襄陽府榷場。邊衅之开，蓋自此始。而胄久用事，亦欲立奇功以固位。會邓友龍等廉得北方事以告，而蘇師旦等又從而怂恿之。","sortOrder":19},
  {"id":"s_work_tddn_4_20","chapterId":"ch_work_tddn_4","text":"开禧元年四月，以李義為镇江都統，皇甫斌為江陵都統兼知襄陽。金人以侵掠、增戍、渝盟見责，遂詔內外諸軍密為行計。七月，胄為平章軍國事，立班丞相上。蘇師旦為安遠軍節度使，領閣門事。師旦本平江書佐，胄頃為鈐轄日，嘗以為筆吏，後依韓門。會上登極，竄名藩邸，用隨龍恩得官，骤至貴顯。八月，以殿帥郭倪為镇江都統、兼知扬州。","sortOrder":20},
  {"id":"s_work_tddn_4_21","chapterId":"ch_work_tddn_4","text":"二年，以薛叔似為湖北京西宣撫使，程松為四川宣撫使，吳曦為副使，邓友龍為兩淮宣撫使。十二月，金虜使趙之杰、完顏良弼來贺正旦，倨慢無禮。於是以北伐告於宗廟，下詔出師。已而，陳孝慶复泗。州，又复虹縣。許進复新息縣。孫成复保信縣。田琳复寿春府。未幾，王大節攻蔡州，不克軍潰。皇甫斌败於唐州。秦世辅軍亂於城固縣。郭倬、李汝翼攻宿州，败績，執統製田俊邁以往。李爽攻寿州，败。於是誅竄諸將败事者，更易諸阃。以邱為兩淮宣撫使。分諸將三衙江上之兵，合十六萬餘人，分守江淮要害。既而吳曦遣其客姚淮源獻關外四州之地於金人，遂封為蜀王。至此，胄始覺為師旦等所誤，遂罢師旦，除名，送韶州安置，仍籍其家财，賜三宣撫司為犒軍費。斬郭倬於镇江，罢程松四川宣撫使。九月，金人陷和尚原。十月，渡淮，围楚州。十一月，以殿帥郭杲駐真州，以援兩淮。邱以签書开督府。既而围襄陽，犯庐、和、真、西和州、德安府，陷隨、濠、階、成州、信陽、安丰軍、大散關。郭倪弃扬州走。","sortOrder":21},
  {"id":"s_work_tddn_4_22","chapterId":"ch_work_tddn_4","text":"三年正月，邱罢，以枢密張巖督视。二月，金人始退師。四川宣撫司、隨軍轉運使安丙及李好義、楊巨源等讨吳曦，斬之，四川平。以楊巨源為四川宣撫使，安丙副之。既而次第复階、鳳、西和州，大散關。四月，遣萧山縣丞方信孺奉使，通謝金國。六月，安丙殺楊巨源。八月，信孺回白事，言金人欲割兩淮，增歲幣、犒軍金帛，索回陷没及歸正人，又有不敢言者。胄再三問之，乃曰：\"欲太師首級。\"胄大怒，坐信孺以私觌物，擅作大臣饋虜人，降三官，臨江軍居住。乃以趙淳為江淮製置使，而用兵之謀复起。再遣監登聞鼓院王冉出使焉。","sortOrder":22},
  {"id":"s_work_tddn_4_23","chapterId":"ch_work_tddn_4","text":"於是楊次山與皇後謀，俾皇子榮王嚴入奏，言\"胄再啟兵端，謀危社稷\"，上不答。皇後從旁力請再三，欲從罢黜，上亦不答。後懼事泄，於是令次山於朝行中擇能任事者。時史弥遠為禮部侍郎、資善堂翊善，遂欣然承命。錢參政象祖，嘗以諫用兵貶信州，乃先以禮召之。禮部尚書衛涇、著作郎王居安，前右司郎官張，皆預其謀。議既定，始以告參政李璧。","sortOrder":23},
  {"id":"s_work_tddn_4_24","chapterId":"ch_work_tddn_4","text":"前一日，弥遠夜易服，持文書往來二參第。時外間籍籍有言其事者。一日，胄在都堂，忽謂李參曰：\"聞有人欲变局面，相公知否？\"李疑事泄，面發赤，徐答曰：\"恐無此事。\"而王居安在馆中，與同舍大言曰：\"數日之後，耳目當一新矣。\"其不密如此。弥遠聞之大懼，然未有殺之之意，遂謀之張。曰：\"势不兩立，不如殺之。\"弥遠撫幾曰：\"君真將种也，吾計决矣。\"","sortOrder":24},
  {"id":"s_work_tddn_4_25","chapterId":"ch_work_tddn_4","text":"時开禧三年十一月二日，胄愛姬三夫人號\"滿頭花\"者生辰。張素與之通家，至是，移庖胄。府，酣飲至五鼓。其夕，周筠聞其事，遂以覆帖告变。時胄已被酒，视之曰：\"这漢又來胡說。\"於燭上焚之。初三日，將早朝，筠复白其事，胄叱之曰：\"誰敢？誰敢？\"遂升車而去。甫至六部桥，忽有聲喏於道旁者，問：\"為何人？\"曰：\"夏震。\"時震以中軍統製權殿司公事，選兵三百俟於此。复問：\"何故？\"曰：\"有旨，太師罢平章事，日下出國門。\"曰：\"有旨，吾何為不知？必伪也。\"語未竟，夏挺、鄭發。王斌等，以健卒百餘人，擁其轎以出，至玉津園夹牆內，挝殺之。","sortOrder":25},
  {"id":"s_work_tddn_4_26","chapterId":"ch_work_tddn_4","text":"是夕，弥遠稱有密旨。錢參政欲奏審，史不許曰：\"事留，恐泄。\"遂行之。是夕，史彷徨立俟門首，至晓猶寂然，至欲易衣逃去。而宰執皆在漏舍以俟。既而胄前驅至，傳呼太師來。錢、李二公疑事泄，皆戰栗無人色。俄而寂不聞聲，久之，夏震乃至，白二公曰：\"已了事矣。\"錢參政乃探懷中堂帖授陳自強曰：\"有旨，太師及丞相皆罢。\"陳曰：\"何罪？\"錢不答，於是揖二公，遂登車去。是夕，使胄不出，則事必泄矣。","sortOrder":26},
  {"id":"s_work_tddn_4_27","chapterId":"ch_work_tddn_4","text":"二參繼赴延和殿奏事，遂以竄殛胄聞，上愕然不信。及台諫交章論列，三日後，猶未悟其死。蓋此夕之謀，悉出於中宮及次山等，宮省事秘，不能詳也。遂下詔暴胄首开兵端等罪，官籍其家。而夫人張氏、王氏聞变，盡取寶货碎之。其後二人皆坐徒斷。","sortOrder":27},
  {"id":"s_work_tddn_4_28","chapterId":"ch_work_tddn_4","text":"夏震為福州觀察使，主管殿前司公事。斬蘇師旦於韶州。程松賓州，陳自強雷州，郭倪、郭亻巽皆除名安置，併籍其家。李璧、張巖皆降官居住。毛自知奪倫魁恩，以首論用兵故也。乃拜錢象祖為右相，衛涇、雷孝友併參政，史弥遠知枢密事，林大中签書院事，楊次山开府儀同三司，賜玉帶。遂以竄殛事，牒報對境三省；以咨目遍遺二宣撫、二製置、十都統，告以上意。諫議大夫葉時，請枭首於兩淮，以謝天下，上不許。","sortOrder":28},
  {"id":"s_work_tddn_4_29","chapterId":"ch_work_tddn_4","text":"時王冉以出使在金人帳。一日，金人呼冉，問：\"韓太師何如人？\"冉因盛稱其忠賢威略。乃徐以邊報示之曰：\"如汝之言，南朝何故誅之？\"冉窘懼不能對。於是無厭之求，難塞之請，皆不敢與较，一切許之，以為脱身計。及歸，乃以金人欲求胄函首為辭，而葉時复有枭首之請，於是詔侍從兩省台諫集議。先是諸公間亦有此請，上重於施行。至是，林枢密大中、樓吏書鑰、倪兵書思，皆以為和義重事，待此而决，奸凶已毙之首，又何足惜？與其亡國，寧若辱國，而倪公主之尤力；且謂在朝有受其恩，欲為之地者。蓋朝堂集議之時，獨章文莊良能於眾中以事關國體，抗詞力爭。所謂欲為之地者，指章也。（葉清逸《聞見錄》雲：\"良能首建議函首，王介以為不可。\"此非事實。）於是遣臨安府副將尹明，斫胄棺，取其首，送江淮製置大使司；且以咨目諭諸路宣撫製置以函首事。遂命許奕為通謝使。王冉竟函首以往，且增歲幣之數。當時識者，殊不謂然。且當是時，金國實已衰弱，初非阿骨打、吳乞買之比。丙寅之冬，淮、襄皆受兵，凡城守者，皆不能下。次年，遂不复能出師，其弱可知矣。傥能稍自堅忍，不患不和，且禮秩歲幣，皆可以殺。而當路者畏懦，惟恐稍失其意，乃聽其恐喝，一切從之。且吾自誅權奸耳，而函首以遺之，則是彼之縣鄙也，何國之為？惜哉！且冉，胄所遣，今欲議和，當別遣使，亦不當复遣冉也。至有題詩於侍從宅曰：\"平生只說樓攻愧，此愧終身不可攻。\"又詩曰：\"自古和戎有大權，未聞函首可安邊。生靈肝腦空涂地，祖父冤仇共戴天。晁错已誅終叛漢，於期未遣尚存燕。廟堂自謂萬全策，却恐防胡未必然。\"又雲：\"歲幣頓增三百萬，和戎又送一於期。無人說與王冉道，莫遣當年寇准知。\"此亦可見一時公論也。明年，閣門舍人周登出使過趙州，觀所謂石桥者，已具述其事。紀功勒銘，大書深刻桥柱矣。金主嘗令引南使觀忠缪侯墓，且釋雲：\"忠於為國，缪於為身。\"詢之，乃韓也。和議既成，乃盡复秦桧官爵，以其嘗主和故耳。","sortOrder":29},
  {"id":"s_work_tddn_4_30","chapterId":"ch_work_tddn_4","text":"餘按紹興秦桧主和，王倫出使，胡忠簡抗疏，請斬桧以謝天下，時皆伟之。开禧胄主戰，倫之子冉复出使，竟函韓首以請和。是和者當斬，而戰者亦不免於死，一是一非，果何如哉？餘嘗以意推之，蓋高宗間關兵間，察知東南地势、财力與一時人物，未可與爭中原，意欲休養生聚，而後為萬全之舉。在德寿日，寿皇嘗陳恢复之計，光尧曰：\"大哥，且待老者百年後却議之。\"蓋可見也。秦桧揣知上意厭兵，力主和議，一時功名之士皆歸罪以為主和之失。及孝宗銳意恢复，張魏公主戰，異時功名之士靡然從之，獨史文惠以為不然。其後符離潰師，雖府库殫竭，士卒物故，而寿皇雄心遠慮，無日不在中原。胄習聞其說，且值金人浸微，於是患失之心生，立功之念起矣。殊不知時移事久，人情習故，一旦骚動，怨嗟併起。而茂陵乃守成之君，無意茲事，任情妄動，自取誅谬，宜也。身陨之後，眾惡歸焉；然其間是非，亦未盡然。若《雜記》所載，趙師Э犬吠，乃鄭斗所造以報撻武學生之憤。至如許及之屈膝，費士寅狗窦，亦皆不得志抱私仇者撰造丑詆，所謂僭逆之類，悉無其實。李心傳蜀人，去天萬里，輕信紀載，疏舛固宜。而一朝信史，乃不擇是否而盡取之，何哉？當泰、禧間，大父為棘卿，外大父為兵侍，直禁林，皆得之耳目所接，俱有家乘、日錄可信用。直書之，以告後之秉史筆者。","sortOrder":30},
  {"id":"s_work_tddn_5_1","chapterId":"ch_work_tddn_5","text":"●卷四","sortOrder":1},
  {"id":"s_work_tddn_5_2","chapterId":"ch_work_tddn_5","text":"○避讳","sortOrder":2},
  {"id":"s_work_tddn_5_3","chapterId":"ch_work_tddn_5","text":"古今避讳之事，雜見諸書，今漫集數條於此，以備考覽。","sortOrder":3},
  {"id":"s_work_tddn_5_4","chapterId":"ch_work_tddn_5","text":"蓋殷以前，尚质不讳名，至周始讳，然猶不盡讳。如穆王名滿，定王時有王孫滿之類。至秦始皇讳政，乃呼正月為征月，《史記·年表》作端月。盧生曰：\"不敢端言其過。\"秦頒端正法度日\"端直\"。皆避政字。","sortOrder":4},
  {"id":"s_work_tddn_5_5","chapterId":"ch_work_tddn_5","text":"漢高祖讳邦，舊史以邦為國。惠帝讳盈，《史記》以萬盈數作滿數。文帝讳恒，以恒山為常山。景帝讳啟，《史記》微子啟作微子开，《漢書》啟母石作开母石。武帝讳彻，以彻侯為通侯，蒯彻為蒯通。宣帝讳詢，以荀卿為孫卿。元帝讳，以氏為盛氏。光武讳秀，以秀才為茂才。明帝讳莊，以老、莊為老、嚴，莊助為嚴助，卞莊為卞嚴。殇帝讳隆，以隆慮為林慮。安帝父讳慶，以慶氏為贺氏。","sortOrder":5},
  {"id":"s_work_tddn_5_6","chapterId":"ch_work_tddn_5","text":"魏武帝讳操，以杜操為杜度。蜀後主讳宗，以孟宗為孟仁。晉景帝讳師，以師保為保傅，京師為京都。文帝讳昭，以昭穆為韶穆，昭君為明君，《三國志》韦昭為韦耀。愍帝讳業，以建業為建康。康帝讳嶽，以邓嶽為邓岱，山嶽為山岱。齊太祖讳道成，師道淵但言師淵。梁武帝小名阿練，子孫皆呼練為白絹。隋文帝父讳忠，凡郎中皆去中字，侍中為侍內，中書為內史，殿中侍御為殿內侍御，置侍郎不置侍中，置御史大夫不置中丞，以侍書御史代之，中庐為次庐。至唐又避太子讳，亦以中郎為旅贲郎將，中書舍人為內舍人。煬帝讳廣，以廣樂為長樂，廣陵為江都。","sortOrder":6},
  {"id":"s_work_tddn_5_7","chapterId":"ch_work_tddn_5","text":"唐世祖讳丙，故以景字代之，如景科、景令，景子之類，是也。唐祖讳虎，凡言虎，率改為猛獸，或為武，如武贲、武林之類。李延寿作《南北史》，易石虎為石季龍，韓擒虎為韓擒。高祖讳淵，趙文淵為文深，凡淵字盡改為泉。劉淵為元海，戴淵為戴若思。太宗讳世民，《唐史》凡言世，皆曰\"代\"，民，皆曰\"人\"，如人、治人、生人、富人侯之類。民部曰\"戶部\"。高宗讳治，凡言治皆曰\"理\"，如\"至理之主，不代出者\"，章懷避當時讳也。陆贽曰：\"與理同道罔不興\"，\"胁從罔理\"。韓文《策問》：\"尧、舜垂衣裳而天下理\"，又\"無為而理者，其舜也欤\"。睿宗讳旦，張仁改仁願。玄宗讳隆基，太一君基、臣基，併改為其字。隆州為阆中，隆康為普康，隆龛為崇龛，隆山郡為仁寿郡。代宗讳豫，以豫章為鐘陵，蘇預改名源明，以薯蓣為薯及山藥。德宗讳適，改括州為處州。憲宗讳純，淳州改為栾州，韦純改名貫之，之純改名處厚，王純改名紹，陆純改名质，柳淳改名灌，嚴純改名休复，李行純改名行諶，崔純亮改名行范，程純改名弘，冯純敏改名約。穆宗讳恒，以恒山為常山。敬宗讳弘，徐弘敏改名有功。鄭涵避文宗舊讳，改名氵。武宗讳炎，贾炎改名嵩。宣宗讳忱，韦諶改名損，穆諶改名仁裕。","sortOrder":7},
  {"id":"s_work_tddn_5_8","chapterId":"ch_work_tddn_5","text":"梁太祖父烈祖名誠，遂改城曰\"牆\"。晉高祖讳敬塘，析敬字為文氏、苟氏，至漢乃复舊。至本朝避翼祖讳，复析為文、為苟。","sortOrder":8},
  {"id":"s_work_tddn_5_9","chapterId":"ch_work_tddn_5","text":"本朝高宗讳構，避嫌名者，仍其字更其音者，勾涛是也；加金字，鉤光祖是也；加絲字，纟句紡是也；加草頭者，苟諶是也；改為句字者，句思是也；增勾龍者，如淵是也；勾龍去上一字者，大淵是也。已上，皆臣下避君讳也。吳太子讳和，以和興為嘉興。唐高宗太子弘，為武後所鸩，追尊為孝敬帝，廟曰義宗，弘文馆改為昭文，弘農縣為恒農，韦弘機但為機。李含光本姓弘，易為李，曲阿弘氏易為洪，溫彦弘遂以大雅字行。晉以毗陵封東海王世子毗，以毗陵為晉陵。唐避章懷太子賢讳，改集賢為崇文馆之類，皆避太子之讳也。呂後讳雉，《封禪書》謂\"野雞夜ず\"。武後讳（音照），以詔書為製書，鮑照為鮑昭。改懿德太子重照為重润，劉思照為思昭。簡文鄭後讳阿春，以《春秋》為《陽秋》，富春為富陽，蘄春為蘄陽。此避後讳也。","sortOrder":9},
  {"id":"s_work_tddn_5_10","chapterId":"ch_work_tddn_5","text":"元後父讳禁，以禁中為省中。武後父讳華，以華州為太州。韦仁約避武後家讳，改名元忠。窦懷貞避韦後家讳，而以字行。劉穆之避王後家讳，以憲祖字行，後复避桓溫母讳，遂稱小字武生。虞茂避穆後母讳，改名預。本朝章憲太後父讳通，嘗改通直郎為同直郎，通州為崇州，通判為同判，通進司為承進司，通奉為中奉，通事舍人為宣事舍人。至明道間，遂复舊。此則避後家讳也。","sortOrder":10},
  {"id":"s_work_tddn_5_11","chapterId":"ch_work_tddn_5","text":"錢王Α，以石榴為金櫻，改劉氏為金氏。楊行密據扬州，州人呼蜜為蜂糖。趙避石勒讳，以羅勒為蘭香。高祖父名誠，以武成王為武明王，武成縣為武義縣。羊祜為荆州，州人呼戶曹為辭曹之類，皆避國主、諸侯讳也。","sortOrder":11},
  {"id":"s_work_tddn_5_12","chapterId":"ch_work_tddn_5","text":"《詩》、《書》則不讳。若文王讳昌，而箕子陳《洪范》曰：\"使羞其行，而邦其昌。\"厲王讳胡，而宣王時，《詩》曰：\"胡不相畏\"，\"胡為虺蜴\"，\"胡然厲矣\"。《周禮》有\"昌本之俎\"，《詩》有\"發之詠。\"《大誥》\"弗弃基\"，不讳後稷弃字。孔子父叔梁紇，而《春秋》書臧孫紇。成王讳誦，而\"吉甫作誦\"之句，正在其時，是也。","sortOrder":12},
  {"id":"s_work_tddn_5_13","chapterId":"ch_work_tddn_5","text":"廟中則不讳。《周頌》祀文、武之樂歌，《雍》曰：\"克昌厥後\"，《噫嘻》曰：\"駿發爾私\"，是也。","sortOrder":13},
  {"id":"s_work_tddn_5_14","chapterId":"ch_work_tddn_5","text":"臨文則不讳。魯莊公名同，而《春秋》書同盟。襄公名午，而書陳侯午卒。僖公名申，書戊申。定公名宋，書宋人、宋仲幾。","sortOrder":14},
  {"id":"s_work_tddn_5_15","chapterId":"ch_work_tddn_5","text":"《漢書·紀》，元封詔書有啟母石之言。《刑法志》：\"建三典以刑邦國\"與\"萬邦作孚\"。韦孟詩：\"總齊群邦\"，皆不避高祖讳。","sortOrder":15},
  {"id":"s_work_tddn_5_16","chapterId":"ch_work_tddn_5","text":"魏太祖名操，而陳思王有\"造日\"之句。曹志，植之子，奏議雲：\"幹植不強。\"","sortOrder":16},
  {"id":"s_work_tddn_5_17","chapterId":"ch_work_tddn_5","text":"三國吳時，有\"言功以權成\"，蓋斥孫權之名。《南史》有\"寧逢五虎\"及\"虎视\"之語，則虎字亦不盡避。","sortOrder":17},
  {"id":"s_work_tddn_5_18","chapterId":"ch_work_tddn_5","text":"韓文公《潮州上表》雲：\"朝廷治平日久。\"曰：\"政治少懈。\"曰：\"巍巍治功。\"曰：\"君臣相戒，以致至治。\"《舉張行素》曰：\"文學治行眾所推。\"亦不避高宗之讳。又《袁州上表》曰：\"顯榮頻煩。\"《舉韦頭》曰：\"顯映班序。\"柳文《樂曲》曰：\"羲和顯耀乘清芬。\"皆不盡避中宗之讳。韓《贺即位表》曰：\"以和萬民。\"亦不讳民字，如此類甚多。","sortOrder":18},
  {"id":"s_work_tddn_5_19","chapterId":"ch_work_tddn_5","text":"胡翼之侍講延英日，講《乾卦》元、亨、利、貞，上為動色，徐曰：\"臨文不讳。\"伊川講南容三复白圭，內侍告曰：\"容字，上舊名也。\"不聽。講畢曰：\"昔仁宗時，宮嫔謂正月為初月，餅之蒸者為炊，天下以為非。嫌名、舊名，請勿讳。\"","sortOrder":19},
  {"id":"s_work_tddn_5_20","chapterId":"ch_work_tddn_5","text":"邦、國有不讳者。襄王名鄭，而鄭不改封。至於出居其國，使者告於秦、晉曰：\"鄙在鄭地。\"受晉文公朝，而鄭伯傳。漢和帝名肇，而郡有京兆，是也。嫌名則有避有不避者。韓退之《辯讳》：\"桓公名白，傳有五皓之稱；厲王名長，琴有修短之目。不聞謂布帛為布皓，腎腸為腎修。漢武名彻，不聞讳車轍之轍。\"然《史記·天官書》：\"謂之車通\"，此非讳車轍之轍乎？若晉康帝名嶽，邓嶽改名為嶽，此則不讳嫌名也。","sortOrder":20},
  {"id":"s_work_tddn_5_21","chapterId":"ch_work_tddn_5","text":"二名不偏讳。唐太宗名世民，在位日，戴胄、唐俭為民部尚書，虞世南、李世皆不避。至高宗時，改民部為戶部。世南已卒，世去世字。或雲：\"卒哭乃讳。\"","sortOrder":21},
  {"id":"s_work_tddn_5_22","chapterId":"ch_work_tddn_5","text":"避讳而易字者。按《東觀漢記》雲：\"惠帝讳盈之字，曰滿；文帝讳恒之字，曰常；光武讳秀之字，曰茂\"雲雲。蓋當時避讳，改為某字，之者变也。如卦变爻曰之也。","sortOrder":22},
  {"id":"s_work_tddn_5_23","chapterId":"ch_work_tddn_5","text":"本朝真宗讳恒，音胡登切。若闕其下畫，則為恒，又犯徽宗旁讳。後遂併恒字不用，而易為常，正用前例也。","sortOrder":23},
  {"id":"s_work_tddn_5_24","chapterId":"ch_work_tddn_5","text":"淮南王安，避父讳長，故淮南書，凡言長悉曰修。王羲之父讳正，故每書正月為初月，或作一月，餘則以政字代之。王舒除會稽內史，以祖讳會，以會稽為郐稽。司馬遷以父讳談，《史記》中，趙談為趙同子，張孟談為孟同。范哗父名泰，《後漢書》，郭泰為郭太。李翱祖父名楚今，故為文皆以今為茲。杜甫父名閒，故杜詩無閒字。蘇子瞻祖名序，故以序為叙，或改作引。曾魯公父名會，故避之者，以勘會為勘當。蔡京父名准，改平准務為平货務。此皆士大夫自避家讳也。","sortOrder":24},
  {"id":"s_work_tddn_5_25","chapterId":"ch_work_tddn_5","text":"《史記·李斯傳》言\"宦者韓談\"，則談字不能盡避。《漢書·爰盎傳》有\"上益莊\"之文，《鄭當時傳》有\"鄭莊千里不赍糧\"之類。此不能盡避也。范晔為太子詹事，以父名泰，固辭，朝議不許。唐窦曾授中書舍人，以父名至忠，不受。議者以音同字別，乃就職。韦聿遷秘書郎，以父嫌名，換司議郎。柳公綽遷吏部尚書，以祖讳，換左丞。李涵父名少康，為太子少傅，呂渭劾之。本朝呂希純，以父名公著，而辭著作郎。富鄭公父名言，而不辭右正言。韓亿絳、縝，家讳保枢，皆為枢密而不避。此除官有避、不避也。","sortOrder":25},
  {"id":"s_work_tddn_5_26","chapterId":"ch_work_tddn_5","text":"至若後唐，郭崇韜父名弘，以弘文馆為崇文馆。建隆間，慕容彦钊、吳廷祚，皆拜使相。而钊父名章，廷祚父名璋，製麻中為改\"同為中書門下平章事\"為\"二品\"。紹興中，沈守約、湯進之二丞相，父皆名舉，於是改提舉書局為提領。此則朝廷為臣下避家讳也。","sortOrder":26},
  {"id":"s_work_tddn_5_27","chapterId":"ch_work_tddn_5","text":"元稹以陽城驿與楊道州名同，更之曰避賢驿，且作詩以記之，白樂天和之雲：\"荆人愛羊祜，戶曹改為詞，一字不忍道，况兼姓呼之。\"是也。鄭誠過郢州浩然亭，謂賢者名不可斥，更名孟亭。歙有任寺、任村，以任所遊之地故也。虞藩為刺史日，更為任公寺、任公村。此則後人避前賢名也。","sortOrder":27},
  {"id":"s_work_tddn_5_28","chapterId":"ch_work_tddn_5","text":"至有君臣同名者。襄王名鄭，衛成公與之同時，亦名鄭。衛侯讳惡，其臣有石惡。宋武帝名裕，褚叔度、王敬弘，皆名裕之；謝景仁、張茂度皆名裕。宋明帝名，王景文亦名。唐玄宗名隆基，劉子玄名知幾。","sortOrder":28},
  {"id":"s_work_tddn_5_29","chapterId":"ch_work_tddn_5","text":"又有父子、祖孫同名者。周康王名钊，生子瑕是為昭王。宋明帝名，其子後废帝亦名昱。魏獻文名弘，其子孝文名宏。聲雖相近，而字猶異也。若周厲王名胡，而僖王名胡齊。蔡文侯、昭侯，相去五世，皆名中。魏安同父名屈，同之子亦名屈。襄陽有《處士羅君墓志》曰：\"君讳靖，父靖，學優不仕。\"此尤為可罪也。","sortOrder":29},
  {"id":"s_work_tddn_5_30","chapterId":"ch_work_tddn_5","text":"若桓玄，呼父溫曰清，此不足责。若韓愈，不避仲卿，又何耶？朱溫之父名誠，以其類戌字，司天監上言，請改戊己之戊為武字，此全無義理。如扬都士人名審，沈氏與書，名而不姓，皆諛之者過耳。又如梁謝舉聞家讳必哭，近世如趙南仲亦然，此亦不失為孝。","sortOrder":30},
  {"id":"s_work_tddn_5_31","chapterId":"ch_work_tddn_5","text":"若唐裴德融父讳皋，高锴為禮部侍郎，典貢舉。德融入试，锴曰：\"伊父讳皋，而某下就试，與及第，困一生事。\"後除屯田員外郎，與同除一人參右丞盧簡。盧先屈前一人，使驅使官傳語曰：\"員外是何人下及第？偶有事，不得奉見。\"裴仓遽而去。李贺以父名晉肅，終身不赴進士舉，抑又甚焉。","sortOrder":31},
  {"id":"s_work_tddn_5_32","chapterId":"ch_work_tddn_5","text":"崔殷夢知舉，吏部尚書歸仁晦托弟仁泽，殷夢唯唯，至於三四。殷夢佥色端笏曰：\"某見進表，讓此官矣。\"仁晦始悟己姓乃殷夢家讳龟從故也。後唐天成中，盧文紀為工部尚書，郎中於鄴參，文紀以父名嗣業，與同音，竟不見。鄴忧畏太過，一夕，雉經而死。","sortOrder":32},
  {"id":"s_work_tddn_5_33","chapterId":"ch_work_tddn_5","text":"楊行密父名Κ，與夫同音，改文散諸大夫為大卿，御史大夫為御史大卿。至有《興唐寺鐘題志》雲：\"金紫光祿大，兼御史大，乃銀青光祿大。\"皆直去夫字，尤為可怪。","sortOrder":33},
  {"id":"s_work_tddn_5_34","chapterId":"ch_work_tddn_5","text":"國朝劉溫叟，父名樂，終身不聽絲竹，不遊岱嵩。徐績父名石，平生不用石器，遇石不踐，遇桥則令人負之而過。此皆避讳不近人情者也。","sortOrder":34},
  {"id":"s_work_tddn_5_35","chapterId":"ch_work_tddn_5","text":"至如唐憲宗時，戎昱有詩名，京兆尹李鸞擬以女嫁之，令改其姓，昱辭焉。五代有石昂者，讀書好學，不求仕進。節度使符習高其行，召為臨淄令。習入朝，監軍楊彦朗知留後。昂以公事上謁，贊者以彦朗家讳石，遂更其姓曰右昂。昂趨於庭，责彦朗曰：\"內侍奈何以私害公？昂姓石，非右也。\"彦朗大怒，昂即解官去。語其子曰：\"吾本不欲仕亂世，果為刑人所辱。\"","sortOrder":35},
  {"id":"s_work_tddn_5_36","chapterId":"ch_work_tddn_5","text":"宣和中，徐申幹臣，自讳其名，知常州，一邑宰白事，言\"已三状申府，未施行\"。徐怒形於色，责之曰：\"君為縣宰，豈不知長吏名，乃作意相侮。\"宰亦好犯上者，即大聲曰：\"今此事申府不報，便當申監司，否則申戶部，申台，申省，申來申去，直待身死即休。\"語罢，長揖而退。徐雖怒，然無以罪之。三人者，皆不肯避權貴之讳以自系其姓名。","sortOrder":36},
  {"id":"s_work_tddn_5_37","chapterId":"ch_work_tddn_5","text":"若北齊熊安生者，將通名見徐之才、和士开，二人相對。以之才讳雄，士开讳安，乃稱觸觸生，群公哂之。","sortOrder":37},
  {"id":"s_work_tddn_5_38","chapterId":"ch_work_tddn_5","text":"蔡京在相位日，權势甚盛，內外官司公移皆避其名，如京東、京西併改為畿左、畿右之類。蔡門下昂避之尤謹，併禁其家人，犯者有笞责。昂嘗自誤及之，家人以為言，乃舉手自击其口。蔡經國聞京閩音，稱京為經，乃奏乞改名純臣。此尤可笑。","sortOrder":38},
  {"id":"s_work_tddn_5_39","chapterId":"ch_work_tddn_5","text":"紹聖間，安為從官，章為相，安見之，但稱享而已。","sortOrder":39},
  {"id":"s_work_tddn_5_40","chapterId":"ch_work_tddn_5","text":"近世方巨山名嶽。或謗其為南仲丞相幕客，趙父名方，乃改姓為萬。既而又為邱山甫端明屬，邱名嶽，於是复改名為方山，遂指以為過焉。善乎胡康侯之論曰：\"後世不明《春秋》之義，有以讳易人姓者，易人名者。愚者迷禮以為孝；諂者獻佞以為忠。忌讳繁，名實亂，而《春秋》之法不行矣。\"","sortOrder":40},
  {"id":"s_work_tddn_5_41","chapterId":"ch_work_tddn_5","text":"○方巨山爭體統","sortOrder":41},
  {"id":"s_work_tddn_5_42","chapterId":"ch_work_tddn_5","text":"贾師憲淳祐己酉歲為湖廣總領。時方嶽巨山知南康軍。一日，總所綱運經從星江。押綱軍卒，驕悍繹骚，市民橫遭其禍者甚眾。巨山大不能堪，遂擒數辈斷治之。贾公聞之，移文詰問，且追本軍都吏，巨山於是就判公牒雲：\"總領雖大，湖廣之尊；南康雖微，江東列郡。當職奉天子命來牧是邦，初非總領之幕客，亦非湖廣之屬郡。軍無紀律，骚動吾民，國有常刑，合從斷遣，此守臣職也，於都吏何與焉！牒報。\"贾公得牒，不勝其憤，遂申朝廷，乞行按劾，於是朝廷俾嶽易邵武以避之。去郡日，有士人作大旗，書一詩以送之，曰：\"秋秋壑兩般秋，湖廣、江東事不侔。直到南康論體統，江西自隔兩三州。\"","sortOrder":42},
  {"id":"s_work_tddn_5_43","chapterId":"ch_work_tddn_5","text":"○曝日","sortOrder":43},
  {"id":"s_work_tddn_5_44","chapterId":"ch_work_tddn_5","text":"袁安臥負暄，令兒搔背，曰：\"甚快人意。\"趙勝負暄風簷，候樵牧之歸。故杜詩雲\"負暄侯樵牧\"，又雲\"負暄近牆壁\"。又《西閣曝日》雲：\"凛冽倦元冬，負暄嗜飛閣。\"又雲：\"毛發且自和，肌膚潛沃若。太陽信深仁，衰氣有托。欹傾煩註眼，容易收病腳。\"樂天《負日》詩雲：\"杲杲冬日出，照我屋南隅。負暄閉目坐，和氣生肌膚。初似飲醇醪，又如蟄者蘇。外融百骸畅，中適一念無。曠然忘所在，心與虛空俱。\"此皆深知負暄之味者也。","sortOrder":44},
  {"id":"s_work_tddn_5_45","chapterId":"ch_work_tddn_5","text":"冬日可愛，真若可持獻者。晁端仁嘗得冷疾，無藥可治，惟日中炙背乃愈。周邦彦嘗有詩雲：\"冬曦如村酿，奇溫止須臾，行行正須此，恋恋忽已無。\"餘嘗於南榮作小日閣，名之曰獻日軒。幕以白油絹，通明虛白，盎然終日，四體融畅，不止須臾而已。適有客戲餘曰：\"此所謂天下都綿袄者。\"相與一笑。後見何斯舉《黃綿袄子歌》，序曰：\"正月大雨雪，十日不已。既晴，鄰舍相呼負日，曰：'黃綿袄子出矣。'\"乃知古已有此語。然王立之亦嘗名日窗為大裘軒。謝無逸為賦詩曰：\"小人拙生事，三冬臥無帳，忍寒東窗底，坐待朝曦上。徐徐晨光熙，稍稍血氣畅，薰然四體和，恍若醉春酿。此法秘勿傳，不易車百輛，君胡得此法，开軒亦東向。蘇公名大裘，意豈在萬丈，但觀名軒心，人人如挟纩。\"陶隱居《清異錄》載开元時，高太素隱商山，起六逍遙馆，各製一銘。其三日《冬日初出》，銘曰：\"折膠墮指，夢想負背，金鑼騰空，映簷白醉。\"樓攻愧嘗取白醉二字以名閣，陳進道為賦詩，攻愧次之雲：\"處世難獨醒，時作映簷醉。年少足裘馬，安知老夫味。天梳與日帽，且复供酒事。謫居幸三適，得此更慚愧。向來六逍遙，特書見清異。君家老希夷，相求谅同氣。曲身成直身，朝寒俄失記。醉中知其天，不飲乃同意。書生暫寄溫，難語純綿麗。\"（洪駒父亦有《大襄軒》詩。）","sortOrder":45},
  {"id":"s_work_tddn_5_46","chapterId":"ch_work_tddn_5","text":"○經验方","sortOrder":46},
  {"id":"s_work_tddn_5_47","chapterId":"ch_work_tddn_5","text":"喉閉之疾，極速而烈。前辈傳帳帶散，惟白礬一味，然或時不盡验。辛丑歲，餘侍親自福建還，沿途多此證，至有阖家十餘口，一夕併命者。道路萧然，行旅惴惴。及抵南浦，有老医教以用鸭嘴、胆礬研細，以酽醋調灌，歸途恃以無恐，然亦未知其果神也。及先子守臨汀日，鈐下一老兵素願謹，忽垂泣請告曰：\"老妻苦喉閉，絕水粒者三日，命垂殆矣。\"偶藥笈有少許，即授之，俾如法用。次日，喜拜庭下雲：\"藥甫下咽，即大吐，去膠痰凡數升，即瘥。\"其後凡治數人，莫不立验。然胆礬難有真者，養生之家，不可不預储以備用也。","sortOrder":47},
  {"id":"s_work_tddn_5_48","chapterId":"ch_work_tddn_5","text":"熊胆善辟尘。试之之法，以净水一器，尘幂其上，投胆粟許，則凝尘豁然而开。以之治目障翳，極验。每以少許净水略調开，盡去筋膜尘土，入冰腦一二片，或淚痒，則加生薑粉些少，時以銀筋點之，絕奇。赤眼亦可用，餘家二老婢，俱以此奏效。","sortOrder":48},
  {"id":"s_work_tddn_5_49","chapterId":"ch_work_tddn_5","text":"辛酉夏，餘足瘍發於外臁，初甚微，其後浸淫。涉秋徂冬，不良於行。凡敷糝膏濯之剂，嘗试略遍，痛痒雜作，大妨應酬。一日，友人俞和父見過，怪其蹣跚，舉以告之。和父笑曰：\"吾能三日已此疾。法當先以淡齏水涤瘡口，幹；次用局方駐車丸研極細，加乳香少許，幹糝之，無不立效。\"遂如其說用之，數日良愈。蓋駐車丸本治血痢滯下，而此瘡亦由氣血凝註所成。医者，意也。古人處方治疾，其出人意表如此丸。其後莫子山傳治痢社僧丸，亦止是一味藥，用有奇验，亦此意也。","sortOrder":49},
  {"id":"s_work_tddn_5_50","chapterId":"ch_work_tddn_5","text":"○用事切當","sortOrder":50},
  {"id":"s_work_tddn_5_51","chapterId":"ch_work_tddn_5","text":"淳熙中，孝宗及皇太子朝上皇於德寿宮，置酒賦詩為樂，從臣皆和。周益公詩雲：\"一丁扶火德，三合巩皇基。\"蓋高宗生於大觀丁亥，孝宗生於建炎丁未，光宗生於紹興丁卯故也。陰陽家以亥、卯、未為三合，一時用事，可謂切當。其後楊誠斋為光宗宮僚，時寧宗已在平陽邸，其《贺寿》詩雲：\"祖尧父舜真千載，禹子湯孫更一家。\"又雲：\"天意分明昌火德，誕辰三世總丁年。\"蓋祖益公語也。","sortOrder":51},
  {"id":"s_work_tddn_5_52","chapterId":"ch_work_tddn_5","text":"嘉熙己亥四月，誕皇子，告廟祀文，學士李、劉功甫當筆，內用四柱作一聯雲：\"亥年巳月，無長蛇封豕之虞；午日丑時，有歸馬放牛之喜。\"蓋時方有蜀扰。其用事可謂中的，然或者則謂失之俳耳。","sortOrder":52},
  {"id":"s_work_tddn_5_53","chapterId":"ch_work_tddn_5","text":"○楊府水渠","sortOrder":53},
  {"id":"s_work_tddn_5_54","chapterId":"ch_work_tddn_5","text":"楊和王居殿巖日，建第清湖洪福桥，規製甚廣。自居其中，旁列諸子四舍，皆極宏麗。落成之日，縱外人遊觀。一僧善相宅，雲：\"此龟形也，得水則吉，失水則凶。\"時和王方被殊眷，從容聞奏，欲引湖水以環其居。思陵首肯曰：\"朕無不可，第恐外庭有語，宜密速為之。\"退即督濠寨兵數百，且多募民夫，夜以繼晝。入自五房院，出自惠利井，蜿蜒萦繞，凡數。百丈，三晝夜即竣事。未幾，台臣果有疏言擅灌湖水入私第，以擬宮禁者。上晓之曰：\"朕南渡之初，金人退而群盜起。遂用議者羁縻之策，刻印盡封之。所有者，止淮、浙數郡耳。會諸將盡平群盜，朕因自誓，除土地外，凡府库金帛，俱置不問。故諸將有餘力以給泉池園圃之費。若以平盜之功言之，雖盡以西湖賜之，曾不為過。况此役已成，惟卿容之。\"言者遂止。","sortOrder":54},
  {"id":"s_work_tddn_5_55","chapterId":"ch_work_tddn_5","text":"既而复建杰閣，藏思陵御札，且揭上賜\"風雲慶會\"四大字於上。蓋取大龟昂首下视西湖之象，以成僧說。自此百餘年間，無复火灾，人皆神之。至辛巳歲，其家舍閣於佑聖觀，識者謂龟失其首，疑為不祥。次年五月，竟毀延燎潭，潭數百楹，不數刻而盡，益验毀閣之禍雲。","sortOrder":55},
  {"id":"s_work_tddn_5_56","chapterId":"ch_work_tddn_5","text":"○潘庭堅王實之","sortOrder":56},
  {"id":"s_work_tddn_5_57","chapterId":"ch_work_tddn_5","text":"庚子辛丑歲，先君子佐閩漕幕時，方壶山大琮為漕，瞿軒王邁實之與方為年家，氣誼相好。用此，實之留富沙之日多，而壶山資給亦良厚，然亦仅資一時飲博之費耳。籍中有吳宜者，王所狎也。一日，三司燕集，大合樂於公廳。吳方舞遍，實之被酒，直造舞筵，携之径去，旁若無人，一座為之愕然。壶山起謝曰：\"此吾狂友王實之也。\"時以為奇事。","sortOrder":57},
  {"id":"s_work_tddn_5_58","chapterId":"ch_work_tddn_5","text":"實之，莆人。登甲科，甚有文名，落魄不羁。為正字日，因輪對，及故相擅權。理宗宣諭曰：\"姑置衛王之事。\"邁即抗聲曰：\"陛下一則曰衛王，二則曰衛王，何容保之至耶？\"上怒不答，径轉御屏，曰：\"此狂生也。\"邁後歸乡里，自稱\"敕賜狂生\"。嘗有詩雲：\"未知死所先期死，自笑狂生老更狂。\"又賦《沁園春》曰：\"狂如此，更狂狂不已。\"押赴琼。","sortOrder":58},
  {"id":"s_work_tddn_5_59","chapterId":"ch_work_tddn_5","text":"同時富沙人紫巖潘方庭堅，亦以豪俠聞，與實之不相下。庭堅初名公筠，後以紹歲乞靈南台神，夢有持方牛首與之，遂易名為方。殿试第三人，跌宕不羁，傲侮一世。為福建帥司機宜文字日，醉騎黃犢，歌《離骚》於市，人以為仙。嘗約同社友剧飲於南雪亭梅花下，衣皆白。既而盡去宽衣，脱帽呼嘯。酒酣客散，則衣間各浓墨大書一詩於上矣。眾皆不能堪。居無何，同社复置酒瀑泉亭。行令曰：\"有能以瀑泉灌顶，而吟不絕口者，眾拜之。\"庭堅被酒豪甚，竟脱巾ヮ髻，裸立流泉之冲，且高唱《濯纓》之章。眾因谬為驚叹，羅拜以為不可及，且舉詩禪問答以困之，潘氣略不慑，應對如流，然寒氣已深入經絡間矣。歸即臥病而殂。既不得年，又以戲笑作孽，不自貴重，聞者惜之。庭堅才高氣劲，讀書五行俱下，終身不忘。作文未嘗视草，尤長於古樂府。年六、七歲時，嘗和人詩雲：\"竹才生便直，梅到死猶香。\"識者已知其不永。其論巴陵一疏，至今人能誦之，以此終身坎壇焉。劉潛夫志其墓雲：\"公論如元氣兮，入人之肝脾。有一時之榮辱兮，有千載之是非。昔在有周兮，觀孟津之師。於扣馬之諫兮，曰抉而去之。彼八百國之同兮，不能止一士之異。呜呼！此所謂世教兮，所謂民彝。\"正謂此也。餘少侍先君子，皆嘗識之，轉眼今五十年矣。","sortOrder":59},
  {"id":"s_work_tddn_6_1","chapterId":"ch_work_tddn_6","text":"●卷五","sortOrder":1},
  {"id":"s_work_tddn_6_2","chapterId":"ch_work_tddn_6","text":"○四皓名","sortOrder":2},
  {"id":"s_work_tddn_6_3","chapterId":"ch_work_tddn_6","text":"四皓之名，見於《法言》。《漢書·樂書》多不同，前辈嘗辨之。王元之在汝日，以詩寄畢文簡曰：\"未必頸如樗里子，定應頭似夏黃公。\"文簡謂綺里季夏，當為一人，黃公則別一人也。《杜詩》雲：\"黃、綺終辭漢。\"王逸少有《尚想黃綺帖》。《陶詩》雲：\"黃、綺之南山。\"又雲：\"且當從黃、綺。\"《南史》，阮孝緒辭梁武之召雲：\"周德雖興，夷、齊不厭薇蕨；漢道方盛，黃、綺無間山林。\"蓋各以首一字呼之。於是元之遂改此句，後皆以文簡為據。然漢刻四皓神坐，一曰園公，二日綺里季，三曰夏黃公，四日里先生。按《三辅舊事》雲：\"漢惠帝為四皓作碑。\"當時所镌，必無誤書，然則元之所用非誤也。蓋昔人論四皓，或雲園、綺，或雲綺、夏，亦未必盡舉首一字。或淵明自讀作\"綺里季、夏\"，亦不可知。周燮曰：\"追綺季之跡。\"《世說》曰：\"綺季，東園公，夏黃公，里先生，謂之四皓。\"《姓書》有綺里先生，季，其字也。是則為夏黃公，益可信矣。","sortOrder":3},
  {"id":"s_work_tddn_6_4","chapterId":"ch_work_tddn_6","text":"按《風俗通紀》，楚鬻熊之後為圈。鄭穆公之子圈，其後為姓。至秦博士逃難，乃改為園。《陳留風俗記》乃圈稱所撰。蓋圈公自是秦博士。周庚以嘗居。園中，故謂之園公。《陳留志》謂圈公名秉字宣明。蔡伯喈集有圈典，魏有圈文生，皆其後也。","sortOrder":4},
  {"id":"s_work_tddn_6_5","chapterId":"ch_work_tddn_6","text":"古字祿與通用，故《樂書》作。鄭康成於《禮書》，皆作祿。《陳留志》則又作，唐李涪嘗辨之矣。然《史記·留侯世家》註雲：\"東園公姓庚，以居園中，因以為號。夏黃公姓崔名廣字少通，齊人，隱居夏里，故號夏黃公。里先生，河內人，太伯之後，姓周名術字元道。京師號曰霸上先生，一日里先生。\"此又何邪？又《吳俗紀》雲：\"先生吳人，姓周氏。今太湖中有祿里村，頭寨，即先生逃秦聘之地。\"《韓詩》：\"虎有爪兮牛有角，虎可搏兮牛可觸。\"蔡氏註：\"角、觸，协音也。\"淳化中，崔判國子監，有字學。太宗問曰：\"李覺嘗言四皓中一人姓，或雲：用上加一撇，或雲：用上加一點，果何音？\"曰：\"臣聞刀下用乃榷音，兩點下用乃鹿音。用上一撇一點，俱不成字。\"然角里作角里，亦非也。後漢有善叔，乃讀作覺音，何邪？","sortOrder":5},
  {"id":"s_work_tddn_6_6","chapterId":"ch_work_tddn_6","text":"○作文自出機杼難","sortOrder":6},
  {"id":"s_work_tddn_6_7","chapterId":"ch_work_tddn_6","text":"曾子固熙寧間守濟州，作北渚亭，蓋取杜陵《宴歷下亭》詩：\"東藩駐皂蓋，北渚陵清河\"之句。至元祐間，晁無咎補之繼來為守，則亭已頹毀久矣。補之因重作亭，且為之記。記成，疑其步骤开阖類子固擬《峴台記》，於是易而為賦，且自序雲：\"或請為記，答曰：'賦，可也。'\"蓋寓述作之初意雲。然所序晉、齊攻戰，三周華不註之事，雖極雄瞻，而或者乃謂與坡翁《赤壁》所賦孟德、周郎之事略同，補之豈蹈袭者哉！大抵作文欲自出機杼者極難，而古賦為尤難。惟陳言之務去，戛戛乎其難哉！雖昌黎亦以為然也。","sortOrder":7},
  {"id":"s_work_tddn_6_8","chapterId":"ch_work_tddn_6","text":"○端平入洛","sortOrder":8},
  {"id":"s_work_tddn_6_9","chapterId":"ch_work_tddn_6","text":"端平元年甲午，史嵩之子申，开荆湖阃，遂與孟珙合韃兵夹攻蔡城，獲亡金完顏守緒殘骸以歸。乃作露布以夸耀一時，且繪八陵圖以獻，朝廷遂議遣使修奉八陵。時鄭忠定丞相當國，於是有乘時撫定中原之意。會趙葵南仲，范武仲，全子才三數公，惑於降人穀用安之說，謂非扼险無以為國，於是守河據關之議起矣。乃命武仲开阃於光、黃之間，以張聲势，而子才合淮西之兵萬餘人赴汴。六月十二日離合肥，十八日渡寿州，二十一日抵蒙城縣。縣有二城相連，背渦為固，城中空無所有，仅存傷殘之民數十而已。沿途茂草長林，白骨相望，虻蠅扑面，杳無人蹤。二十二日至城父縣，縣中有未燒者十餘家，官舍兩、三處，城池頗高深，舊號小東京雲。二十四日入亳州，總領七人出降。城雖土筑，尚堅。单州出戍軍六百餘人在內，皆出降。市井殘毀，有賣餅者雲：\"戍兵暴橫，亳人怨之。前日降韃，今日降宋，皆此軍也。\"遂以為导，過魏真縣、城邑縣、太康縣，皆殘毀無居人。七月二日，抵東京二十里扎寨，猶有居人遺跡，及桑棗園。初五日，整兵入城。行省李伯淵，先期以文書來降，願與穀用安、范用吉等結約。至是，乃殺所立大王崔立，率父老出迎，見兵六、七百人。荆棘遺骸，交午道路，止存民居千餘家，故宮及相國寺佛閣不動而已。","sortOrder":9},
  {"id":"s_work_tddn_6_10","chapterId":"ch_work_tddn_6","text":"黃河南舊有寸金堤，近為北兵所决，河水淫溢。自寿春至汴，道路水深有至腰及頸處，行役良苦，幸前無敵兵，所以能盡進至此。子才遂駐汴，以俟糧夫之集。而潁川路鈐樊辛、路分王安，亦以偏師下鄭州。二十日，趙文仲以淮東之師五萬，由泗、宿至汴，與子才之軍會焉。因謂子才曰：\"我辈始謀據關守河，今已抵汴半月，不急趣洛陽、潼關何待邪？\"子才以糧餉未集對，文仲益督趣之，遂檄范用吉提新招義士三千，樊辛提武安軍四千，李先提雄關軍二千，文仲亦以胡顯提雄關軍四千，共一萬三千人。命淮西帥機徐敏子為監軍，先令西上，且命楊義以庐州強勇等軍一萬五千人繼之，各給五日糧。諸軍以糧少為辭，則諭之以陆續起發。於是敏子領軍，以二十一日啟行，且令諸軍以五日糧為七日食，蓋懼餉饋或稽故也。","sortOrder":10},
  {"id":"s_work_tddn_6_11","chapterId":"ch_work_tddn_6","text":"至中牟縣，遂遣其客戴應龍回汴趣糧。且與諸將議，遣勇士諭洛，獨胡顯議為不合。敏子因命顯以其所部之半，以扼河陰。二十六日，遣和州寧淮軍正將張迪，以二百人潛赴洛陽。至夜，逾城大噪而入，城中寂然無應者。蓋北軍之戍洛陽者，皆空其城誘我矣。逮晚，始有民庶三百餘家登城投降。二十八日，遂入洛城。二十九日，軍食已盡，乃采蒿和面作餅而食之。是晚，有潰軍失道，奔迸而至。雲：\"楊義一軍，為北兵大陣冲散。今北軍已據北牢矣。\"蓋楊義至洛東三十里，方散坐蓐食，忽數百步外，山椒有立黃紅伞者，眾方駭異，而伏兵突起深蒿中，義仓卒無備，遂致大潰，擁入洛水者甚眾，義仅以身免。於是在洛之師，聞而奪氣。","sortOrder":11},
  {"id":"s_work_tddn_6_12","chapterId":"ch_work_tddn_6","text":"八月一日，北軍已有近城下寨者，且士卒飢甚，遂殺馬而食。敏子與諸將議進止，久之，無他策，势須回師。遂遣步軍兩項往劫東西寨，自提大軍濟洛水而陣。北軍冲突，堅勿動。初二日黎明，北軍以团牌擁進接戰，我軍分而為三，併殺四百餘人，奪团牌三百餘，至午不解。而軍士至此，四日不食矣。始議突围而東。會范用吉下歸順人楚併者獻策曰：\"若投東，則正值北軍大队，無噍類矣。若轉南登封山，由均、許走蔡、息，則或可脱虎口耳。\"事势既急，遂從之。北軍既知我遁，縱兵尾击，死傷者十八九。敏子中流矢，傷右胯幾殆，所乘馬死焉。徒步間行，道收潰散，得三百餘人。結陣而南，經生界团，結砦柵，轉斗而前。凡食桑葉者兩日，食梨棗者七日，乃抵浮光。樊顯、張迪死焉。","sortOrder":12},
  {"id":"s_work_tddn_6_13","chapterId":"ch_work_tddn_6","text":"敏子前所遣客戴應龍，自汴趣糧赴洛，至半道，逢楊義軍潰卒，知洛東丧衄之耗，遂馳還汴，白南仲、子才。二公相謂曰：\"事势如此，我辈自往可也。\"帥參劉子澄，則以為無益。抵暮，下令促裝。翌日昧爽起發，眾皆以為援洛，而前旌已出東門，始知為班師焉。","sortOrder":13},
  {"id":"s_work_tddn_6_14","chapterId":"ch_work_tddn_6","text":"是役也，乘亡金丧亂之餘，中原ㄈ扰之际，乘機而進，直抵舊京，氣势翕合，未為全失。所失在於主帥成功之心太急，入洛之師無援，糧道不繼，以致败亡，此殆天意。後世以成败論功名，遂以貪功冒進罪之，恐亦非至公之論也。此事得之當時隨軍幕府日紀，頗為詳確。近於忠信嘗編《三京本末》，與此互有同異焉。","sortOrder":14},
  {"id":"s_work_tddn_6_15","chapterId":"ch_work_tddn_6","text":"○端平襄州本末","sortOrder":15},
  {"id":"s_work_tddn_6_16","chapterId":"ch_work_tddn_6","text":"趙忠肅公方，开阃荆襄日久，軍民知其威聲。端平甲午冬，朝廷以其子范武仲為荆湖製置大使，镇襄陽，蓋欲其紹世勋，作藩屏也。至郡，則倚王、樊文彬、李伯淵、黃國弼數人為腹心，朝夕酣狎，了無上下之序。民訟邊備，一切废弛。且諸將不能协濟，反自相忌嫉。而一時幕府，亦袖手坐觀成败而已。","sortOrder":16},
  {"id":"s_work_tddn_6_17","chapterId":"ch_work_tddn_6","text":"乙未五月，唐州守楊亻先禀議，因言本州統製軍馬郭勝有異志。蓋楊、郭有隙非一日矣。楊之來，郭已疑之。及楊受犒歸，趙乃以檄召郭勝，於是郭之反謀始决。六月二日，趙下令以襄陽簿廳置勘院，將以勘郭勝也。先是，趙幕客蒋應符往司唐州，遂泄其謀於郭。初六日，乘楊亻先朝拜天貺節，遂閉城，率眾射死亻先於涼轎中。凡回易錢之在州者千餘萬皆掠取之。且下令曰：\"百姓及忠義軍大軍之屯戍在城者，皆不殺。\"即密遣人求北援。","sortOrder":17},
  {"id":"s_work_tddn_6_18","chapterId":"ch_work_tddn_6","text":"初七日，反報至襄陽，時製阃諸客，方命妓宴趙楷於城西檀溪，趙忽急召兩製機議事，時趙括夫瑞州人，以製幹權，章清孫以襄ヘ權，始知唐州之事已泄。初八日，命忠衛都統江海領兵。初九日，先鋒行兵號二萬。又命隨州守臣全子才節製諸項捕賊軍馬，攝棗陽軍劉子澄策應，趙楷監軍。三人者，皆以西師之败镌责，趙欲於此立功，以為复官之地。","sortOrder":18},
  {"id":"s_work_tddn_6_19","chapterId":"ch_work_tddn_6","text":"七月二日，北軍至唐州、棗林，全、劉聞之遁去。先又調德安守王策援，亦不至，反俱以捷聞。全、王至襄，凡痛飲半月而回。既而探報益急，寇已半渡黃河。而王歸德安，以黃州克敵軍叛（即李藏器之軍留黃陂上者）德安境，遣人招納四千八百餘人，意欲阻撓淮西製帥楊恢，趙欣然從之。九月十日，聞王帶所納叛軍來，襄人疑其反覆不常，而末如之何。趙忽令諸門不許出一人一擔，而所置緝捕司帶行人孫山等察探，变是為非，於是襄人愈侧足矣。二十三日，棗陽告急，趙复不遣援兵。自此，京西諸郡俱叛。十一月一日，北軍首領亻奔盏，至襄陽江北對壘，不戰而败。遣李師古持書與趙，趙不啟封，焚之。十一日，北哨入南關，即追逐，斬守關趙寧以徇。十九日，北騎至襄陽城下，約六、七千人，下寨於檀溪山。二十日，戰於上閘口。餘哲軍败，丧數千人，再戰，勝之。二十一日，北軍始退。十二月，北軍自峡州回，戰於江北樊城。我師少勝，則以大捷聞。","sortOrder":19},
  {"id":"s_work_tddn_6_20","chapterId":"ch_work_tddn_6","text":"自十月初，下令清野，凡襄四境民居竹木無孑遺。至是，物价踴貴，諸將日飲。亡何，用散樂段得仙者佐歡，繞城躍馬，殊不介意。二月五日，始遣王帶克敵軍往均州光化軍巡邏，逗遛不進，仅至小樊，乃以收复兩郡捷聞。是日，朝廷遣镇江都統李虎，號無敵軍，偕光州都統王福所部軍，至襄策應，而克敵軍不能自安矣，趙遂急遣王曼避之。趙出城迓虎，虎傳朝廷宣諭之命，趙涕泣謝恩。乃對虎慷慨，共十餘大觥以歸。無敵軍即宣言欲剿除克敵，雲：\"不因你瞞番人在此，如何我瞞四千里路來。\"十四日，王回，趙令戍郢州，恃平日狎，不從，必欲入城。十六日，下令大宴，犒諸製領。於是克敵愈疑，公出怨言，襄人愈皇皇矣。有以其言密告趙內機檢者（趙之侄），宴遂中止。二十日，止宴李虎、王、王福、楊茂先、李伯淵、黃國弼、夏全於府，大醉極歡，達旦而罢。二十一日，克敵軍往南門燒紙，蓋合謀也。夜三鼓，縱火於市東竹竿巷口，及於諸處縱火發喊，搶入製府轅門，為門內軍射殺二人，复至東市劫掠，擐甲露刃，不許救扑。至二十三日火方熄。趙帥於南門城上，呼王詰問，李虎適在旁，雲：\"好斬。\"言未脱口，而首已斷，身皆分裂矣。趙遂下令，凡背心有紅月號者，皆斬，克敵軍號也。於是刀刃亂下，死者多無辜，然叛軍未盡剿也。未時，火复自南門起，凡官民之居，一而空。漕使李伯度、教官羅叔度兩家避難東城上，亦為叛軍焚殺。二十三日，遣李伯淵往江北剿殺叛軍，未回，克敵軍遂殺其家，因乘亂劫掠民居尤酷。趙帥於是先焚其父威惠廟，遂同李虎、黃國弼、夏全及回回四人，潛出西門，失去製司印。城中久之方覺，遂皆狼狽奔逃而出矣。","sortOrder":20},
  {"id":"s_work_tddn_6_21","chapterId":"ch_work_tddn_6","text":"是日，江北忠衛軍亦反。趙至荆州，复遣都統江海戍荆門。有軍校獲製司印來獻，趙補以統領之職。是時叛亂相仍，趙乃嚴刑以安反侧。於教場後掘地，方三丈，深二丈。以石作窗為地牢，上覆以土，下施丑械，懸梯而下，以准遣胡主之。","sortOrder":21},
  {"id":"s_work_tddn_6_22","chapterId":"ch_work_tddn_6","text":"大抵襄州之禍，萌於趙武仲之來，成於王招納克敵軍，激於李虎無敵軍之至。自嶽武穆收复，凡一百三十年，生聚繁庶，不减昔日。城池高深，甲於西陲。一旦灰燼，禍至惨也。","sortOrder":22},
  {"id":"s_work_tddn_6_23","chapterId":"ch_work_tddn_6","text":"先是郡廳相對，有雅歌樓，雄麗特甚。一日，趙方坐衙，忽睹樓中妓女人物，雜還宴飲。趙怒，以為僚屬置宴，略不避忌。亟遣人觇之，則樓門扃甚嚴，凝尘滿室，識者已疑其不祥。章叔恭時為ヘ，一夕，坐中堂閱案牍，至夜分，忽若有人自後呼之曰：\"快去！快去！此地不久也。\"心疑之而未深信，越月而亂作。益知禍患有定數，鬼神固已先知矣。此事皆章叔恭得之目击雲。","sortOrder":23},
  {"id":"s_work_tddn_6_24","chapterId":"ch_work_tddn_6","text":"○趙氏靈璧石","sortOrder":24},
  {"id":"s_work_tddn_6_25","chapterId":"ch_work_tddn_6","text":"趙邦永，本姓李，李全將也。趙南仲愛其勇，納之，改姓趙氏。入洛之師，實為統軍。嘗過靈璧縣，道旁奇石林立，一峰巍然，Β秀润。南仲立馬旁睨，撫玩久之。後數年家居，偶有以片石為獻者，南仲因詫諸客以昔年符離所見者。邦永時適在旁，聞語即退。才食頃，數百兵舁一石而來，植之庭間，俨然馬上所見也。南仲駭以為神，扣所從來，則雲：\"昔年相公註视之际，意謂愛此，隨命部下五百卒輦歸，而未敢獻。適聞所言，始敢以進。\"南仲為之一笑。","sortOrder":25},
  {"id":"s_work_tddn_6_26","chapterId":"ch_work_tddn_6","text":"○南園香山","sortOrder":26},
  {"id":"s_work_tddn_6_27","chapterId":"ch_work_tddn_6","text":"事有一時傳訛，而人競信之者，閱古之败，眾惡皆歸焉。然其間率多浮誕之語，抑有乘時以丑名惡聲，以詆平日所不樂以甘心者，如犬吠村莊等事是也。姑以《四朝聞見錄》所載一事言之。謂蜀帥獻沈香山，高五丈，立之南園凌風閣下。今慶樂園，即昔之南園也。所謂香山，尚巍然立於閣前，乃枯耳，初非沉香也。推此以往，人言未可盡信也如此。餘嘗戲賦絕句雲：\"舊事凄涼尚可尋，斷碑閒臥草深深。凌風閣下槎牙树，當日人疑是水沈。\"","sortOrder":27},
  {"id":"s_work_tddn_6_28","chapterId":"ch_work_tddn_6","text":"○李泌錢若水事相類","sortOrder":28},
  {"id":"s_work_tddn_6_29","chapterId":"ch_work_tddn_6","text":"李泌在衡嶽，有僧明瓒號懶殘。泌察其非凡，中夜潛往謁之。懶殘命坐，拨火中芋以啖之，曰：\"勿多言，領取十年宰相。\"（《李泌家傳》及《甘泽謠》）錢若水為舉子時，見陳希夷於華山。希夷曰：\"明日當再來。\"若水如期往，見一老僧與希夷擁地爐坐。僧熟视若水久之，不語，以火箸畫灰，作\"做不得\"三字。徐曰：\"急流勇退人也。\"若水辭去。後為枢密副使，年才四十致仕。老僧者，麻衣道者也。（《邵氏聞見錄》）","sortOrder":29},
  {"id":"s_work_tddn_6_30","chapterId":"ch_work_tddn_6","text":"又若水謁華山陳摶，曰：\"目如點漆，黑白分明，當作神仙。\"有紫衣老僧曰：\"不然。他日但能富貴，急流中勇退人也。\"（《明道雜志》）","sortOrder":30},
  {"id":"s_work_tddn_6_31","chapterId":"ch_work_tddn_6","text":"又若水謁陳希夷，曰：\"子神清氣一，可致神仙。\"遂招白閣道者决之，乃以為不然。（《畫墁錄》）","sortOrder":31},
  {"id":"s_work_tddn_6_32","chapterId":"ch_work_tddn_6","text":"又法雲佛國禪師惟白，傳康節《易》學甚精熟，未嘗語人。元符辛巳，鄭達夫以大宗丞召佛國，即招達夫飲，併約妙應大師伯華同席。顧妙應曰：\"如何？\"妙應曰：\"决作，决作。\"佛國乃語達夫曰：\"君異日必為相，直待蔡元長、張天覺顛沛之後，即爰立矣。\"已而果然。（《鑒堂遺事》）","sortOrder":32},
  {"id":"s_work_tddn_6_33","chapterId":"ch_work_tddn_6","text":"以上數說，皆同而微異，豈即一事演而為數說乎？大抵近世雜說，率多剿入，不可盡信，故餘表而出之。","sortOrder":33},
  {"id":"s_work_tddn_6_34","chapterId":"ch_work_tddn_6","text":"○用事偶同","sortOrder":34},
  {"id":"s_work_tddn_6_35","chapterId":"ch_work_tddn_6","text":"欧陽公《非非堂記》曰：\"是是近乎諂，非非近乎訕，不幸而過，寧訕無諂。\"坡翁為劉壮舆作《是是堂》詩雲：\"閒燕言仁義，是非安可無；非非義之屬，是是仁之徒；非非近乎訕，是是近乎諛。\"","sortOrder":35},
  {"id":"s_work_tddn_6_36","chapterId":"ch_work_tddn_6","text":"子由《彈呂惠卿章》雲：\"放，违命也，推其仁則可以托國；食子，徇君也，推其忍則至於弒君。\"山穀《懷半山老人》詩雲：\"啜羹不如放，樂羊終愧巴西。\"其意蓋指惠卿也。","sortOrder":36},
  {"id":"s_work_tddn_6_37","chapterId":"ch_work_tddn_6","text":"二公豈相蹈袭者邪？其用事造語，若出一轍，而不以為嫌也。然《韓非子》所載放，乃是西巴，恐一時偶誤耳。","sortOrder":37},
  {"id":"s_work_tddn_6_38","chapterId":"ch_work_tddn_6","text":"○方翥","sortOrder":38},
  {"id":"s_work_tddn_6_39","chapterId":"ch_work_tddn_6","text":"{甫}田方翥试南宮，第三場欲出納卷，有物礙其足，视之，則一卷子，止有前二篇，其文亦通畅，不解何以不終卷而弃於地也。翥筆端俊甚，以其緒餘足成之，併携出中門，投之幕中，一時不暇記其姓名，翥既中第，亦不复省問。他年，翥為馆職，偶及试闈異事，因及之。偶有客在坐，同年也，默不一語。翼日，具冠裳造方，自叙本末。言：\"试日，疾不能支。吾扶拽而出，所謂试卷者，莫記所在，已絕望矣。一旦榜出，乃在選中。恍然疑姓名之偶同，幸未嘗與人言。亟入京物色之，良是，借真卷觀之，俨然有續成者，竟莫测所以。今日乃知出君之筆，君，吾恩人也。\"方笑謝而已。","sortOrder":39},
  {"id":"s_work_tddn_6_40","chapterId":"ch_work_tddn_6","text":"按冯京知舉，張芸叟賦公生明，重叠用韻，已而為第四名，竊怪主司滷莽。及元祐中，使金過北門，冯為留守，始修門生敬酒，適冯因言：\"昔忝知舉，秘監賦重叠用韻，以論策佳，辄為改之，擢置高第，頗記憶否？\"芸叟方飲，不覺酒杯覆懷，再三愧謝。與此略同。","sortOrder":40},
  {"id":"s_work_tddn_6_41","chapterId":"ch_work_tddn_6","text":"○乔文惠晚景","sortOrder":41},
  {"id":"s_work_tddn_6_42","chapterId":"ch_work_tddn_6","text":"乔文惠行簡，嘉熙之末，自相位拜平章軍國重事，年已八秩矣，時皆以富貴長年羨之。而公晚年子孫淪丧，况味尤惡，嘗作《上梁文》雲：\"有園有沼，聊為卒歲之遊；無子無孫，盡是他人之物。\"又《乞歸田里表》雲：\"少、壮、老，百年已逾八帙；祖、子、孫，三世仅存一身。\"聞者怜之。","sortOrder":42},
  {"id":"s_work_tddn_6_43","chapterId":"ch_work_tddn_6","text":"○趙伯美","sortOrder":43},
  {"id":"s_work_tddn_6_44","chapterId":"ch_work_tddn_6","text":"趙嘉慶，字伯美，素號忠直，然性頗猜忌褊躁，故所至與物多忤。淳祐庚戌，盱江峒寇猖獗，以府丞吳蒙明發知建昌軍。至則撫勞剿除，漸致安靖，朝廷奖勞之。未幾，以病丐祠，有旨轉一官，別與差遣。時伯美在後省，遂繳寢轉官之命。既而再乞祠，遂主玉局。而伯美复繳其祠，且謂：\"前奏稽遲，是必賊蒙使其兄司農丞革，坐局行赇，遏截御筆之所致。以區區支壘，琐琐下流，辄敢倚同氣以置局於輦下，植死党而為阱於國中。乞收回玉局之命，併從尚書省札下吳革，责戒励状。仰今後不得懷奸事上，徇欲欺君。如或不悛，重置典憲。\"省札既下，吳農丞辨析状雲：\"革弟蒙，分符罔功，以病丐祠。增秩改麾，既被繳驳，聖恩宽大，遂畀祠廪。或予或奪，惟上所命。且革濫缀班行，治事有公宇，退食有公廨，何謂置局？何謂行赇？况弟蒙始於請祠，終於得祠，初非幹進，何事營求？蓋弟蒙之取怒嘉慶者，祗緣丁未歲同官京推，以女求婿，屢請不諧，遂成仇隙。求盱江僚屬之荐舉，則有書；求盱江公库之文籍，則有目。厚貌深情，機阱莫测。况於革，尤為無辜。且所謂责励状者，乃州縣警吏民之文。仰惟國家待士以禮，三百年間，未聞有此典故。革粗識事體，安敢辨白。但乞將革罢斥，遠跡仇怨，實拜公朝之賜。\"有旨吳革知南安軍。而伯美复上章辨證，且於繳蔡榮疏內，謂榮與革結為死党，滋長其惡，議欲與之報复。","sortOrder":44},
  {"id":"s_work_tddn_6_45","chapterId":"ch_work_tddn_6","text":"後二年，伯美為湖南憲，牟氵榮叔清知衡陽。行移之間，微有抵牾。伯美遂上章劾叔清，報可稍稽，复疑為叔清乡相謝渎山方叔所匿，遂再疏按之，且言沈匿之弊。謝相大不能堪，遂於榻前奏陳，將承受蘇镛斷遣，仍作勘會雲：\"據湖南提刑趙嘉慶，昨於奏状稱，已按知衡州牟氵榮，久而未下，謂是相府遏奏。尋令臨安府追上承受，及通奏進銀台司等人根究，俱稱即不曾有奏投進。所有牟氵榮，既是外台已按，雖是未見按章，先合施行。\"奉旨牟氵榮與祠。隨有御筆雲：\"趙嘉慶劾牟氵榮，初無奏牍，辄誣大臣以沈匿之事，力肆攻詆。然以在外小臣，乃敢欺罔君上，誣謗宰臣。且不顧廉恥，行赇賂吏，尚氣節者，得如是乎？國朝典故，凌蔑宰相，罪在不恕。朕不欲已甚，姑镌一秩罢任，以為翼虛駕伪，虧國體，坏綱紀者之戒。\"","sortOrder":45},
  {"id":"s_work_tddn_6_46","chapterId":"ch_work_tddn_6","text":"明年，謝罢相，董榘堂槐繼之。嘉慶為大蓬供職，後复有申省状雲：\"重念嘉慶重遭誣罔，沮於威势，不容分疏。但誣奏傳播萬里，而元來按發之事，未能暴白天下。承受蘇镛，久已叛去，忽得其状，具述前相之子，使其仆任康祖誘胁，打回元奏因依。乃是事未發以前，牟氵榮自知在郡酷虐有罪，懼為民訴，先已馳告謝修，修遂令任康祖誘胁蘇镛，遇有嘉慶章奏，須先袖呈相府。先奏實被謝修分付以水濕打回。第二奏既到，謝修自知败露，却將蘇镛送獄，妄令供析。欲乞敷奏施行，俾元來屈抑，稍得暴白於四方。\"得旨與改正理選月日。","sortOrder":46},
  {"id":"s_work_tddn_6_47","chapterId":"ch_work_tddn_6","text":"是歲冬，察官朱應元劾伯美：\"向者，持節湖南，不理民訟，惟理贓錢。不問虛實之有無，但责郡吏之代納。兜攬民訟，交通關節，為郡將所持，遂生怨隙。\"遂用此罢去。","sortOrder":47},
  {"id":"s_work_tddn_6_48","chapterId":"ch_work_tddn_6","text":"○二蘇議禮","sortOrder":48},
  {"id":"s_work_tddn_6_49","chapterId":"ch_work_tddn_6","text":"《禮》家如聚訟，雖兄弟亦不容苟同。其大者，無如天地之祭分合一議。自昔諸儒之論，不知其幾，今姑摭二蘇之議言之。東坡則據《周頌·昊天有成命·序》雲：\"郊祀天地也。\"以為此乃合祭天地之明文。潁濱乃據《周禮》為說，謂冬至祀天於圓丘，夏至祀地於方泽。其後朝廷迄從坡說，合祭以至於今焉。","sortOrder":49},
  {"id":"s_work_tddn_7_1","chapterId":"ch_work_tddn_7","text":"●卷六","sortOrder":1},
  {"id":"s_work_tddn_7_2","chapterId":"ch_work_tddn_7","text":"○紹興御府書畫式","sortOrder":2},
  {"id":"s_work_tddn_7_3","chapterId":"ch_work_tddn_7","text":"思陵妙悟八法，留神古雅。當幹戈ㄈ扰之际，訪求法書名畫，不遺餘力。清閒之燕，展玩摹拓不少怠。蓋睿好之篤，不憚勞費，故四方爭以奉上無虛日。後又於榷場購北方遺失之物，故紹興內府所藏，不减宣政。惜乎鑒定諸人如曹勋、宋貺、龍大淵、張俭、鄭藻、平协、劉炎、黃冕、魏茂實、任原辈，人品不高，目力苦短。凡經前辈品題者，盡皆拆去，故今御府所藏，多無題識，其源委、授受、歲月、考订，邈不可求，為可恨耳。其裝礻票裁製，各有尺度，印識標題，具有成式。餘偶得其書，稍加考正，具列於後，嘉與好事者共之，庶亦可想像承平文物之盛焉。","sortOrder":3},
  {"id":"s_work_tddn_7_4","chapterId":"ch_work_tddn_7","text":"出等真跡法書。兩漢、三國、二王、六朝、隋、唐君臣墨跡（併系御題佥，各書\"妙\"字）。","sortOrder":4},
  {"id":"s_work_tddn_7_5","chapterId":"ch_work_tddn_7","text":"用克絲作樓台錦衤票。青绿簟文錦里。大薑牙雲鸞白綾引首。高麗紙〈貝覃〉。出等白玉碾龍簪顶軸（或碾花）。檀香木杆。钿匣盛。上、中、下等唐真跡。（內上、中等，併降付米友仁跋）用紅霞雲鸞錦衤票。碧鸞綾里。白鸞綾引首。高麗紙〈貝覃〉。白玉軸（上等用簪顶，餘用平等）。檀香木杆。次等晉、唐真跡（併石刻晉、唐名帖）。用紫鸞鵲錦衤票。碧鸞綾里。白鸞綾引首。蠲紙衤票。次等白玉軸。引首後衤票卷縫用御府圖書印。引首上下縫用紹興印。","sortOrder":5},
  {"id":"s_work_tddn_7_6","chapterId":"ch_work_tddn_7","text":"鉤摹六朝真跡（併系米友仁跋）。用青樓台錦衤票。碧鸞綾里。白鸞綾引首。高麗紙衤票。白玉軸。御府臨書六朝、羲、獻、唐人法帖，併雜詩賦等（內長篇不用邊道，衣古厚紙，不揭不背）。用氈路錦。衲錦。柿紅龟背錦。紫百花龍錦。皂鸞綾衤票等。碧鸞綾里。白鸞綾引首。玉軸或瑪瑙軸臨時取旨。內趙世元鉤摹者亦用衲錦衤票。蠲紙〈貝覃〉。瑪瑙軸。併降付莊宗古、鄭滋，令依真本紙色及印記對樣裝造。將元拆下舊題跋進呈揀用。五代、本朝臣下臨帖真跡。","sortOrder":6},
  {"id":"s_work_tddn_7_7","chapterId":"ch_work_tddn_7","text":"用皂鸞綾衤票。碧鸞綾里。白鸞綾引首。夹背蠲紙〈貝覃〉。玉軸或瑪瑙軸。米芾臨晉、唐雜書上等。用紫鸞鵲錦衤票。紫馳尼里。楷光紙〈貝覃〉。次等簪顶玉軸。引首前後，用內府圖書、內殿書記印。或有題跋，於縫上用御府圖籍印。最後用紹興印。併降付米友仁親書審定，題於〈貝覃〉卷後。","sortOrder":7},
  {"id":"s_work_tddn_7_8","chapterId":"ch_work_tddn_7","text":"蘇、黃、米芾、薛紹彭、蔡襄等雜詩、賦、書簡真跡。用皂鸞綾衤票。白鸞綾引首。夹背蠲紙〈貝覃〉。象牙軸。用睿思東閣印、內府圖記。","sortOrder":8},
  {"id":"s_work_tddn_7_9","chapterId":"ch_work_tddn_7","text":"米芾書雜文、簡牍。用皂鸞綾衤票。碧鸞綾里。白鸞綾引首。蠲紙〈貝覃〉。象牙軸。用內府書印、紹興印。併降付米友仁验定，令曹彦明同共編類等第，每十帖作一卷。內雜帖作册子。趙世元鉤摹下等諸雜法帖。用皂木錦衤票。瑪瑙軸。或牙軸。前引首用機暇清賞印，縫用內府書記印，後用紹興印。仍將原本拆下題跋揀用。六朝名畫橫卷。用克絲作樓台錦衤票。青绿簟文錦里（次等用碧鸞綾里）。白大鸞綾引首。高麗紙〈貝覃〉。出等白玉碾花軸。六朝名畫掛軸。用皂鸞綾上下衤票。碧鸞綾引首。碧鸞綾托衤票（全軸）。檀香軸杆。上等玉軸。唐、五代畫橫卷（皇朝名畫同）。用曲水紫錦衤票。碧鸞綾里。白鸞綾引首。玉軸。或瑪瑙軸（內下等併謄本用皂衤票雜色軸）。蠲紙〈貝覃〉。唐、五代、皇朝等名畫掛軸，併同六朝裝褫，軸頭旋取旨。蘇軾、文與可雜畫（姚明裝造）。用皂大花綾衤票。碧花綾里。黃白綾双引首。乌犀或瑪瑙軸。米芾雜畫橫軸。用皂鸞綾衤票。碧鸞綾里。白鸞綾引首。白玉軸。或瑪瑙軸。僧梵隆雜畫橫軸（陳子常承受）。樗蒲錦襟。碧鸞綾里。白鸞綾引首。瑪瑙軸。諸畫併上用乾卦印，下用希世印，後用紹興印。","sortOrder":9},
  {"id":"s_work_tddn_7_10","chapterId":"ch_work_tddn_7","text":"諸畫裝褫尺寸定式。","sortOrder":10},
  {"id":"s_work_tddn_7_11","chapterId":"ch_work_tddn_7","text":"大整幅上引首三寸，下引首二寸。小全幅上引首二寸七分。下引首一寸九分。經帶四分。上衤票除打ㄓ竹外，净一尺六寸五分。下衤票除上軸外，净七寸。一幅半上引首三寸六分。下引首二寸六分。經帶八分。双幅上引首四寸，下引首二寸七分。上衤票除打ㄓ竹外，净一尺六寸八分。下衤票除上軸杆外，净七寸三分。兩幅半上引首四寸二分。下引首二寸九分。經帶一寸二分。三幅上引首四寸四分。下引首三寸一分。經帶一寸三分。四幅上引首四寸八分。下引首三寸三分。經帶一寸五分。橫卷衤票合長一尺三寸（高者用全幅）。引首闊四寸五分（高者五寸）。應書畫面佥，併用真古經紙，隨書畫等第取旨。應六朝、隋、唐出等法書名畫，併御臨名帖，本朝名臣帖，併御書面佥。內中、下品，併降付書房，令裴禧書。應書畫橫卷、掛軸，併用雜色錦袋复帕，象牙牌子。應搜訪到書法墨跡，降付書房。先令趙世元定验品第進呈訖，次令莊宗古分揀付曹勋、宋貺、張俭、龍大淵、鄭藻、平协、黃冕、魏茂實、任源等覆定验訖，裝褫。應搜訪到名畫，先降付魏茂實定验，打《千字文》號及定验印記進呈訖，降付莊宗古分手裝背。應搜訪到古畫，內有破碎不堪補背者，令書房依元樣對本臨摹進呈訖，降付莊宗古，依元本染古槌破，用印裝造。謄劉娘子位併馬興祖謄畫。應古畫如有宣和御書題名，併行拆下不用。別令曹勋等定验，別行讠巽名作畫目進呈取旨。","sortOrder":11},
  {"id":"s_work_tddn_7_12","chapterId":"ch_work_tddn_7","text":"碑刻橫卷定式","sortOrder":12},
  {"id":"s_work_tddn_7_13","chapterId":"ch_work_tddn_7","text":"《定武蘭亭》，阑道高七寸六分。每行闊八分，共二十八行。《樂毅論》，阑道高七寸五分。每行闊六分，共四十三行。《真草千文》，阑道高七寸二分。每行闊八分，共二百行。智永《歸田賦》，阑道高七寸二分半。每行闊八分，共四十四行。獻之《洛神賦》，阑道高八寸三分。每行闊六分，共九行。《枯木賦》，阑道高九寸九分。每行闊九分，共三十九行。應古厚紙，不許揭薄。若紙去其半，則損字精神，一如摹本矣。應古畫裝褫，不許重洗，恐失人物精神，花木艳。亦不許裁剪過多，既失古意，又恐將來不可再背。應搜訪到法書，多系青阑道，絹衬背。唐名士多於阑道前後題跋。令莊宗古裁去上下阑道，揀高格者，隨法書進呈，取旨揀用。依紹興格式裝褫。","sortOrder":13},
  {"id":"s_work_tddn_7_14","chapterId":"ch_work_tddn_7","text":"內府裝褫分科引式格式","sortOrder":14},
  {"id":"s_work_tddn_7_15","chapterId":"ch_work_tddn_7","text":"粘裁摺界裝背染古","sortOrder":15},
  {"id":"s_work_tddn_7_16","chapterId":"ch_work_tddn_7","text":"集文定验圖記","sortOrder":16},
  {"id":"s_work_tddn_7_17","chapterId":"ch_work_tddn_7","text":"按唐《藝文志序》，載四库裝軸之法，極其環致。《六典》載崇文馆有裝潢匠五人，即今背匠也。本朝秘府謂之裝界即此事，蓋古今所尚雲。","sortOrder":17},
  {"id":"s_work_tddn_7_18","chapterId":"ch_work_tddn_7","text":"○解颐","sortOrder":18},
  {"id":"s_work_tddn_7_19","chapterId":"ch_work_tddn_7","text":"匡衡好學，精力絕人，諸儒為之語曰：\"無說《詩》；匡鼎來，匡說詩，解人颐。\"蓋言其善於講誦，能使人喜而至於解颐也。至今俗諺以人喜過甚者，雲：\"兜不上下颏\"，即其意也。本朝盛度，以第二名登第，其父喜甚，颐解而卒。又岐山縣樊紀登第，其父亦以喜而颐脱，有聲如破瓮。按《医經》雲：\"喜則氣缓，能令致脱颐。\"信非戲語也。","sortOrder":19},
  {"id":"s_work_tddn_7_20","chapterId":"ch_work_tddn_7","text":"○山陵使故事","sortOrder":20},
  {"id":"s_work_tddn_7_21","chapterId":"ch_work_tddn_7","text":"韓魏公為永昭山陵使，事畢，而英宗不豫，不敢還。至四載，以永厚陵成，复護葬於洛陽。因上疏雲：\"自唐至於五代，故事山陵使事訖，合行求去。\"遂以司徒、兩镇節鉞，判相州。","sortOrder":21},
  {"id":"s_work_tddn_7_22","chapterId":"ch_work_tddn_7","text":"元符間，章子厚為永泰山陵使，有作詞戲之雲：\"草草山陵職事，厭厭罢相情懷。\"蓋謂故事當然也。","sortOrder":22},
  {"id":"s_work_tddn_7_23","chapterId":"ch_work_tddn_7","text":"淳熙間，高宗山陵欲差五使，王季海為首相，殊以為忧。尤延之時為禮官，於是授之以說雲：\"今此乃攒宮耳，不當置五使。\"季海遂倡其說曰：\"祖宗全盛，營陵西洛，乃差五使。今權卜會稽，止當差總護使耳。且歲旱，民力何以堪之。\"於是止差伯圭充總護使，洪邁充桥道頓遞使。殊不知季海拜高宗朝宰相，本無解罢之嫌，亦一時不深考典故耳。","sortOrder":23},
  {"id":"s_work_tddn_7_24","chapterId":"ch_work_tddn_7","text":"○胡明仲本末","sortOrder":24},
  {"id":"s_work_tddn_7_25","chapterId":"ch_work_tddn_7","text":"胡致堂寅字明仲，文定公安國之庶子也。將生，欲不舉。文定夫人夢大魚躍盆水中，急往救之，則已溺將死矣，遂抱以為己子。少桀黠難製，父閉之空閣中，其上有雜木，過數旬，寅盡刻為人形。安國曰：\"當思所以移其心。\"遂別置書數千卷於其上，年餘，悉能成誦，不遺一卷，遂為名儒。","sortOrder":25},
  {"id":"s_work_tddn_7_26","chapterId":"ch_work_tddn_7","text":"及貴顯，不复為本生母持服，為右正言章夏所劾，會秦丞相亦惡之，遂謫新州安置。嘗於謫所著《讀史管見》數千萬言，極意譏貶秦氏。如論桑維翰，\"雖因耶律德光而相，其意特欲興晉而已，固無挟敵以自重，劫主以盜權之意，猶足為賢\"等語甚多。蓋此書有為而作，非徒區區評論也。","sortOrder":26},
  {"id":"s_work_tddn_7_27","chapterId":"ch_work_tddn_7","text":"及論漢宜帝立皇考廟曰：\"既為伯父母、叔父母之後而父母亡，則當降所生父母，而伯父母、叔父母之稱，昭昭然矣。稱謂既如此，則三年之丧，宜降其服期，又昭昭然矣。稱謂既如此，服丧又如此，則情之主乎內者，隆所當隆，殺所當殺，不敢交奪於幽隱之中，又昭昭然矣。\"","sortOrder":27},
  {"id":"s_work_tddn_7_28","chapterId":"ch_work_tddn_7","text":"其論哀帝議立定陶王後曰：\"故為人後者，不顧私親，安而行之，猶天性也。當是時而责為人後者，絕私親之顧，彼反得以旁緣不孝之似而责之。顧私親者，至以孝自居，不顧者，反陷於罪辟。\"雲雲。","sortOrder":28},
  {"id":"s_work_tddn_7_29","chapterId":"ch_work_tddn_7","text":"其論晉出帝追封敬儒為宋王曰：\"服而或加或降者，以恩屈於義也。屈所生之恩，以伸所厚之義，則恩輕而義重矣。恩輕而義重，則所生父母，固可名之曰伯父母、叔父母矣。為此論者，皆是欲借此以自解，然持論太過，所謂欲蓋而益彰，前辈蓋嘗評之，故今詳著始末於此，固非敢輕議先儒也。若夫定陶立後，敬儒封王，紛紛為是無定者，皆父子私心不能自克，互相為欺，以致此耳。若昭陵立英宗為皇子詔曰：'濮安懿王之子，猶朕之子也。'思陵立寿皇為皇子詔曰：'藝祖皇帝七世孫也。'明白洞達，大哉王言，後世安得而擬議之哉？\"","sortOrder":29},
  {"id":"s_work_tddn_7_30","chapterId":"ch_work_tddn_7","text":"○詩用事","sortOrder":30},
  {"id":"s_work_tddn_7_31","chapterId":"ch_work_tddn_7","text":"糜先生，吳之老儒也，[B12U]、，皆其子侄行。記問該洽，《九經》註疏，悉能成誦，場屋之文，未嘗謄稿，為時乡師。然垂老連蹇，未嘗預貢士籍。時吳中孚（名惟信號菊潭）客吳，能詩，善絕句，糜極稱之，以為不可及。一日，遇諸涂，扣以近作，吳因朗誦《傷春絕句》雲：\"白發傷春又一年，閒將心事卜金錢。梨花瘦盡東風懶，商略平生到杜鵑。\"糜老至屈膝拜之曰：\"子真謫仙人也。老夫每欲效顰，則漢高祖、唐太宗，追逐不少置矣。\"蓋前辈服善若此。陳簡斋嘗語人以作詩之要雲：\"天下書雖不可不讀，然慎不可有意於用事。\"正謂此也。今人或以用事多為博贍，誤矣。","sortOrder":31},
  {"id":"s_work_tddn_7_32","chapterId":"ch_work_tddn_7","text":"○王魁傳","sortOrder":32},
  {"id":"s_work_tddn_7_33","chapterId":"ch_work_tddn_7","text":"世俗所謂王魁之事殊不經，且不見於傳記雜說，疑無此事。《異聞集》雖有之，然集乃唐末陳翰所編，魁乃宋朝人，是必後人剿入耳。","sortOrder":33},
  {"id":"s_work_tddn_7_34","chapterId":"ch_work_tddn_7","text":"按嘉祐中，進士奏名訖，未御试，京師妄傳王俊民為状元，不知言之所起，亦不知俊民為何人。及御试，王荆公時為知製誥，與楊樂道共為詳定官。舊製，御试舉人，設初考官，先定等第，复弥之以送覆考再定，乃付詳定。發初考所等以對，覆考如同即已，不同，則詳其程文為定。時荆公以初、覆所定第一人，皆未允當，於行間別取一人為首，楊樂道以為不可，議未决，太常少卿朱從道時為封弥，聞之，謂同舍曰：\"二公何用力爭？從道十日前，已聞王俊民為状元，事必前定，二公徒自苦耳。\"既而，二人各以己意進禀，而詔從荆公之請。及發封，乃王俊民也。","sortOrder":34},
  {"id":"s_work_tddn_7_35","chapterId":"ch_work_tddn_7","text":"後又見初虞世所集《養生必用方》，戒人不可妄服金虎碧霞丹，乃詳載其說雲：\"状元王俊民，字康侯，為應天府發解官，得狂疾，於貢院中嘗對一石碑呼叫不已，碑石中若有應之者，亦若康侯之奋怒也。病甚不省，覺，取書册，中交股刀自裁及寸，左右抱持之遂免。出试院未久，疾势亦已平复。予與康侯有父祖乡曲之舊，又自童稚共筆砚，嘉祐中，同试於省場，傳聞可駭，亟自汶拿舟抵彭城。時十月盡矣，康侯亦起居飲食如故，但不樂，或雲：'平生自守如此，乃有此疾。'予亦多方开慰。歲暮，予北歸，康侯有詩送予雲：'寒窗一夜雪，紛紛來朔風。之子動歸興，輕袂飄如蓬。問子何所之？家在濟水東；問子何所學？上庠教化宮。行將携老母，寓居學其中。'雲雲。予既去，徐医以為有痰，以金虎碧霞丹吐之。或謂心藏有熱，勸服治心經諸冷藥。積久，為寒中洞泄，氣脱肉消，飲食不前而死。康侯父知舒州太湖縣，遣一道士與弟覺民自舒來雲：'道士能奏章達上清，及訴問鬼神幽暗中事。'道士作醮書符，傳道冥中語雲：'五十年打殺謝、吳、劉不結案事。'康侯丙子生，死才二十七歲，五十年前，豈宿生邪？康侯既死，有妄人托夏噩姓名作《王魁傳》，實欲市利於少年狎邪辈，其事皆不然。康侯，萊州掖縣人。祖世田舍翁，父名弁，字子儀，誦詩登科，為鄆州司理。康侯時十五餘歲，三兄弟隨侍，與予同在鄆學。子儀為开封軍巡判官，康侯兄弟入太學，不三年，號成人。子儀待蘇州崑山闕，來居汶，康侯兄弟又與予在汶學。子儀謫潭州稅，康侯兄弟自潭來貫鄢陵戶。康侯登科為第一。省试前，父雪崑山事，自潭移舒州太湖縣。康侯是年歸舒州省親，次年，赴徐州任，明年，死於徐，實嘉祐八年五月十二日也。康侯性刚峭不可犯，有志力學，愛身如冰玉，不知猥巷俚人語。不幸為匪人厚誣，弟辈又不為辨明，懼日久無知者，故因戒世人服金虎碧霞丹，且以明康侯於泉下。紹聖元年九月，漕河舟中記。\"","sortOrder":35},
  {"id":"s_work_tddn_7_36","chapterId":"ch_work_tddn_7","text":"○向氏粥田","sortOrder":36},
  {"id":"s_work_tddn_7_37","chapterId":"ch_work_tddn_7","text":"楊和王最所鐘愛者第六女，性極賢淑。初事趙汝敕，繼事向子丰，居於，未有所育，王甚念之。一日，向妾得男，楊氏使秘之，以為己出，且亟報王。王喜甚，即請誥命，輕舟往视之。向氏家知王來，良窘，無策以泥其行。時王以保寧、昭慶兩镇節鉞領殿巖，於湖為本镇。子丰因使人諷郡官往迓之。自郡將以次，皆屬。謹伺於界首。王初以人不知其來，及是聞官吏郊迎，深恐勞動多事，遂中道而返。因厚以金繒花果以遺其女，且拨吳門良田千畝以為粥米，逮今向氏家有崑山粥米莊雲。此事得之向氏子孫。","sortOrder":37},
  {"id":"s_work_tddn_7_38","chapterId":"ch_work_tddn_7","text":"○祥瑞","sortOrder":38},
  {"id":"s_work_tddn_7_39","chapterId":"ch_work_tddn_7","text":"世所謂祥瑞者，麟鳳、龟龍、騶虞、白雀、醴泉、甘露、朱草、靈芝、連理之木、合穎之禾皆是也。然夷考所出之時，多在危亂之世。今不暇援引古昔，姑以近代顯著者言之。","sortOrder":39},
  {"id":"s_work_tddn_7_40","chapterId":"ch_work_tddn_7","text":"王建父子之據蜀也，天复六年，巨省見青城山，鳳凰見萬歲縣，黃龍見嘉陽江，而甘露、白雀、白鹿、龟龍併見於諸州。武成元年，騶虞見武定，嘉禾生廣昌，麟見壁州，龍五十見於洵陽水中。永平二年，劍州木連理，文州麟見，黃龍見富義江。三年，麟見永泰，白龍見邛江，騶虞見壁山，有三鹿隨之。四年，麟見昌州。通正元年，黃龍見太昌池。瑞物之出，殆無虛歲，而太子元膺以叛死，大火焚其宮室，兵败於外，政亂於內，終之以身死衍立而國亡。其為瑞征乃如此耳。","sortOrder":40},
  {"id":"s_work_tddn_7_41","chapterId":"ch_work_tddn_7","text":"至如政和隆盛之际，地不愛寶，所在奏貢芝草者，動二三萬本。蘄、黃間，至有一鋪二十五里之間，遍野而出。密州山間，至弥滿四野，有一本數十葉，眾色鹹備者。太守李文仲，采及三十萬本，作一綱進，即進職，除本道運使。汝海諸郡縣，山石变為瑪瑙，動以千百。伊陽太和山崩，出水晶幾萬斤，皆以匣進京師。長沙、益陽山溪，流出生金數百斤，其間大者一塊至重四十九斤。其他草木鳥獸之珍不可一二數。一時君臣稱頌，祥瑞蓋無虛月。然越數歲，而遂罹狄難，邦國丧亂，父子遷播。所謂瑞應，又如此也。","sortOrder":41},
  {"id":"s_work_tddn_7_42","chapterId":"ch_work_tddn_7","text":"善乎先儒之論曰：\"未有丧仁而久者也，未有恃祥而寿者也。\"商之王以桑穀昌，以雉ず大。鄭以龍衰，魯以麟弱。白雉亡漢，黃犀死莽，惡在其為符也。世有喜言祥瑞之人，觀此亦可以少悟矣。","sortOrder":42},
  {"id":"s_work_tddn_7_43","chapterId":"ch_work_tddn_7","text":"○杭學遊士聚散","sortOrder":43},
  {"id":"s_work_tddn_7_44","chapterId":"ch_work_tddn_7","text":"杭學自昔多四方之人。淳祐辛亥，鄭丞相清之當國，朝議以遊士多無檢束，群居率以私喜怒軒輊人，甚者，以植党撓官府之政，扣閽攬黜陟之權，或受賂丑詆朝紳，或設局骗胁民庶，風俗浸坏。遂行下各州，自试於學，仍照舊比分數，以待類申，將以是歲七月引试為始。會教官林經德對士子上請語微失，於是大哄肆骂。時趙京尹與眾教官調停，一時但欲求靜，遂許以三百名內，一半取土著，一半取遊士，於是乃息。","sortOrder":44},
  {"id":"s_work_tddn_7_45","chapterId":"ch_work_tddn_7","text":"越數日，宰執奏事，上面諭曰：\"近行諸州各试之法，正欲散遊學之士。不知臨安府凭何指揮复放外方之人。\"趙尹聞之，恐甚，乃移牒，俾遊士限日出境，其計始窮。乃為檄文，相率而去，雲：\"天之將丧斯文，實系興衰之運。士亦何負於國，遽罹斥逐之辜，靜言思之，良可丑也。慨祖宗之立法，廣學校以储材，非惟衍丰芑以貽後人，蓋亦隆漢都而尊上國。肆惟皇上，克廣前猷。炳炳宸奎，厘為四學，戋戋束帛，例及諸生。蒙教育之如天，恨補報之無地，但思粉骨，何畏觸喉。直言安石之奸，共惜元城之去，實為公議，不利小人。始陰諷其三緘，終盡打於一網。不任其咎，移過於君，是誠何心，空人之國。鄭侨猶謂毀校不可，而李斯尚知逐客為非，今彼不顧行之，使我何顏居此？厄哉吾道，告爾同盟，毋見義以不為，宜行己而有恥。苟為溫飽，可勝周粟之羞，相與提携，莫蹈秦坑之禍。斯言既出，明日遂行。\"","sortOrder":45},
  {"id":"s_work_tddn_7_46","chapterId":"ch_work_tddn_7","text":"八月朔，乃相率而出，复作文告先聖曰：\"斯文將丧，呜呼天乎！吏議逐客，呜呼人乎！乘桴浮海，呜呼聖乎！遁世無悶，呜呼士乎！敢告。\"","sortOrder":46},
  {"id":"s_work_tddn_7_47","chapterId":"ch_work_tddn_7","text":"又作絕句詩雲：\"塞翁何必恨失馬，城火可怜殃及魚。一笑出門天萬里，擔頭猶有斥奸書。\"","sortOrder":47},
  {"id":"s_work_tddn_7_48","chapterId":"ch_work_tddn_7","text":"又五言雲：\"鄭五不去國，金陵深懼君。校存知必毀，書在已如焚。自是清流禍，非幹北党分。歸欤雖幸矣，恨未效朱雲。\"","sortOrder":48},
  {"id":"s_work_tddn_7_49","chapterId":"ch_work_tddn_7","text":"又古詩雲：\"上書如啜盧仝茶，直論國體寧無哗。依然茅苇縱橫斜，鐘山老柏林槎牙。呜呼時事如絲麻，食肉者口徒咿哇。鬼蜮空含射影沙，逐客令下堪吁嗟。識者將謂秦得邪，淳祐浸不知瑞嘉。邪人刚指正人邪，時有引喙鳴靈鴉。失腳奇禍遭羅，尼山草木枯無華。奄奄山鬼相揄揶，我今束書歸天涯，不惜一去惜國家。\"","sortOrder":49},
  {"id":"s_work_tddn_7_50","chapterId":"ch_work_tddn_7","text":"於是京尹待罪，兩教官各降一資，而陳顯伯、鄭雄飛方以公道自任，且欲收譽士林，乃相繼上疏，欲复其舊。而贾似道居淮阃，至以遊士欲渡淮以胁上必從。而理宗以周粟秦坑等語怒未解，深不然之。至开慶己未，吳丞相潛再登揆席，首欲收士心复舊法，會去不果。戴慶可以參枢輪筆，竟作指揮，許京庠有籍無分人引试一次，於是漸复雲集矣。","sortOrder":50},
  {"id":"s_work_tddn_8_1","chapterId":"ch_work_tddn_8","text":"●卷七","sortOrder":1},
  {"id":"s_work_tddn_8_2","chapterId":"ch_work_tddn_8","text":"○鴟夷子見黜","sortOrder":2},
  {"id":"s_work_tddn_8_3","chapterId":"ch_work_tddn_8","text":"吳江三高亭祠鴟夷子皮、張季鷹、陆魯望。而議者以為子皮為吳大仇，法不當祀。前辈有詩雲：\"可笑吳癡忘越憾，却夸范蠡作三高。\"又雲：\"千年家國無窮恨，只合江邊祀子胥。\"蓋深非之。","sortOrder":3},
  {"id":"s_work_tddn_8_4","chapterId":"ch_work_tddn_8","text":"後有戲作文彈之者雲：\"匿怨友其人，丘明所恥，非其鬼而祭，聖經是誅。今有竊高人之名，處眾惡之所，有識之士，莫不共憤，無知之魂，豈當久居。\"又雲：\"范蠡，越則謀臣，吳為敵國。以利誘太宰，而脱彼勾踐，鼓兵却公孫雄，而滅我夫差。既遂厥謀，反疑其主。鄙君如乌喙，累大夫种以伏誅，目已曰鴟夷，載西施子而潛遁。\"又雲：\"如蠡者，变姓名為陶朱，诡蹤跡於江海，語其高節則未可，謂之智術則有餘。假扁舟五湖之名，居笠泽三高之首。况當此無邊勝境之土，豈應著不共戴天之仇。\"雲雲。","sortOrder":4},
  {"id":"s_work_tddn_8_5","chapterId":"ch_work_tddn_8","text":"鴟夷之見黜於吳，宜也。而史越王判紹興日，作會稽先賢祠，亦复黜之不得在高士之列。其說雲：\"或謂鴟夷子皮之决，贺季真之高，而不得名高士，何也？呜呼！予於是豈無意哉！夫貴於士者，進退不失禮義，彼子皮去國之遺言，有人臣所不忍。而季真阿時所好，黃冠東歸，又使李林甫辈，祖餞賦詩，予見其辱，未見其榮也。使子皮居嚴子陵之上，季真置張子同之列，則有不可者。故具述之，觊來者知予之不敢苟，而高士之尤可貴也。\"呜呼！子皮既不容於吳，又不齒於越，千古之下，至無容身之地，公論至後世而定，亦可畏哉！是以古之君子，交絕不出惡聲，况君臣之际乎？司馬公修《通鑒》，而不取屈原《離骚》之事，正此意也。餘感其事，故書之，以為異世之戒雲。","sortOrder":5},
  {"id":"s_work_tddn_8_6","chapterId":"ch_work_tddn_8","text":"○王敦之诈","sortOrder":6},
  {"id":"s_work_tddn_8_7","chapterId":"ch_work_tddn_8","text":"王敦初尚武帝女武陽公主。如廁，見漆箱內盛幹棗，本以塞鼻。王謂廁上亦下果食，遂至盡食。既還，婢擎金藻盆盛水，琉璃碗盛澡豆，因倒著水中而飲之，謂是幹飲，群婢莫不掩口而笑之。","sortOrder":7},
  {"id":"s_work_tddn_8_8","chapterId":"ch_work_tddn_8","text":"他日，又至石季倫廁。十餘婢侍列，皆麗服藻飾。置甲煎粉、沉香汁之屬，無不畢備，又與新衣著令出。他客多羞不能如廁，敦獨脱故衣著新衣，神色傲然。群婢相謂曰：\"此客必能作賊。\"","sortOrder":8},
  {"id":"s_work_tddn_8_9","chapterId":"ch_work_tddn_8","text":"一王敦耳，何前蠢而後倨邪？幹棗、澡豆，亦何至誤食而不悟。至季倫之廁，則倨傲狠愎之状殆不可得而掩矣。則知敦此前之誤，直诈耳。王荆公誤食魚餌，亦近似之。人之不近人情者，鮮不為大奸大慝，吾於敦，重有感焉。","sortOrder":9},
  {"id":"s_work_tddn_8_10","chapterId":"ch_work_tddn_8","text":"○赠雲貢雲","sortOrder":10},
  {"id":"s_work_tddn_8_11","chapterId":"ch_work_tddn_8","text":"陶通明詩雲：\"山中何所有，嶺上多白雲，只可自怡悅，不堪持赠君。\"雲，固非可持赠之物也。","sortOrder":11},
  {"id":"s_work_tddn_8_12","chapterId":"ch_work_tddn_8","text":"坡翁一日還自山中，見雲氣如群馬奔突自山中來，遂以手掇开籠，收於其中。及歸，白雲盈籠，开籠放之，遂作《扌蹇雲篇》雲：\"道逢南山雲，吸如電過。竟誰使令之，袞袞從空下。\"又雲：\"或飛入吾車，Τ仄人肘胯，搏取置笥中，提携反茅舍。开緘仍放之，掣去仍变化。\"然則雲真可以持赠矣。","sortOrder":12},
  {"id":"s_work_tddn_8_13","chapterId":"ch_work_tddn_8","text":"宣和中，艮嶽初成，令近山多造油絹囊，以水濕之，晓張於絕危峦之間，既而雲盡入，遂括囊以獻，名曰\"貢雲\"。每車駕所臨，則盡縱之，須臾，氵翁然充塞，如在千巖萬壑間。然則不特可以持赠，又可以貢矣。併資一笑。","sortOrder":13},
  {"id":"s_work_tddn_8_14","chapterId":"ch_work_tddn_8","text":"○出師旗折","sortOrder":14},
  {"id":"s_work_tddn_8_15","chapterId":"ch_work_tddn_8","text":"贾師憲平章，德祐乙亥正月十六日，親總大軍，督師江上，祭於北關外，而大帥之旗，適為風所折，識者駭之，而一時遊幕之賓，反傅會為吉讖。夷考往昔，若春秋時，晉侯、楚人戰於城濮，晉中軍風於泽，亡大旆之左旃。晉安帝元興二年，桓玄篡位於姑熟，百僚陪列，儀衛整肅，而龍旃竿折。成都王穎以陆機督諸將讨長沙王，臨戎而牙旗折。趙王倫即帝位，祠太廟，適遇大風，飄折麾蓋。王澄為荆州刺史，率眾軍將赴國難，而飄風折其節柱。齊文宣至鄴受魏禪，李貽上省，旦發領軍府，大風暴起，坏所御車幔。哥舒翰守潼關，天子御勤政樓臨送，師始東，先驅牙旗觸門墮柱，旄竿折。鄭註赴鳳翔，出都門，旗竿折。宣和間，童貫出師，而牙旗竿折，時蔡攸為之副，自建少保節度使及宣撫副使二大旗於後，竟為執旗卒盜竄而去。端平入洛之師，全子才帥旗亦為風所折，無非亡身败軍之征也。","sortOrder":15},
  {"id":"s_work_tddn_8_16","chapterId":"ch_work_tddn_8","text":"按《真人水鏡經》雲：\"凡出軍立牙，必令堅完，若折，則將軍不利。\"蓋牙，即旗也。又《玉歷通政經》雲：\"軍行，牙竿旗幹折者，師不可出，出必败績。\"蓋旗者，一軍之號令也，安有旗折而為祥者乎？","sortOrder":16},
  {"id":"s_work_tddn_8_17","chapterId":"ch_work_tddn_8","text":"獨有武王伐紂，大風折蓋。及劉裕击盧循，將戰，而所執麾竿折，幡沈於水。眾鹹懼，裕笑曰：\"昔覆舟之役，亦如此，勝必矣。\"乃大破循軍。哥舒曜讨李希烈，帝祖於通化門，是日牙竿折。時以曜父翰昔出師有此而败，甚忧之，而曜竟收汝州，擒周晃。所謂吉者，止此三事，然亦偶耳。","sortOrder":17},
  {"id":"s_work_tddn_8_18","chapterId":"ch_work_tddn_8","text":"○朱氏陰德","sortOrder":18},
  {"id":"s_work_tddn_8_19","chapterId":"ch_work_tddn_8","text":"朱承逸居之城東門，為本州孔目官，樂善好施。嘗五鼓趨郡，過骆駝桥，聞桥下哭聲甚哀，使仆视之，有男子携妻及小兒在焉。扣所以，雲：\"負势家錢三百千，計息以數倍。督索無以偿，將併命於此。\"朱侧然，遣仆護其歸，且自往其家，正見债家悍仆，群坐於門。朱因以好言諭之曰：\"汝主以三百千故，將使四人死於水，於汝安乎？幸吾見之耳。汝亟歸告若主，彼今既無所偿，逼之何益！吾當為代還本錢，可亟以元券來。\"债家聞之，慚懼聽命，即如數取付之。其人感泣，願終身為奴婢，不聽，复以二百千資之而去。","sortOrder":19},
  {"id":"s_work_tddn_8_20","chapterId":"ch_work_tddn_8","text":"是歲，生孫名服。熙寧中，金榜第二人，仕至中書舍人。次孫肱，亦登第，著名節，即著《南陽活人書》者。服子，即著《萍洲可談》者，遂為吾乡名族焉。","sortOrder":20},
  {"id":"s_work_tddn_8_21","chapterId":"ch_work_tddn_8","text":"天之報善，昭昭也如此。","sortOrder":21},
  {"id":"s_work_tddn_8_22","chapterId":"ch_work_tddn_8","text":"○畢將軍馬","sortOrder":22},
  {"id":"s_work_tddn_8_23","chapterId":"ch_work_tddn_8","text":"畢再遇，兖州將家也。开禧用兵，諸將多败事，獨再遇累有功。金人認其旗幟即避之。屢遷至镇江都統製、扬州承宣使、驍衛上將軍。後以老病致仕，始居於。","sortOrder":23},
  {"id":"s_work_tddn_8_24","chapterId":"ch_work_tddn_8","text":"有戰馬，號黑大虫，駿驵異常，獨主翁能御之。再遇既死，其家以鐵ㄌ羁之圉中。適遇嶽祠迎神，聞金鼓聲，意謂赴敵，於是長嘶奋迅，斷組而出。其家慮傷人，命健卒十餘，挽之而歸。因好言戒之雲：\"將軍已死，汝莫生事累我家。\"馬耸耳以聽，汪然出涕，喑哑長鳴數聲而毙。呜呼！人之受恩而忘其主者，曾異類之不若，能不愧乎？","sortOrder":24},
  {"id":"s_work_tddn_8_25","chapterId":"ch_work_tddn_8","text":"○洪君畴","sortOrder":25},
  {"id":"s_work_tddn_8_26","chapterId":"ch_work_tddn_8","text":"近世敢言之士，雖間有之，然能終始一節，明目張胆，盲人之所難者，絕無而仅有，曰溫陵洪公天錫君畴一人而已。方寶祐間，宦寺肆橫，簸弄天綱，外阃朝紳，多出門下，廟堂不敢言，台諫長其惡，或餌其利，或畏其威，一時聲焰，真足動搖山嶽，回天而駐日也。","sortOrder":26},
  {"id":"s_work_tddn_8_27","chapterId":"ch_work_tddn_8","text":"乙卯元正，以公為御史，公來自孤遠，時莫知為何如人。首疏以正心格君為說，且曰：\"臣職在憲府，不惟不能奉承大臣風旨，亦不敢奉承陛下風旨。\"固已耸動聽聞矣。次月，囊封曰：\"古今為天下患者三：宦官也，外戚也，小人也。謹按入內內侍省東頭供奉官幹辦內東門司董宋臣，宦寺之貪黠者也。併緣造寺，豪奪民田，密召倡優，入亵清禁（先是，正月內呼營妓數辈入內祗應），搂攬番商，大开賄賂。不斥宋臣，必為聖德之累。將作監謝堂，外戚之貪黠者也。狠愎之性，善於凌物，攫拿之状，旁若無人。不曰'以備中殿宣索'，則曰'當取教旨豁除'。椒德令芳，天下備頌，不去一堂，必為宮闈之累。集英殿修撰、知慶元府厲文翁，小人之無忌憚者也。神皋流毒，屢玷抨彈，藉衣錦威，行攫金術。今又移其剝越者剝鄞矣！然民敢怨而不敢言者，以其依凭邸第耳。不去文翁，必為王邸之累。臣恐社稷之忧，不止累陛下，累宮闈，累王邸而已。乞將宋臣逐出，堂姑予祠，文翁罢黜，臣雖九陨不悔。\"","sortOrder":27},
  {"id":"s_work_tddn_8_28","chapterId":"ch_work_tddn_8","text":"疏上兩日不報，君畴径出江幹待罪。於是中書牟子才存叟、右史李昂英俊明，交章留之，乞行其言。乃令堂自陳乞祠，除職予郡，宋臣自乞解罢，令首尾了日解職，文翁別與州郡差遣。仍命台臣吳燧勉回供職。","sortOrder":28},
  {"id":"s_work_tddn_8_29","chapterId":"ch_work_tddn_8","text":"會立夏日，天雨尘土，奏乞屏絕私邪，休息土木，以弭天灾。又案少司監餘作賓、後戚謝奕懋。至五月，复疏都知盧允升、門司董宋臣及內司諸吏，怙势作威，奪民田，伐墓木等事。盡言不讳，直捣其奸。疏留中不下，止令尚書省契勘內司爭田伐木等事，及罢內司諸吏職事而已。公論為之抑鬱。","sortOrder":29},
  {"id":"s_work_tddn_8_30","chapterId":"ch_work_tddn_8","text":"大宗丞趙崇れ上時相謝方叔惠國書，略雲：\"竊惟今日閹寺驕恣特甚。宰執不聞正救，台諫不敢誰何。一新入孤立之察官，乃銳意出身攻之，此豈易得哉！侧耳數日，寂無所聞。不责備於他人，而责備於光范。不然，仓卒出御筆某人除少卿，亦必無可遏之理也，大丞相不可謂非我责也。丞相得君最深，名位已極，傥言之勝，宗社賴之，言之不勝，則去，去則諸君子必不容不爭，是勝亦勝，負亦勝，况未必去邪？\"謝君得書有赧色。翌日，果有御筆洪天錫除大理少卿，而公去國矣。","sortOrder":30},
  {"id":"s_work_tddn_8_31","chapterId":"ch_work_tddn_8","text":"太學生沈元堅上書，數二之罪，乞留君畴。且曰：\"天錫左遷，豈非罰其不當言宦官之過耶？李衢、朱應元之分察，豈非諭其不复言宦寺之意耶？王、程元鳳同日超遷，胡大昌、丁大全之併遷台長，豈非賞其不敢言宦官之功耶？陛下喜群臣之默默，憤天錫之哓哓，左遷以逐之，於天錫何損？緘默受賞者，獨無愧乎？\"","sortOrder":31},
  {"id":"s_work_tddn_8_32","chapterId":"ch_work_tddn_8","text":"既而三學亦皆有書。常丞趙崇絜敏可書，略雲：\"譬如一家之中，強奴悍仆，作奸犯罪，為人子者，泣涕而告，其父母反逐其子而留其仆。今台臣爭之不勝，則諸閹所畏者誰欤！\"","sortOrder":32},
  {"id":"s_work_tddn_8_33","chapterId":"ch_work_tddn_8","text":"左史李俊明再有封事，言：\"北司洋洋得志，蔑视南衙，將至於不可控製之地矣。\"姚宗卿希得暫兼夕郎，遂繳吳燧儀曹之除，謂近者天錫拜疏留中，燧謂天錫曰：\"今日之事，留則俱留，去則俱去。\"既聞有疏，遂变前言曰：\"吾不挈家，不丧女，不憚暑，則可俱去，今當奈何？負天錫，所以負陛下也。\"謝集賢一疏自解雲：\"臣自班行，叨尘相位，一命已上，皆出親擢。賦性僻介，素不與內侍往還，應幹文字，悉由通進司投進，自知絜其身，而袖手旁觀之人，往往察臣之所避而趨之。比者天錫又論二。恭聞聖訓，以為爭田伐木皆王衤康舊事。臣費盡心力，上則忠告陛下，量作處分，下則弥縫事體，安恤人言。不謂下石之人，撰造言語，鼓弄宦寺，曰：'天錫攻汝，相君之意也，相君許其弟除朝士而嗾之也。'既誣臣以教天錫攻內侍之事，又誣臣以啟陛下遷天錫之說，必欲丑詆臣於不可辨白之地。但臣分量已盈，歸老山林，正其時矣。從此為宰相者，必將共宦寺結為一片，天下皆在籠絡中矣。惟望陛下早正右席之拜，使臣亟釋重負，退延殘生，實出保全之賜。\"御筆慰之曰：\"但安素志，奚足深辨。\"越數日，除天錫太常少卿，而君畴已在汶上矣。","sortOrder":33},
  {"id":"s_work_tddn_8_34","chapterId":"ch_work_tddn_8","text":"朱應元既為御史，月課乃首劾李俊明，公論大不平。同舍生作書责之，略曰：\"溫陵洪公出台，以執事繼之者，正謂其平時負肮臟之譽。法筵之初疏，莫不延頸以聽，乃及文溪之左螭，時煥之仓節，豈以其近言二頗忤上意，而時煥與洪有瓜葛，亦二所惡者邪？信然，則執事之志荒矣。二之橫，三尺童子，恨不嚙之，洪公因眾怨，出死力以决之。貂逐台諫，豈人主之本心哉！執事昧於所擇，不知所得幾何，所失如是之大也。\"時方逢臣君錫在馆閣，亦上廟堂書，勸以去就力爭，而謝相不能用。","sortOrder":34},
  {"id":"s_work_tddn_8_35","chapterId":"ch_work_tddn_8","text":"公論既不能勝，二孺乃簧谮於上，謂：\"內司爭田伐木詞訟，皆台吏受賄以強察官之判，所以上罔聖聽，况台吏之家資極富，若使簿錄其家，盡可上裨國計。\"於是竟降宣諭指揮，令諫官丁大全追上御史台，點檢楊升、金永隆、楊叔茂，牒送臨安府根勘，籍没家财，各行黥配，以快其憤焉。初意欲令台胥妄供以污君畴，賴上察其奸而止。大全竟以治吏之功，躐除副端。","sortOrder":35},
  {"id":"s_work_tddn_8_36","chapterId":"ch_work_tddn_8","text":"未幾，謝相罢，而二孺猶未大快其意。复厚賂太學率履斋上舍生林自養，裁書投匦，以攻謝相為名，力詆君畴雲：\"竊見洪天錫之分察，出自陛下親擢。不能為觸邪豸為指佞草，专以能攻上身為急務，以剪除上左右以立名，以奉承風旨為大耐官職。棘卿左遷，所以正舍豺問狸之罪。內侍縱曰有過，使其得賢宰相以製之，又何患焉？天錫之去，乃翦方叔之羽翼，豈怒其扫除二孺哉人但見天錫言事而遷他官，則曰：'此劾內侍之過也。'吳燧以改除致繳，則曰：'此天錫之荐主也。'李昂英以月評被論，亦曰：'此天錫之救兵也。'甚而台省之胥，贓盈惡貫，以置典憲，亦曰：'為內侍泄冤也。'貪缪之相，誤國殄民，逐之已晚，亦曰：'為內侍翻本也。'一犬吠形，百犬吠聲。向者李昂英直前奏札，嘗謂天錫為方叔私人矣。氵存攻內侍，實出方叔指嗾之，而欲撓亂聖心耳。欲乞將方叔亟正典刑，使天下明知宰相台諫之去，出自獨斷，於內侍初無預焉。\"於是學舍鳴鼓攻之，且上書以聲自養之罪。复申前庑，備申公堂，乞行重罰。遂從第一等規屏斥，盡除學籍，毀抹綾紙備榜監學晓諭，而朝旨亦有聽讀指揮。雖紛紛若此，曾不傷二孺之毫毛。至庚申歲，吳丞相柄國，始以外柯斥焉。景定辛酉，起君畴為廣東計使。甲子八月，以大蓬召，不就。十一月，度宗即位，首除為侍御史兼侍讀。明年六月，上封事，力陳公田、關會之弊。七月，改除工部侍郎，兼直學士院，兼侍讀，公力辭。旋畀職名出帥閩焉。公在閩阃日，嘗書桃符雲：\"平生要識琼崖面，到此當堅鐵石心。\"蓋其刚劲之氣，未嘗一日少沮也。","sortOrder":36},
  {"id":"s_work_tddn_8_37","chapterId":"ch_work_tddn_8","text":"○謝惠國坐亡","sortOrder":37},
  {"id":"s_work_tddn_8_38","chapterId":"ch_work_tddn_8","text":"謝方叔惠國，自寶祐免相歸江西寓第，從容午桥泉石凡一紀餘。鹹淳戊辰，朝會慶寿，為子侄親友所誤，萃先帝宸翰為巨帙，曰《寶奎錄》，侑以自製丹砂、金器、古琴之類以進。當國者以為有意媒進，嗾言官後省交攻之，削其封爵，奪其恩數，且劾其侄常簿章，婿江州ヘ李鉦、客匠簿呂圻，至欲謫之遠外，禍且不测。荆阃呂武忠文德，平時事公謹，書緘往來，必稱恩府，而自書為門下使臣。至是一力回護，幸而免焉。壬申正月，公燕居無他，忽報双鶴相繼而毙，公喟然叹曰：\"鶴既仙化，餘亦從此逝矣。\"於是區處家事，凡他人負欠文券，一切焚之。沐浴朝衣，焚香望闕遙拜，次詣家廟祝白，招親友從容叙別，具有條理。遂大書偈曰：\"罢相歸來十七年，燒香禮佛學神仙。今朝双鶴催歸去，一念無慚對越天。\"瞑目靜坐，須臾而逝。遺表來上，特旨盡复元官，恩數赠恤加厚焉。生死之际，亦近世諸公之所無也。","sortOrder":38},
  {"id":"s_work_tddn_8_39","chapterId":"ch_work_tddn_8","text":"○洪端明入冥","sortOrder":39},
  {"id":"s_work_tddn_8_40","chapterId":"ch_work_tddn_8","text":"洪焘仲魯，忠文公咨夔次子也。嘉熙丁酉，居忧天目山，素有元章愛石之癖，而山中所產亦秀润，不减太湖、洞庭。村仆骆老者，专任搜抉之役。會族叔，璞假畚锸鋤斧，將為筑室用，骆掌其事，擇元刂钝數事付之。璞怒其輕己，率其子共殴之，至毙，是歲中元日也。洪公力與維持，泯其事。璞素豪獷，持一邑短長。邑令王衍，婺安人，惡其所為，廉得之，遂收璞父子及血屬於獄。洪公亦以曾任調停，例追逮，良窘。時，王實斋遂守吳，契家亟往求援，王為宛轉趙憲崇揮，改送餘杭縣獄，具以主仆名分，因斗而死，璞止從夏楚，梗仅編置贖銅而已。","sortOrder":40},
  {"id":"s_work_tddn_8_41","chapterId":"ch_work_tddn_8","text":"明年戊戌中元，洪公方走廁，忽睹骆老在廁雲：\"近山雨後出數石，秀可愛，主人幸一觀之。\"洪仓卒忘其死，往從其行，才跬步間，覺此身已在簷楹間。稍至一土神廟，便有四力士自廟中出，挟之空行，其去甚駛。天昏昏如昧爽，足下風涛澎湃聲可恐，意非佳境。反顧骆曰：\"既若此，何不告我？\"骆曰：\"勿恐，略至便可還也。\"稍前，一河甚闊，方念無津梁可度，則身已達彼岸。又見數百人掩面趣右而去。自此冥行如深夜。忽曛黑中，一山橫前，有竅如月，數百人皆自此入，心方疑異，而身亦度竅矣。到此，足方履地。既前，复有一河，污濁特甚，僧尼道俗汨没其間。至此，方悟為入冥，心甚悲恐。","sortOrder":41},
  {"id":"s_work_tddn_8_42","chapterId":"ch_work_tddn_8","text":"稍前，頗有人居，萧疏殊甚。又前，有宮室軒敞巍耸，四垂帘幕，庭下列緋绿人獄卒甚眾，俨如人間大官府，初無所謂阿旁牛頭也。右庑絕昏黑，隱隱見荷枷棰楚者甚苦。其外小庭中，一黑蟒大與庭等，仰视一燈，悲鳴無度。洪所立左庑，則微明若欲曙時。微聞其傍喃喃若誦經聲。洪平日不喜此，方窘懼中，亦慢隨其聲誦之。庭中人忽起立怒视，而殿上帘盡卷。有绿衣者出，坐東向，緋衣者坐西向，最後金紫人居中。庭下绿衣吏抱文書而上，高唱雲：\"洪某枉法行财，罪當死。\"洪懼甚，不覺身已立庭下。漫答雲：\"為叔解紛，初非枉法。\"金紫人怒曰：\"此人間哗詞，安得至此？\"洪曰：\"死不辭，然有三說。璞，叔也；骆，仆也。不忍以仆故置叔於辟，一也；骆無子，妻貧老無以養，使璞資之終其身，二也；且骆妻自謂一經檢验，永失人身，意自不欲，非強之和，三也。\"金紫人始首肯雲：\"為叔解紛，初非枉法，此說有理，可供状來。\"便有紙筆在前，直書其說以呈。金紫人怒方霁曰：\"可與骆氏立後。\"且命绿衣导之以回。轉盼間，骆之父母皆在焉。途中，因扣绿衣所見大蟒為何物。厲聲答雲：\"此开邊喜殺之人也。\"稍前，見數十百人持騾馬皮而來，又扣之，曰：\"此受生回也。\"又見獄吏持刀杖，驅百餘人自西而來。其中有洪氏族長為僧者曰煜黎，亦在焉。方疑之，煜忽呼曰：\"三十哥（系仲魯第行）安得在此！\"為所驅卒击其首粉碎，回视之，仍复完矣。因扣绿衣雲：\"人間何事最善？\"绿衣舉手加額曰：\"善哉問！忠孝為先，繼絕次之，戒殺又次之。\"又問：\"何罪最重？\"曰：\"开邊好殺罪重，豪奪次之。\"（或謂其說尚多）因問：\"金紫者何人？\"拱手對曰：\"商公飛卿（字仲，乾淳間從官）。\"复扣平生食祿，遂於袖中出大帙示之，己姓名下，其字如蚁，不能盡閱。後註雲：\"合參知政事。以某年、月、日奸室女某人，某日為某事，降秘閣修撰轉運副使。\"洪悚然淚下曰：\"奈何？\"绿衣曰：\"但力行好事。\"且言：\"某亦人間人，任知池州司戶，溺死。陰間錄其正直，得職於此。\"稍前，至大溪，有桥如魚網，心疑其異，而身已度矣。又前，溪亦大，绿衣推墮之，恍然而寤，則死已三日矣。妻子環立於侧，特以心微暖，口尚動，未就斂耳。","sortOrder":42},
  {"id":"s_work_tddn_8_43","chapterId":"ch_work_tddn_8","text":"後一歲，璞亦入冥，笕身墮鐵網中。見鄰院僧行昭立庭下，主者詰责曰：\"汝為僧，乃专以殺生為事，何邪？\"昭曰：\"殺生乃屠者黃四，某不過與之庖饌耳。\"亟問黃四，無異辭，乃訊足二十而去。方窘懼間，忽傳呼都天判官决獄，视之，則忠文公也。璞號泣求救，公曰：\"汝殺人，何所逃罪，然未應爾也。\"恍然身已出網外而蘇。","sortOrder":43},
  {"id":"s_work_tddn_8_44","chapterId":"ch_work_tddn_8","text":"後行昭以營桥立積木上败足，呻S吟Y痛楚者三歲而殂，璞亦未幾死。後洪公於庚申歲首，以秘撰兩浙漕召。憶向所見，心甚恐，後亦無他，官至文昌端明殿學士。晚雖齟齬，然竟享上寿而終，豈非力行好事所致乎？","sortOrder":44},
  {"id":"s_work_tddn_8_45","chapterId":"ch_work_tddn_8","text":"此事洪公常入梓以示人。餘向於先子侍旁，親聞伯魯尚書言甚詳。後會其猶子憲使起畏義立，复詢顛末書之。","sortOrder":45},
  {"id":"s_work_tddn_8_46","chapterId":"ch_work_tddn_8","text":"○野婆","sortOrder":46},
  {"id":"s_work_tddn_8_47","chapterId":"ch_work_tddn_8","text":"邕宜以西，南丹諸蠻皆居窮崖絕穀間。有獸名野婆，黃發椎髻，跣足裸形，俨然一媪也。上下山穀如飛猱，自腰已下，有皮累垂蓋膝若犢鼻，力敵數壮夫，喜盜人子女。然性多疑畏骂，已盜，必复至失子家窥伺之，其家知為所竊，則積鄰里大骂不絕口，往往不勝骂者之眾，則挟以還之。其群皆雌，無匹偶，每遇男子，必負去求合。","sortOrder":47},
  {"id":"s_work_tddn_8_48","chapterId":"ch_work_tddn_8","text":"嘗為健夫設計挤之大壑中，展轉哮吼，胫絕不可起。徭人集眾刺殺之，至死，以手護腰間不置。剖之，得印方寸，瑩若蒼玉，字類符篆不可識，非镌非鏤，蓋自然之文，然亦竟莫知其所寶為何用也。周子功，景定間使大理，取道於此，親見其所謂印者。","sortOrder":48},
  {"id":"s_work_tddn_8_49","chapterId":"ch_work_tddn_8","text":"此事前所未聞，是知窮荒絕徼，天奇地怪，亦何所不有？未可以見聞所未及，遂以為誕也。《後漢郡國志》引《博物記》曰：\"日南出野女，群行不見夫，其状且白，裸袒無衣襦。\"得非此乎？《博物記》當是秦漢間古書，張茂先蓋取其名而為志也。","sortOrder":49},
  {"id":"s_work_tddn_8_50","chapterId":"ch_work_tddn_8","text":"○王宣子讨賊","sortOrder":50},
  {"id":"s_work_tddn_8_51","chapterId":"ch_work_tddn_8","text":"王佐宣子帥長沙日，茶賊陳丰嘯聚數千人，出没旁郡，朝廷命宣子讨之。時冯太尉湛謫居在焉，宣子乃權宜用之。諜知贓巢所在，乘日晡放飯少休時，遣亡命卒三十人，持短兵以前，湛自率百人繼其後，径入山寨。丰方抱孫獨坐，其徒皆無在者。卒睹官軍，错愕不知所為，亟鳴金嘯集，已無及矣，於是成擒，餘党亦多就捕。","sortOrder":51},
  {"id":"s_work_tddn_8_52","chapterId":"ch_work_tddn_8","text":"宣子乃以湛功聞於朝，於是湛以勞复元官，宣子增秩。辛幼安以詞贺之，有雲：\"三萬卷，龍頭客，浑未得文章力。把詩書馬上，笑驅鋒鏑。金印明年如斗大，貂蝉元自兜鍪出。\"宣子得之，疑為諷己，意頗衔之。殊不知陳後山亦嘗用此語送蘇尚書知定州雲：\"枉讀平生三萬卷，貂蝉當复坐兜鍪。\"幼安正用此。然宣子尹京之時，嘗有書與執政雲：\"佐本書生，歷官處自有本末，未嘗得罪於清議。今乃蒙置諸士大夫所不可為之地，而與數君子接踵而進，除目一傳，天下士人视佐為何等類？終身之累，孰大於此！\"是亦宣子之本心耳。","sortOrder":52},
  {"id":"s_work_tddn_9_1","chapterId":"ch_work_tddn_9","text":"●卷八","sortOrder":1},
  {"id":"s_work_tddn_9_2","chapterId":"ch_work_tddn_9","text":"○張魏公二事","sortOrder":2},
  {"id":"s_work_tddn_9_3","chapterId":"ch_work_tddn_9","text":"高宗视師金陵，張魏公為守，楊和王領殿前司。有卒夜出，與兵馬都監喧競，卒訴之，公判雲：\"都監夜巡，職也，禁兵酉點後不許出營，法也，牒宿衛司照條行。\"楊不得已斬之。","sortOrder":3},
  {"id":"s_work_tddn_9_4","chapterId":"ch_work_tddn_9","text":"又嘗詣學，士有投牒者，视之，則爭博進也。即判雲：\"士子爭财於學校，教化不明，太守罪也。當職先罰俸半月，牒學照規行。\"教官大窘，引去。","sortOrder":4},
  {"id":"s_work_tddn_9_5","chapterId":"ch_work_tddn_9","text":"○羅春伯政事","sortOrder":5},
  {"id":"s_work_tddn_9_6","chapterId":"ch_work_tddn_9","text":"羅點春伯為浙西仓攝平江府。忽有故主訟其逐仆欠錢者，究問雖得實，而仆黠甚，反欲污其主，乃自陳嘗與主饋之姬通，既而物色，則無有也。於是遂令仆自供奸状，甚詳，因判雲：\"仆既欠主人之錢，又且污染其婢。事之有無雖未可知，然其自供罪状已明，合從奸罪定斷，徒配施行。所有女使，候主人有詞日根究。\"聞者無不快之。","sortOrder":6},
  {"id":"s_work_tddn_9_7","chapterId":"ch_work_tddn_9","text":"○〈廣甫〉峭","sortOrder":7},
  {"id":"s_work_tddn_9_8","chapterId":"ch_work_tddn_9","text":"魏收有\"逋峭難為\"之語，人多不知其義。熙寧間，蘇子容丞相奉使契丹，道北京。時文潞公為留守，燕款從容，因扣逋峭之義。蘇公曰：\"向聞之宋元憲雲：'事見《木經》。'蓋梁上小柱名，取其有折势之義耳。\"乃就用此事作詩為謝雲：\"自知伯起難逋峭，不及淳於善滑稽。\"","sortOrder":8},
  {"id":"s_work_tddn_9_9","chapterId":"ch_work_tddn_9","text":"而齊、魏間以人有儀矩可喜者，則謂之庸峭。《集韻》曰：\"〈廣甫〉〈廣餘〉，屋不平也。〈廣甫〉，奔模反；〈廣餘〉，同都反。今造屈势有曲折者，謂之〈廣甫〉峭雲。\"二字與前義亦近似。今京師指人之有風指者，亦謂之波峭。雖轉〈廣甫〉為波，豈亦此義耶？","sortOrder":9},
  {"id":"s_work_tddn_9_10","chapterId":"ch_work_tddn_9","text":"○許公言","sortOrder":10},
  {"id":"s_work_tddn_9_11","chapterId":"ch_work_tddn_9","text":"安定郡王子涛，字仲山。在京師時，其兄子冲喜延道流方士。有許公言者，能以藥為黃金。其人皎然玉树，有小爐，高不盈尺。以少藥物就掌中調之，納火中，須臾精金也。謂仲山曰：\"如何？\"仲山曰：\"畢竟只是假。\"許愕然，拊其背曰：\"善自愛。\"","sortOrder":11},
  {"id":"s_work_tddn_9_12","chapterId":"ch_work_tddn_9","text":"越數日，告子冲別，挽留不可。將出門，邀仲山耳語，首言：\"君兄且死矣。君手有直紋，未可量，但早年亦〈喜〉困，宜順受之，寿可至六十九。人寿修短，视其操行。上帝所甚惡者貪，所甚靳者寿，人能不犯其所甚惡，未有不得其所靳者。君能不忘吾言，可至七十九，持之益謹，更可至八十九，外此，非吾所知也。\"仲山問其行何之，曰：\"中原將亂，吾入蜀耳。\"","sortOrder":12},
  {"id":"s_work_tddn_9_13","chapterId":"ch_work_tddn_9","text":"未數月，子冲一夕無疾而亡。逾年，金入寇，仲山負其母以南，晝伏宵行，數阽於危，仅行脱。平生守許之戒不渝。晚而袭爵，年八十七乃終。克家端明，乃其曾孫也。","sortOrder":13},
  {"id":"s_work_tddn_9_14","chapterId":"ch_work_tddn_9","text":"○士子訴试","sortOrder":14},
  {"id":"s_work_tddn_9_15","chapterId":"ch_work_tddn_9","text":"王希呂仲衡知紹興郡，舉進士。有為二试卷，異其名，皆中選。黜者不厭，哗然訴之。王呼其首問曰：\"爾生幾何年？凡幾试矣？\"眾謂怜其潦倒，則皆以老於場屋對。王曰：\"曾中選否？\"曰：\"正為累试皆不利也。\"王忽作色曰：爾曹累试不一得，彼一试而兩得，尚敢訴耶！\"叱而出之。","sortOrder":15},
  {"id":"s_work_tddn_9_16","chapterId":"ch_work_tddn_9","text":"○趙德莊誨後進","sortOrder":16},
  {"id":"s_work_tddn_9_17","chapterId":"ch_work_tddn_9","text":"趙忠定汝愚初登第，謁趙彦端德莊。德莊故餘幹令，因家焉。故與忠定父兄遊，語之曰：\"謹毋以一魁置胸中。\"又曰：\"士大夫多為富貴誘坏。\"又曰：\"今日於上前得一二語奖諭，明日於宰相處得一二語褒拂，往往丧其所守者多矣。\"忠定拱手曰：\"謹受教。\"前辈於後進如此。","sortOrder":17},
  {"id":"s_work_tddn_9_18","chapterId":"ch_work_tddn_9","text":"○朱墨史","sortOrder":18},
  {"id":"s_work_tddn_9_19","chapterId":"ch_work_tddn_9","text":"紹聖中，蔡卞重修《神宗實錄》，用朱黃删改。每一卷成，辄納之禁中。蓋將盡泯其跡，而使新錄獨傳。所謂朱墨本者，世不可得而复見矣。","sortOrder":19},
  {"id":"s_work_tddn_9_20","chapterId":"ch_work_tddn_9","text":"及梁師成用事，自謂蘇氏遺體，頗招延元祐諸家子孫若范溫、秦湛之徒。師成在禁中見其書，為諸人道之。諸人幸其書之出，因曰：\"此亦不可不錄也。\"師成如其言。及败没入，有得其書，携以渡江，遂傳於世。","sortOrder":20},
  {"id":"s_work_tddn_9_21","chapterId":"ch_work_tddn_9","text":"○蘇大璋","sortOrder":21},
  {"id":"s_work_tddn_9_22","chapterId":"ch_work_tddn_9","text":"三山蘇大璋之，治《易》有聲。戊午乡舉，夢為第十一人，數為人言之，以為必如夢告。既试，將揭榜，同經人訴於郡，謂其自許之確如此，必將與试官有成約，萬一果然，乞究治之。及申號至第十一名，果《易》也。帥携此状入院，遍示考官，謂：\"設如此言，諸公將何以自解？不若以待補首卷易之。\"眾皆以為然。既拆號，則自待補為正解者，大璋也；由正解而易為待補者，乃投牒之人也。次年，蘇遂冠南宮。此與王俊民事相類。","sortOrder":22},
  {"id":"s_work_tddn_9_23","chapterId":"ch_work_tddn_9","text":"○徐漢玉","sortOrder":23},
  {"id":"s_work_tddn_9_24","chapterId":"ch_work_tddn_9","text":"永嘉徐宣字漢玉。治周成子獄，無所枉，自知必得罪，束擔俟命。忽夢神人驅之使去，答曰：\"吾分宜去，不待驅逐，但未知當往何所？\"神曰：\"汝得嚴州。\"覺與家人言：\"夢真妄耳。吾得罪必南遷，安得在畿乎？\"已而謫道州，又徙象州。行至來賓縣，得《圖經》视之，唐嚴州也。叹曰：\"吾其不返乎？\"果終焉。","sortOrder":24},
  {"id":"s_work_tddn_9_25","chapterId":"ch_work_tddn_9","text":"○韓忄造造奇卜","sortOrder":25},
  {"id":"s_work_tddn_9_26","chapterId":"ch_work_tddn_9","text":"紹興末，有韓忄造者，賣卜於臨安之三桥，多奇中。庚辰春，曾侍郎仲躬、呂太史伯恭至其肆，則先一人在焉。問其姓，宗子也。次第談命，首言趙可至郡守，却多貴子，不達者亦卿郎。次及曾，則曰：\"命甚佳，有家世，有文學，有政事，亦有官職。只欠一事，終身無科第。\"次至呂，問：\"何幹至此？\"呂曰：\"赴试。\"曰：\"去年不合發解，今安得省试？\"曰：\"赴詞科。\"曰：\"却是詞科人，但不在今年詞科，別有人矣。後三年，兩试皆得之，且不失甲科。\"复扣其何所至。沉吟久之曰：\"名滿天下，可惜無福。\"已而其言皆验。趙名善待，仕至嶽州守。其子汝述為尚書，適、逵、遇皆卿監郎。曾仲躬名逮吉，父、文清公之子，能世其家。舉進士不第，至從官以没。呂太史，隆興癸未谅陰榜南宮第七人，又中宏詞科，為儒宗。不幸得末疾，甫四十六歲而終。術之神验如此。","sortOrder":26},
  {"id":"s_work_tddn_9_27","chapterId":"ch_work_tddn_9","text":"○以賦罢相","sortOrder":27},
  {"id":"s_work_tddn_9_28","chapterId":"ch_work_tddn_9","text":"阜陵在位，上庠月書前列试卷，時經御覽。辛丑大旱，七月私试；《闵雨有志乎民賦》。魁劉大譽，第六韻雲：\"雨固自於天，感召豈無所主。傥燮調得人，則斯可有節，而聚斂無度，則亦能不雨。此或未明闵之何補？不見商霖未作，相傳說於高宗；漢旱欲蘇，烹弘羊於孝武。\"未幾，趙溫叔罢相。","sortOrder":28},
  {"id":"s_work_tddn_9_29","chapterId":"ch_work_tddn_9","text":"○小兒瘡痘","sortOrder":29},
  {"id":"s_work_tddn_9_30","chapterId":"ch_work_tddn_9","text":"小兒瘡痘，固是危事，然要不可扰之。嘗見趙賓曰：\"或多以酒面等物發之，非也，或以消毒飲升麻湯等解之，亦非也。大要在固臟氣之外，任其自然耳。惟本事方、捻金散最佳。\"又陳劍南刚翁雲：\"痘瘡切不可多服升麻湯，只須以四君子湯加黃芪一味為穩耳。\"二說皆有理，然或有变證，則不得不資於藥。癸酉歲，兒女皆發痘瘡。同僚括蒼陳坡，老儒也。因言：\"向分教三山日，其孫方三歲。發熱七日，瘡出而倒靨色黑，唇口冰冷，危證也。遍试諸藥皆不效，因乞靈於城隍神，以卜生死。道經一士門，士怪其侵晨仓皇，因遮扣之，遂告以故。士曰：'恰有藥可起此疾，奇甚。\"因為經營少許，俾服之，移時，即紅润如常。後求其方，甚秘惜之。及代歸，方以見赆。其法用狗蠅（狗身上能飛者）七枚擂細，和醅酒少許調服。蠅夏月極多，易得，冬月，則藏於狗耳中，不可不知也。\"","sortOrder":30},
  {"id":"s_work_tddn_9_31","chapterId":"ch_work_tddn_9","text":"既而次女瘡後，餘毒上攻，遂成內障，目不辨人，極可忧。遍试諸藥，半月不验。後得老医一方，用蛇蜕一具，净洗，焙令燥。又天花粉（即瓜萎根）等分細末之，以羊子肝破开，入藥在內，麻皮縛定，用米泔水熟煮，切食之，凡旬餘而愈。其後程甥亦用此取效，真奇剂也。","sortOrder":31},
  {"id":"s_work_tddn_9_32","chapterId":"ch_work_tddn_9","text":"○曹西士上竿詩","sortOrder":32},
  {"id":"s_work_tddn_9_33","chapterId":"ch_work_tddn_9","text":"趙南仲以誅李全之功見忌於趙清臣，史揆每左右之，遂留於朝。其後恢复事起，遂分委以邊圉。赴镇之日，朝紳置酒以餞。適有呈緣竿伎者，曹西士賦詩雲：\"又被鑼聲送上竿，这番難似舊時難。勸君著腳須教穩，多少傍人冷眼看。\"未幾，師果不競。","sortOrder":33},
  {"id":"s_work_tddn_9_34","chapterId":"ch_work_tddn_9","text":"○昌化章氏","sortOrder":34},
  {"id":"s_work_tddn_9_35","chapterId":"ch_work_tddn_9","text":"昌化章氏，崑弟二人，皆未有子。其兄先抱育族人一子，未幾，其妻得子。其弟言：\"兄既有子，盍以所抱子與我？\"兄告其妻，妻猶在蓐曰：\"不然。未有子而抱之，甫得子而弃之，人其謂我何？且新生那可保也。\"弟請不已，嫂曰：\"不得已，寧以吾新生與之。\"弟初不敢當，嫂卒與之。已而，二子皆成立。長曰，字景韓，季曰詡，字景虞。擁之子樵、，詡之孫鑄、鑒，皆相繼登第，遂為名族。孝友睦姻之報如此。婦人有識，尤可尚也。","sortOrder":35},
  {"id":"s_work_tddn_9_36","chapterId":"ch_work_tddn_9","text":"○吳季謙改秩","sortOrder":36},
  {"id":"s_work_tddn_9_37","chapterId":"ch_work_tddn_9","text":"吳季謙愈，初為鄂州邑尉，常獲劫盜。訊之，則昔年有某郡ヘ者，江行遇盜，殺之。其妻有色，盜胁之曰：\"汝能從我乎？\"妻曰：\"汝能從我，則我亦從汝，否則殺我。\"盜問故，曰：\"吾事夫若幹年，今至此已矣，無可言者。仅有一兒才數月，吾欲浮之江中，幸而有育之者，庶其有遺种，吾然後從汝無悔。\"盜許之，乃以黑漆团合盛此兒，藉以文褓，且置銀二片其旁，使隨流去。如是十餘年。一日，盜至鄂，舣舟。挟其家至某寺設供。至一僧房，庋間黑合在焉，妻一見識之，驚絕幾倒。因曰：\"吾疾作，姑小憩於此，毋撓我。\"乘間密問僧：\"何從得此合？\"僧言：\"某年月日得於水濱，有婴兒及白金在焉。吾收育之，為求乳食。今在此，年長矣。\"呼视之，酷肖其父。乃為僧言始末，且言：\"在某所，能為我聞之有司，密捕之可以為功受賞，吾冤亦釋矣。\"僧為報尉，一掩獲之，遂取其子以歸。季謙用是改秩。","sortOrder":37},
  {"id":"s_work_tddn_9_38","chapterId":"ch_work_tddn_9","text":"○作邑啟事","sortOrder":38},
  {"id":"s_work_tddn_9_39","chapterId":"ch_work_tddn_9","text":"龚聖任言，林德崇父，嘗為剧縣有聲。其與監司啟有雲：\"鳴琴堂上，將貽不治事之譏；投巫水中，必得擅殺人之罪。\"時以為名言。","sortOrder":39},
  {"id":"s_work_tddn_9_40","chapterId":"ch_work_tddn_9","text":"劉潛夫宰建陽，亦有一聯雲：\"每嗟民力，至叔世而張弓；欲竭吏能，恐聖門之鳴鼓。\"語意尤勝，信乎治邑之難也。","sortOrder":40},
  {"id":"s_work_tddn_9_41","chapterId":"ch_work_tddn_9","text":"○斋不茹葷必变食","sortOrder":41},
  {"id":"s_work_tddn_9_42","chapterId":"ch_work_tddn_9","text":"《莊子·人間世》雲：\"仲尼曰：'斋，吾語若。'顏回曰：'回之家貧，唯不飲酒不茹葷者數月矣。若此，則可以為斋乎？'曰：'祭祀之斋，非心斋也。'\"鄭玄註曰：\"葷，辛菜也。\"按《說文》：\"葷，臭菜也。\"锴曰：\"通謂芸、苔、椿、韭、蒜、葱、阿魏之屬，氣不絜也。\"","sortOrder":42},
  {"id":"s_work_tddn_9_43","chapterId":"ch_work_tddn_9","text":"《荀子·哀公篇》：\"孔子曰：'夫端衣玄裳，冕而乘辂者，志不在於食葷。'\"註雲：\"葷菜，葱、韭之屬。\"《論語》：\"斋必变食。\"《周禮·膳夫》：\"王斋，日三舉。\"鄭註雲：\"斋必变食也。\"《疏》曰：\"斋必变食，故加牲體至三太牢。\"（牛、羊、豕具為一牢。）","sortOrder":43},
  {"id":"s_work_tddn_9_44","chapterId":"ch_work_tddn_9","text":"胡明仲論梁武曰：\"祭祀之斋，居必遷坐，必变服，必变食，食為盛饌。一其心志，絜其氣體，以與神明交，未嘗不飲酒，不茹葷也。\"","sortOrder":44},
  {"id":"s_work_tddn_9_45","chapterId":"ch_work_tddn_9","text":"晦庵釋\"斋必变食\"亦取《莊子》，而黃氏亦兼取之。朱又謂\"葷是五辛\"，又曰：\"今致斋有酒，非也。\"然《禮》中乃有\"飲不至醉\"之說，何邪？","sortOrder":45},
  {"id":"s_work_tddn_9_46","chapterId":"ch_work_tddn_9","text":"○二李省詩","sortOrder":46},
  {"id":"s_work_tddn_9_47","chapterId":"ch_work_tddn_9","text":"蜀中類试，相傳主司多私意與士人相約為暗號，中朝亦或有之，而蜀以為常。李壁季章、宴季永，同登庚戌科，己酉赴類省试。二公皆以文名一時，而律賦非所長。乡人侯某者以能賦稱，因資之以润色。既書卷，不以詩示侯，侯疑其必有謂。將出門，侯故少留，李遂先出，而侯踵其後。至納卷所，扣吏以二李卷子，欲借一觀，以小金牌與之。吏取以示，則詩之景聯皆曰：\"日射紅鸞扇，風清白獸樽。\"侯即於己卷改用之。既而皆中選。二李謝主司，主司問：\"此二句，惟以授於崑仲，何為又以與人？\"李恍然不知所以。他日，微有所聞，終身與侯不协。","sortOrder":47},
  {"id":"s_work_tddn_9_48","chapterId":"ch_work_tddn_9","text":"○宗子請給","sortOrder":48},
  {"id":"s_work_tddn_9_49","chapterId":"ch_work_tddn_9","text":"王介甫為相，裁减宗室恩數，宗子相率訴馬前，公諭之曰：\"祖宗親盡，亦須祧遷，何况賢辈。\"荆公行一切不恤之政，獨於此事，未為不然。","sortOrder":49},
  {"id":"s_work_tddn_9_50","chapterId":"ch_work_tddn_9","text":"熙寧詔裁宗室授官法及恩例，東坡亦以為然，曰：\"此實陛下至明至斷，所以深計遠慮，割愛為民。\"其後無戚疏少長，皆仰食縣官。西南兩宗無賴者，至縱其婢使與闾巷通，生子則認為己子而利其請給，此自古所無之弊例也。","sortOrder":50},
  {"id":"s_work_tddn_9_51","chapterId":"ch_work_tddn_9","text":"○鄭安晚前讖","sortOrder":51},
  {"id":"s_work_tddn_9_52","chapterId":"ch_work_tddn_9","text":"鄭丞相清之，在太學十五年，殊困滯無聊。乙亥歲，甫升舍選，而以無名闕，未及奏名，遂仍赴丁丑省试。臨期，又避知舉袁和叔親试別頭，愈覺不意。及试，《青紫明主恩》詩押明字。短晷逼暮，思索良艱。漫檢韻中，有穎字可用，遂用為末句雲：\"他年蒙渥泽，方玉帶围穎。\"歸為同舍道之，皆大笑曰：\"绿衫尚未能得著，乃思量系玉帶乎？\"已而中選，攀附骤貴，官至極品，竟此賜，遂成吉讖。以此知世之叨竊富貴，皆非偶然也。","sortOrder":52},
  {"id":"s_work_tddn_9_53","chapterId":"ch_work_tddn_9","text":"○趙佥判花字樣","sortOrder":53},
  {"id":"s_work_tddn_9_54","chapterId":"ch_work_tddn_9","text":"趙時杖為平江佥幕，其訓名不雅。凡書判决杖，吏辈皆用紙貼之，此亦可笑。其押字，作一大口字，而申其下一畫。陳子爽恺作守，初到見之，書其侧雲：\"佥判押字大空空，請改之，庶幾務實。仍請別押一樣來。\"聞者無不大笑。正可與李晉仁喏樣為對也。","sortOrder":54},
  {"id":"s_work_tddn_9_55","chapterId":"ch_work_tddn_9","text":"○一府三守","sortOrder":55},
  {"id":"s_work_tddn_9_56","chapterId":"ch_work_tddn_9","text":"放翁《筆記》言：慶歷初，夏竦判永興軍，陳執中、范雍，併為知軍。一府三守，不知職守如何分？既非長貳，文移書牒之類必有程式。官屬胥吏，何所禀承？國史不載，莫可考也。然諫官御史不以為非，三公亦不辭，豈在當時，亦便於事邪？今按竦先以都部署兼經略招讨使，判永興軍。既而執中為同都部署經略使知軍，而詔竦判如故。未幾，竦屯州，執中屯涇州。蓋兩人議邊事不合，故分任之。未幾，又以范雍知軍。竦、執中既分出按邊，而領府事猶故。於是一府三守，公吏奔趨往來想不勝其扰，自昔未嘗有也。然則史未嘗不載，而於事安得為便乎？","sortOrder":56},
  {"id":"s_work_tddn_9_57","chapterId":"ch_work_tddn_9","text":"○六么羽調","sortOrder":57},
  {"id":"s_work_tddn_9_58","chapterId":"ch_work_tddn_9","text":"《演繁露》雲：唐有新翻羽調绿腰。白樂天詩集自註雲：'即六么也。'今世亦有六么，而其曲有高平、仙呂調，又不與羽調相协，不知是唐遺聲否？按今六么中，呂調亦有之，非特高平、仙呂也。《唐禮樂志》：俗樂二十八調，中呂、高平、仙呂在七羽之數。蓋中呂、夹鐘，羽也；高平、林鐘，羽也；仙呂、夷則，羽也。安得謂之不與羽調相协？蓋未之考爾。","sortOrder":58},
  {"id":"s_work_tddn_9_59","chapterId":"ch_work_tddn_9","text":"○香炬錦茵","sortOrder":59},
  {"id":"s_work_tddn_9_60","chapterId":"ch_work_tddn_9","text":"秦會之當國，四方饋遺日至。方滋德帥廣東，為蠟炬以眾香實其中，遣駛卒持詣相府，厚遺主藏吏，期必達，吏使俟命。一日，宴客，吏曰：\"燭盡。適廣東方經略送燭一掩，未敢啟。\"乃取而用之。俄而異香滿坐，察之，則自燭中出也。亟命藏其餘枚，數之，適得四十九。呼駛問故，則曰：\"經略专造此燭供獻，仅五十條，既成，恐不嘉，试熱其一，不敢以他燭充數。\"秦大喜，以為奉己之专也，待方益厚。","sortOrder":60},
  {"id":"s_work_tddn_9_61","chapterId":"ch_work_tddn_9","text":"鄭仲為蜀宣撫，格天閣畢工，鄭書適至，遺錦地衣一鋪。秦命鋪閣上，廣袤無尺寸差，秦默然不樂，鄭竟失志，至於得罪。二公為計同，一以見疑，一以見厚，固有幸不幸，要不若居正之無悔吝也。","sortOrder":61},
  {"id":"s_work_tddn_9_62","chapterId":"ch_work_tddn_9","text":"○登聞鼓","sortOrder":62},
  {"id":"s_work_tddn_9_63","chapterId":"ch_work_tddn_9","text":"《筆談》言洛京留台有舊案，言國初取索滷簿法仗，報言：\"本京滷簿，因清泰間末帝將帶逃走，不知所在。\"人傳以為笑。","sortOrder":63},
  {"id":"s_work_tddn_9_64","chapterId":"ch_work_tddn_9","text":"今登聞鼓院，初供職吏，具須知单状，稱：\"本院元管鼓一面，在東京宣德門外，被太學生陳東等击碎，不曾搬取前來。\"正與此相類，皆可資捧腹也。","sortOrder":64},
  {"id":"s_work_tddn_9_65","chapterId":"ch_work_tddn_9","text":"○義絕合離","sortOrder":65},
  {"id":"s_work_tddn_9_66","chapterId":"ch_work_tddn_9","text":"莆田有楊氏，訟其子與婦不孝。官為逮問，則婦之翁為人殴死，楊亦預焉。坐獄未竟，而值覃霈，得不坐。然婦仍在楊氏家。有司以大辟既已該宥，不复問其餘，小民無知，亦安之不以為怪也。其後，父又訟其子及婦。軍判官姚缶以為\"雖有仇隙，既仍為婦，則當盡婦禮\"，欲併科罪。陳伯玉振孫時以ヘ攝郡，獨謂：\"父子天合，夫婦人合；人合者，恩義有虧則已矣。在法，休離皆許還合，而獨於義絕不許者，蓋謂此類。况兩下相殺，又義絕之尤大者乎！初間，楊罪既脱，合勒其婦休離，有司既失之矣。若楊婦盡禮於舅姑，則為反親事仇，稍有不至，則舅姑反得以不孝罪之矣。當離不離，則是违法。在律，违律為婚，既不成婚，即有相犯，併同凡人。今其婦合比附此條，不合收坐。\"時皆服其得法之意焉。","sortOrder":66},
  {"id":"s_work_tddn_9_67","chapterId":"ch_work_tddn_9","text":"按《筆談》所載，寿州有人殺妻之父母兄弟數口。州司以不道，緣坐其妻子。刑曹驳之曰：\"殴妻之父母，即為義絕，况身謀殺，不應复坐。\"此與前事正相類。凡泥法而不明於理，不可以言法也。","sortOrder":67},
  {"id":"s_work_tddn_9_68","chapterId":"ch_work_tddn_9","text":"○熊子复","sortOrder":68},
  {"id":"s_work_tddn_9_69","chapterId":"ch_work_tddn_9","text":"熊克字子复，博學有文。王季海守富沙日，漕使开宴，命子复撰樂語，季海讀之稱善。詢司謁者曰：\"誰為之？\"答曰：\"新任某州熊教授也。\"自此甚見前席。別後，子复一向官湖湘間，不相聞者幾二十年。及改秩作邑滿，造朝謁光范。季海時為元枢，詢子复曰：\"近亦有著述乎？\"子复以兩編獻。廣日，後殿奏事畢，阜陵從容曰：\"卿見近日有作四六者乎？\"時學士院闕官，上不訪之趙丞相而訪之季海，於是以陆務觀等數人對。上雲：\"朕自知之，今欲得在下僚未知名者爾。\"季海遂及子复姓名。上雲：\"此人有近作可進來。\"季海退以所獻繳入。翌日，上謂季海曰：\"熊克之文，朕嘗觀之，可喜。\"蓋欲置之三馆兼翰苑也。季海奏雲：\"如此恐太骤，不如且除院轄，徐召试。使克文聲著於士大夫間，則人無間言。\"阜陵然之，遂除提轄文思院。","sortOrder":69},
  {"id":"s_work_tddn_9_70","chapterId":"ch_work_tddn_9","text":"他日，趙丞相進擬，上曰：\"朕自有人。\"趙問\"何人\"，上曰：\"熊克。\"又曰：\"陛下何以知之？\"曰：\"朕嘗見其文字。\"又問：\"陛下何從得其文字，此必有近習為道地者。\"上曰：\"不然。\"季海雖知由己所荐，以上既不言，亦不敢泄。而趙終疑之。未幾召试。故時，學士院發策，率先示大略，试者得為之備。趙乃以喻周子充雲：\"此非佳士也。\"克屢造請求間目，子充不答，及對策殊略，克大以為恨。故在玉堂，每當子充製詔，辄無美辭，後竟出知台州。","sortOrder":70},
  {"id":"s_work_tddn_9_71","chapterId":"ch_work_tddn_9","text":"○鄭時中得官","sortOrder":71},
  {"id":"s_work_tddn_9_72","chapterId":"ch_work_tddn_9","text":"鄭時中字复亨，三衢人。在上庠日，多遊朝紳間。好大言，嘗語同舍曰：\"前舉漕荐，乃術者曹穀先許，今复來矣。\"有好事者聞之曰：\"此必穀又許之。\"乃與偕走其肆，則鄭實未嘗先往。曹沉吟久之，頻自搖首，推演再三，乃曰：\"吾十年前，曾許此命來春必高選，今所見乃不然。雖然，宋春定得官，但非登科耳。今秋得舉，却不必問。\"鄭乃曰：\"吾家無延賞，來年不郊，非科舉何由得官？\"穀曰：\"某見得如此耳。\"既而程泰之大昌與鄭同荐，程第而鄭不利。時餘松茂老為秦會之客，第三人及第。秦與謀代，餘因荐鄭，秦亦悅其辯，設禮有加，鄭無以頌之。","sortOrder":72},
  {"id":"s_work_tddn_9_73","chapterId":"ch_work_tddn_9","text":"嘗聞其季父行可名仲熊者，言舊在太學，目击靖康金人欲立張邦昌，秦為中司，特議立趙氏。金酋召赴軍前，秦遂遣妻王氏南歸。已登舟，王聞变，亟步以往。秦時猶未入北軍，因同入肆買齏面。人已盈坐，主人橫一卓溝上使坐，王忧懼不能舉箸，秦兼盡之，略無懼色。已，乃同至軍前被執。鄭因於坐間舉此事，謂親得之行可。秦意正欲暴白此事，而人無知者，聞其言大喜。時行可猶仕州縣，即召用之，二年，同為執政。是歲复亨亦得官，其神验如此。","sortOrder":73},
  {"id":"s_work_tddn_9_74","chapterId":"ch_work_tddn_9","text":"○詩詞祖述","sortOrder":74},
  {"id":"s_work_tddn_9_75","chapterId":"ch_work_tddn_9","text":"隆興間，魏勝戰死淮陰，孝宗追惜之。一日，諭近臣曰：\"人才須用而後見，使魏勝不因邊衅，何以見其才？如李廣在文帝時，是以不用，使生高帝時，必將大有功矣。\"","sortOrder":75},
  {"id":"s_work_tddn_9_76","chapterId":"ch_work_tddn_9","text":"其後放翁赠劉改之曰：\"李廣不生楚漢間，封侯萬戶宜其難。\"蓋用阜陵語也。改之大喜，以為善名我。","sortOrder":76},
  {"id":"s_work_tddn_9_77","chapterId":"ch_work_tddn_9","text":"異時，劉潛夫作《沁園曲》雲：\"使李將軍遇高皇帝，萬戶侯何足道哉！\"又祖放翁語也。","sortOrder":77},
  {"id":"s_work_tddn_9_78","chapterId":"ch_work_tddn_9","text":"○嘲觅荐舉","sortOrder":78},
  {"id":"s_work_tddn_9_79","chapterId":"ch_work_tddn_9","text":"直斋陳先生雲：向為紹興教官日，有同官初至者，偶問其京削欠幾何？答雲：\"欠一二紙。\"數月，聞有舉之者。會間，贺其成事，則又曰：\"尚欠一、二紙。\"又越月，复聞有舉者，扣之，則所答如前。餘頗怪之。他日，與王深甫言之，深甫笑曰：\"是何足怪？子不見臨安丐者之乞房錢乎？暮夜，號呼於衢路曰：'吾今夕所欠十幾文耳。'有怜之者，如數與之曰：'汝可以歸臥矣。'感謝而退。去之數十步，則其號呼如初焉。子不彼之怪，而此之怪，何哉？\"因相與大笑而罢。","sortOrder":79},
  {"id":"s_work_tddn_10_1","chapterId":"ch_work_tddn_10","text":"●卷九","sortOrder":1},
  {"id":"s_work_tddn_10_2","chapterId":"ch_work_tddn_10","text":"○形影身心詩","sortOrder":2},
  {"id":"s_work_tddn_10_3","chapterId":"ch_work_tddn_10","text":"靖節作形影相赠、《神釋》之詩。謂貴賤賢愚，莫不營營惜生。故極陳形影之苦，而以神辨自然，以釋其惑。《形赠影》曰：\"願君取吾言，得酒莫苟辭。\"《影答形》曰：\"立善有遺愛，胡可不自竭。\"形累養而欲飲，影役名而求善，皆惜生之惑也。神乃釋之曰：\"大鈞無私力，萬理自森著。人為三才中，豈不以我故。\"此神自謂也。又曰：\"日醉或能忘，將非趣齡具。\"所以辨養之累。又曰：\"立善常所忻，誰當與汝譽？\"所以解名之役，然亦仅在趣齡與無譽而已。設使為善見知，飲酒得寿，則亦將從之耶？於是又極其釋曰：\"縱浪大化中，不喜亦不懼。應盡便須盡，無事勿多慮。\"此乃不以死生禍福動其心，泰然委順，乃得神之自然，釋氏所謂斷常見者也。","sortOrder":3},
  {"id":"s_work_tddn_10_4","chapterId":"ch_work_tddn_10","text":"坡翁從而反之曰：\"予知神非形，何复異人天。豈惟三才中，所在靡不然。\"又雲：\"委順忧傷生，忧死生亦遷。縱浪大化中，正為化所纏。應盡便須盡，寧复俟此言。\"","sortOrder":4},
  {"id":"s_work_tddn_10_5","chapterId":"ch_work_tddn_10","text":"白樂天因之作《心問身》詩雲：\"心問身雲何泰然，嚴冬暖被日高眠。放君快活知恩否，不早朝來十一年。\"身答心曰：\"心是身王身是宮，君今居在我宮中，是君家舍君須愛，何事論恩自說功。\"心复答身曰：\"因我疏慵休罢早，遣君安樂歲時多。世間老苦人何限，不放君閒奈我何。\"此則以心為吾身之君，而身乃心之役也。","sortOrder":5},
  {"id":"s_work_tddn_10_6","chapterId":"ch_work_tddn_10","text":"坡翁又從而賦六言曰：\"淵明形神自我，樂天身心於物。而今月下三人，他日當成幾佛？\"","sortOrder":6},
  {"id":"s_work_tddn_10_7","chapterId":"ch_work_tddn_10","text":"然二公之說雖不同，而皆祖之列子力命之論。力謂命曰：\"若之功，奚若我哉？\"命曰：\"汝奚功於物，而欲比朕？\"力曰：\"寿夭窮達，貴賤富貧，我力之所能也。\"命遂歷陳彭祖之寿，顏淵之天，仲尼之困，殷紂之君，季札無爵於君，田恒专有齊國，夷、齊之饿，季氏之富：\"若是，汝力之所能，奈何寿彼而天此，窮聖而達逆，賤賢而貴愚，貧善而富惡耶？\"力曰：\"若如是言，我固無功於物，而物若此耶？此則若之所製耶？\"命曰：\"既謂之命，奈何有製之者？朕直而推之，曲而任之。自寿自夭，自窮自達，自貴自賤，自富自貧，朕豈能識之哉！\"此蓋言寿夭窮達，貴賤富貧，雖曰莫非天命，而亦非造物者所能製之，直付之自然耳。此則淵明神釋，所謂\"大鈞無私力\"之論也。","sortOrder":7},
  {"id":"s_work_tddn_10_8","chapterId":"ch_work_tddn_10","text":"其後楊龟山有《讀東坡和陶影答形》詩雲：\"君如煙上火，火盡君乃別；我如鏡中像，鏡坏我不滅。\"蓋言影因形而有無，是生滅相。故佛雲：\"一切有為法，如夢幻泡影。\"正言其非實有也，何謂不滅？此則又墮虛無之論矣。","sortOrder":8},
  {"id":"s_work_tddn_10_9","chapterId":"ch_work_tddn_10","text":"○父執之禮","sortOrder":9},
  {"id":"s_work_tddn_10_10","chapterId":"ch_work_tddn_10","text":"前辈事父執之禮甚嚴。漢馬伏波有疾，梁松來候之，獨拜床下，援不答。松去，諸子問曰：\"梁伯孫，帝婿貴重，公卿莫不憚之，大人獨不為禮？\"援曰：\"我乃松之父友也，雖貴，何得失其序乎！\"","sortOrder":10},
  {"id":"s_work_tddn_10_11","chapterId":"ch_work_tddn_10","text":"王丹召為太子少傅，大司徒侯霸欲與交友，遣子昱候於道，迎拜車下，丹下答之。昱曰：\"家君欲與君結友，何為見拜？\"丹曰：\"君房有是言，丹未之許也。\"然則答拜乃疏之耳。","sortOrder":11},
  {"id":"s_work_tddn_10_12","chapterId":"ch_work_tddn_10","text":"至國朝東都時，此禮猶在。韓魏公留鑰北京日，李稷以國子博士為漕，頗慢公，公不與较，待之甚禮。俄，潞公代魏公為留守，未至，扬言雲：\"李稷之父絢，我門下士也。聞稷敢慢魏公，必以父死失教至此。吾视稷，猶子也，果不悛，將庭訓之。\"公至北京，李稷謁見，坐客次。久之，著道服出，語之曰：\"而父，吾客也，只八拜。\"稷不獲已，如數拜之。此事或傳李稷為許將。","sortOrder":12},
  {"id":"s_work_tddn_10_13","chapterId":"ch_work_tddn_10","text":"熙寧初，呂晦叔諸子謁欧陽公於潁上，疑當拜與否。既見叙，拜，文忠不复辭，受之如受子侄之禮。二子既出，深叹前辈不可及。","sortOrder":13},
  {"id":"s_work_tddn_10_14","chapterId":"ch_work_tddn_10","text":"崇寧間，陆佃農師在政府日，有大卿岑象先巖起於農師為父執。一日來訪，延之堂奧，具冠裳拜之。既而岑作手簡來謝雲：\"前日登門展慶，蒙公敦篤事契，俾納貴禮。於公有謙之光，使老者增僭易之過。然大將軍有揖客，古人以為美談，今文昌綱轄有受拜客，顧不美於前人乎。\"","sortOrder":14},
  {"id":"s_work_tddn_10_15","chapterId":"ch_work_tddn_10","text":"前辈遇通家子弟，初見請納拜者，既受之，則設席望其家，遙拜其父祖，乃始就坐。蓋當時風俗尚厚，雖執政之於庶官亦講此禮，不以為異也。自南渡以後，則世道日薄矣。然餘幼時，猶見親舊通家初見日，必先拜其家影堂，然後請謁，此禮今亦不复見也。","sortOrder":15},
  {"id":"s_work_tddn_10_16","chapterId":"ch_work_tddn_10","text":"○李全","sortOrder":16},
  {"id":"s_work_tddn_10_17","chapterId":"ch_work_tddn_10","text":"李全，淄州人，第三，以販牛馬來青州。有北永州牛客張介引至涟水。時金國多盜，道梗難行，财本浸耗，遂投充涟水尉司弓卒。因結群不逞為義兄弟，任俠狂暴，剽掠民财，党與日盛，莫敢誰何，號為李三統轄。後复還淄業屠，嘗就河洗刷牛馬，於遊土中蹴得鐵槍杆，長七八尺。於是就上打成槍頭，重可四十五斤。日習击刺，技日以精，為眾推服，因呼為李鐵槍。遂挟其徒橫行淄、青間，出没抄掠。","sortOrder":17},
  {"id":"s_work_tddn_10_18","chapterId":"ch_work_tddn_10","text":"淄、青界內有楊家堡，居民皆楊氏，以穿甲製靴為業。堡主曰楊安兒，有力強勇，一堡所服。亦嘗為盜於山東，聚眾至數萬。有妹曰小姐姐（或雲其女，其後稱曰姑姑），年可二十，膂力過人，能馬上運双刀，所向披靡。全軍所過，諸堡皆載牛酒以迎，獨楊堡不以為意。全知其事，故攻劫之。安兒亦出民兵對壘，謂全曰：\"你是好漢，可與我妹挑打一番。若贏時，我妹與你為妻。\"全遂與酣戰，終日無勝負，全忿且慚。適其處有丛筱，全令二壮士執鉤刀，夜伏筱中。翌日再戰，全佯北，楊逐之，伏者出，以刀鉤止，大呼，全回馬挟之以去。安兒乃領眾備牛酒，迎歸成姻，遂還青州，自是名聞南北。","sortOrder":18},
  {"id":"s_work_tddn_10_19","chapterId":"ch_work_tddn_10","text":"時金人方困於敵，張介又從而招之，授以兵馬，衣以紅袍，號紅袄軍。嘉定十一年間，金人愈窮蹙。全因南附。乃與石、沈铎辈結党以來，知楚州應之純遂納之，累戰功至副總管。明年，金主下詔招之，全复書有雲：\"寧作江淮之鬼，不為金國之臣。\"遂以輕兵往濰州，遷其父母兄嫂之骨葬於淮南，以誓不复北向。時山東已為韃所破，金不能有，全遂下益都，張林出降，遂併獻濟、莒、沧、濱、淄、密等凡二府九州四十縣，降頭目千人，戰馬千五百匹，中勇軍十五萬人。聞於朝，遂以全為左武衛大將軍、廣州觀察使、京東忠義軍都統製、馬步軍副總管，特賜銀、絹、缗錢等。","sortOrder":19},
  {"id":"s_work_tddn_10_20","chapterId":"ch_work_tddn_10","text":"先是，贾涉知鹽城縣，以事忤淮漕，方信孺劾之，未報。涉廉知信孺陰遣梁昭祖航海致饋，以結李全，遂遣人捕得之，亟申於朝，方由是罢，涉召入為大理司直，未幾，知楚州。時忠義軍頭目李先拳勇有胆氣，且併領石、沈铎之軍，李全深忌之。至是，極力挤先，涉遂以李先反侧聞於朝。於是召先赴密院審查，甫至都門，殿帥冯树宴之三茅觀後小寨，命勇士扑殺之，於是全愈無忌憚矣。先既誅，涟水人情不安，頭目裴淵等遂請石為帥於盱眙。製司大恐，遂令李全率萬人以往，全憚，不敢動。製司無策，遂分其軍為五。乃呼裴淵赴山陽禀議，责以专擅招，令密圖之，以功贖罪。會韃兵至涟水，硅亦自疑，遂殺淵以歸韃。先是，權尚書胡榘，嘗言全狼子野心，不可倚仗。及全獲捷於曹家莊，擒金人伪駙馬，乃作《濠梁歌》以諛之雲：春殘天氣何佳哉，捷書夜自濠梁來，將軍生擒伪駙馬，敵兵十萬冰山摧。何物輕犭挑胡羯，萬里煙尘暗邊徼，邊臣玩寇不却攘，三月淮Й驚蹀血。廟謨密遣山東兵，李將軍者推忠精，鐵槍匹馬首破陣，喑呜叱咤風雲生。摧殺群妖天與力，虜丑成擒不容逸，失聲走透虜鼓捶，猶截騰驤三百匹。防围健使催賜金，曹家莊畔殺胡林，遊魂欲反定懸胆，將軍豈知關塞深。君不見，往日蘄王邀兀術，围合狐跳追不得，夫人明日拜函封，乞罪將軍縱狂逸。豈知李侯心胆粗，捕縛犭製子才須臾。金牛走敵猛將有，沔州斬賊儒生無。宗社威靈人製勝，養銳圖全無輕進，會須入汴縛酆王，笳鼓歸來取金印。既而涉以病歸，遂以鄭損繼之。損與涉素不相成，幕中諸客懼損修怨，乃嗾李全申請，乞差真德秀、陳靴、梁丙知楚州。於是朝廷遂改損為四川製置，乃以知閣門事許國用徐本中例換授朝議大夫，再轉為太府少卿知楚州。","sortOrder":20},
  {"id":"s_work_tddn_10_21","chapterId":"ch_work_tddn_10","text":"國自是歉然，懼儕辈輕己。开阃之初，命管軍以下皆執朝參之禮。時全已為保寧軍節度使，前阃皆與抗禮。至是，幕府宋恭、荀夢玉等懼变，遂調停，約全拜於庭下，國答拜於堂上。議已定，及庭參，國乃傲然坐而受之，全大慚憤，竟還青州。至冬，國大閱兩淮軍馬，全妻李姑姑者，欲下教場犒軍，實求衅耳，幕府复調停力止。及淮西軍回，人仅得交子五貫，乃盡以弓刀售之李軍，而淮西軍亦怨矣。未幾，全將劉慶福自青來，謀以丁祭之夕作亂，以謀泄而止。既而製府出榜，以高顯為詞，指摘北軍。慶福亦大書一榜，揭於其右，語殊不遜。次日，慶福开宴於萬柳亭，遊幕諸客及青州ヘ姚在焉。酒行方酣，忽報全至海州，促慶福北還。時國方納謁，北軍径自南門入，直製府。強勇軍方解甲，望見北軍，皆弃去，遂排大門而入。帳前親兵欲御之，國乃大呼曰：\"此辈不過欲多得錢絹耳。\"方行喝犒，聞北軍大喊登城，張旗幟，火已四起，飛矢如雨。國額中一箭，径趨避於楚台。北軍劫掠府库，焚毀殆盡。國在楚台久之，使令姚求和。遂缒城而出，以直系書\"青州姚通判\"，以長竿揭之馬前，往見李姑姑。李遜謝不能統轄諸軍以致生变。姚遂請收軍，李雲：\"只請製置到此商量，便可定也。\"姚亟回報，則國已遁矣。次日，北軍得國於三茅道堂，以小竹舆舆至李軍。國不能發一語，复送還楚台，以兵環守，國遂死焉。文武官遇害者凡數十人。未幾，全乃入弔，行慰奠禮，且上章自劾，朝廷不敢問也。遂進全為少保，而以大理卿徐希稷知楚州。","sortOrder":21},
  {"id":"s_work_tddn_10_22","chapterId":"ch_work_tddn_10","text":"軍变之先一日，荀夢玉已知其謀，亟告於國，國不以為然。至是，全得其告变之書，欲殺之，而夢玉已歸滁。乃命數十騎邀於路而殺之。製府捐三千缗捕賊，而全亦捐五千缗，無状大率如此。希稷至楚，一意逢迎，全益以驕。既而還青州，或傳為金人所擒，或以為已死。劉卓乘時自夸以驅除餘党。及丞相入其言，遂召希稷，而以卓為代，璋即以盱眙軍馬自隨。中途所乘馬無故而踣，卓怒，遂斬二濠寨官，人疑其非吉征也。卓初至，軍聲頗振，不數日，措置乖方。南、北軍已相疑，適忠義軍總管夏全自盱眙領五千人來。先是，全欲殺夏，卓為解免之，至是，卓留以自衛，且資其軍以製全。然夏軍素驕，時作過劫掠居民，卓乃捕為首數人斬之，猶未戢。乃札忠義都統權司張忠政權副都統，忠政辭不就。楊姑姑知之，遂呼忠政謀所以拒製司之策。忠政曰：\"朝廷無負北軍，夫人若欲忠政反，惟有死耳。\"遂歸家，令妻子自經，次焚告敕寶货於庭，然後自盡。","sortOrder":22},
  {"id":"s_work_tddn_10_23","chapterId":"ch_work_tddn_10","text":"製司聞变，遂戒嚴。命夏全封閉李全、劉全、張林等府库，且出榜令北軍限三日出城。是日，諸營搬移自東北門出。夏軍坐門首搜檢，凡金銀婦女多攘取之。餘皆疑懼不敢出，製司又從而驅逐之。有黑旗一對仅百人，乃北軍之精銳者，堅不肯出。潛易衣裝，與夏軍混雜。南軍欲註矢揮刃，則呼曰：\"我夏太尉軍也。\"南軍遂不疑之。至晡，大西門上火忽起，至夜，遂四面縱火，殺害軍民。卓遂命守子城，護府库。凡兩日夜，軍皆無火飯，飢困不复用命。夏全知事急，遂挺身入北軍。李姑姑遂與夏剧飲，酒酣，泣曰：\"少保今不知存亡，妾願以身事太尉，府库人馬，皆太尉物也。本一家人，何為自相戕？若今日剿除李氏，太尉能自保富貴乎？\"夏全惑其說，乃陰與李軍合，反戈以攻南軍。卓屢遣人招夏議事，竟不至，乃以十萬貫犒軍求和。夏全乃令开一路，以馬軍二百衛送卓出大西門。星夜南奔，至寶應，已四鼓矣。從行官屬惟餘元е、沈宣子，餘悉死焉。夏軍回至淮陰，乃為時青、令暉夹击，盡得所擄财物七巨艘。既至盱眙，范成、張惠閉門拒之，且就軍中殺其母妻，於是夏全乃輕身北竄。劉卓遂移司於扬之堡寨，朝廷遂改楚為淮安州，命將作少監姚知州事。","sortOrder":23},
  {"id":"s_work_tddn_10_24","chapterId":"ch_work_tddn_10","text":"時李全猶未還，王義深、國安用為權司。劉慶福與張甫謀就楚之淮河縛大浮桥。或告李姑姑以二人欲以州獻金人，姑姑即遣人請姚議事，不獲已而往，則大廳已設四果卓，餘二客則慶福及甫也。慶福先至，姑姑雲：\"哥哥不快，可去問則个。\"謂李福也。時福臥於密室，凡迂曲數四乃至。慶福至榻前雲：\"哥哥没甚事？\"福雲：\"煩惱得恁地。\"劉觇福榻有劍出，稍心動，亟出，福急揮劍中其腦。既而甫至，於外呼雲：\"總管没什事否？\"福隱身門左，俟其入，即揮劍，又仆之，福遂携二首以出，乃大張樂剧飲。姚遂揭榜，以劉、張欲謀作逆，密奉朝旨已行誅戮，乃聞於朝。李福增秩，姑姑賜金，進封楚國夫人。末幾，福复以預借糧券求衅，遂召北軍入城，官民死者甚眾，姚賴國安用匿之而免。於是朝廷諸阃各主剿除分屯之說，久之不决。既而盱眙守彭忄屯乃遣張惠、范成入淮安，說國安用令殺李福及李姑姑。未幾，李福就戮，而姑姑則易服往海州矣。其後分屯之說已定，而江阃所遣趙夫剿殺之兵適至。北軍怒為張、范所賣，欲殺之，二人遂遁去。國安用追至盱眙，彭忄屯宴之，方大合東，忽報軍变，始知張、范已獻盱眙於北矣，彭忄屯遂為所擒。","sortOrder":24},
  {"id":"s_work_tddn_10_25","chapterId":"ch_work_tddn_10","text":"既而李全至楚，揭榜自稱山東、淮南行省，於是盡據淮安、海州、涟水等處。先是，全遣張國明入朝禀議，書至，朝廷未有以處之。會時青亦遣人至，國明遂遣人報全，全遂殺青。國明極言李全無它意，朝廷遂遣趙拱奉兩镇節鉞印綬以往。而江阃乃遣申生結全帳下謀殺之。事覺，全囚申生，以其事上於朝。蓋全時已有叛志矣。會鹽城陳遇謀於東海截奪全青州運糧之船，全由是愈怒，遂興問罪之師。首攻海陵，守臣宋濟迎降，遂進围扬州。朝廷始降詔削奪全官爵，住給錢糧，會諸路兵誅讨，然戰多不利，內外為之震動。是時全合諸項軍馬，併驅乡民二十餘萬，一夕筑長围數十里，围合扬之三城，為必取之計。會元夕，欲示閒暇，於城中張燈大宴，全亦張燈於平山堂中。夜，全乘醉引馬步極力薄城，趙范命其弟葵領兵出城迎戰，至三鼓，勝負未决。葵先命李虎、丁勝同持兵塞其瓮門。至是，全欲還，而門已塞，進退失據，且戰且退，遂陷於新塘，由是各散去。次日於沮洳亂尸中，得一紅袍而無一手指者，乃全也（先是全投北，嘗自斷一指，以示不复南歸）。時紹定四年正月。後三日，北軍悉遁，製府露布聞於朝，遂乘勝复泰之鹽城。後三月，淮南諸州北軍皆空城而去矣。其雏松寿者，乃徐希稷之子。贾涉开阃維扬日，嘗使與諸子同學。其後全無子，屢托涉祝之。涉以希稷向與之念，遂命與之，後更名雲。（劉子澄嘗著《淮東補史》，紀載甚詳。然餘所聞於當時諸公，或削書所未有者，因摭其概於此，以補劉氏之闊文雲。）","sortOrder":25},
  {"id":"s_work_tddn_10_26","chapterId":"ch_work_tddn_10","text":"○王公袞复仇","sortOrder":26},
  {"id":"s_work_tddn_10_27","chapterId":"ch_work_tddn_10","text":"王宣子尚書母，葬山陰獅子坞，為盜所發。時宣子為吏部員外郎，其弟公袞待次乌江尉，居乡物色得之，乃本村無賴嵇泗德者所為。遂聞於官，具服其罪，止從徒斷，黥隸他州，公袞不勝悲憤。時猶拘留鈐轄司，公袞遂誘守卒飲之以酒，皆大醉，因手斷賊首，朝复提之自歸有司。宣子亟以状白堂，納官以贖弟罪。事下給舍議，時楊椿元老為給事，張孝祥安國兼舍人，書議状曰：\"复仇，義也。夫仇可复，則天下之人，將交仇而不止，於是聖人為法以製之。當誅也，吾為爾誅之；當刑也，吾為爾刑之。以爾之仇，麗吾之法。於是凡為人子而仇於父母者不敢复，而惟法之聽，何也？法行則复仇之義在焉故也。今夫佐、公袞之母，既葬而暴其骨，是﹃尸也。父母之仇，孰大於是？佐、公袞得賊而辄殺之，義也，而莫之敢也，以為有法焉。律曰：'發冢开棺者、絞。'二子之母，遺骸散逸於故藏之外，則賊之死無疑矣。賊誠死，則二子之仇亦報，此佐、公袞所以不敢殺之於其始獲，而必歸之吏也。獄成而吏出之，使賊陽陽出入闾巷與齊民齒。夫父母之仇，不共戴天者也。二子之始不敢殺也，蓋不敢以私義故亂法。今獄已成矣，法不當死，二子殺之，罪也；法當死，而吏废法，則地下之辱，沈痛鬱結，終莫之伸，為之子者，尚安得自比於人也哉！佐有官守，則公袞之殺是賊，协於義而宜於法者也。《春秋》之義，复仇。公袞起儒生，羸如不勝衣。當殺賊時，奴隸皆驚走，賊以死捍，公袞得不死，適耳。且此賊掘冢至十數，嘗败而不死，今又败焉，而又不死，則其為惡，必侈於前。公袞之殺之也，豈特直王氏之冤而已哉！椿等謂公袞复仇之義可嘉，公袞殺掘冢法應死之人為無罪，納官贖弟佐之請當不許，故縱失刑有司之罰宜如律。\"詔：\"給舍議是。\"","sortOrder":27},
  {"id":"s_work_tddn_10_28","chapterId":"ch_work_tddn_10","text":"其後，公袞於乾道間為敕令所删定官。一日，登對。孝宗顧問左右曰：\"是非手斬發冢盜者乎？\"意頗喜之。未幾，除左司。","sortOrder":28},
  {"id":"s_work_tddn_10_29","chapterId":"ch_work_tddn_10","text":"公袞為人癯甚。王龟齡嘗赠詩有雲：\"貌若羸中甚武\"者，蓋紀實也。","sortOrder":29},
  {"id":"s_work_tddn_10_30","chapterId":"ch_work_tddn_10","text":"○富春子","sortOrder":30},
  {"id":"s_work_tddn_10_31","chapterId":"ch_work_tddn_10","text":"寶慶間，有孫氏子名守榮，善風角鳥占，其術多验，號富春子。薄遊上，聞谯樓鼓角聲，驚曰：\"旦夕且有变，而土人當有典郡者。\"適見富公王元春，因贺之曰：\"旦夕乡郡之除，必君也。\"王以為誕。越兩月，而潘丙作亂，王果以告变之功典郡，自是人始神之。後登史衛王之門，頗為信用。一日，聞鵲噪，史令占之，雲：\"來日哺時，當有寶物至，然非丞相所可用者。今已抵關，必有所礙，而未入耳。\"翌日，果李全以玉柱斧為貢，為閽者遲留，质之於府而後納。史嘗得李全書，置之袖間，未啟也。因扣雲：\"吾袖中書，所言何事？\"對曰：\"假破囊二十萬耳。\"剝封，果然，史以此深忌之。後以他故，黥至遠郡死焉。後未見有得其術者。","sortOrder":31},
  {"id":"s_work_tddn_10_32","chapterId":"ch_work_tddn_10","text":"○王宣子失告命","sortOrder":32},
  {"id":"s_work_tddn_10_33","chapterId":"ch_work_tddn_10","text":"輦轂之下，政先彈壓，然一智不足以勝眾奸。王佐宣子雖以文魁天下，而吏才極高，寿皇深喜之。尹臨安日，禁戢群盜甚嚴，都城肅然。既而以治辦受賞增秩，告命甫下，置臥內，旦起忽失之。宣子知為所侮，略不見之辭色。他日奏事畢，從容以白上曰：\"鼠辈惡臣窮其奸，故為是以沮臣爾。\"上曰：\"何以處之？\"對曰：\"臣若張皇物色，正墮其計中，惟有置之不問。異時從吏部求一公據足矣，今未敢請也。\"上稱善。","sortOrder":33},
  {"id":"s_work_tddn_10_34","chapterId":"ch_work_tddn_10","text":"○配鹽幽菽","sortOrder":34},
  {"id":"s_work_tddn_10_35","chapterId":"ch_work_tddn_10","text":"昔傳江西一士，求見楊誠斋，頗以該洽自負。越數日，誠斋簡之雲：\"聞公自江西來配鹽幽菽，欲求少許。\"士人茫然莫晓，亟往謝曰：\"某讀書不多，實不知為何物？\"誠斋徐檢《禮部韻略》豉字示之，註雲：\"配鹽幽菽也。\"然其義亦未可深晓。《楚辭》曰：\"大苦鹹酸辛甘行。\"說者曰：\"大苦，豉也。言取豉汁調以鹹酢椒薑飴蜜，則辛甘之味皆發而行。\"然古無豆豉，史《急就篇》乃有\"芜夷鹽豉\"。《史記·货殖傳》有\"蘖曲鹽鼓中答\"。《三辅决錄》曰：\"前對大夫范仲公，鹽豉蒜果共一筒。\"蓋秦、漢以來始有之。","sortOrder":35},
  {"id":"s_work_tddn_10_36","chapterId":"ch_work_tddn_10","text":"○疽陰陽證","sortOrder":36},
  {"id":"s_work_tddn_10_37","chapterId":"ch_work_tddn_10","text":"族伯臨川推官，平生以體孱氣弱，多服乌附、丹砂。晚年疽發背，其大如扇，医者悉歸罪於丹石之毒，凡べ粉、羊血解毒之品，莫不遍试，殊不少損。或以後市街老祝医為荐者，祝本瘍医，然指下極精。诊脈已，即雲：\"非敢求異於諸公，然此乃極陰證。在我法中，正當多服伏火朱砂及三建湯，否則，非吾所知也。\"諸子皆有難色，然其势已殆，姑嘗试一二小料。而祝复俾作大剂，頓服三日後，始用膏藥敷貼，而丹砂、乌附略不輟口，餘半月而瘡遂平。凡服三建湯二百五十服，此亦可謂奇工矣。","sortOrder":37},
  {"id":"s_work_tddn_10_38","chapterId":"ch_work_tddn_10","text":"洪景盧所載，時康祖病心痔，用聖惠方治腰痛，鹿茸、附子藥服之而差。又福州郭医用茸，附医漏痔疾，皆此類也。蓋痈疽皆有陰陽證，要當一决於指下，而今世外科往往不善於脈，每以私意揣摩，故多失之，此不可不精察也。","sortOrder":38},
  {"id":"s_work_tddn_10_39","chapterId":"ch_work_tddn_10","text":"○陳周士","sortOrder":39},
  {"id":"s_work_tddn_10_40","chapterId":"ch_work_tddn_10","text":"禍福報應之說，多傅會傳訛，未可盡信。今有乡曲目击晓然一事，著之於此，以為世戒。陳周士造，直斋侍郎振孫之長子，登第為嘉禾ヘ，攝郡。一日，宴客於月波樓。有周監酒者勇爵，代庖於此，乃趙與篆德淵之隸。是日，適以小舟載客薄遊，初不知郡將之在樓也。周士適顧見，周急舣棹趨避。周士令詢之，知為周也，怒形於色曰：\"某不才，望輕，遂為一卒相侮如此。\"乃捃摭其數事，作書達之於趙，備言贓濫過惡。時趙守吳，即日遣逮，决脊編置，仍押至嘉禾示眾。時方炎暑，周士乃裸而暴之烈日中，瘡血臭腐，數日而死。臨危叹曰：\"陳通判屈打殺我，當訴之陰府矣。\"時寶祐丙辰季夏也。是歲十二月，周士疽發背而殂。吁！可畏哉！","sortOrder":40},
  {"id":"s_work_tddn_10_41","chapterId":"ch_work_tddn_10","text":"○秀王嗣袭","sortOrder":41},
  {"id":"s_work_tddn_10_42","chapterId":"ch_work_tddn_10","text":"秀安僖王，寿皇本生父也。用濮安懿王故事，以子孫嗣袭。安僖薨，子伯圭嗣，是為崇王，謚憲靖。長孫曰師夔，早卒，師揆嗣，是為澧王。師垂、師揆皆先卒，師禹嗣，是為和王。師皋又卒。師巖，寶慶元年自知慶元府入嗣，未朝謝而薨，是為永王。師弥以寶慶三年嗣，至寶祐六年，歷三十一年而後薨，是為润王。次師貢，先薨。曾孫希字行，亦皆先亡。至景定二年，元孫與泽以浙西仓歸班袭嗣，至鹹淳七年薨，是為臨海郡王。其次與先卒。是歲冬，與泽以知全州換授吉州刺史，主奉香火。其間以傍宗入繼者，蓋十居五六焉。","sortOrder":42},
  {"id":"s_work_tddn_11_1","chapterId":"ch_work_tddn_11","text":"●卷十","sortOrder":1},
  {"id":"s_work_tddn_11_2","chapterId":"ch_work_tddn_11","text":"○古今左右之辨","sortOrder":2},
  {"id":"s_work_tddn_11_3","chapterId":"ch_work_tddn_11","text":"南人尚左，北人尚右，或問孰為是？因考其說於此，與有識者订之。《檀弓》鄭氏註雲：\"丧尚右，右、陰也；吉尚左，左、陽也。\"《老子》亦雲：\"吉事尚左，凶事尚右。\"河上公註：\"左，生位也；右，陰道也。\"《禮正義》：\"案特牲、少牢，吉祭皆載右畔。\"《士虞禮》：\"凶事載左畔，吉祭載右畔。從地道尊右，凶事載左畔，取其反吉也。\"《老子》又曰：\"偏將軍處左，上將軍處右。\"河上公註：\"卑而居陽，以其不专殺，尊而居左，以其主殺也。\"吳世杰《漢書刊誤》雲：\"凶事尚右，孔子有娣之丧之事也。\"《禮》：\"乘君之乘車，不敢曠左。\"註謂：\"車上貴左，乘車則貴左，兵車則貴右。乘車，君在左，御者在中。兵車，君在中，御者在左。\"《少儀》論乘兵車雲：\"軍尚左。\"《毓》雲：\"軍將尊，尚左。\"按《老子》\"上將軍處右，偏將軍處左\"，非指車同言也。《左傳》：\"韓厥代御，居中。\"杜註：\"自非元帥，御皆在中，將在左。\"乃知兵車惟君及元帥然後尚右，其餘軍將亦尚左而已。按古人主當阼，以右為尊而遜客，而己居左，則左非尊位也。後世以左為主位，而貴不敢當，則以左為尊也。如魏無忌迎侯生，而虛車左，何也？地道陰道尚右，故後世之祀，以右為上，今宗廟亦然。人家門符，左神荼，右鬱壘，考張平子賦亦雲：\"守以鬱壘，神荼副焉。\"《左傳》載：\"天子所右，寡君亦右之；天子所左，寡君亦左之。\"則以右為助之重且大者。漢右賢左戚。他如左官，左遷，又皆以左為輕。或謂左手足不如右強，故論輕重者，必重右而輕左。（漢製尚右，詳見《班史》）","sortOrder":3},
  {"id":"s_work_tddn_11_4","chapterId":"ch_work_tddn_11","text":"○《史記》多誤","sortOrder":4},
  {"id":"s_work_tddn_11_5","chapterId":"ch_work_tddn_11","text":"班孟堅《漢書》，大抵沿袭《史記》，至於季布、萧何、袁盎、張騫、衛霍、李廣等贊，率因《史記》舊文稍增損之（《張騫贊》，即《史記·大宛傳》後）。或有全用其語者，前作後述，其體當然。至如《司馬相如傳贊》，乃固所自為，而《史記》乃全載其語，而作太史公曰，何邪？又遷在武帝時，雄生漢末，亦安得謂\"扬雄以為靡麗之賦，勸百而諷一\"哉？諸家註釋，皆不及之。又《公孫弘傳》，載平帝元始中，詔賜弘子孫爵。徐廣註謂\"後人寫此以續卷後\"，然則相如之贊，亦後人剿入，而誤以為太史公無疑。","sortOrder":5},
  {"id":"s_work_tddn_11_6","chapterId":"ch_work_tddn_11","text":"至若《管仲傳》雲\"後百餘年有晏子\"，《孫武傳》雲\"後百餘歲有孫臏\"，《屈原傳》雲\"後百餘年有贾生\"，皆以其近似類推之耳。至於。《優孟傳》雲\"其後二百餘年秦有優旃\"，而《淳於髡傳》亦雲\"其後百餘年楚有優孟\"，何邪？殊不思優孟在楚莊王時，淳於髡在齊威王時。楚莊乃春秋之世，齊威乃戰國之時，謂前百餘年楚有優孟可也，今乃错谬若此。且先傳髡而後叙孟，其次序晓然，謂之非誤，可乎？","sortOrder":6},
  {"id":"s_work_tddn_11_7","chapterId":"ch_work_tddn_11","text":"○文章相類","sortOrder":7},
  {"id":"s_work_tddn_11_8","chapterId":"ch_work_tddn_11","text":"李德裕《文章論》雲：\"文章當如千兵萬馬，風恬雨霁，寂無人聲。\"黃夢升《題兄子庠之辭》雲：\"子之文章，電激雷震，雨雹忽止，阒然泯滅。\"欧公喜誦之，遂以此語作《祭蘇子美文》雲：\"子之心胸，蟠屈龍蛇，風雲变化，雨雹交加，忽然揮斥，霹靂轟車。人有遭之，心驚胆破，震汗如麻。須臾霁止，而四顧山川草木，开發萌芽。子於文章，雄豪放肆，有如此者，吁可怪耶！東坡《跋薑君弼課策》亦雲：\"雲興天际，然車蓋，凝盧未舜，弥漫ЩЪ。驚雷出火，乔木糜碎，般地空，萬夫皆废。溜練四墜，日中見沫，移晷而收，野無完塊。\"張文潛《雨望賦》雲：\"飄風击雲，奔曠萬里，一蔽率然如百萬之卒赴敵骤戰兮，車旗崩騰而矢石亂至也。已而餘飄既定，盛怒已泄，雲逐逐而散歸，縱橫委乎天末。又如戰勝之兵，整旗就队，徐驅而回歸兮，杳然惟見夫川平而野闊。\"皆同此一機括也。","sortOrder":8},
  {"id":"s_work_tddn_11_9","chapterId":"ch_work_tddn_11","text":"○楊太後","sortOrder":9},
  {"id":"s_work_tddn_11_10","chapterId":"ch_work_tddn_11","text":"慈明楊太後養母張夫人善聲伎。隨夫出蜀，至儀真長芦寺前僦居。主僧善相，適出見之，知其女當貴。因招其父母飯，語之故，且勉之往行都，當有所遇。以無資告，僧以二千楮假之，遂如杭。或导之入慈福宮，為樂部頭。後方十歲，以為則剧孩兒。憲聖尤愛之，舉動無不當後意。有嫉之者，適太皇入浴，儕辈俾服後衣冠為戲，因谮之後。後笑曰：\"汝辈休驚，他將來會到我地位上在。\"其後茂陵每至後所必目之，後知其意。一日內宴，因以為賜，且曰：\"看我面，好好看他。\"傅伯寿草《立後製》有雲：\"洪惟太母，念我文孫。美其冠於後庭，俾之見於內殿。\"蓋紀實也。既貴，恥其家微，陰有所遺，而絕不與通。密遣內求同宗，遂得右庠生嚴陵楊次山以為侄。既而宣召入見，次山言與淚俱，且指他事為验，或謂皆後所授也。後初姓某，至是始歸姓楊氏焉。次山隨即補官，循至節鉞郡王雲。（長芦僧事與章獻玉泉事絕相類）","sortOrder":10},
  {"id":"s_work_tddn_11_11","chapterId":"ch_work_tddn_11","text":"○脱靴返棹二圖贊","sortOrder":11},
  {"id":"s_work_tddn_11_12","chapterId":"ch_work_tddn_11","text":"牟存叟端明守當涂日，郡圃有脱靴亭，以謫仙采石得名，存叟繪以為圖。又以山穀崇寧初守當涂，方九日而罢，蓋坐嘗作《荆州承天院塔記》，轉運判官陳舉承執政趙挺之風旨，摘其間數語以為幸灾謗國，除名謫宜州，遂作《返棹》一圖以為對。各系以贊，未幾流傳中都。時相丁大全、內侍董宋臣聞而惡之，遂捃摭其在都日饋遺過客錢酒等物，併指為贓。下所居郡，監逮甚嚴。自此朝紳結舌，馴致开慶之禍焉。","sortOrder":12},
  {"id":"s_work_tddn_11_13","chapterId":"ch_work_tddn_11","text":"二贊削稿久矣，餘偶得之。《脱靴》雲：\"錦袍兮乌帻，神清兮氣逸，凌轹兮萬象，麾斥兮八極。我思古人，伊李太白。孰為使之朝禁林而暮采石也，其天寶之嬖幸欤？疏レ詞章，浸润宮掖。吾觀脱靴之圖，未嘗不嫉小人之情状，而傷君子之疏直。惟公之高躅兮，霍神龍之不可以羁绁。矧富貴如敝屣兮，其得失又何所欣戚也。\"","sortOrder":13},
  {"id":"s_work_tddn_11_14","chapterId":"ch_work_tddn_11","text":"《返棹》雲：\"幅巾兮野服，貌腴兮神肅，孤騫兮風雅，唾视兮爵祿。我思古人，伊黃山穀。曷為使之六年道而九日姑孰也，其符紹之朋党欤？組織寺記，指レ實錄。吾觀返棹之圖，未嘗不感君子之流落，而痛小人之報复。惟公之高風兮，渺驚鸿之不可以信宿。矧吾道猶虛舟兮，其去來又何所榮辱也。\"","sortOrder":14},
  {"id":"s_work_tddn_11_15","chapterId":"ch_work_tddn_11","text":"予嘗謂山穀初以言語掇禍，公又以山穀得罪，是殆有數。然清名照映於二百年間，士之生世，亦何憚而不為君子哉！","sortOrder":15},
  {"id":"s_work_tddn_11_16","chapterId":"ch_work_tddn_11","text":"○輕容方空","sortOrder":16},
  {"id":"s_work_tddn_11_17","chapterId":"ch_work_tddn_11","text":"紗之至輕者，有所謂輕容，出唐《類苑》雲：\"輕容，無花薄紗也。\"王建《宮詞》雲：\"嫌羅不著愛輕容。\"元微之有寄白樂天白輕容，樂天製而為衣。而詩中容字乃為流俗妄改為庸，又作榕，蓋不知其所出。《元丰九域志》：\"越州歲貢輕容紗五匹\"是也。","sortOrder":17},
  {"id":"s_work_tddn_11_18","chapterId":"ch_work_tddn_11","text":"又有所謂方空者。《漢元帝紀》：\"罢齊三服官。\"註雲：\"春獻冠帻，纟徙為首服，紈素為冬服，輕绡為夏服，凡三。\"師古曰：\"纟徙與纟徙同音山爾反，即今之方目紗也。\"又後漢建初二年，詔齊相省冰紈、方空、吹纶絮。紈，素也。冰，言色鮮絜如冰。《釋名》曰：\"綬方空者，紗薄如空也。\"或曰：\"空，孔也。即今之方目紗也。纶如絮而細，吹者，言吹噓可成此紗也。\"荆公詩雲\"春衫猶未著方空\"者是也。","sortOrder":18},
  {"id":"s_work_tddn_11_19","chapterId":"ch_work_tddn_11","text":"二紗名，世少知，故表出之。","sortOrder":19},
  {"id":"s_work_tddn_11_20","chapterId":"ch_work_tddn_11","text":"○范公石湖","sortOrder":20},
  {"id":"s_work_tddn_11_21","chapterId":"ch_work_tddn_11","text":"文穆范公成大，晚歲卜筑於吳江盤門外十里。蓋因阖闾所筑越來溪故城之基，隨地势高下而為亭榭。所植多名花，而梅尤多。別筑農圃堂對楞伽山，臨石湖，蓋太湖之一派，范蠡所從入五湖者也，所謂姑蘇前後台，相距亦止半里耳，寿皇嘗御書\"石湖\"二大字以賜之。公作《上梁文》，所謂\"吳波萬頃，偶維風雨之舟；越戍千年，因筑湖山之歡\"者是也。又有北山堂、千巖觀、天鏡閣、寿樂堂，他亭宇尤多。一時名人勝士，篇章賦詠，莫不極鋪張之美。","sortOrder":21},
  {"id":"s_work_tddn_11_22","chapterId":"ch_work_tddn_11","text":"乾道壬辰三月上巳，周益公以春官去國，過吳，范公招飲園中。夜分，題名壁間雲：\"吳台、越壘，距門才十里，而陆沉於荒煙蔓草者千七百年。紫薇舍人，始創別墅，登臨得要，甲於東南。豈鴟夷子成功於此，扁舟去之，天絕景，須苗裔之賢者，然後享其樂邪？\"為击節，而前後所題盡废焉。","sortOrder":22},
  {"id":"s_work_tddn_11_23","chapterId":"ch_work_tddn_11","text":"○多蚊","sortOrder":23},
  {"id":"s_work_tddn_11_24","chapterId":"ch_work_tddn_11","text":"吳興多蚊，每暑夕浴罢，解衣盤礴，則營營群聚，嘬不容少安，心每苦之。坡翁嘗曰：\"湖州多蚊蚋，豹腳尤甚。\"且見之詩雲：\"飛蚊猛捷如花鷹。\"又雲：\"風定軒窗飛豹腳。\"蓋湖之豹腳蚊著名久矣。舊傳崇王入侍寿皇，聖語雲：\"聞湖州多蚊，果否？\"後侍宴，因以小金盒貯豹腳者數十枚進呈。蓋不特著名，亦且尘乙覽矣。","sortOrder":24},
  {"id":"s_work_tddn_11_25","chapterId":"ch_work_tddn_11","text":"蓋蚊乃水虫所化，泽國故應爾。聞京師獨馬行街無蚊蚋，人以為井市燈火之盛故也。吳興獨江子匯無蚊，舊傳馬自然嘗泊舟於此所致。故錢信《平望蚊》詩雲：\"安得神仙術，试為施康濟，使此平望村，如吾江子匯。\"然餘有小樓在臨安軍將桥，面臨官河，污秽特甚。自暑徂秋，每夕露眠，寂無一蚊，過此仅數百步，則不然矣，此亦物理之不可晓者。渡淮蚊蚋尤盛，高郵露筋廟是也。孫公《談圃》雲：\"泰州西洋多蚊，使者按行，以艾煙薰之，方少退。有一廳吏醉仆，為蚊所而死。世傳范文正詩雲：\"飽似櫻桃重，飢如柳絮輕，但知從此去，不要問前程。\"即其地也。聞大河以北，河水一解，如雲如煙。若信、安、沧、景之間，夏月牛馬皆涂之以泥，否則必為所毙。","sortOrder":25},
  {"id":"s_work_tddn_11_26","chapterId":"ch_work_tddn_11","text":"按《爾雅》：\"真、[B177]母，一名蚊母，相傳此鳥能吐蚊。\"陳藏器雲：\"其聲如人呕吐，每吐辄出蚊一二升。\"李肇《唐史補》稱：\"江東有蚊母鳥，亦謂之吐蚊鳥。夏夜則鳴吐蚊於丛苇間，湖州尤甚。\"又曰：\"端新州有鳥，類青而嘴大。常於池塘捕魚，每一鳴，則蚊群出其口，亦謂之吐蚊鳥，又謂之真；然以其羽為扇，却可辟蚊。嶺南又有蚊子木，實如枇杷，熟則自裂，蚊盡出而實空。塞北又有蚊母草者，其說亦然。\"《淮南子》曰：\"水蠆為兼，孑分為[B177]，兔為能。物之所為，出於不意，弗知者驚，知者不怪。\"今孑分，污水中無足虫也，好自伸屈於水上，見人辄沉，久則蜕而為蚊，蓋水虫之所变明矣。東方朔隱語雲：\"長喙細身，晝亡夜存，嗜肉惡煙，為指掌所扪。\"若生草中者，吻尤利，而足有文彩，號為豹腳。又其字或從昏，志其時也，又為閩，以虫之在門中也。《說文》曰：\"秦謂之蚋，楚謂之蚊。\"《夏小正》雲：\"丹鳥，螢也。羞白鳥，謂螢以蚊為糧雲。\"","sortOrder":26},
  {"id":"s_work_tddn_11_27","chapterId":"ch_work_tddn_11","text":"然則育蚊者非一端，固不可专歸罪於水也。因萃數說，戲為吾乡解嘲。（孑，俱折反；分，勿二反）","sortOrder":27},
  {"id":"s_work_tddn_11_28","chapterId":"ch_work_tddn_11","text":"○俞侍郎執法","sortOrder":28},
  {"id":"s_work_tddn_11_29","chapterId":"ch_work_tddn_11","text":"吾乡前辈俞且軒侍郎，善墨戲竹石，蓋源流射泽而自成一家，逮今為人寶重。然人知其能畫，而不知其為人，因書其概於此。","sortOrder":29},
  {"id":"s_work_tddn_11_30","chapterId":"ch_work_tddn_11","text":"侍郎名澄字子清，用伯祖閣學俟（宇居易）恩入仕，中刑法科。短小精悍，清談簡約，樂易無涯岸，而居官守正不阿。其為福建檢法，陳應澄丞相帥三山，治盜過嚴，一日，驅數十囚欲投諸海。澄白其長曰：\"朝廷有憲部而郡國無憲台，可乎？\"力爭之，因命閱實。遂為區別戮者、黥者各若幹。陳始怒而後喜其有守，悉從之，且荐以京削。為刑部郎日，有乡豪素以俠稱，為時所畏。殺人諉罪其奴。獄上，驳之，請自鞫豪，因得其直。光宗壮之，即日除大理少卿，然竟為豪挤去。又常德有舟艄程亮，殺巡檢宋正國一家十二口，累歲始獲，乃在寧廟登極赦前，吏受其賂，欲出之。澄奏援太祖朝戮范義超故事，以為殺人於異代，既更开國大霈，猶所不赦，况亮乎？於是遂正典刑，他可紀者尚多。後權刑部侍郎，以侍製致仕，家居十年乃終，年七十八。且軒，其自號也。俞氏自退翁起家，未七十而納祿者，至澄凡五人。且皆享高年，有園池、琴書、歌舞之樂，乡曲榮之。後餘得竹石二紙於故家，葉如黍米，石亦奇润，自成一家。上題印曰\"居易戲作\"，蓋閣學俟所為也。因知子清戲墨有所來，此亦人所未知者，因併表而出之。","sortOrder":30},
  {"id":"s_work_tddn_11_31","chapterId":"ch_work_tddn_11","text":"○尹惟晓詞","sortOrder":31},
  {"id":"s_work_tddn_11_32","chapterId":"ch_work_tddn_11","text":"梅津尹涣惟晓未第時，嘗薄遊苕溪籍中，適有所盼。後十年，自吳來，舣舟碧澜，問訊舊遊，則久為一宗子所據，已育子，而猶掛名籍中。於是假之郡將，久而始來。顏色瘁赧，不足膏沐，相對若不勝情。梅津為賦《唐多令》雲：\"蓣末轉清商，溪聲供夕涼。缓傳杯，催唤紅妆。煥綰乌雲新浴罢，拂地水沉香。歌短舊情長，重來驚鬢霜。怅绿陰，青子成双。說著前歡佯不采；莲子，打鴛鴦。\"數百載而下，真可與杜牧之\"尋芳较晚\"之為偶也。","sortOrder":32},
  {"id":"s_work_tddn_11_33","chapterId":"ch_work_tddn_11","text":"○都廁","sortOrder":33},
  {"id":"s_work_tddn_11_34","chapterId":"ch_work_tddn_11","text":"《劉安別傳》雲：\"安既上天，坐起不恭。仙伯主者，奏安不敬，應斥。八公為安謝過，乃赦之，謫守都廁三年。\"半山詩雲：\"身與仙人守都廁，可能雞犬得長生？\"然則都廁者，得非今世俗所謂都坑乎？","sortOrder":34},
  {"id":"s_work_tddn_11_35","chapterId":"ch_work_tddn_11","text":"然廁字亦有數義。《說文》雲：\"惲、廁也，圊也。\"《莊子·庚桑楚篇》：\"適其偃。\"註雲：\"偃，屏廁也。屏廁則以偃溲。\"《儀禮·既夕禮》：\"甸人筑冷坎，隸人涅廁、塞廁。\"《萬石君傳》：\"建為郎中，每五日歸謁親，切問侍者，取親中裙廁〈片俞〉，身自浣洗。\"孟康註曰：\"廁，行清；〈片俞〉，行中受粪函也。\"","sortOrder":35},
  {"id":"s_work_tddn_11_36","chapterId":"ch_work_tddn_11","text":"他如：晉侯食麥，脹如廁，陷而卒。趙襄子如廁，心動，執豫讓。高祖如廁，心動，見柏人。金日讠阎如廁，心動，擒莽何羅。范睢佯死置廁中。李斯如廁見鼠。贾姬如廁逢彘。陶侃如廁見朱有。劉、王敦併誤入石崇廁。郭璞被發廁上。劉和季廁上置香爐。沈慶之夢滷簿入廁中。崔浩焚經投廁中。錢義廁神。李赤廁鬼。文類甚多，皆為溷廁之廁無疑。","sortOrder":36},
  {"id":"s_work_tddn_11_37","chapterId":"ch_work_tddn_11","text":"而《汲黯傳》：\"大將軍青侍中，上踞廁見之。\"音訓則謂床邊為廁。《張敞傳》：\"孝文皇帝居霸陵，比臨廁。\"服虔註曰：\"廁、侧臨水。\"韦昭則曰：\"高岸狹水為廁。\"《張釋之傳》：\"從行至霸陵，上居外臨廁。\"師古註亦曰：\"岸之邊侧也。\"因併考著於此雲。","sortOrder":37},
  {"id":"s_work_tddn_11_38","chapterId":"ch_work_tddn_11","text":"○敬巖註《唐書》","sortOrder":38},
  {"id":"s_work_tddn_11_39","chapterId":"ch_work_tddn_11","text":"王元敬大卿亻必，強直自遂，不輕許可，嘗註《唐書》，自以為人莫能及。括蒼老士某者，深於史學，亦嘗增註《唐書》，因携以求正焉。王讀至建成、元吉之事，遽笑雲：\"建成，储君也，當以弒書，豈得謂殺？此書殊未然。\"遂掷還之。某士者大不平，徐起答之曰：\"殺兄之字，蓋本《孟子》'象日以殺舜為事'，今卿弒兄之字，出於何書？\"王仓卒無以為對。是知文字未可以輕訾議也。","sortOrder":39},
  {"id":"s_work_tddn_11_40","chapterId":"ch_work_tddn_11","text":"○黃子由夫人","sortOrder":40},
  {"id":"s_work_tddn_11_41","chapterId":"ch_work_tddn_11","text":"黃子由尚書夫人胡氏，與可元功尚書之女也。俊敏強記，經史諸書略能成誦。善筆札，時作詩文亦可觀。於琴奕寫竹等藝尤精，自號惠斋居士，時人比之李易安雲。","sortOrder":41},
  {"id":"s_work_tddn_11_42","chapterId":"ch_work_tddn_11","text":"時趙師Э從善知臨安府，立放生池碑於湖上，高文虎炳如內翰為之作記，誤書\"鳥獸魚鱉，鹹若商歷以興\"。既以锓石分送朝行，夫人一誦，即知其誤。會炳如以藏頭策題得罪多士，而從善又以學舍張蓋殴人等，嘗斷其仆。諸士既聞其事，遂作小詞譏詆之：\"作為夏王道不是商王，这鳥獸魚鱉是你者？\"乃胡氏首指其誤也。他日，胡氏殂，其婢竊物以逃，捕得之，送臨安府。從善衔之，遂鞫其婢，指言主母平日與奕者鄭日新通（鄭、越人，世號越童），所失物乃主母與之耳，因逮鄭系獄黥之。未幾，子由以帷薄不修去國。事之有無固不可知，而從善之用心亦薄矣。","sortOrder":42},
  {"id":"s_work_tddn_11_43","chapterId":"ch_work_tddn_11","text":"後十餘年，從善死，其子希蒼亦死。其婦錢氏茕處，獨任一仆幹主家事。有老仆知其私，頗持之。錢氏與幹者欲滅其口，遂以他事系官，竟毙於獄，且擅焚之。未幾，仆家聲其冤於憲台。時林介持憲節方振風采，遂逮錢氏於庭，經營巨援，仅爾獲免，而幹者遂從黥籍。信人之存心，不可以不近厚，而報复之理，昭昭不容掩也如此。","sortOrder":43},
  {"id":"s_work_tddn_11_44","chapterId":"ch_work_tddn_11","text":"○洪景盧自矜","sortOrder":44},
  {"id":"s_work_tddn_11_45","chapterId":"ch_work_tddn_11","text":"洪景盧居翰苑日，嘗入直，值製詔沓至，自早至脯，凡视二十餘草。事竟，小步庭間，見老叟負暄花陰。誰何之？雲：\"京師人也，累世為院吏，今八十餘，幼時及識元祐間諸學士，今子孫复為吏，故養老於此。\"因言：\"聞今日文書甚多，學士必大勞神也。\"洪喜其言，曰：\"今日草二十餘製，皆已畢事矣。\"老者复頌雲：\"學士才思敏捷，真不多見。\"洪矜之雲：\"蘇學士想亦不過如此速耳。\"老者复首肯咨嗟曰：\"蘇學士敏捷亦不過如此，但不曾檢閱書册耳。\"洪為赧然，自恨失言。嘗對客自言如此，且雲：\"人不可自矜，是時使有地縫，亦當入矣。\"","sortOrder":45},
  {"id":"s_work_tddn_11_46","chapterId":"ch_work_tddn_11","text":"○吳郡王冷泉畫贊","sortOrder":46},
  {"id":"s_work_tddn_11_47","chapterId":"ch_work_tddn_11","text":"莊簡吳秦王益，以元舅之尊，德寿特親愛之，入宮，每用家人禮。憲聖常持盈滿之戒，每告之曰：\"凡有宴召，非得吾旨，不可擅入。\"一日，王竹冠練衣，芒鞋筇杖，獨携一童，縱行三竺、靈隱山中，濯足冷泉磐石之上，遊人望之，俨如神仙，遂為邏者聞奏。次日，德寿以小詩召之曰：\"趁此一軒風月好，橘香酒熟待君來。\"令小當持賜，王遂亟往。光尧迎見，笑謂曰：\"夜來冷泉之遊，樂乎？\"王恍然頓首謝。光尧曰：\"朕宮中亦有此景，卿欲見之否？\"蓋壘石疏泉，像飛來香林之勝。架堂其上曰冷泉。中揭一畫，乃圖莊簡野服濯足於石上，且御製一贊雲：\"富貴不驕，戚畹稱賢。扫除膏粱，放曠林泉。沧浪濯足，風度萧然。國之元舅，人中神仙。\"於是盡醉而罢，因以賜之，亦可謂戚畹之至榮矣。畫今藏其曾孫絜家，餘嘗見之。","sortOrder":47},
  {"id":"s_work_tddn_11_48","chapterId":"ch_work_tddn_11","text":"○絹紙","sortOrder":48},
  {"id":"s_work_tddn_11_49","chapterId":"ch_work_tddn_11","text":"坡翁嘗醉中為河陽鄭ヘ書，明日视之，紙乃絹也，遂自題於後雲：\"古者本謂絹紙，近世失之雲。\"蓋古人多以絹為紙，乌絲欄乃織成為卷而書之。所謂{爾虫}紙者，亦以{爾虫}為紙也。按《蔡倫傳》雲：\"用缣帛者，謂之紙。缣貴簡重，不便於人，乃用木膚麻皮等。\"","sortOrder":49},
  {"id":"s_work_tddn_11_50","chapterId":"ch_work_tddn_11","text":"隋《修文殿御覽》，載晉人藏書數，有白絹草書、白絹行書、白鍛絹楷書之目。又魏太和間，博士張楫上《古今字帖》，其《巾部》辨紙字雲：\"今世其字從巾。蓋古之素帛，依舊長短，隨事截絹，枚數重壘，即名蟠紙，故字從糸，此形聲也。蔡倫以布捣М作紙，故字從巾，是其聲雖同，而糸、巾則殊也。\"盧仝《茶歌》有\"白絹斜封三道印\"之句，豈以絹書之邪？","sortOrder":50},
  {"id":"s_work_tddn_11_51","chapterId":"ch_work_tddn_11","text":"○談重薄命","sortOrder":51},
  {"id":"s_work_tddn_11_52","chapterId":"ch_work_tddn_11","text":"吳興人談重元鼎少領乡荐不第，晚就南廊，更數试，复不入等。章文莊兄弟皆與之同舍。嘉定戊辰，文莊兄弟在朝，談入京將更试，請曰：\"二兄何以授我？\"乃相與作備對數十付。已而文莊入為考官，得談卷甚喜。所批稍高，編排當在上二等。已而曰：\"名器不可以故人私之，但使脱助教足矣。\"於是稍移向下。既而算計四等，合放若幹，而談之名適在末等之首，竟垂翅而歸。一文學之微，造物亦靳之耶？","sortOrder":52},
  {"id":"s_work_tddn_11_53","chapterId":"ch_work_tddn_11","text":"○椰酒菊酒","sortOrder":53},
  {"id":"s_work_tddn_11_54","chapterId":"ch_work_tddn_11","text":"今人以椰子漿為椰子酒，而不知椰子花可以酿酒。唐殷尧封《寄嶺南張明府》詩雲：\"椰花好為酒，誰伴醉如泥。\"","sortOrder":54},
  {"id":"s_work_tddn_11_55","chapterId":"ch_work_tddn_11","text":"九日菊酒，以淵明采菊，白衣送酒得名。而不知《西京雜記》所載菊花酒法，以菊花舒時，併采茎葉雜秫米酿之，至來年九月九日始熟。此皆目前之事，而未有言者，何也？","sortOrder":55},
  {"id":"s_work_tddn_11_56","chapterId":"ch_work_tddn_11","text":"○《混成集》","sortOrder":56},
  {"id":"s_work_tddn_11_57","chapterId":"ch_work_tddn_11","text":"《混成集》，修內司所刊本，巨帙百餘。古今歌詞之譜，靡不備具。只大曲一類凡數百解，他可知矣，然有譜無詞者居半。《霓裳》一曲共三十六段。嘗聞紫霞翁雲，幼日隨其祖郡王曲宴禁中，太後令內人歌之，凡用三十人，每番十人，奏音極高妙。翁一日自品象管作數聲，真有駐雲落木之意，要非人間曲也。又言：\"無太皇最知音，極喜歌。木笪人者，以歌《杏花天》，木笪遂補教坊都管。\"間憶舊事，因書之以遺好事者，蓋二曲皆今人所罕知雲。","sortOrder":57},
  {"id":"s_work_tddn_11_58","chapterId":"ch_work_tddn_11","text":"○明真王真人","sortOrder":58},
  {"id":"s_work_tddn_11_59","chapterId":"ch_work_tddn_11","text":"王妙堅者，本興國軍九宮山道嫗也。居常以符水咒棗等術行乞村落，碌碌無他異。既而至杭，多遊西湖兩山中。一日，至西陵桥茶肆少憩，適其鄰有陳生隸職御酒库。其妻適見之，因扣以婦人頭直（音腻）不可疏者，還可禳解否？嫗曰：\"此特細事。\"命市真麻油半斤，燒竹瀝投之，且為持咒，俾之沐發。蓋是時恭聖楊後方誅韓，心有所疑，而發直不解，意有物出示，以此遍求禳治之術。會陳妻以油進，用之良验，意頗神之，遂召妙堅入宮，賜予甚厚，日被親幸。且為創道宇，賜名明真，俾主之，累封真人。","sortOrder":59},
  {"id":"s_work_tddn_11_60","chapterId":"ch_work_tddn_11","text":"同時有黃冠易如刚者，嗜酒夸誕，薄知其事，欲以奇動。於是以黃絹方丈帚書大符以進。後大喜，賜予亦渥，後住太乙東宮。","sortOrder":60},
  {"id":"s_work_tddn_11_62","chapterId":"ch_work_tddn_11","text":"《詩》曰：\"王之爪牙。\"故軍將皆建旗於前，日\"大牙\"，凡部曲受約束，禀進退，悉趨其下。近世重武，通謂刺史治所曰牙。緣是從卒為牙中兵，武吏為牙前將。俚語誤轉為衙。","sortOrder":62},
  {"id":"s_work_tddn_11_63","chapterId":"ch_work_tddn_11","text":"《珩璜論》雲：\"突厥畏李靖，徙牙於碛中。牙者，旗也。\"《東京賦》：\"竿上以牙飾之，所以自表識也。太守出有門旗，其遺法也。\"後人遂以牙為衙，早晚衙，亦太守出則建旗之義。或以衙為廨舍，兒子為衙內。《唐韻》註：\"衙，府也。\"亦訛。","sortOrder":63},
  {"id":"s_work_tddn_11_64","chapterId":"ch_work_tddn_11","text":"武德元年，宇文化及下牙，方敢啟状。《釋文》：\"牙，旗名也，軍中所建。\"高保勖病，召衙內指揮使梁延副；衙內，蓋官稱耳。唐謂前殿為正衙，豈亦以衛仗建旗而名邪？","sortOrder":64},
  {"id":"s_work_tddn_11_65","chapterId":"ch_work_tddn_11","text":"○字舞","sortOrder":65},
  {"id":"s_work_tddn_11_66","chapterId":"ch_work_tddn_11","text":"州郡遇聖節錫宴，率命猥妓數十群舞於庭，作\"天下太平\"字，殊為不經。而唐《樂府雜錄》雲：\"舞有字，以舞人亚身於地，布成字也。\"王建《宮詞》雲：\"羅衫葉葉繡重重，金鳳銀鹅各一丛。每遇舞頭分兩向，太平萬歲字當中。\"則此事由來久矣。","sortOrder":66},
  {"id":"s_work_tddn_12_1","chapterId":"ch_work_tddn_12","text":"●卷十一","sortOrder":1},
  {"id":"s_work_tddn_12_2","chapterId":"ch_work_tddn_12","text":"○黃德润先見","sortOrder":2},
  {"id":"s_work_tddn_12_3","chapterId":"ch_work_tddn_12","text":"黃洽德润事阜陵為台諫，執政未嘗有大建明，或譏其循默。淳熙末，上將內禪。一日，朝退，留二府賜坐，從容諭及倦勤之意，諸公交贊，公獨無語。上顧曰：\"卿以為何如？\"對曰：\"皇太子聖德，誠克負荷。顧李氏不足母天下，宜留聖慮。\"上愕然色变。公徐奏：\"陛下問臣，臣不敢自默。然臣既出此語，自今不得复觐清光，陛下異日思臣之語，欲复見臣，亦不可得矣。\"退即求去甚力，以大資政知潭州。","sortOrder":3},
  {"id":"s_work_tddn_12_4","chapterId":"ch_work_tddn_12","text":"後寿皇在重華宮，每撫幾叹曰：\"悔不用黃洽之言。\"或至淚下。","sortOrder":4},
  {"id":"s_work_tddn_12_5","chapterId":"ch_work_tddn_12","text":"○譜牒難考","sortOrder":5},
  {"id":"s_work_tddn_12_6","chapterId":"ch_work_tddn_12","text":"欧公著族譜，號為精密。其言詢生通，自通三世生琮，為吉州刺史，當唐末，黃巢陷州縣，率州民捍賊，乡里賴以保全，琮以下譜亡。自琮八世生萬，為安福令，公為安福九世孫。","sortOrder":6},
  {"id":"s_work_tddn_12_7","chapterId":"ch_work_tddn_12","text":"以是考之，詢在唐初，至黃巢時，幾三百年，仅得五世。琮在唐末，至宋仁宗才百四十五年，乃為十六世，恐無是理。後世譜牒散亡，其難考如此。欧陽氏無他族，其源流甚明，尚爾，矧他姓邪？","sortOrder":7},
  {"id":"s_work_tddn_12_8","chapterId":"ch_work_tddn_12","text":"○滕茂實","sortOrder":8},
  {"id":"s_work_tddn_12_9","chapterId":"ch_work_tddn_12","text":"滕茂實字秀穎，吳人（國史作杭州人）。初名裸，登政和第，徽宗改賜今名。靖康初，以太學正兼明堂司令，與路允迪、宋彦通奉使金國，割三镇。太原尋奉密詔，據城不下，金人怒之，囚於雲中。淵聖北遷，茂實冠裳迎謁，拜伏號泣，請侍舊主俱行。不從，且誘之曰：\"國破主遷，所以留公者，蓋將大用。\"遂留之雁門。","sortOrder":9},
  {"id":"s_work_tddn_12_10","chapterId":"ch_work_tddn_12","text":"先是，自分必死，遂嘱友人董诜以奉使黃幡裹尸而葬，且大書九篆字雲：\"宋使者東陽滕茂實墓。\"复作詩，自叙雲：\"茂實奉使無状，不复返父母之邦，所當從其主以全臣節。或怒而與之死，幸以所杖幡裹其尸，及以所篆九字刊之石，埋之台山寺下，不必封树。蓋昔年病中，嘗夢遊清涼境界，覺而病愈，恐亦前緣。今預作哀辭，幾於不達，方之淵明則不可，若蘇屬國牧羊海上，而五言之作，始敢援此例雲。\"詩曰：\"齏鹽老書生，缪列王都官，索米了無補，從事敢辭難。殊怜复盟好，仗節來榆關，城守久不下，川途望漫漫。俭辈果不惜，一往何當還。牧羊困蘇武，假道拘張騫。流離念窘束，坐閱四序遷，同來悉已歸，我獨留塞垣。形影自相弔，國破家亦殘，呼天竟不聞，痛甚傷肺肝。相逢老兄弟，悼叹安得歡，波澜卷大厦，一木難求安。就不违我心，渠不汗我顏。昔燕破齊土，群臣望風奔，王獨守節，齊人有甘言。經首自絕ㄕ，感慨今昔聞，未嘗食齊祿，徒以老為民。况我祿數世，一死何足論，遠或没江海，近或死朝昏。斂我不須衣，裹尸以黃幡，題作宋臣墓，篆字當深刊。我室年尚少，兒女皆童顽，四海無置錐，飄流倍悲酸。誰當給衣食，使不厄飢寒。歲時一酹我，猶足慰我魂，我魂亦悠悠，異乡寄沉冤。他時風雨夜，草木號空山。\"","sortOrder":10},
  {"id":"s_work_tddn_12_11","chapterId":"ch_work_tddn_12","text":"後竟以忧憤成疾殂。北人哀其忠，為之起墓雁門山，歲時致祭焉。","sortOrder":11},
  {"id":"s_work_tddn_12_12","chapterId":"ch_work_tddn_12","text":"所記張浮休之弟確，嘗為乌延帥幕，獨不庭謁。童貫及徽宗本以五月五日生，以俗忌移之十月十日，皆可以補史闕。","sortOrder":12},
  {"id":"s_work_tddn_12_13","chapterId":"ch_work_tddn_12","text":"後董诜自拔歸南，上所為詩，赠直龍圖閣。國史雖有本傳，甚略，且無其詩併叙，與此亦少異。餘訪之北方記錄，得其實焉。","sortOrder":13},
  {"id":"s_work_tddn_12_14","chapterId":"ch_work_tddn_12","text":"○何宏中","sortOrder":14},
  {"id":"s_work_tddn_12_15","chapterId":"ch_work_tddn_12","text":"何宏中字廷遠，先世居雁門。父子寄，守武州宣寧尉，殁王事。宏中，宣和元年武舉，廷對第二名，調滑州韦城尉。汴京被围，獨韦城不下。後為河東、河北兩路統製。接應副使武漢英守銀冶路，立山寨七十四所。漢英戰死，宏中堅守，以糧盡被擒。金人怜其忠，授以官，廷遠投牒於地曰：\"我嘗以此物誘人出死力，若辈乃欲以此吓我邪？\"囚西京獄。久之，免為黃冠，自號通理先生。起紫微殿，遷徽宗、東華君御容以事之。所著有《成真》、《通理》二集。正隆四年病殁，臨終有詩雲：\"馬革盛尸每恨遲，西山饿死亦何辭，姓名不到中興歷，自有皇天後土知。\"其志亦可哀矣！國史乃失其傳焉。","sortOrder":15},
  {"id":"s_work_tddn_12_16","chapterId":"ch_work_tddn_12","text":"○姚孝錫","sortOrder":16},
  {"id":"s_work_tddn_12_17","chapterId":"ch_work_tddn_12","text":"姚孝錫字仲純，丰縣人，登宣和六年第，調代州兵曹。金人寇雁門，州將忄匡怯議降，孝錫竟投床大鼾，不與其議。既得脱去，遂往五台薄移疾不仕，因家焉，時年三十九。治生積粟至數萬石，遇飢歲，盡出以赈貧乏，乡人德之。所居正據五台之勝，亭榭數十座，花竹百畝。中歲，盡以家事付諸子，日與賓朋放浪山水詩酒間，自號醉軒。至八十三乃終，有集號《雞肋》。《有題滕茂實祠》雲：\"本期蘇、鄭共扬鑣，不意芝蘭失後凋，遺老氐今猶涕淚，後生無复識風標。西陉雁度霜前塞，滹水樵爭日暮桥，追想平生英伟魄，凌雲一笑豈能招。\"七言如\"節物後先南北異，人情冷暖古今同\"；\"久客交情谙冷暖，衰年病骨識陰晴\"；\"玄晏暮年常抱病，子山終日苦思歸\"；\"深林有獸鳥先噪，废圃無人泉自流\"；\"食貧豈复甘秦炙，客病空懷奏楚音\"；五言如\"岸涨魚吹沫，山空石轉雷\"；\"穀虛生地籁，境寂散天香\"。皆佳句也。","sortOrder":17},
  {"id":"s_work_tddn_12_18","chapterId":"ch_work_tddn_12","text":"○蜀娼詞","sortOrder":18},
  {"id":"s_work_tddn_12_19","chapterId":"ch_work_tddn_12","text":"蜀娼類能文，蓋薛涛之遺風也。放翁客自蜀挟一妓歸，蓄之別室，率數日一往。偶以病少疏，妓頗疑之。客作詞自解，妓即韻答之雲：\"說盟說誓，說情說意，動便春愁滿紙。多應念得脱空經，是那个先生教底？不茶不飯，不言不語，一味供他憔悴。相思已是不曾閒，又那得工夫咒你？\"或謗翁嘗挟蜀尼以歸，即此妓也。","sortOrder":19},
  {"id":"s_work_tddn_12_20","chapterId":"ch_work_tddn_12","text":"又傳一蜀妓述送行詞雲：\"欲寄意，浑無所有，折盡市桥官柳。看君著上征衫，又相將放船楚江口。後會不知何日又，是男兒，休要镇長相守。苟富貴無相忘，若相忘有如此酒。\"亦可喜也。","sortOrder":20},
  {"id":"s_work_tddn_12_21","chapterId":"ch_work_tddn_12","text":"○桤木","sortOrder":21},
  {"id":"s_work_tddn_12_22","chapterId":"ch_work_tddn_12","text":"杜詩《乞桤木》詩無音，或讀作豈，而韻書亦無此字。集中又有\"桤林礙日吟風葉\"，鄭氏註曰：\"五來反。\"若然，當作呆字。","sortOrder":22},
  {"id":"s_work_tddn_12_23","chapterId":"ch_work_tddn_12","text":"餘嘗見陳體仁端明雲：\"見前辈讀若欹韻。\"頗以為疑，後見《劍南》詩有：\"著書增木品，搜句觅桤栽。\"又荆公詩雲：\"濯錦江邊木有桤，小園封植佇華滋。\"益信欹音為然。","sortOrder":23},
  {"id":"s_work_tddn_12_24","chapterId":"ch_work_tddn_12","text":"桤，惟蜀有之，不才木也，或謂即榕雲。","sortOrder":24},
  {"id":"s_work_tddn_12_25","chapterId":"ch_work_tddn_12","text":"○辦章","sortOrder":25},
  {"id":"s_work_tddn_12_26","chapterId":"ch_work_tddn_12","text":"《毛詩·采菽》：\"平平左右。\"《毛氏傳》曰：\"平平，辦治也。\"《正義》雲：\"《尧典》'平章百姓'，《書傳》作'辦章'，則平、辦義通。\"《讀詩記》引《荀子》雲：\"分不亂於上，能不窮於下，治辦之極也。《詩》雲：'平平左右。'\"","sortOrder":26},
  {"id":"s_work_tddn_12_27","chapterId":"ch_work_tddn_12","text":"今考書傳，不見辦章事。《史記》作便章。徐廣雲：\"下雲便程，則訓平為便也。\"る按：\"《尚書》併作平字。\"《索隱》雲：\"古文《尚書》作平字。此文蓋讀平為浦庚切。平即訓辦，遂為辦章。邹誕生本亦同。\"漢以伏生書為今文，安國書為古文。《尧典》今、古文皆有之，而作辦章者，今文也。特未知《詩疏》所授書傳為誰作耳？昌黎《袁氏先廟碑》亦雲：\"贊辦章。\"","sortOrder":27},
  {"id":"s_work_tddn_12_28","chapterId":"ch_work_tddn_12","text":"○曹泳","sortOrder":28},
  {"id":"s_work_tddn_12_29","chapterId":"ch_work_tddn_12","text":"紹興乙亥十月二十二日秦桧亡。翼日，曹泳勒停，安置新州。先是，二十一日車駕幸桧第视疾，時已不能言，懷中出一札，乞以喜代辅政，上视之無語。既出，呼幹辦府問何人為此，則答以曹泳，遂有是命。泳初竄名軍中，併緣功賞列得班行。嘗監黃巖酒稅，秩滿到部，註某闕鈔上省。桧押敕，顧見泳姓名，問何處人？省吏對：\"此吏部擬註，不知也。\"命於侍右書鋪物色召見之，熟视曰：\"公，桧恩家也。\"泳恍然不知所答。則又曰：\"忘之邪？\"泳曰：\"昏忘，實不省於何處遭遇太師？\"桧入室，有頃，取小册示泳使觀之。首尾不記他事，但有字一行曰：\"某年月日，某人錢五千，曹泳秀才絹二匹。\"蓋微時，索遊富人家得五千，求益不可，泳時為馆客，探囊中得二缣曰：\"此吾束修之餘也，今舉以遺子。\"既別，不相聞。雖知桧貴震天下，不謂其即秦秀才也。泳曰：\"不意太師乃能記憶微賤如此。\"桧曰：\"公真長者。\"命其子孫出拜之。俾以上書易文資，骤用之至戶部侍郎，知臨安府，與謝嘗有隙，台州之獄，泳有力焉。","sortOrder":29},
  {"id":"s_work_tddn_12_30","chapterId":"ch_work_tddn_12","text":"桧暮年頗有異志，泳實預其密謀。熔本桧妻党王氏子，蠢駿。嘗燕親賓，優者進妓，熔於座中大笑絕倒，桧殊不怿。桧素畏內，妾嘗孕，逐之，生子為仙遊林氏子，曰一飛，以桧故，仕至侍郎兼給事中。其兄一鳴，弟一鹗，皆位朝列。泳嘗勸桧還一飛以補喜處，未果而桧死雲。","sortOrder":30},
  {"id":"s_work_tddn_12_31","chapterId":"ch_work_tddn_12","text":"此事聞之謝之孫直。《中興遺史》所載則曹筠也，與此頗有異同，故詳載之。","sortOrder":31},
  {"id":"s_work_tddn_12_32","chapterId":"ch_work_tddn_12","text":"○朱漢章本末","sortOrder":32},
  {"id":"s_work_tddn_12_33","chapterId":"ch_work_tddn_12","text":"紹興三十二年六月十一日內禪，前一日宰相朱倬罢。倬字漢章，三山人，登宣和第。或謂張浚明橐荐之，非也，其實因劉貴妃以進。","sortOrder":33},
  {"id":"s_work_tddn_12_34","chapterId":"ch_work_tddn_12","text":"妃，北人，流寓閩中，有殊色。中貴人掌神御者圖上其貌，久之不省，始歸西外之宗家。它日，上見圖悅之，命召入，遂有寵。其父懋，後至節度使。倬居乡里識之，夤緣締交。後為學官，請外，得舒州。將陛辭，刺知上燕閒所觀史傳，於奏疏中道之，大稱旨，留為郎。不數年，為中司，遂至宰相。","sortOrder":34},
  {"id":"s_work_tddn_12_35","chapterId":"ch_work_tddn_12","text":"最惡王十朋，其在台，嘗風陳丞相康伯去之。陳以告汪聖錫，汪曰：\"彼為中司，胡不自击之？\"陳曰：\"畏公議也。\"汪曰：\"彼且畏公議，相公獨不畏公議乎？\"既而十朋不自安，請外，將予郡，倬又曰：\"顛人如何作郡？\"乃得外大宗丞。公論大喧，然上眷殊厚。","sortOrder":35},
  {"id":"s_work_tddn_12_36","chapterId":"ch_work_tddn_12","text":"辛巳，视師回至平江，洪遵景嚴為守。時倬與康伯併相，遵以求入為祷，倬唯唯，康伯曰：\"進退近臣，當由上意，非某所敢知也。\"及將內禪，康伯奏：\"書沼方冗，翰苑獨員洪遵在近。\"欲召之，倬惡其非出己，即曰：\"不可。其弟邁新為右史，今复召遵，此蘇軾與轍所以变亂元祐也。\"上卒召遵副端。張震真父為同列言：\"上方行尧舜之事，此人豈可辅初政？不去之，必為天下患。\"遂力攻之。上初不聽。時競傳覃霈在學生員皆免解，倬子端厚嘗肄業，既荫補矣，頗欲併緣在學人例，竄名其間。真父廉得其事，疏中言之，上始怒，遂罢相。景巖適當製，有雲：\"為君子邦家之基，曾未聞於成效。有元良天下之本，乃欲冀於畴庸。時真父疏不付出，內外迄莫知所坐，雖倬亦自疑懼，惴惴累年。","sortOrder":36},
  {"id":"s_work_tddn_12_37","chapterId":"ch_work_tddn_12","text":"汪公帥閩，至郡，方欲謁之，一夕暴下卒。國史本傳乃謂高宗有內禪意，倬請徐之，及孝宗即位，諫臣以為言，以忧懼卒。或以為服藥而殂，皆不然也。","sortOrder":37},
  {"id":"s_work_tddn_12_38","chapterId":"ch_work_tddn_12","text":"○陆務觀得罪","sortOrder":38},
  {"id":"s_work_tddn_12_39","chapterId":"ch_work_tddn_12","text":"陆務觀以史師垣荐，賜第。孝宗一日內宴，史與曾觌皆預焉。酒酣，一內人以帕子從曾乞詞。時德寿宮有內人與掌果子者交涉，方付有司治之。觌因謝不敢曰：\"獨不聞德寿宮有公事乎？\"遂已。","sortOrder":39},
  {"id":"s_work_tddn_12_40","chapterId":"ch_work_tddn_12","text":"它日，史偶為務觀道之，務觀以告張焘子宮。張時在政府，翼日奏：\"陛下新嗣服，豈宜與臣下燕狎如此？\"上愧問曰：\"卿得之誰？\"曰：\"臣得之陆遊，遊得之史浩。\"上由是惡遊，未幾去國。","sortOrder":40},
  {"id":"s_work_tddn_12_41","chapterId":"ch_work_tddn_12","text":"○蘇師旦麻","sortOrder":41},
  {"id":"s_work_tddn_12_42","chapterId":"ch_work_tddn_12","text":"蘇師旦將建節，學士顏或、莫子純皆莫肯當製。易祓彦章為枢密院檢詳文字，師旦為都承旨，祓與之昵，欣然願任责。遂以國子司業兼兩製，竟為師旦草麻，極其諛佞。至用前人舊封所為有文事，有武備，無智名，無勇功者，蓋以孔子比之，子房不足道也。既宣布，物論哗然，亟擢祓左司諫。諸生為之語曰：\"陽城毀裴延齡之麻，由諫官而下遷於司業；易祓草蘇師旦之製，由司業而上擢於諫官。\"既而韓誅，蘇得罪，祓遂遠貶。","sortOrder":42},
  {"id":"s_work_tddn_12_43","chapterId":"ch_work_tddn_12","text":"○雷变免相","sortOrder":43},
  {"id":"s_work_tddn_12_44","chapterId":"ch_work_tddn_12","text":"乾道丁亥十一月二日冬至，郊祀有風雷之变，宰相葉、魏杞，皆策免。先是，會慶節，金國使在庭時受誓戒矣。議者欲權免上寿，就馆錫宴，廟堂姑息，不能主其議，宴集英如常，天变豈偶然哉！洪邁當製，有曰：\"理陰陽而遂萬物，所嗟論道之非；因灾異而策三公，實負在天之愧。\"蓋有所風也。","sortOrder":44},
  {"id":"s_work_tddn_12_45","chapterId":"ch_work_tddn_12","text":"○高宗立储","sortOrder":45},
  {"id":"s_work_tddn_12_46","chapterId":"ch_work_tddn_12","text":"孝宗與恩平郡王璩，同養於宮中。孝宗英睿夙成，秦桧憚之，憲聖後亦主璩。高宗聖意雖有所向，猶未堅决。嘗各賜宮女十人。史丞相浩時為普安府教授，即為王言，上以试王，當謹奉之，王亦以為然。閱數日，果皆召入。恩平十人皆犯之矣，普安者，完璧也。已而皆竟賜焉。上意遂定。","sortOrder":46},
  {"id":"s_work_tddn_12_47","chapterId":"ch_work_tddn_12","text":"○慈懿李後","sortOrder":47},
  {"id":"s_work_tddn_12_48","chapterId":"ch_work_tddn_12","text":"慈懿李皇後，安陽人，父道本，戚方諸將，故群盜也。後天姿悍妒，既正椒房，稍自恣。始，成肅謝後事高宗及憲懿聖甚謹，至後頗偃蹇。或乘肩舆直至內殿，成肅以為言，後恚曰：\"我是官家結發夫妻。\"蓋謂成肅自嫔御册立也。語聞，成肅及寿皇皆大怒，有意废之。史太師已老，嘗詔入見北宮，密與之謀，浩以為不可，遂已。宮省事秘，莫得詳也。其後益無忌憚。貴妃黃氏有寵，後妒，每欲殺之。紹熙二年，光宗初郊，宿青城斋宮，後乘便，遂置之死地。或以聞，上駭且忿怒，於是遂得心疾。及上不豫，兩宮有間言，天下寒心，皆歸過於後。後以慶元庚申上仙，權殯赤山。甫畢，雷震山崩，亟复修治之。","sortOrder":48},
  {"id":"s_work_tddn_12_49","chapterId":"ch_work_tddn_12","text":"○道學","sortOrder":49},
  {"id":"s_work_tddn_12_50","chapterId":"ch_work_tddn_12","text":"伊洛之學行於世，至乾道、淳熙間盛矣。其能發明先賢旨意，溯流徂源，論著講解卓然自為一家者，惟廣漢張氏敬夫、東萊呂氏伯恭、新安朱氏元晦而已。朱公尤淵洽精詣，蓋其以至高之才，至博之學，而一切收斂，歸諸義理。其上極於性命天人之妙，而下至於訓詁名數之末，未嘗舉一而废一。蓋孔孟之道，至伊洛而始得其傳，而伊洛之學，至諸公而始無餘蘊。必若是，然後可以言道學也已。此外有橫浦張氏子韶，象山陆氏子靜，亦皆以其學傳授。而張嘗參宗杲禪，陆又嘗參杲之徒德光，故其學往往流於異端而不自知。程子所謂今之異端，因其高明者也。至於永嘉諸公，則以詞章議論馳騁，固已不可同日語也。","sortOrder":50},
  {"id":"s_work_tddn_12_51","chapterId":"ch_work_tddn_12","text":"世又有一种淺陋之士，自视無堪以為進取之地，辄亦自附於道學之名。裒衣博帶，危坐闊步。或抄節語錄以資高談；或閉眉合眼號為默識。而扣击其所學，則於古今無所聞知，考验其所行，則於義利無所分別。此聖門之大罪人，吾道之大不幸，而遂使小人得以藉口為伪學之目，而君子受玉石俱焚之禍者也。","sortOrder":51},
  {"id":"s_work_tddn_12_52","chapterId":"ch_work_tddn_12","text":"韓胄用事，遂逐趙忠定。凡不附己者，指為道學盡逐之。已而自知道學二字，本非不美，於是更目之為伪學。臣僚之荐舉，進士之結保，皆有\"如是伪學者，甘伏朝典\"之辭。一時嗜利無恥之徒，雖嘗自附於道學之名者，往往旋易衣冠，強習歌鼓，欲以自別。甚者，邓友龍辈，附會迎合，首啟兵衅。而向之得罪於慶元初者，亦從而和之，可叹也已。","sortOrder":52},
  {"id":"s_work_tddn_12_53","chapterId":"ch_work_tddn_12","text":"○邓友龍开邊","sortOrder":53},
  {"id":"s_work_tddn_12_54","chapterId":"ch_work_tddn_12","text":"邓友龍，長沙人，嘗從張南軒遊，自诡道學。既登朝，時論方攻伪學，因讳而晦其事。時外祖章文莊公為學官，喜滑稽。嘗以祀事同斋宿，談謔之际，友龍不能堪，以語及之雲雲。章戲之曰：\"若然，則又是道學矣。\"友龍面發赤，大衔之。","sortOrder":54},
  {"id":"s_work_tddn_12_55","chapterId":"ch_work_tddn_12","text":"未幾入台，章公由學士院補外。公本謝丞相客也。會友龍為右史，而宇文紹節自右史代之，於是召文莊為宗政少卿，友龍不能平，以嗾紹節。紹節甫供職，未及受告，首論其事，語侵謝，蓋亦以見厭於韓矣。章命既寢，謝遂去國，而友龍亦出為淮西漕，日久，謀复入。","sortOrder":55},
  {"id":"s_work_tddn_12_56","chapterId":"ch_work_tddn_12","text":"時金人方困於北兵，且其國歲荐飢，於是沿邊不逞之徒號為\"跳河子\"者，時時剽獵事状，陳說利害。友龍得之以為奇货，於是獻之於韓。韓用事久，思釣奇立功以自善，得之大喜。附而和者雖不一，其端實友龍發之也。孔子所以畏鄙夫患得患失者，有以夫。","sortOrder":56},
  {"id":"s_work_tddn_12_57","chapterId":"ch_work_tddn_12","text":"○文莊論安丙矯詔","sortOrder":57},
  {"id":"s_work_tddn_12_58","chapterId":"ch_work_tddn_12","text":"安丙之誅吳曦也，矯詔自稱宣撫副使，遂径入衔上奏。時章文莊直學士院，因謂：\"矯製假命，一時權宜濟事可也。事定奏功，便當退用初衔，而遽稱所假，是豈复有朝廷乎？今為朝廷計，宜先赦其矯詔之罪，然後賞其斬曦之功，則恩威併用，折冲萬里之外矣。\"而時相方自以為功，謂此詔非矯，實朝廷密旨，且詣御樓受俘，於是疏不果上。已而受俘之議雖格，而竟以所矯官職授之。其後丙亦自毙，否則又一曦也。","sortOrder":58},
  {"id":"s_work_tddn_12_59","chapterId":"ch_work_tddn_12","text":"○王沈趨張說","sortOrder":59},
  {"id":"s_work_tddn_12_60","chapterId":"ch_work_tddn_12","text":"張說之為承旨也，朝士多趨之。王质景文、沈瀛子寿，始俱在學校有聲，既而俱立朝，物譽亦歸之。相與言：\"吾儕當以詣說為戒。\"眾皆聞其說而壮之。已而，质潛往說所，甫入客位，而瀛已先在焉，相视愕然。明日喧傳，清議鄙之，久皆不安而去焉。","sortOrder":60},
  {"id":"s_work_tddn_12_61","chapterId":"ch_work_tddn_12","text":"○协韻牵強","sortOrder":61},
  {"id":"s_work_tddn_12_62","chapterId":"ch_work_tddn_12","text":"詩辭固多协韻，晦庵用吳才老補音多通，然亦有太甚者。古人但隨聲取协，方言又多不同。至沈約以來，方有四聲之拘耳，然亦正不必牵強也。《離骚》一經，惟\"多艱多替\"之句，最為不协。孫莘老、蘇子容本雲：\"古亦應协。\"未必然也。晦庵以艱音巾，替音天，雖用才老之說，然恐無此理。以餘觀之，若移\"長太息以掩涕\"一句在\"哀生民之多艱\"下，則涕與替正协，不勞牵強也。","sortOrder":62},
  {"id":"s_work_tddn_12_63","chapterId":"ch_work_tddn_12","text":"○沈君與","sortOrder":63},
  {"id":"s_work_tddn_12_64","chapterId":"ch_work_tddn_12","text":"吳興東林沈偕君與，即東老之子也，家饒於财。少遊京師入上庠，好狎遊。時蔡奴聲价甲於都下。沈欲訪之，乃呼一賣珠人於其門首茶肆中，議价再三不售，撒其珠於屋上，賣珠者窘甚。君與笑曰：\"第隨我來，依汝所索還錢。\"蔡於帘中窥見，令取视之，珠也。大驚，惟恐其不來。後數日乃詣之，其家喜相報曰：\"前日撒珠郎至矣。\"接之甚至，自是常往來。一日，携上樊樓，樓乃京師酒肆之甲，飲徒常千餘人。沈遍語在坐，皆令極量盡歡，至夜，盡為還所直而去，於是豪侈之聲滿三辅。既而擢第，盡買國子監書以歸。","sortOrder":64},
  {"id":"s_work_tddn_12_65","chapterId":"ch_work_tddn_12","text":"時贾收耘老隱居苕城南橫塘上，沈嘗以詩遺之蟹曰：\"黃亢稻熟墜西風，肥入江南十月雄。橫跪蹣跚鉗齒白，圓脐吸胁斗膏紅。羞須園老香研柚，羹藉庖丁細擘葱。分寄橫塘溪上客，持螯莫放酒杯空。\"耘老得之不樂曰：\"吾未之識，後進輕我。\"且聞其不羁，因和韻詆之雲：\"彭越孫多伏下風，蝤蛑奴视敢稱雄。江湖縱養膏腴紫，鼎镬終烹爪眼紅。嗍稱吳兒牙似鍍，劈慚湖女手如葱。獨怜盤內秋脐實，不比溪邊夏壳空。\"君與怒曰：\"吾聞贾多與郡將往還預政，言人短長，曾為人所訟。吾以長上推之，乃鄙我若此\"，复用韻報之雲：\"虫腹無端苦動風，团雌還却勝尖雄。水寒且弄双鉗利，湯老難逃一背紅。液入幾家煩海滷，醢成何處污園葱。好收心躁潛蛇穴，毋使雷驚族類空。\"贾晚娶真氏，人謂贾秀才娶真縣君以為笑，沈所指团雌為此。贾尋悔之，而戲語已傳播矣。","sortOrder":65},
  {"id":"s_work_tddn_12_66","chapterId":"ch_work_tddn_12","text":"○吳倜","sortOrder":66},
  {"id":"s_work_tddn_12_67","chapterId":"ch_work_tddn_12","text":"吳倜字公度，吳興人，试補太學為第一。崇寧五年，群禮部七千之士而魁之，其名聲風采，人莫不求識面而願交。邃經學，妙語言，為時聞人。","sortOrder":67},
  {"id":"s_work_tddn_12_68","chapterId":"ch_work_tddn_12","text":"其父伯陽，嘗夢若遊奕使者立東階，問：\"秀才在否？\"曰：\"不在。\"遂去，出門見旌幡容物，弥望不絕，曰：\"秀才歸。\"但道天赦曾來，已而捷音至。先以名次高下商价，自榜尾行間前列以至首選，自百千漸至千缗，乃出其榜。初自删定敕令所出為寧海推官。","sortOrder":68},
  {"id":"s_work_tddn_12_69","chapterId":"ch_work_tddn_12","text":"時蔡京罢相居城中，意其生計從容，委買川土物無虛月，倜意不平。念吾以文學起身，而不以儒者見遇，報以實直。京覺之而怒。重和二年，召為九域圖志所編修官。時京以太師魯公賜第京師，朝朔望。一日，上問京：\"卿曩居杭，識推官吳倜乎？今以大臣荐，欲除官。\"對曰：\"識之，其人傲狠無上。\"上驚曰：\"何以知之？\"曰：\"吳知陛下御讳而不肯改，乃以一圈围之。\"蓋言\"倜\"字也，上默然不怿。未幾，言者承風旨論罢，自是不复出。","sortOrder":69},
  {"id":"s_work_tddn_12_70","chapterId":"ch_work_tddn_12","text":"及京败，知鄆州孫言邑人有草祭之謠，上其事。甚者論其即仓為宅，拆仓邑人字為人君二字，謂京有不臣之心。雖若附會，然亦平日好以字畫中傷善類之報也。","sortOrder":70},
  {"id":"s_work_tddn_12_71","chapterId":"ch_work_tddn_12","text":"○御宴煙火","sortOrder":71},
  {"id":"s_work_tddn_12_72","chapterId":"ch_work_tddn_12","text":"穆陵初年，嘗於上元日清燕殿排當，恭請恭聖太後。既而燒煙火於庭，有所謂地老鼠者，径至大母聖座下，大母為之驚惶，拂衣径起，意頗疑怒，為之罢宴。穆陵恐甚，不自安，遂將排辦巨陳詢盡監系聽命。黎明，穆陵至陳朝謝罪，且言內臣排辦不謹，取自行遣。恭聖笑曰：\"終不成他特地來驚我，想是誤耳，可以赦罪。\"於是子母如初焉。","sortOrder":72},
  {"id":"s_work_tddn_12_73","chapterId":"ch_work_tddn_12","text":"○朱芮殺龍","sortOrder":73},
  {"id":"s_work_tddn_12_74","chapterId":"ch_work_tddn_12","text":"吳興彰南朱教授（失其名）嘗江行，舟人急報小龍見，請祷之，朱出视之，小蛇也。以箸夹入沸湯中，蛇躍出自投於江，却行波面，盼朱再四乃没。有頃，片雲霹靂，煙霧蔽舟。既而视之，舟上一竅如錢，朱已毙於舟中矣。","sortOrder":74},
  {"id":"s_work_tddn_12_75","chapterId":"ch_work_tddn_12","text":"又王村芮祭酒煜，初任仁和尉。長河堰有龍王廟，每祭則有小蛇出，或止香爐，或飲於杯，往來者謹事之。堰歲數坏，人以為龍所為。芮疲於修筑之役，一日，焚香設奠，蛇果出爐上。芮端笏數之曰：\"有功於民者乃得祀。龍，廟食於此，未嘗有功，而歲數坏堰，勞民之力，為罪多矣。無功有罪，於國法當殺。\"即舉笏击之，應手碎。是夕，宿於近地，疾風甚雨，大木盡拔，土人大恐，而芮處之自若。後卒為名臣，其幸不幸也如此。","sortOrder":75},
  {"id":"s_work_tddn_13_1","chapterId":"ch_work_tddn_13","text":"●卷十二","sortOrder":1},
  {"id":"s_work_tddn_13_2","chapterId":"ch_work_tddn_13","text":"○薑尧章自叙（单丙文附）","sortOrder":2},
  {"id":"s_work_tddn_13_3","chapterId":"ch_work_tddn_13","text":"番易有布衣薑夔尧章，出處備見張辑宗瑞所著《白石小傳》矣。近得其一書，自述頗詳，可與前傳相表里雲。","sortOrder":3},
  {"id":"s_work_tddn_13_4","chapterId":"ch_work_tddn_13","text":"\"某早孤不振，幸不墜先人之緒業，少日奔走，凡世之所謂名公鉅儒，皆嘗受其知矣。內翰梁公於某為乡曲，愛其詩似唐人，謂長短句妙天下。枢使鄭公愛其文，使坐上為之，因击節稱賞。參政范公以為翰墨人品，皆似晉、宋之雅士。待製楊公以為於文無所不工，甚似陆天隨，於是為忘年友。复州萧公，世所謂千巖先生者也，以為四十年作詩，始得此友。待製朱公既愛其文，又愛其深於禮樂。丞相京公不特稱其禮樂之書，又愛其骈俪之文。丞相謝公愛其樂書，使次子來謁焉。稼軒辛公，深服其長短句如二卿。孫公從之，胡氏應期，江陵楊公，南州張公，金陵吳公，及吳德夫、項平甫、徐子淵、曾幼度、商仲、王晦叔、易彦章之徒，皆當世俊士，不可悉數。或愛其人，或愛其詩，或愛其文，或愛其字，或折節交之。若東州之士則樓公大防、葉公正則，則尤所賞激者。嗟乎！四海之內，知己者不為少矣，而未有能振之於窭困無聊之地者。舊所依倚，惟有張兄幹甫，其人甚賢。十年相處，情甚骨肉。而某亦竭誠盡力，忧樂關念。平甫念其困踬場屋，至欲输資以拜爵，某辭謝不願，又欲割錫山之膏腴以養其山林無用之身。惜乎平甫下世，今惘惘然若有所失。人生百年有幾，賓主如某與平甫者复有幾，撫事感慨，不能為懷。平甫既殁，稚子甚幼，入其門則必為之凄然，終日獨坐，逡巡而歸。思欲舍去，則念平甫垂絕之言，何忍言去！留而不去，則既無主人矣！其能久乎？\"雲雲。","sortOrder":4},
  {"id":"s_work_tddn_13_5","chapterId":"ch_work_tddn_13","text":"同時黃白石景說之言曰：\"造物者不欲以富貴冫免尧章，使之聲名耀於無窮也，此意甚厚。\"又楊伯子長孺之言曰：\"先君在朝列時，薄海英才，雲次鱗集，亦不少矣！而布衣中得一人焉，曰薑尧章。\"呜呼！尧章一布衣耳，乃得盛名於天壤間若此，則軒冕鐘鼎，真可敝屣矣。","sortOrder":5},
  {"id":"s_work_tddn_13_6","chapterId":"ch_work_tddn_13","text":"是時，又有单煒丙文者，沅陵人，博學能文，得二王筆法，字畫遒劲，合古法度，於考订法書尤精。武舉得官，仕至路分，著聲江湖間，名士大夫多與之交，自號定斋居士。與尧章投分最稔，亦韻士也。尧章詩詞已板行，獨雜文未之見，餘嘗於親舊間得其手稿數篇，尚思所以廣其傳焉。","sortOrder":6},
  {"id":"s_work_tddn_13_7","chapterId":"ch_work_tddn_13","text":"○白石禊帖偏旁考","sortOrder":7},
  {"id":"s_work_tddn_13_8","chapterId":"ch_work_tddn_13","text":"尧章考古極精，有《絳帖評》十卷行於世，審订深妙，人服其贍。又嘗於故家見其所書《禊帖偏旁考》亦奇，因識於此，與好古者共之。","sortOrder":8},
  {"id":"s_work_tddn_13_9","chapterId":"ch_work_tddn_13","text":"\"永\"字無畫，發筆處微折轉。\"和\"字口下橫筆稍出。\"年\"字懸筆上凑顶。\"在\"字左反剔。\"歲\"字有點，在山之下，戈畫之右。\"事\"字腳斜拂不挑。\"流\"字內\"肱\"字處就回筆，不是點。\"殊\"字挑腳帶橫。\"是\"字下疋（音疏）凡三轉不斷。\"趣\"字波略反卷向上。\"欣\"字欠右一筆作章草發筆之状，不是捺。\"抱\"字已开口。\"死生亦大矣\"亦字是四點。\"興感\"感字，戈邊亦直作一筆，不是點。\"未嘗不\"不字下反挑處有一闕。","sortOrder":9},
  {"id":"s_work_tddn_13_10","chapterId":"ch_work_tddn_13","text":"右法如此甚多，略舉其大概。持此法亦足以觀天下之《蘭亭》矣。","sortOrder":10},
  {"id":"s_work_tddn_13_11","chapterId":"ch_work_tddn_13","text":"○禊序不入選帖","sortOrder":11},
  {"id":"s_work_tddn_13_12","chapterId":"ch_work_tddn_13","text":"逸少《禊序》，高妙千古，而不入選。或謂\"絲竹管絃，天朗氣清\"，有以累之。不知\"絲竹管絃\"，不特見前漢《張禹傳》，而《東都賦》亦有\"絲竹管絃，燁煜抗五聲\"之語。然此二字相承，用之久矣。張衡賦：\"仲冬之月，時和氣清。\"又晉褚爽《禊賦》亦曰：\"伊暮春之令月，將解禊於通川，風搖林而自清，氣扶嶺而自鮮。\"况清明為三月節氣，朗即明，又何嫌乎？若以筆墨之妙言之，固當居諸帖之首，乃不得列官法帖中，又何哉？豈以其表表得名，自應別出，不可與諸任齒耶？亦前辈選詩不入李、杜之意耳，識者试評之。","sortOrder":12},
  {"id":"s_work_tddn_13_13","chapterId":"ch_work_tddn_13","text":"○淳紹歲幣","sortOrder":13},
  {"id":"s_work_tddn_13_14","chapterId":"ch_work_tddn_13","text":"紹興歲幣，銀二十萬兩，絹二十萬匹（紅絹十二萬匹，匹重十兩。浙絹八萬匹，匹重九兩）。枢密院差使臣四員管押銀綱，戶部差使臣十二員管押絹綱。同左帑库子、秤子，於先一年腊月下旬，至盱眙軍歲幣库下卸。續差將官一員，部押軍兵三百人，防護過淮。交割官正使，例差淮南漕屬；副使，本軍ヘ或鄰州ヘ充。例用歲前三日，先赍銀百鋌、絹五百匹，過淮呈樣金人。交幣正使，例是南京漕屬；副使，諸州同知。於所赍銀、絹內，揀白絹六匹、銀六錠，三分之，令走馬使人，以一分往燕京，一分往汴京漕司呈樣，一分留泗州歲幣库，以備參照。例用开歲三日長交，通不過兩月結局。初交絹十退其九，以金人秤尺無法，又胥吏需索作難之故。數月後所需如欲，方始通融，然亦十退其四五（自初交至結局，通支金人交幣官吏糜費銀一千三百餘兩、金三十五兩、木綿三十六匹、白布六十二匹，酒三百四十石，共折銀六百二十兩，本色酒二千六百瓶，茶果雜物等併在外，俱系淮東漕司出備）。又貼耗銀二千四百餘兩，每歲例增添銀二百餘兩，併淮東漕司管認。凡吾正副使併官吏飯食之類，併淮東漕司應辦。下至安泊棚屋厨廁等，皆自盱眙運竹木往彼蓋造，彼皆不與焉。盱眙日差倚郭知縣部夫過淮搬運銀絹，兼應辦事務。其揀退者，遇夜复搬運過淮，歸盱眙库交收，其勞人往复如此。且我官吏至淮北岸約二百餘步，始至交幣所，皆徒步而往，雨濘，則攝衣躡屐甚踔而行，艱苦不可具道也。","sortOrder":14},
  {"id":"s_work_tddn_13_15","chapterId":"ch_work_tddn_13","text":"淳熙十三年，淮南漕司幹官權安節為歲幣使，其金人正使一毫不取，揀退銀絹甚多，逼令携歸，安節固拒，金人至遣甲兵逼逐。安節不勝其憤曰：\"寧死於此，不得交，誓不回，雖野宿不火食亦無害。\"聲色俱厲。彼度不能奪，竟如數收受，給公文而歸。寿皇知之，喜曰：\"安節在彼界能如此，甚可重。若非遇事，何自知之。\"遂除鹽六部門。時通判扬州汪大定，亦同此役，頗著勞績，亦蒙奖拔焉。","sortOrder":15},
  {"id":"s_work_tddn_13_16","chapterId":"ch_work_tddn_13","text":"若正旦生朝遣使，每次禮物金器一千兩、銀器一萬兩、彩緞一千匹（綿茸背，紧絲捻金線，青絲綾，樗蒲綾，線子羅）。又有腦子、香茶等物，及私觌香茶、藥物、果子、幣帛、雜物等，复不與焉。若外遣泛使，則其禮物等又皆倍之。又有起發副使土物之費（正使五百貫，銀絹各一百兩匹。副使四百貫，銀絹各一百兩匹。又有公使各藥等錢，上節銀各五十兩、絹十匹，中節銀絹各十兩匹，下節各五兩匹）。又有朝辭回程宣賜等費（正副使各金二十五兩，併腰帶笏馬。回程茶藥各二兩，銀合及泛賜等物在外）。若盱眙等軍，在路四處應辦南北贺正生辰，常使往回程各八次，賜御筵每處費錢一萬八千五百餘貫，而沿途應辦复不預。若北使之來，賜予尤不赀焉（宣和甲辰歲幣銀二十萬兩，絹三十萬匹，绿礬二十萬栲，栲例五番運送交納。又代输燕京稅物綿絲雜物計一百萬貫，內絲綿併要燕京土產。紹興壬戌初講和，歲幣銀絹各二十五萬匹兩。今每歲各减五萬匹兩）。至兀術病篤之际，告戒其四行府帥雲：\"江南累歲供需歲幣，竭其财賦，安得不重斂於民？非理扰亂，人心離怨，叛亡必矣。在彼者尚知有此，為我者，當何如哉！\"時聘使往來，旁午於道。凡過盱眙，例遊第一山，酌玻璃泉，題詩石壁，以記歲月，遂成故事，镌刻題名幾滿。紹興癸丑，國信使鄭汝諧一詩雲：\"忍恥包羞事北庭，奚奴得意管逢迎，燕山有石無人勒，却向都梁記姓名。\"可謂知言矣。噫！开邊之用固無窮，而和戎之費亦不易，餘因詳書之。","sortOrder":16},
  {"id":"s_work_tddn_13_17","chapterId":"ch_work_tddn_13","text":"○書籍之厄","sortOrder":17},
  {"id":"s_work_tddn_13_18","chapterId":"ch_work_tddn_13","text":"世間凡物未有聚而不散者，而書為甚。隋牛弘靖請开獻書之路，極論废興，述五厄之說，則書之厄也久矣，今姑摭其概言之。","sortOrder":18},
  {"id":"s_work_tddn_13_19","chapterId":"ch_work_tddn_13","text":"梁元帝江陵蓄古今圖書十四萬卷，隋嘉則殿書三十七萬卷。唐惟貞觀、开元最盛，兩都各聚書四部至七萬卷。宋宣和殿、太清樓、龍圖閣、御府所储尤盛於前代，今可考者，《崇文總目》四十六類三萬六百六十九卷，史馆一萬五千餘卷，餘不能具數。南渡以來，复加集錄馆閣書目五十二類四萬四千四百八十六卷、續目一萬四千九百餘卷，是皆藏於官府耳。","sortOrder":19},
  {"id":"s_work_tddn_13_20","chapterId":"ch_work_tddn_13","text":"若士大夫之家所藏，在前世如張華載書三十車，杜兼聚書萬卷，韦述蓄書二萬卷，鄴侯插架三萬卷，金樓於聚書八萬卷，唐吳競西斋一萬三千四百餘卷。宋室承平時，如南都戚氏，歷陽沈氏，庐山李氏，九江陳氏，番易吳氏，王文康，李文正，宋宣獻，晁以道，劉壮舆，皆號藏書之富。邯鄲李淑五十七類二萬三千一百八十餘卷，田鎬三萬卷，昭德晁氏二萬四千五百卷，南都王仲至四萬三千餘卷，而類書浩博，若《太平御覽》之類，复不與焉。次如曾南丰及李氏山房，亦皆一二萬卷，然後靡不厄於兵火者。","sortOrder":20},
  {"id":"s_work_tddn_13_21","chapterId":"ch_work_tddn_13","text":"至若吾乡故家如石林葉氏、贺氏，皆號藏書之多，至十萬卷。其後齊斋倪氏，月河莫氏，竹斋沈氏，程氏，贺氏，皆號藏書之富，各不下數萬餘卷，亦皆散失無遺。近年惟直斋陳氏書最多，蓋嘗仕於莆，傳錄夹氵祭鄭氏、方氏、林氏、吳氏舊書至五萬一千一百八十餘卷，且仿《讀書志》作解題，極其精詳，近亦散失。至如秀巖，東窗，鳳山三李，高氏，牟氏皆蜀人，號為史家，所藏僻書尤多，今亦已無餘矣。","sortOrder":21},
  {"id":"s_work_tddn_13_22","chapterId":"ch_work_tddn_13","text":"吾家三世積累，先君子尤酷嗜，至鬻負郭之田以供筆札之用。冥搜極讨，不憚勞費，凡有書四萬二千餘卷，及三代以來金石之刻一千五百餘种，庋置書种、志雅二堂，日事校讎，居然ぷ金之富。餘小於遭時多故，不善保藏，善和之書，一旦扫地。因考今昔，有感斯文，為之流涕。因書以識吾過，以示子孫雲。","sortOrder":22},
  {"id":"s_work_tddn_13_23","chapterId":"ch_work_tddn_13","text":"○雷書","sortOrder":23},
  {"id":"s_work_tddn_13_24","chapterId":"ch_work_tddn_13","text":"神而不可名，变化而不可测者，莫如雷霆。《淮南子》曰：\"陰陽相薄，感而為雷，激而為電。\"故先儒為之說曰：\"陰氣凝聚，陽在內而不得出，則奋击而為雷霆。聲，陽也；光，亦陽也。光發而聲隨之，陽氣奋击欲出之势也。\"或問世所得雷斧何物也？曰：\"此猶星陨而為石也。本乎天者，氣而非形，偶陨於地，則成形矣。\"或問人有不善為雷震死者何也？曰：\"人作惡有惡氣，霹靂乃天地之怒氣，是怒氣亦惡氣也，怒氣與惡氣相感故爾。\"或問雷之破山、坏屋、折树、殺畜何也？曰：\"此氣鬱而怒，方爾奋击，偶或值之，則遭震矣。\"康節嘗問伊川曰：\"子以雷起於何處？\"伊川曰：\"起於起處。\"然則先儒之所言者，非不精詳，而餘猶謂有不可晓者焉：","sortOrder":24},
  {"id":"s_work_tddn_13_25","chapterId":"ch_work_tddn_13","text":"大中祥符間，嶽州玉真觀為火所焚，惟留一柱，有\"謝仙火\"三字，倒書而刻之。慶歷中，有以此字問何仙姑者，雲：\"謝仙者，雷部中鬼也，掌行火於世間。\"後有於道藏經中得謝仙事，验以為神。又吳中慧聚寺大殿二柱，嘗因雷震，有天書\"績溪火\"三字，餘若符篆不可晓。及近歲德清縣新市镇覺海寺佛殿柱，亦為雷震，有字径五寸餘，若漢隸者雲：\"收利火謝均思通。\"又雲：\"酉異李氵勺火。\"此乃得之目击者。又宜興善權廣教寺殿柱，亦有雷書\"骆審火及謝均火\"者。華亭縣天王寺亦有雷書\"高洞扬雅一十六人火令章\"凡一十一字，皆倒書。內\"令章\"二字特奇劲，類唐人書法，然則雷之神，真有謝姓者邪。近丁亥六月五日，雷震眾安桥南酒肆，卓間有雷書\"[1234][1234]永\"三字，此類甚多，殊不可测，此所以神而不可知者乎？孔子不語怪力亂神，非不語也，蓋有未易語者耳。","sortOrder":25},
  {"id":"s_work_tddn_13_26","chapterId":"ch_work_tddn_13","text":"○贾相寿詞","sortOrder":26},
  {"id":"s_work_tddn_13_27","chapterId":"ch_work_tddn_13","text":"贾師憲當國日，臥治湖山，作堂曰半間，又治圃曰養樂，然後為就養，其實怙權固位，欲罢不能也。每歲八月八日生辰，四方善頌者以數千計。悉俾翘馆謄考，以第甲乙，一時傳頌，為之紙貴，然皆調詞囈語也。偶得首選者數阕，戲書於此。","sortOrder":27},
  {"id":"s_work_tddn_13_28","chapterId":"ch_work_tddn_13","text":"陳惟〈善合〉《寶鼎》詞雲：\"神鰲誰斷，幾千年再、乾坤初造。算當日，枰棋如許，爭一著吾其衽左。談笑頃，又十年生聚，處處（風）葵棗。江如鏡，楚氛餘幾，猛聽甘泉捷報。天衣細意從頭補，烂山龍、華虫黼藻。宮漏永、千門角鑰，截斷紅尘飛不到。街九軌，看千貂避路，庭院五侯深鎖。好一部、太子六典，一一周公手做。赤舄繡裳，消得道斑烂衣好。盡庞眉鶴發，天上千秋難老。甲子嚴頭才一過，未說汾陽考。看金盤、露滴瑤池，龍尾放班回早。\"","sortOrder":28},
  {"id":"s_work_tddn_13_29","chapterId":"ch_work_tddn_13","text":"廖瑩中群玉《木蘭花慢》雲：\"請諸君著眼，來看我，福華編。記江上秋風，鯨涨雪，雁徼迷煙。一時幾多人物，只我公，只手護山川。爭睹階符瑞象，又扶紅日中天。因懷，下走奉，磨盾夜無眠。知重开宇宙，活人萬萬，合寿千千。凫太平世也，要東還越上是何年。消得清時鐘鼓，不妨平地神仙。\"陆景思《甘州》雲：\"滿清平世界，慶秋成，看看斗米三錢。論從來活國，論功第一，無過丰年。辦得間民一飽，餘事笑談間。若問平戎策，微妙難傳。玉帝要留公住，把西湖一曲，分入林園。有茶爐丹竈，更有釣魚船。覺秋風、未曾吹著，但砌蘭、長倚北堂萱。千千歲，上天將相，平地神仙。\"","sortOrder":29},
  {"id":"s_work_tddn_13_30","chapterId":"ch_work_tddn_13","text":"奚[1234]倬然《齊天樂》雲：\"金飄吹净人間暑，連朝弄涼新雨。萬寶功成，無人解得，秋入天機深處。間中自數，幾心酌乾坤，手斟霜躇。護了山河，共看元影在銀兔。而今神仙正好，向青空觅个，冲澹襟宇。帝念群生，如何便肯，從我乘風歸去。夷遊洞府，把月杼雲機，教他兒女。水逸山明，此情天付與。\"從橐《陂塘柳》雲：\"指庭前、翠雲金雨，霏霏香滿仙字。一清透彻浑無底，秋水也無流處。君试數，此樣襟懷，頓得乾坤住。閒情半許，聽萬物氤氲，從來形色，每向靜中觑。琪花路。相接西池寿母，年年絃月時序。荷衣菊佩尋常事，分付兩山容與。天證取，此老平生，可向青天語。瑤卮缓舉，要見我何心，西湖萬頃，來去自鷗鷺。\"","sortOrder":30},
  {"id":"s_work_tddn_13_31","chapterId":"ch_work_tddn_13","text":"郭應酉居安《聲聲慢》雲：\"捷書連晝，甘雨洒通宵，新來喜沁尧眉。許大擔當，人間佛力須弥。年年八月八日，長記他三月三時，平生事，想氐和天語，不遣人知。一片閒心鶴外，被乾坤系定，虹玉腰围。閶閹雲邊，西風萬籁吹齊。歸舟更歸何處是，天教家在蘇堤。千千歲，比周公，多个彩衣。\"且侑以俪語雲：\"彩衣宰辅，古無一品之曾參；袞服湖山，今有半閒之姬旦。\"所謂三月三者，蓋頌其庚申草坪之捷，而歸舟乃舫斋名也。贾大喜，自仁和宰除官告院。既而語客曰：\"此詞固佳，然失之太俳，安得有著彩衣周公乎？\"","sortOrder":31},
  {"id":"s_work_tddn_13_32","chapterId":"ch_work_tddn_13","text":"○事聖茹素","sortOrder":32},
  {"id":"s_work_tddn_13_33","chapterId":"ch_work_tddn_13","text":"餘家濟南歷城，曾大父少師遭靖康狄難，一家十六人皆奔竄四出。大父獨逃空穀，晝伏宵行。一旦，遇追騎在後，自度不可脱，遂急竄古祠，亟伏佑聖坐下，傍無蔽障，亦不過待盡而已。須臾，北軍大索，雖眢井、林莽、棟梁間，極其冥搜，而一坐之下，初不知有人焉。及抵杭，則一家不期而集，不失一人，豈非神所佑乎？逮今吾家世事佑聖甚虔。凡聖降日，斋戒必謹。蓋以答神庥詔子孫，非世俗祈福田利益比也。","sortOrder":33},
  {"id":"s_work_tddn_13_34","chapterId":"ch_work_tddn_13","text":"○笏異","sortOrder":34},
  {"id":"s_work_tddn_13_35","chapterId":"ch_work_tddn_13","text":"汪伯彦初拜相於維扬，正謝上殿，而笏墜中斷，上以他笏賜之，非吉征也。未幾，有南渡之扰。","sortOrder":35},
  {"id":"s_work_tddn_13_36","chapterId":"ch_work_tddn_13","text":"金淵叔參預日，一日，奏事下殿，與台臣劉應弼邂逅。忽所持笏铿然有聲，视之，有紋如線，上下如一，若墜於地者，殊不可测。甫退朝，則劉彈章已出。蓋降陛相遇之际，正白簡初上之時也，可謂異矣。時淳祐甲辰歲也。","sortOrder":36},
  {"id":"s_work_tddn_13_37","chapterId":"ch_work_tddn_13","text":"○三教圖贊","sortOrder":37},
  {"id":"s_work_tddn_13_38","chapterId":"ch_work_tddn_13","text":"理宗朝，有待詔馬遠畫《三教圖》。黃面老子則跏趺中坐，猶龍翁俨立於傍，吾夫子乃作禮於前。此蓋內故令作此，以侮聖人也。一日傳旨，俾古心江子遠作贊，亦故以此戲之。公即贊之曰：\"釋氏趺坐，老聃傍睨，惟吾夫子，絕倒在地。\"遂大稱旨。其辭亦可謂微而婉矣。","sortOrder":38},
  {"id":"s_work_tddn_13_39","chapterId":"ch_work_tddn_13","text":"○捕猿戒","sortOrder":39},
  {"id":"s_work_tddn_13_40","chapterId":"ch_work_tddn_13","text":"邓艾征涪陵，見猿母抱子，艾射中之。子為拔箭，取木葉塞創。艾叹息，投弩水中。","sortOrder":40},
  {"id":"s_work_tddn_13_41","chapterId":"ch_work_tddn_13","text":"范蜀公載吉州有捕猿者，殺其母之皮，併其子賣之龍泉萧氏。示以母皮，抱之跳踯號呼而毙，萧氏子為作《孝猿傳》。","sortOrder":41},
  {"id":"s_work_tddn_13_42","chapterId":"ch_work_tddn_13","text":"先君向守鄞江，屬邑武平素產金絲猿，大者難馴，小者則其母抱持不少置。法當先以藥矢毙其母，母既中矢，度不能自免，則以乳汁遍洒林葉間，以飲其子，然後墮地就死。乃取其母皮痛鞭之，其子亟悲鳴而下，束手就獲。蓋每夕必寢其皮而後安，否則不可育也。噫！此所謂獸状而人心者乎！取之者不仁甚矣。故先子在官日，每嚴捕弋之禁雲。","sortOrder":42},
  {"id":"s_work_tddn_13_43","chapterId":"ch_work_tddn_13","text":"○火浣布","sortOrder":43},
  {"id":"s_work_tddn_13_44","chapterId":"ch_work_tddn_13","text":"東方朔《神異經》所載，南荒之外有火山，晝夜火然。其中有鼠重有百斤，毛長二尺餘，細如絲，可作布。鼠常居火中，時出外，以水逐而沃之方死。取其毛緝織為布，或垢，浣以火，燒之則净。又《十洲記》雲：\"炎州有火林山，山上有火鼠，毛可織為火浣布，有垢，燒即除。\"其說不一。魏文帝嘗著論，謂世言異物，皆未必真有。至明帝時，有以火浣布至者，於是遂刊此論。是知天壤間何所不有？耳目未接，固未可斷以為必無也。","sortOrder":44},
  {"id":"s_work_tddn_13_45","chapterId":"ch_work_tddn_13","text":"昔溫陵有海商漏舶，搜其橐中，得火鼠布一匹，遂拘置郡帑。凡太守好事者，必割少許歸以為玩。外大父常守郡，亦得尺許。餘嘗親見之，色微黃白，頗類木棉，絲縷蒙茸，若蝶紛蜂黃然。每浣以油腻，投之炽火中，移刻，布與火同色。然後取出，則絜白如雪，了無所損，後為人強取以去。（或雲，石炭有絲，可織為布，亦不畏火，未知果否。）","sortOrder":45},
  {"id":"s_work_tddn_13_46","chapterId":"ch_work_tddn_13","text":"○歷差失閏","sortOrder":46},
  {"id":"s_work_tddn_13_47","chapterId":"ch_work_tddn_13","text":"鹹淳庚午十一月三十日冬至，後為閏十一月，既已頒歷，而浙西安撫司准備差遣臧元震，以書白堂，且作《章歲積日圖》，力言置閏之誤。","sortOrder":47},
  {"id":"s_work_tddn_13_48","chapterId":"ch_work_tddn_13","text":"其說謂歷法以章法為重，章歲為重。蓋歷數起於冬至，卦氣起於中孚，而十九年為之一章。一章必置七閏，必第七閏在冬至之前，必章歲至朔同日，此其綱領也。《前漢律歷志》雲：\"朔旦冬至，是謂章月。\"《後漢志》雲：\"至朔同日，謂之章月。積分成閏，閏七而盡，其歲十九，名之曰章。\"《唐志》雲：\"天數終於九，地數終於十，合二終以紀閏餘。\"此章法之不可废也如此。今頒降庚午歲歷，乃以前十一月三十日為冬至，又以冬至後為閏十一月，殊所未晓。竊謂庚午之閏，與每歲閏月不同，庚午之冬至，與每歲之冬至又不同。蓋自淳祐壬子數至鹹淳庚午，凡十九年，是為章歲，其十一月是為章月。以十九年七閏推之，則閏月當在冬至之前，不當在冬至之後。以至朔同日論之，則冬至當在十一月初一日，不當在三十日。今若以冬至在前十一月三十日，則是章歲至朔不同日矣。若以閏月在冬至後，則是十九年之內，止有六閏，又欠一閏矣。且尋常一章，共計六千八百四十日，於內加七閏月，除小盡，積日六千九百四十日，或六千九百三十九日，止有一日來去。今自淳祐十一年辛亥章歲十一月初一日章月冬至後起算，十九年至鹹淳六年庚午章歲十一月初一日，合是冬至，方管六千九百四十日。今算造官以閏月在十一月三十日冬至之後，則此一章，只有六閏，更加六閏除小盡外，實積止有六千九百十二日，比之前後章數歲之數，實欠二十八日，歷法之差，莫甚於此。况天正冬至，乃歷之始，必自冬至後積三年餘分，而後可以置第一閏。今庚午年章歲丙寅日申初三刻冬至，去第二日丁卯，仅有四个時辰。且未有正日，安得便有餘分？且未有餘分，安得便有閏月？則是後一章發頭處，便算不行，其缪可知也。今欲改正庚午歷，却有一說，簡而易行。蓋歷法有平朔，有經朔，有定朔也。一大一小，此平朔也；兩大兩小，此經朔也；三大三小，此定朔也，此古人常行之法。今若能行定朔之說而改正之，則當以前十一月大為閏十月小，以閏十一月小為十一月大，則丙寅日冬至即可為十一月初一日，却以閏十一月初一之丁卯為十一月初二日，庶幾遞趱下一日，直至閏十一月二十九日丁未，却為大盡。如此，則冬至既在十一月初一，則至朔同日矣，閏月既在冬至節前，則十九年七閏矣。此昔人所謂晦節無定，由時消息，上合履端之始，下得歸餘於終，正此謂也。蓋自古之歷，行之既久，未有不差，既差，未有不改者。漢歷五变，而《太初歷》最密，《元和歷》最差。唐歷九变，而《大衍歷》最密，《觀象歷》最缪。本朝开基以後，歷凡九改，而莫不善於《紀元歷》。中興以後，歷凡七改，而莫善於《統元歷》。且後漢元和初歷差，亦是十九年不得七閏。雖歷已頒，亦改正之，今何惜於改正哉。","sortOrder":48},
  {"id":"s_work_tddn_13_49","chapterId":"ch_work_tddn_13","text":"於是朝廷下之有司，差官偕元震至蓬省與太史局官辨正，而太史之辭窮。朝廷從其說而改正之，因更《會天歷》為《承天歷》。元震轉一官判太史局，邓宗文、谭玉等已下，各降官有差焉。","sortOrder":49},
  {"id":"s_work_tddn_13_50","chapterId":"ch_work_tddn_13","text":"餘雖不善章元紀之數，然以杜征南《長歷》以考《春秋》之月日，雖甚精密，而其置閏之法則異乎此，竊有疑焉。謂如隱公二年閏十二月，五年、七年亦皆閏十二月，然猶是三歲一閏，五歲再閏。如莊公二十年置閏，其後則二十四年以至二十八年，皆以四歲一閏，無乃失之疏乎？僖公十二年閏，至十七年方閏；二十五年閏，至三十年方閏，率以五歲一閏，何其愈疏乎？如定公八年置閏，其後則十年，以至十二年、十四年，皆以二歲一閏，無乃失之數乎？闵之二年辛酉既閏矣，僖之元年壬戌又閏，僖之七年、八年，哀之十四年、十五年，皆以連歲置閏，何其愈數乎？至於襄之二十七年，一歲之間，頓置兩閏，蓋曰十一月辰在申，司歷過也。於是既覺其缪，故前閏建酉，後閏建戌，以應天正。然前乎此者，二十一年既有閏，二十四年、二十六年又有閏。歷年凡六，置閏者三，何緣至此失閏已再，而頓置兩閏乎？近則十餘月，遠或二十餘年，其疏數殆不可晓。豈別有其術乎？抑不明置閏之法以致此乎？併著於此，以扣識者。","sortOrder":50},
  {"id":"s_work_tddn_14_1","chapterId":"ch_work_tddn_14","text":"●卷十三","sortOrder":1},
  {"id":"s_work_tddn_14_2","chapterId":"ch_work_tddn_14","text":"○漢改秦歷始置閏","sortOrder":2},
  {"id":"s_work_tddn_14_3","chapterId":"ch_work_tddn_14","text":"餘嘗考春秋置閏之異於前矣，後閱程氏《考古編》，謂漢初不獨袭秦正朔，亦因秦歷以十月為歲首，不置閏，當閏之歲，率歸餘於終為後九月，《漢紀》、《表》及《史記》，自高帝至文帝，其書後九月皆同，是未嘗推時定閏也。至太初九年，改用夏正，以建寅為歲首，然猶歷十四載，至征和二年，始於四月後書閏月，豈史失書耶？抑自此始置閏也。餘因其說深疑之，精思其故，頗得其說焉。蓋閏月之不書者，亦偶以其時無可書之事耳。正如《春秋經》桓公四年、七年，其所紀事至夏而止，以是年秋、冬無可紀之事也。定公十四年，至秋而止，亦以是年冬無可紀之事也。魯史紀事之法，大率如此，其餘閏月亦然。觀文公六年，《經》書閏月不告月，《春秋》書閏，方見於此。复以杜預《長歷》考之，自隱至哀凡更三十餘閏，至此方書，豈曰前乎此者，皆史失書，抑豈曰，自此始有閏也。今漢紀事，正效《春秋》，如太初元年、三年，天漢元年、三年皆止於秋，太始元年則止於夏，皆以其後無事可紀，故不書耳。然則閏月不書，亦若是乎？蓋三歲一閏，五歲再閏，古歷法也。若謂自此始置閏，則合自此後三歲、五歲，累累書之。然自征和二年至後元元年，當置閏而不書，自後元二年至昭帝始元元年，乃因事而後書。其後當閏歲，又皆不書，是知不書者，偶無事耳。然則非史失書，亦非自此置閏也。雖然，此非餘臆說也，复證以《史記·歷書》，自太初更歷以至征和也，如太初二年，天漢元年、四年，太始二年皆有閏，則知餘言似可信雲。","sortOrder":3},
  {"id":"s_work_tddn_14_4","chapterId":"ch_work_tddn_14","text":"○《綱目》誤書","sortOrder":4},
  {"id":"s_work_tddn_14_5","chapterId":"ch_work_tddn_14","text":"《綱目》一書，朱夫子擬經之作也。然其間不能無誤，而學者又從而為之說。蓋著書之難，自昔而然。今漫摭數事與同志評之，非敢指摘前辈以為能也。北齊高緯，以六月遊南苑，從官死者六十人，見《本紀》。《通鑒》書曰：\"賜死。\"賜，乃之訛耳。《綱目》乃直書曰：\"殺其從官六十人。\"而不言其故，其誤甚矣。尹起莘乃為之說曰：\"此朱子書法所寓。\"且引《孟子》殺人以挺與刃與政之說，固善矣，然其實則《通鑒》誤之於前，《綱目》承之於後耳。緯荒遊無時，不避寒暑，於從官死者尚六十人，則其餘可知矣。據事直書，其罪自見，何必没其實哉！","sortOrder":5},
  {"id":"s_work_tddn_14_6","chapterId":"ch_work_tddn_14","text":"又郭威弒二君，《綱目》於隱帝書殺，於湘陰王書弒。尹又為之說雲：\"此二君有罪無罪之別也，此書法所寓也。\"然均之弒君，隱帝立已數年，湘陰未成乎君，不應書法倒置如此，亦恐誤書耳。","sortOrder":6},
  {"id":"s_work_tddn_14_7","chapterId":"ch_work_tddn_14","text":"又隋开皇十七年，詔諸司論屬官罪，聽律外决杖。《綱目》條下雲，萧摩诃子世略在江南作亂，摩诃當從坐。大理少卿趙綽固諫，上命綽退，綽曰：\"臣奏獄未决，不敢退。\"帝乃釋之。按《通鑒》，摩诃當從坐，上曰：\"世略年未二十，亦何能為？以其名將之子為人所逼耳。\"因赦摩诃。綽固諫不可，上不能奪，欲綽去而赦之，因命綽退。綽曰：\"臣奏獄未决，不敢退。\"上曰：\"大理其為朕特舍摩诃也。\"因命左右釋之。此乃綽欲令摩诃從坐，而帝特赦之耳，《綱目》誤矣。","sortOrder":7},
  {"id":"s_work_tddn_14_8","chapterId":"ch_work_tddn_14","text":"又《通鑒》貞觀元年，杜淹荐邸懷道雲：\"親見其諫煬帝幸江都。\"上曰：\"卿何自不諫？\"曰：\"臣不居重任，知諫不從。\"上曰：\"知不可諫，何為立其朝？卿仕世充尊顯，何亦不諫？\"曰：\"臣非不諫，但不從耳。\"上曰：\"世充若拒諫，卿何得免禍？\"淹不能對。按此實责其知煬帝之不可諫，而猶立其朝耳。今《綱目》乃於上言世充拒諫，易其語曰：\"然則何以立於其朝？\"失其實矣。","sortOrder":8},
  {"id":"s_work_tddn_14_9","chapterId":"ch_work_tddn_14","text":"又《綱目》开元九年冬十一月罢諸王都督刺史以後凡四條。按《通鑒》，是年之末十二月幸驪山雲雲；是歲諸王為都督刺史者悉召還雲雲。此非十一月事，亦非十二月事也，當依《通鑒》作是歲為是。","sortOrder":9},
  {"id":"s_work_tddn_14_10","chapterId":"ch_work_tddn_14","text":"又《綱目》書德宗貞元二年十一月皇後崩，不書氏。按《通鑒》，是年十一月甲午立淑妃王氏為後，至丁酉崩，特四日耳。此承《通鑒》所書，而逸其上文耳。","sortOrder":10},
  {"id":"s_work_tddn_14_11","chapterId":"ch_work_tddn_14","text":"尹又謂唐史妃久疾，帝念之，遂立為後，册訖而崩，必有所寓意者，亦過也。","sortOrder":11},
  {"id":"s_work_tddn_14_12","chapterId":"ch_work_tddn_14","text":"○秦會之收諸將兵柄","sortOrder":12},
  {"id":"s_work_tddn_14_13","chapterId":"ch_work_tddn_14","text":"秦會之既主和，懼諸將不從命，於是詔三大將入觐。一日，至都堂，問以克复之期曰：\"上驅馳霜露十餘年，似厭兵矣，今决在何時可了，遲速進退之計當若何？\"張、韓對曰：\"前者提兵，直趨某地，請糧若幹，率裁量不盡得。而退軍出某所，某人坐视不肯併力，或申請辄不報，常若不能专力雲雲。桧曰：\"有是乎？諸公今不過欲帶行一職事，足以誰何士大夫者，朝廷不靳也。\"嶽最後至，意大略同，而語加峻曰：\"如今文臣不愛錢，武臣不惜命，欲了即了耳。\"桧頷之，於是三枢密拜矣。三人累表辭謝，桧與上約，答詔视常時率遲留一二日，凡諸禮例恩賜，各自倍多。桧別下詔，三大屯皆改隸御前矣。始諸將苦斗，積職已為廉車正任，然皆起卒伍，父事大將，常不得舉首，或溷其家室。嶽師律尤嚴，將校有犯，大則誅殺，小亦鞭撻痛毒，用能役使深入如意。命既下，諸校新免所隸，可自結知，人人便宽，喜其命，就應已略定，三人扰扰，未暇問也。稍從容，見桧，始以置衔漏掛兵權為請。桧笑曰：\"諸君知宣撫製置使乎？此邊官爾。諸公今為枢庭官，顧不役屬耶？\"三人者怅怅而退，始悟失兵柄焉。","sortOrder":13},
  {"id":"s_work_tddn_14_14","chapterId":"ch_work_tddn_14","text":"○張才彦","sortOrder":14},
  {"id":"s_work_tddn_14_15","chapterId":"ch_work_tddn_14","text":"歷陽張邵才彦，乃總得居士祁晉彦之兄也。建炎三年，自承務郎上書賜對，假大宗伯奉使撻覽軍前，拘留幽燕者凡十五年。及和議成，紹興十三年，始與洪皓、朱弁俱還。後為敷文閣待製，奉祠累年。乙亥更化，得知池陽，卒。初，總得為小官時，嘗為常子正同、胡明仲寅論荐。其後子正死，明仲斥久矣。紹興二十四年，總得之子安國由乡荐试得對集英，考官置第七，秦埙為冠。埙试浙漕、南宮，皆第一。先臚傳一夕，進御安國卷，紙既厚，筆墨复精妙，上覽之喜甚，擢為首選，實以抑秦，秦不能堪，曰：\"胡寅雖遠斥，力猶能使故人子為状元邪！\"已而廷唱，上又稱其詩，安國詣謝。秦問：\"學何書？\"曰：\"顏書。\"又曰：\"上愛状元詩，常觀誰詩？\"曰：\"杜詩。\"秦色莊，笑曰：\"好底盡為君占却。\"","sortOrder":15},
  {"id":"s_work_tddn_14_16","chapterId":"ch_work_tddn_14","text":"先是太母歸自北方，將發，得與天族別。淵聖偃臥車前，泣曰：\"幸語丞相歸我，處我一郡足矣。\"才彦時亦聞之，痛憤。至是，服中遺相書，謂彼雖欲留淵聖以堅和好，然所貪者金帛，實不難於還，宜亟遣使。因大忤之，悔已莫及。更為好詞，上疏頌其靖康乞立趙氏，冀贖失言之罪。上方褒秦和戎之功，才彦遂自秘選躐進敷文待製，秦愈疑之。才彦居四明，杜門絕交不出，懼禍，乃為佯狂。初，出使未還，妻李卒於家已累年。至是妄言吾妻死非命，且指總得為辭。蓋是時，實由已病言，或出於狂易；抑知安國得罪，冀以自免。語轉上聞，於是逮總得赴大理獄，鞫殺嫂事，囚系甚苦。其年十月，秦死。逼歲，安國叫閽，中批命刑部尚書韓仲通特入棘寺，始得釋去。方被逮時，道無錫，夢大士告以無恐，蓋預知秦亡。然因是總得亦病狂惑。","sortOrder":16},
  {"id":"s_work_tddn_14_17","chapterId":"ch_work_tddn_14","text":"安國更八郡，有德愛。以當暑送虞雍公飲芜湖舟中，中暑卒，年才三十餘，士論惜之。","sortOrder":17},
  {"id":"s_work_tddn_14_18","chapterId":"ch_work_tddn_14","text":"○韓通立傳","sortOrder":18},
  {"id":"s_work_tddn_14_19","chapterId":"ch_work_tddn_14","text":"舊傳焦千之學於欧陽公，一日，造劉貢父，劉問：\"《五代史》成邪？\"焦對將脱稿。劉問：\"為韓瞠眼立傳乎？\"焦默然。劉笑曰：\"如此，亦是第二等文字耳。\"","sortOrder":19},
  {"id":"s_work_tddn_14_20","chapterId":"ch_work_tddn_14","text":"《唐餘錄》者，直集賢院王子融所撰，寶元二年上之。時惟有薛居正《五代史》，欧陽書未出也。此書有紀、志、傳，又博采諸家之說，效裴松之《三國志註》，附見下方。表韓通於《忠義傳》，且冠之以國初褒赠之典，《新》、《舊史》皆所不及焉。乃王沂公曾之弟，後以元杲反，乞以字為名。其後呂伯恭編《文鑒》，製、詔一類，亦以褒赠通製為首，蓋祖幹融之意也。","sortOrder":20},
  {"id":"s_work_tddn_14_21","chapterId":"ch_work_tddn_14","text":"○老蘇族譜記","sortOrder":21},
  {"id":"s_work_tddn_14_22","chapterId":"ch_work_tddn_14","text":"沧洲先生程公許，字季與，眉山人，仕至文昌，寓居上，與先子從容談蜀中舊事，歷歷可聽。其言老泉《族譜亭記》，言乡俗之薄，起於某人，而不著其姓名者，蓋蘇與其妻党程氏大不鹹，所謂某人者，其妻之兄弟也。老泉有《自尤》詩，述其女事外家，不得志以死，其辭甚哀，則其怨隙不平也久矣。其後東坡兄弟以念母之故，相與釋憾。程正辅於坡為表弟，坡之南遷，時宰聞其先世之隙，遂以正辅為本路憲將，使之甘心焉。而正辅反篤中外之義，相與周旋之者甚至。坡詩往复倡和，中亦可概見矣。","sortOrder":22},
  {"id":"s_work_tddn_14_23","chapterId":"ch_work_tddn_14","text":"正辅上世為縣錄事，縣有殺人者，獄已具，程獨疑之，因缓其事，多方物色之，果得真殺人者，而系者遂得釋。他日，役滿家居，夢神告之曰：\"汝有活冤獄之功，當令汝子孫名宦相繼，為衣冠盛族。\"至其子遂擢第，其後益大，如夢言，然多行不義，德馨弗聞。","sortOrder":23},
  {"id":"s_work_tddn_14_24","chapterId":"ch_work_tddn_14","text":"有名唐者，宣政間附王、蔡，最貴顯。又有名敦厚字子山者，亦知名。邵康節之孫溥公濟守眉日，子山與之不鹹，廉得其罪状，用匹絹大書，櫝盛之，遣介持抵成都帥府治之前逆旅舍，委之而去。逆旅人得之以告帥，萧振德起得之，以為奇货，逮公濟赴成都獄，嚴鞫之。獄吏知其冤，遂教公濟一切承之，不然，死無以自明，公濟悟，如其教不复辯。獄上，朝論以為匿名書，法不當受，而製司非得旨，不應擅逮守臣，遂皆罢之。公濟雖得勿問，而憤憤不能堪，訴之於天，許黃十壇，至其子始偿如數。子山之居極壮麗，一夕大火，不遺寸椽。子山本附秦桧，至右史，後忤意，謫安遠縣令以死焉。","sortOrder":24},
  {"id":"s_work_tddn_14_25","chapterId":"ch_work_tddn_14","text":"○中謝中贺","sortOrder":25},
  {"id":"s_work_tddn_14_26","chapterId":"ch_work_tddn_14","text":"今臣僚上表，所稱惟誠惶誠恐，及誠歡誠喜、頓首稽首者，謂之中謝中贺。自唐以來，其體如此。蓋臣某以下，亦略叙數語，便入此句，然後敷陳其詳。如柳子厚《平淮西贺表》：\"臣負罪積衅，违尚書箋表，十有四年\"雲雲，\"懷印曳绂，有社有人\"，語意未竟也。其下既雲\"誠惶誠恐\"，蓋以此一句，結上數語雲爾。","sortOrder":26},
  {"id":"s_work_tddn_14_27","chapterId":"ch_work_tddn_14","text":"今人不察，或於首聯之後，凑用兩短句，言震惕之義，而复接以中謝之語，則遂成重复矣。前辈表章如東坡、荆公，多不失此體。近時周益公為相，《謝复封表》雲：\"華陽黑水，裂地而封，舊物青氈，從天而下。磨玷之勤未泯，執圭之寵弥加。臣誠惶誠恐。\"或以為疑，嘗以問公，公答之正如此。","sortOrder":27},
  {"id":"s_work_tddn_14_28","chapterId":"ch_work_tddn_14","text":"○复、覆、伏三字音義","sortOrder":28},
  {"id":"s_work_tddn_14_29","chapterId":"ch_work_tddn_14","text":"复、覆、伏三字音義相出入，易於混亂，今各疏於左。复有三字音，房六切者，复歸之复也，字書訓以往來，是也。《易卦》之《复》，《毛詩》\"复古复竟\"，《論語》\"言可复也\"，\"克己复禮\"，皆是也。《易註》雲\"還\"，《語註》\"猶覆\"，與《詩》\"為恢复之复\"，其義一也。扶富切者，又之義也，字書訓以又，是也。《書》\"复歸於亳\"，《詩》\"复會諸侯\"，《語》\"复夢周公\"，\"則不复也\"，及\"复見复聞\"之類，皆是也。芳六切，與覆同音者，反复之复也。《易乾象贊》\"反复道也\"，《釋文》\"芳六反，本亦作覆，是也\"。","sortOrder":29},
  {"id":"s_work_tddn_14_30","chapterId":"ch_work_tddn_14","text":"覆亦有三音，芳六反者，反覆之覆也，字書訓以反，是也。《中庸》\"傾者覆之\"，註：\"败也。\"與《易》\"反复道也\"之复，音同義異。敷救切者，覆帱之覆也，字書訓以蓋，是也。扶又切者，伏兵也。《左傳》\"君為三覆以待之\"是也。","sortOrder":30},
  {"id":"s_work_tddn_14_31","chapterId":"ch_work_tddn_14","text":"伏亦有三音，房六切者，伏羲之伏也，字書訓以伺也、匿也、隱也，是也。三伏之伏，及伏羲、優生、赤伏符，皆是也。扶富切者，鳥抱卵也。《莊子》\"越雞不能伏鵠卵\"，及《後漢》\"大丈夫當雄飛，安能雌伏\"皆是也。《前漢·五行志》\"元帝初元中，丞相府史家雌雞伏子\"，顏雲：\"房富反。\"用字者，不可以不辨焉。","sortOrder":31},
  {"id":"s_work_tddn_14_32","chapterId":"ch_work_tddn_14","text":"○嶽武穆逸事","sortOrder":32},
  {"id":"s_work_tddn_14_33","chapterId":"ch_work_tddn_14","text":"杜充之駐建康也，嶽飛軍立硬寨於宜興，命親將守之。飛兵出不利，夫人密諭親將選精銳、具糇糧，潛為策應之備。未幾，飛兵還，即入教場呼問之曰：\"汝欲何為？\"曰：\"聞太尉軍小不利，故擇敢戰之士以備策應，此男女孝順耳。\"飛曰：\"吾命汝堅守根本，天不能移，地不能動。汝今不待吾令，擅自動搖，是無師律也。\"立命责短状，將大懼，祈哀吐實，謂此非某所自為，蓋夫人亦曾有命耳。飛愈怒，竟斬之。","sortOrder":33},
  {"id":"s_work_tddn_14_34","chapterId":"ch_work_tddn_14","text":"又紹興和議初成，金人以河南歸我。判宗正事士亻，衔命道荆、襄、宛、洛，只謁巩襄原。道過南邓，嶽飛止之曰：\"金虜無信，君宜少駐。\"士亻以上命有程，辭去。不數舍，煙尘四起，軍聲嚣然，於是失色南奔。忽遇大軍，望之，嶽幟也，遂馳就之。飛笑曰：\"固謂君勿行，正恐此耳。然已遣董御帶、牛觀察在前與之交鋒矣。兵勝败無常，君王人，且近屬，吾當以自己兵衛送君。\"行數里，兩將捷書至，蓋亻未行前一日出師也。其後飛得罪下獄，亻極辯其無辜，且以百口保之。非惟感恩，蓋親見其用兵神速故耳。朝臣併論亻身為宗室，不應交結將帥，因指為飛党，遂罢宗司與祠雲。","sortOrder":34},
  {"id":"s_work_tddn_14_35","chapterId":"ch_work_tddn_14","text":"又張魏公之出督也，陛辭之日，與高宗約曰：\"臣當先驅清道，望陛下六龍夙駕，約至汴京，作上元帥。\"飛聞之曰：\"相公得非睡語乎？\"於是魏公憾之終身。","sortOrder":35},
  {"id":"s_work_tddn_14_36","chapterId":"ch_work_tddn_14","text":"○若幹如幹","sortOrder":36},
  {"id":"s_work_tddn_14_37","chapterId":"ch_work_tddn_14","text":"若幹二字，出古禮乡射。《大射》數射算雲：若幹純、若幹奇。若，如也；幹，求也。言事本不定，嘗如此求之。又《曲禮》：\"問天子之年，聞之始服衣若幹尺矣。\"《前漢·食货志》顏註雲：\"設數之言也。幹如个，謂當如个數也，亦曰如幹。\"《文選·任彦升竟陵王状》：\"食邑如幹戶。\"註雲：\"如幹戶即若幹戶也。\"","sortOrder":37},
  {"id":"s_work_tddn_14_38","chapterId":"ch_work_tddn_14","text":"然又為复姓，後周有若幹鳳，及右將軍若幹惠。若，音人者反。《釋文》雲：\"以國為姓。\"然則若幹又國名也。","sortOrder":38},
  {"id":"s_work_tddn_14_39","chapterId":"ch_work_tddn_14","text":"○祠山應語","sortOrder":39},
  {"id":"s_work_tddn_14_40","chapterId":"ch_work_tddn_14","text":"餘世祀祠山張王，動止必祷，應如蓍龟，姑志奇验數事於此，以彰神休。先子需澄江次，為有力者攘去，再以毗陵等三壘幹祀地，逾月不報。先妣時留，祷於南關之祠，有\"水邊消息的非遙\"之語，及收杭信，則聞霍山所祈，亦得此签，越日臨汀之命下矣。","sortOrder":40},
  {"id":"s_work_tddn_14_41","chapterId":"ch_work_tddn_14","text":"戊辰年，鑄子甫五歲，病骨蒸，势殆甚，凡藥皆弗效。祷签得《蠱之上九》雲：\"蠱有三頭，紛紛扰扰，如虫在皿，執一則了。\"退謀之医，试投逐虫之剂，凡去尤蛔二，其色如丹，即日良愈。","sortOrder":41},
  {"id":"s_work_tddn_14_42","chapterId":"ch_work_tddn_14","text":"甲寅春往桐川炷香，得签雲：\"不堪疾病及東床\"雲雲。是歲外舅捐馆。壬午五月二十八日，杭城金波桥冯氏火作，次日，势益張，雖相去幾十里，而人情惶惶不自安。時楊大芳、潘夢得皆同居，相慰勞曰：\"巫言神語皆吉，毋庸輕動。\"餘不能决，因卜去就於神，得五十六雲：\"遭人彈劾失官資，火欲相焚盜欲窥。\"於是挈家湖濱，是夕四鼓，遂成焦土。","sortOrder":42},
  {"id":"s_work_tddn_14_43","chapterId":"ch_work_tddn_14","text":"○傅伯寿以啟擢用","sortOrder":43},
  {"id":"s_work_tddn_14_44","chapterId":"ch_work_tddn_14","text":"傅伯寿為浙西憲。韓胄用事，伯寿首以啟贽之曰：\"澄清方效於范滂，跋扈遽逢於梁冀。人無恥矣，鹹依右相之山；我則異欤，獨仰韓公之斗。首明趨向，願出熔陶。\"由是擢用至佥書枢密院事。韓败，追三官，奪執政恩。","sortOrder":44},
  {"id":"s_work_tddn_14_45","chapterId":"ch_work_tddn_14","text":"○林外","sortOrder":45},
  {"id":"s_work_tddn_14_46","chapterId":"ch_work_tddn_14","text":"林外字豈尘，泉南人。詞翰瀟爽，詼譎不羁，飲酒無算。在上庠，暇日獨遊西湖，幽寂處得小旗亭，飲焉。外美風姿，角巾羽氅，飄飄然神仙中人也。豫市虎皮錢箧數枚藏腰間，每出其一，命酒家保傾倒，使视其數，酬酒直即藏去。酒且盡，复出一箧，傾倒如初。逮暮，所飲幾斗餘，不醉，而箧中錢若循環無窮者，肆人皆驚異之。將去，索筆題壁間曰：\"藥爐丹竈舊生涯，白雲深處是吾家。江城恋酒不歸去，老却碧桃無限花。\"明日都下盛傳某家酒肆有神仙至雲。又嘗為《垂虹亭》詞，所謂\"飛梁遏水者\"，倒題桥下，人亦傳為呂翁作。惟高廟識之曰：\"是必閩人也，不然，何得以鎖字协埽字韻。\"已而知其果外也。此詞已有紀載，茲不复書。","sortOrder":46},
  {"id":"s_work_tddn_14_47","chapterId":"ch_work_tddn_14","text":"南劍黯淡滩，湍险善覆舟，行人多畏避之。外嘗戲題滩傍驿壁曰：\"千古傳名黯淡滩，十船過此九船翻。惟有泉南林上舍，我自岸上走，你怎奈何我？\"雖一時戲語，頗亦有味。","sortOrder":47},
  {"id":"s_work_tddn_14_48","chapterId":"ch_work_tddn_14","text":"○甄雲卿","sortOrder":48},
  {"id":"s_work_tddn_14_49","chapterId":"ch_work_tddn_14","text":"永嘉甄雲卿字龍友，少有俊聲，詞華奇麗。而資性浮躁，於乡人無不狎侮，木待問蘊之為尤甚。木生朝，為詞贺之，末雲：\"聞道海壇沙涨也，明年。\"蓋諺雲：\"海壇沙涨，溫州出相。\"明年者，俗言且待也。又嘗損益前人酒令曰：\"金銀銅鐵鋪，絲綿綢絹綱，鬼魅魍魉魁。\"蓋木以癸未魁天下也。","sortOrder":49},
  {"id":"s_work_tddn_14_50","chapterId":"ch_work_tddn_14","text":"甄辯給雄一時，謔笑皆有餘味。一日登對，上戲問雲：\"卿安得與龍為友？\"甄仓忙占奏，殊不能佳。及退殿陛，自恨失言曰：\"何不雲尧舜在上，臣安得不與夔龍為友？\"聞者惜之。","sortOrder":50},
  {"id":"s_work_tddn_14_51","chapterId":"ch_work_tddn_14","text":"競渡日，著彩衣立龍首，自歌所作《思遠樓前》之詞，旁若無人。然於性理解悟，凡禪衲機鋒，皆莫能答。將亡之日，命其子阎湯，且召蘊之，將嘱以後事。甄居城外，昏暮門阖不得入，其子白之，甄曰：\"然則勿阎以待旦。\"既旦，木聞之亟來，甄喜曰：\"吾將行，得君主吾丧，則濟矣。\"木許诺，乃入浴更衣，與木訣，坐而逝。既复开目曰：\"吾儒無此也。\"复臥，乃絕。","sortOrder":51},
  {"id":"s_work_tddn_14_52","chapterId":"ch_work_tddn_14","text":"○西林道人","sortOrder":52},
  {"id":"s_work_tddn_14_53","chapterId":"ch_work_tddn_14","text":"端平間，周文璞、趙師秀數詩人，春日薄遊湖山，極飲西林桥酒壚，皆大醉熟睡。忽有ヮ髻道人過而睨之，哂曰：\"詩仙醉邪？\"顧酒家：\"善看客，我當代偿酒錢。\"索水小盂，以瓢中藥少投之，入口略嗽，巽之地上，則皆精銀也。時遊人方盛，皆環视駭叹，忽失道人所在。薄暮，諸公始醒，酒家具道所以，皆怅然自失。其家持銀往市，得錢止可酬所直，了無贏餘。明日，喧傳都下，酒家圖其事於壁，自以為遇仙酒肆。好事者競趨之，遂為湖山旗亭之甲，而諸公亦若有悟雲。","sortOrder":53},
  {"id":"s_work_tddn_14_54","chapterId":"ch_work_tddn_14","text":"○崔福","sortOrder":54},
  {"id":"s_work_tddn_14_55","chapterId":"ch_work_tddn_14","text":"崔福，故群盜也，嘗為官軍所捕。會夜大雪，方與婴兒同榻，兒寒夜啼，不得睡覺。捕者至，因以故衣擁兒口，兒得衣，身暖啼止，遂得逸去。因隸籍軍伍，累從陳子華捕賊，積功至刺史、大將軍。後從陳往江西，留南昌。既而子華易阃金陵，兼節製淮西，而崔仍留洪。時ヘ攝郡，一日，ヘ與郡僚宴滕王閣，崔怒其不見招，憾之。適至府治前，民有立牌訴冤者，崔乃携其人，直至飲所，责以郡官不理民事。嗾諸卒盡碎其飲器，官吏皆奔逸竄去，莫敢婴其鋒。子華知之，遂檄還建康。會淮西有警，命王鑒出師，鑒請福為援。福不樂為鑒用，托以葬女擅歸。鑒怒，遂白其前後過惡，且必正其慢令之罪。會子華亦厭忌之，於是遂從軍法，然後聲其罪於朝。","sortOrder":55},
  {"id":"s_work_tddn_14_56","chapterId":"ch_work_tddn_14","text":"福勇悍善戰有聲，其死也軍中惜之。然其跋扈之跡已不可掩，殺身之禍，實有以自取之也。","sortOrder":56},
  {"id":"s_work_tddn_14_57","chapterId":"ch_work_tddn_14","text":"○張林叔弓","sortOrder":57},
  {"id":"s_work_tddn_14_58","chapterId":"ch_work_tddn_14","text":"張，延平人。少負才入太學，有聲，為節性斋長，既又為時中斋長。其人眇小而好作為，動以苛禮律諸生，同舍多不平之。","sortOrder":58},
  {"id":"s_work_tddn_14_59","chapterId":"ch_work_tddn_14","text":"莆田林叔弓，亦輕浮之士也，於是以其名字作詩賦各一首嘲之。其警聯雲：\"身材短小，欠曹交六尺之長；腹內空虛，乏劉叉一點之墨。\"詩警句雲：\"中分爻兩段，風使十橫斜。文上元無分，人前強出些。\"曲盡形容之妙，聞者絕倒。又私试《辟四門》賦雲：\"想帝女下嫔，大展親家之禮；谅商均不肖，幾成太子之遊。\"《天子之堂九尺》雲：\"假令晏子來朝，莫窥其面；縱使曹交入見，仅露其頭。\"《顏淵具體而微》賦雲：\"博我以文，約我以禮，望之俨然；道與之貌，天與之形，眇乎小爾。\"亦皆叔弓之所為也。","sortOrder":59},
  {"id":"s_work_tddn_14_60","chapterId":"ch_work_tddn_14","text":"○優語","sortOrder":60},
  {"id":"s_work_tddn_14_61","chapterId":"ch_work_tddn_14","text":"宣和中，童貫用兵燕蓟，败而竄。一日內宴，教坊進伎為三四婢，首飾皆不同。其一當額為髻，曰蔡太師家人也；其二髻偏墜，曰鄭太宰家人也；又一人滿頭為髻如小兒，曰童大王家人也。問其故，蔡氏者曰：\"太師觐清光，此名朝天髻。\"鄭氏者曰：\"吾太宰奉祠就第，此懶梳髻。\"至童氏者曰：\"大王方用兵，此三十六髻也。\"","sortOrder":61},
  {"id":"s_work_tddn_14_62","chapterId":"ch_work_tddn_14","text":"近者己亥歲，史之為京尹，其弟以參政督兵於淮。一日內宴，伶人衣金紫，而幞頭忽脱，乃紅巾也。或驚問曰：\"賊裹紅巾，何為官亦如此？\"傍一人答雲：\"如今做官底，都是如此。\"於是褫其衣冠，則有萬回佛自懷中墜地。其旁者雲：\"他雖做賊，且看他哥哥面。\"","sortOrder":62},
  {"id":"s_work_tddn_14_63","chapterId":"ch_work_tddn_14","text":"又女官吳知古用事，人皆侧目。內宴日，參軍四筵張樂，胥辈請佥文書，參軍怒曰：\"我方聽栗，可少缓。\"請至三四，其答如前。胥击其首曰：\"什事不被栗坏了。\"蓋是俗呼黃冠為栗也。","sortOrder":63},
  {"id":"s_work_tddn_14_64","chapterId":"ch_work_tddn_14","text":"王叔知吳門日，名其酒曰彻底清。錫宴日，伶人持一樽夸於眾曰：\"此酒名彻底清。\"既而开樽，則濁醪也。旁誚之雲：\"汝既為彻底清，却如何如此？\"答雲：\"本是彻底清，被錢打得浑了。\"此類甚多，而蜀優尤能涉獵古今，援引經史，以佐口吻資笑談。","sortOrder":64},
  {"id":"s_work_tddn_14_65","chapterId":"ch_work_tddn_14","text":"當史丞相弥遠用事，選人改官，多出其門。製阃大宴，有優為衣冠者數辈，皆稱為孔門弟子。相與言，吾儕皆選人，遂各言其姓曰：吾為常從事，吾為於從政，吾為吾將仕，吾為路文學。別有二人出曰：\"吾宰予也。夫子曰：'於予與改。'可謂僥幸。\"其一曰：\"吾顏回也。夫子曰：'回也不改。'吾為四科之首而不改，汝何為獨改？\"曰：\"吾鑽故改，汝何不鑽？\"回曰：\"吾非不鑽，而鑽弥堅耳。\"曰：\"汝之不改宜也，何不鑽弥遠乎？\"其離析文義，可謂侮聖言，而巧發微中，有足稱言者焉。","sortOrder":65},
  {"id":"s_work_tddn_14_66","chapterId":"ch_work_tddn_14","text":"有袁三者，名尤著。有從官姓袁者，製蜀，頗乏廉聲。群優四人，分主酒色财氣，各夸張其好尚之樂，而餘者互譏誚之。至袁優，則曰：\"吾所好者财也。\"因極言财之美利，眾亦譏誚之不已。徐以手自指曰：\"任你譏笑，其如袁丈好此何？\"","sortOrder":66},
  {"id":"s_work_tddn_14_67","chapterId":"ch_work_tddn_14","text":"○譏不肖子","sortOrder":67},
  {"id":"s_work_tddn_14_68","chapterId":"ch_work_tddn_14","text":"有士赴考，其父充役，為貼書勉其子，登第則可免。子方浪遊都城，窘無資用，即答曰：\"大人欲某勉力就试，則宜多給其費，否則至場中定藏行也。\"奕者以不露機為藏行雲。","sortOrder":68},
  {"id":"s_work_tddn_14_69","chapterId":"ch_work_tddn_14","text":"又有士父使從學，月與油燭一千，其子請益，不可，子以書白雲：\"所謂焚膏繼晷者，非為身計，正為門戶計。且異日恩封，庶幾及父母耳。有如吝小費，則大人承事，娘子孺人，遼乎邈哉！\"聞者絕倒。","sortOrder":69},
  {"id":"s_work_tddn_15_1","chapterId":"ch_work_tddn_15","text":"●卷十四","sortOrder":1},
  {"id":"s_work_tddn_15_2","chapterId":"ch_work_tddn_15","text":"○馆閣觀畫","sortOrder":2},
  {"id":"s_work_tddn_15_3","chapterId":"ch_work_tddn_15","text":"乙亥歲秋，秘書監丞黃忄全汝濟，以蓬省旬點，邀餘偕行，於是具衣冠望拜右文殿，然後遊道山堂。堂故米老書扁，後以理宗御書易之。著作之庭，胡邦衡所書，曰蓬峦，曰群玉堂。堂屏，有坡翁所作竹石，相傳淳熙間，南安守某人，乃取之長樂僧寺壁間，去其故土，而背施髹漆，匣以持獻曾海野，曾殂後，复獻韓相平原，韓誅，簿錄送官。左為汗青軒，軒後多古桂，兩旁環石柱二。小亭曰蓬萊，曰濯纓，曰方壶，曰含章，曰茹芝，曰芸香。射亭曰繹志，曰采良門。\"采良\"二字，莫知所出。","sortOrder":3},
  {"id":"s_work_tddn_15_4","chapterId":"ch_work_tddn_15","text":"登浑儀台，觀銅浑儀。紹興間內侍邵諤所為，精致特甚，色泽如銀如玉。此器凡二，一留司天台，一留此以備测验。","sortOrder":4},
  {"id":"s_work_tddn_15_5","chapterId":"ch_work_tddn_15","text":"最後步石渠，登秘閣，兩旁皆列龛藏先朝會要及御書畫，別有朱漆巨匣五十餘，皆古今法書名畫也。是日仅閱秋、收、冬、餘四匣。畫皆以鸞鵲綾、象軸為飾，有御題者，則加以金花綾。每卷表里，皆有尚書省印，防閒雖甚嚴，而往往以伪易真，殊不可晓。其佳者有董源畫《孔子哭魚邱子圖》，唐模顧恺之《洗經圖》，此二圖絕高古。李成《重峦寒溜》，孫大古《志公》，展子虔作《伏生》，無名人《三天女》，亦古妙。燕文貴紙畫山水小卷極精。土雷小景，符道隱山水，關仝山水，胡環馬，陳晦柏，文與可古木便面，亦奇，餘悉常品，亦有甚谬者。通閱一百六十餘卷，絕品不滿十焉。暇日想像書之，以為平生清賞之冠也。","sortOrder":5},
  {"id":"s_work_tddn_15_6","chapterId":"ch_work_tddn_15","text":"○針砭","sortOrder":6},
  {"id":"s_work_tddn_15_7","chapterId":"ch_work_tddn_15","text":"古者針砭之妙，真有起死之功。蓋脈絡之會，湯液所不及者，中其俞穴，其效如神，方書傳記，所載不一。若唐長孫後懷高宗，將產，數日不能分娩。詔医博士李洞玄候脈，奏雲：\"緣子以手執母心，所以不產。\"太宗問：\"當何如？\"洞玄曰：\"留子母不全，母全子必死。\"後曰：\"留子，帝業永昌。\"遂隔腹針之，透心至手，後崩，太子即誕。後至天陰，手中有瘢。庞安常视孕婦難產者，亦曰：\"兒雖已出胞，而手執母腸胃，不复脱衣。\"即扪兒手所在，針其虎口，兒既痛，即縮手而生，及觀兒虎口，果有針痕。近世屠光遠亦以此法治番陽酒官之妻。三人如出一律，其妙如此。蓋医者，意也，一時從權，有出於六百四十九穴之外者。","sortOrder":7},
  {"id":"s_work_tddn_15_8","chapterId":"ch_work_tddn_15","text":"《脞說》載李行簡外甥女，適葛氏而寡，次嫁朱訓，忽得疾如中風状。山人曹居白视之，曰：\"此邪疾也。\"乃出針刺其足外踝上二寸許，至一茶久，婦人醒，曰：\"疾平矣。\"始言每疾作時，夢故夫引行山林中。今早夢如前，而故夫為棘刺刺足胫間不可脱，惶懼宛轉，乘間乃得歸。曹笑曰：\"適所刺者，八邪穴也。\"此事尤涉神怪。餘按《千金翼》有刺百邪所病十三穴，一曰鬼宮，二日鬼信，三曰鬼壘，四日鬼心，五曰鬼路，六日鬼枕，七日鬼床，八日鬼市，九日鬼病，十曰鬼堂，十一日鬼藏，十二曰鬼臣，十三曰鬼封，然則居白所施正此耳。今世針法不傳，庸医野老，道聽涂說，勇於嘗试，非惟無益也。比聞趙信公在維扬製阃日，有老張總管者，北人也，精於用針，其徒某得其粗焉。一日，信公侍姬苦脾血疾垂殆，時張老留旁郡，亟呼其徒治之，某曰：\"此疾已殆，仅有一穴或可療。\"於是刺足外踝二寸餘，而針為血氣所吸留，竟不可出。某仓惶請罪曰：\"穴雖中，而針不出，此非吾師不可，請急召之。\"於是命流星馬宵征，凡一晝夜而老張至。笑曰：\"穴良是，但末得吾出針法耳。\"遂別於手腕之交刺之，針甫入，而外踝之針躍而出焉，即日疾愈，亦可謂奇矣。","sortOrder":8},
  {"id":"s_work_tddn_15_9","chapterId":"ch_work_tddn_15","text":"然古者，針以石為之。昔金元起欲註《素問》，訪王孺以砭石，答曰：\"古人以石為針，必不用鐵。\"《說文》有此砭字，許慎雲：\"以石刺病也。\"《東山經》雲：\"高氏之山多針石。\"郭璞雲：\"可以為砭針。\"《春秋》：\"美不如惡石。\"服子慎註雲：\"石，砭石也。\"季世無复佳石，故以針代之耳。又嘗聞舅氏章叔恭雲：昔ヘ襄州日，嘗獲试針銅人，全像以精銅為之，腑臟無一不具。其外俞穴，則错金書穴名於旁，凡背面二器相合，則浑然全身，蓋舊都用此以试医者。其法外涂黃蠟，中實以汞，俾医工以分折寸，按穴试針，中穴，則針入而汞出，稍差，則針不可入矣，亦奇巧之器也。後趙南仲歸之內府，叔恭嘗寫二圖，刻梓以傳焉，因併附見於此焉。","sortOrder":9},
  {"id":"s_work_tddn_15_10","chapterId":"ch_work_tddn_15","text":"○巴陵本末","sortOrder":10},
  {"id":"s_work_tddn_15_11","chapterId":"ch_work_tddn_15","text":"穆陵既正九五之位，皇兄濟王出封宛陵，辭不就。史丞相同叔以其有逼近之嫌，遂徙寓於城之西。寶慶元年乙酉正月八日，含山狂士潘甫與弟壬、丙率太湖亡命數十人，各以紅半袖為號，乘夜逾城而入，至邸索王，聲言義舉推戴。王聞变，易敝衣，匿水窦中，久而得之。擁至州治，旋往東嶽行祠，取龍椅置設廳，以黃袍加之。王號泣不從，胁之以兵，不獲已，與之約曰：\"汝能勿傷太後、官家否？\"眾許诺，遂發軍資库出金帛楮券犒軍。命守臣謝周卿率見任及寄居官立班，且揭李全榜於州門，聲言史丞相私意援立等罪。且稱見率精兵二十萬，水陆併進。時皆耸動，以為山東狡謀。比晓，則執兵者大半皆太湖漁人，巡尉司蠻卒辈多識之，始疑其伪。王乃與郡將謀，帥州兵剿之，其數元不滿百也，潘壬竟逸去（後明亮獲之楚州河岸）。寓公王元春遂以輕舟告变於朝，急調殿司將彭忄屯赴之，兵至，賊已就誅矣。主兵官苟統領者，堅欲入城，意在乘時劫掠。舟抵南關張王祠下，忽若有方巾著白袍人挤之入水，於是亟聞之，朝廷亦以事平，俾班師焉。使非有此，一城必大扰矣。越一日，史相遣其客餘天錫來，且頒宣医视疾之旨。時王本無疾，實使之自為之計，遂縊於州治之便室，舁歸故第治丧（本州有老徐駐泊雲：嘗往视疾，至則已死矣。見其已用錦被覆於地，口鼻皆流血，沾渍衣裳，審爾，則非縊死矣）。始欲治葬於西山寺，其後遂藁葬西溪焉。初，朝廷得報，謂出山東謀，史揆懼甚，既而事败，李全亦自通於朝，以為初不與聞，疑慮始釋。遂下詔貶王為巴陵縣公，夫人吳氏賜度牒為女冠，移居紹興，改湖州為吉安州。王元春以告变功，遂知乡郡。時秀王第十三子師弥，逃難菁山園廟，亦奖其能守園陵，躐等升嗣袭。甚者以潘阆嘗從秦王為記室，有同謀之嫌，亦黜其先賢之祀焉。先是，天台宋濟中楫為守日，更立諸坊扁，其左題曰，守臣宋濟立。未幾变作，或以為先讖雲。","sortOrder":11},
  {"id":"s_work_tddn_15_12","chapterId":"ch_work_tddn_15","text":"其後，魏了翁華父、真德秀希元、洪咨夔舜俞、潘枋庭堅，皆相繼疏其冤。大理評事庐陵胡夢昱季晦，應詔上書，引晉申生為厲，漢戾太子，及秦王廷美之事，凡萬餘言，訐直無忌，遂竄象州，翁定、杜丰、胡炎，皆有詩送之。翁雲：\"應詔書聞便遠行，庐陵不獨說邦衡。寸心只恐孤天地，百口何期累弟兄。世態浮雲多变換，公朝初日合清明。危言在國為元氣，君子從來豈願名。\"杜雲：\"庐陵一小郡，百歲兩胡公。論事雖小異，處心應略同。有書莫焚稿，無恨豈傷弓。病愧不遠別，寫詩霜月中。\"胡雲：\"一封朝奏大明宮，吹起庐陵古直風。言路從來天樣闊，蠻煙誰使径旁通。朝中競送長沙傅，嶺表爭迎小澹翁。學馆諸生空飽飯，臨分忧國意何窮？\"竟殁於貶所。","sortOrder":12},
  {"id":"s_work_tddn_15_13","chapterId":"ch_work_tddn_15","text":"端平更化，詔許歸葬，官其一子。洪舜俞當製雲：\"朕訪落伊始，首下詔求谠言，蓋與諫鼓、謗木同意。以直言求人，而以直言罪之，豈朕心哉？爾風裁峻絜，志概激壮，徭廷尉平上書公車，言人之所難言。方嘉貫日之忠，已墮偃月之計。問涂胥口，訪事泷頭，曾無幾微見於面，何氣節之烈也。仁祖能起介於遠謫之餘，孝祖能拔铨於投荒之後。撫今懷遠，魂不可招；潦霧墮鳶，追悔何及。仍官厥子，以旌折槛之直，且識投杼之過，爾雖死不朽矣。\"以周成子與謀，鞫之棘寺，不服，大理卿徐力辨其非，皆坐貶死。台諫李知孝莫泽，奉承風旨，凡平日睚眦之怒，悉指以從伪，彈劾無虛日，朝野為之侧足。越再歲，忽頒宽恩，或謂史揆嘗有所睹而然。","sortOrder":13},
  {"id":"s_work_tddn_15_14","chapterId":"ch_work_tddn_15","text":"辛卯鬱攸之变，太室省部悉為煨燼，下詔求言。籍田令徐清叟應詔疏略雲：\"人倫睦則天道順，一或悖其常，則天應之以禍也。巴陵有過，罔克繼紹，大臣协定大計，挈神器歸之陛下。不幸狂寇猝發，陷巴陵於不道，衣服僭擬，死有餘罪。然在彼縱非，而在我者不可不厚。奪爵废祀，暫焉猶可，久而不赦，厥罰甚焉。况曩因巴陵诖誤，名在丹書者，比以慶赉，生者叙复，死者歸葬。然恩及疏逖，而親者反薄，臣恐寧宗在天之靈，或謂不然也。蓋陛下之與巴陵，俱寧宗皇帝之子，陛下富貴如此，而巴陵﹃辱如彼，詎合人父均愛其子之意！近者，京城之火，上延太室，往往緣此。蓋以陛下一念之慍，忍加同氣，累載積年，猶未消釋，有以傷和而召異也。\"雲雲。","sortOrder":14},
  {"id":"s_work_tddn_15_15","chapterId":"ch_work_tddn_15","text":"癸巳六月；御筆命有司改葬，追复王爵，所有命繼之事，則事關家國，非朕敢私。","sortOrder":15},
  {"id":"s_work_tddn_15_16","chapterId":"ch_work_tddn_15","text":"丙申歲，正言方大琮奏疏亦雲：\"古今有不可亡之理，理者何？綱常是也。陛下隱之於心，其有不安者乎？臣在田野間，侧聞寧宗皇帝嘉定選擇之時，追記先朝，眷念魏邸，故陛下之立，必自魏來。彼故王退守藩服，变出仓卒，川之事，深可痛矣。臣嘗記真德秀之疏曰：'前有避匿之跡，後有讨捕之謀。'又記洪咨夔之疏曰：'川之变，非濟邸之本心，濟邸之殁，非陛下之本心。'魏了翁直前之疏，徐清叟火灾之疏，皆可謂得其情矣。胡夢昱一疏，尤為惻怛；貫穿百代之興亡，指陳天人之感應，讀之使人流涕。當是時也，天地祖宗猶有以察陛下之有所製；黃壤沉魄，猶有以亮陛下之不得已。今將十載，天毙老妖，端平改絃，威福自出，此非昭冤雪枉之時乎？臣恭睹六年六月御筆有曰'胁狂陷逆'，又曰'复爵塋墳'，而立後一事，則以事系家國，難以輕議。又恭睹二年七月御筆，有曰'衛王功茂，深欲保全其家'，又曰'札付宅之兄弟，自今臣僚，無复捃摭'。一則牢關固拒，如待深仇，何其重於繼同氣之後；一則丁寧覆護，如撫愛子，何其厚於保奸孽之家。合二筆而觀，有人心者，以為何如哉！故王之跡，非若秦邸，而秦邸子孫，至今繁盛。今也，西溪荒阡，麥飯無主，霜嫠孤寄，抑墮緇流。\"雲雲。\"臣剽聞故王嘗從陛下會朝侍班，同榻共食，情愛備至。使無弥遠先入之言，寧不怆念畴昔之故。若故王者，生蒙友愛之義，死乃不蒙繼絕之恩乎？臣聞真德秀垂殁，語其家以不能申前言為大恨。又見洪咨夔嘗對臣言曰：'上意未回，則天意亦未易回。'今二臣亡矣！獨夢昱所謂冤不散則禍不消，今雖官其一子，未足偿其一門之痛，是不惟故王之冤未散，而夢昱之論亦未明也。群臣泛議，一語及此，搖手吐舌，指為深讳。陛下豁然开悟，特下明詔，正權臣之罪，洗故王之冤，則端平德刑之大者明矣。是必改瑩？高燥，亟謀紹承，幸伉俪之猶存，庶精爽之有托。若敖之鬼不餒，新城之巫永消，則天心之悔禍有期，人心之厭亂有日，特在陛下一念間耳。宋文帝何如主，猶能還二王之家，正徐傅之戮，而况九京之下，所望於英明之主哉。\"雲雲。","sortOrder":16},
  {"id":"s_work_tddn_15_17","chapterId":"ch_work_tddn_15","text":"丙申明，大雷電雨雹，詔求直言。架閣韓祥疏曰：\"四海之大，誰無兄弟，尊為元首，寧忍忘情，宿草荒阡，彼獨何辜？二三臣子勸陛下紹巴陵之後則弗顧，請陛下行徐傅之誅則弗忍，焉知新城冤魄不日夜侧怆，請命上帝乎？\"司農丞鄭逢辰封章略曰：\"妖由人興，变不虛發。推原其故，陛下掇天怒者，其失有四：一曰天倫未篤，二日朝綱未振，三日近習之势浸張，四日後宮之寵浸盛。何謂天倫未篤？兄弟，人之大倫也。巴陵之死，幽魂藁葬，败冢荒邱，天陰鬼哭，夜雨血腥，行道之人，見者陨涕。太子申生之死，猶能請命於帝，巴陵亦先帝之子，陛下之兄也。川之变，竄身水窦，襟裾沾濡，凶徒迫胁，情實可怜。今乃燕嘗乏祀，嫠婦無歸，豈不掇天怒邪？\"雲石。","sortOrder":17},
  {"id":"s_work_tddn_15_18","chapterId":"ch_work_tddn_15","text":"丁酉火灾，三學生員上書，謂火起新房廊，乃故王舊邸之所，火至仟林寺而止，乃故王舊宅之林，皆指為伯有為厲之验。太常丞趙琳疏，亦以《春秋》鄭伯有良霄為厲之验。一時朝紳韦布，鹹謂故王之冤不伸，致幹和氣。獨府學生李道子立異一書，援唐立武後事，謂此陛下家事，勿恤人言。又有廣南額外攝官事邹雲一書，尤為可駭。大略謂：\"濟邸不能一死，受程軍、陳登之徒，班廷拜舞於仓猝之际，天日开明，著身無地，夫复何言。今天下之士，反起興怜，陛下又從而加惠之，复其爵位，給其帑藏，可謂曲盡其恩。今天下之士，不知大義所在，复以立嗣為言，簧鼓天下之聽。且濟邸雖未得罪於天下，而實得罪於《春秋》，濟王不道，法所當除。陛下尚軫在原，猶存爵位，借使勉從群議，俾延於世，不可也。矧當世情多阻之時，人心趨亂者眾，萬一貪夫不靖之徒，有以立楚懷王孫而激亂者，是時置國家於何地，其亦不思之甚矣。以真德秀之賢，猶且昧此，况他人乎？\"二人併特旨補將仕郎，權夕郎丁伯桂驳之，乃止。殿院蒋峴伯見，謂：\"火灾止是失備，更無餘說。\"且雲：\"濟邸之於陛下，本非同氣之親，非兄弟而強為兄弟。\"又雲：\"《中庸》達道，始於君臣而决於父子，《大易》二篇，基於父子而成於君臣，而况下於父子者乎？此見君臣之道，獨立於天地之間。\"又雲：\"君臣既定，父子不必言，兄弟不當問。\"又雲：\"天不能命，神不能語，巫而誣焉。\"於是太武學生劉實甫等二百餘人，相率上書力攻之，峴遂罢言職。至景定甲子歲，度宗踐祚之初，監察御史常懋長孺奏：\"巴陵之事，豈其本心？真宗能還秦邸之後，以成太宗之心，陛下豈不能為故王續一線之脈哉！\"既而御筆雲：\"濟王生前之官，先帝已與追复，尚有未复所赠官，嘗曰留以遺後人，即仁皇踐祚，赠秦王太師、尚書令之典也。所宜繼志，以慰泉壤，可追复太師、保靜镇潼軍節度使，仍令所屬讨論墳塋之製，日下增修，餘照先帝端平元年六月十二日指揮。\"","sortOrder":18},
  {"id":"s_work_tddn_15_19","chapterId":"ch_work_tddn_15","text":"又至德祐乙亥，邊事ㄈ扰，台臣以此為請。而常長孺入為文昌，一再奏陳，以為：\"此亦挽回天意之機。且川之事，非其本心，置之死地過矣，不為立後又過矣。匹夫匹婦之冤，猶能召飛霜枯草之灾，况嘗備储闈之選乎？且理宗以來，疆土日蹙，灾变日至，毋乃巴陵得請於帝乎？若子產所謂有以歸之，斯可矣。欲乞英斷，為理祖、度考了此一段未為之事，不然，臣恐申生之請未已也。\"遂有旨：太師、保靜镇潼軍節度使、濟王，特封镇王，賜謚昭肅。所有墳塋令臨安府兩浙漕司相视，更加修繕。仍令封椿安邊所拨田一萬畝給賜，仍差王應麟前往致祭，蓋應麟亦嘗有請也。又批令於兩班中，擇昭穆相當二三歲以下者，指定一員，以奉其祀。呜呼！挽回天意，至此亦晚矣，悲夫！","sortOrder":19},
  {"id":"s_work_tddn_15_20","chapterId":"ch_work_tddn_15","text":"○數奇","sortOrder":20},
  {"id":"s_work_tddn_15_21","chapterId":"ch_work_tddn_15","text":"《李廣傳》：\"廣數奇，毋令當单於。\"註雲：\"奇，不偶也，言廣命叟不偶也。數音所角切，奇、居宜切。\"宋景文以為江南本《漢書》，數乃所具切，角字乃具字之誤耳。然或以為疑。餘因考《藝文類聚》、《冯敬通集》\"吾數奇命薄\"，《唐文粹》徐敬業詩\"數奇良可叹\"，王維詩\"衛青不败由天幸，李廣無功緣數奇\"，杜詩\"數奇謫關塞，道廣存箕潁\"，羅隱詩\"數奇當自愧，時薄欲何幹\"，坡詩\"數奇逢惡歲，計拙集枯梧\"，觀其偶對，則數為命數，非疏數之數，音所具切明矣。","sortOrder":21},
  {"id":"s_work_tddn_15_22","chapterId":"ch_work_tddn_15","text":"○諫筍諫果","sortOrder":22},
  {"id":"s_work_tddn_15_23","chapterId":"ch_work_tddn_15","text":"世傳涪翁喜苦筍，嘗從斌老乞苦筍詩雲：\"南園苦筍味勝肉，籠箨稱冤莫采錄，煩君更致蒼玉束，明日風雨吹成竹。\"又《和坡翁春菜》詩雲：\"公如端為苦筍歸，明日春衫誠可脱。\"坡得詩，戲語坐客雲：\"吾固不愛做官，魯直遂欲以苦筍硬差致仕。\"聞者絕倒。嘗賦苦筍雲：\"苦而有味，如忠諫之可活國。\"放翁又從而奖之雲：\"我見魏征殊妩媚，約束兒童勿多取。\"於是世以諫筍目之。殊不知翁嘗自跋雲：\"餘生長江南，里人喜食苦筍，试取而嘗之，氣苦不堪於鼻，味苦不可於口，故嘗屏之，未始為客一設。及來黔，黔人冬掘苦筍萌於土中，才一寸許，味如蜜蔗，初春則不食，惟道人食苦筍。四十餘日出土尺餘，味猶甘苦相半。\"以此觀之，涪翁所食，乃取其甘，非貴乎苦也。南康簡寂觀有甜苦筍，周益公詩雲：\"疏食山間荼亦甘，况逢苦筍十分甜，尹看齒頰留餘味，端為森森正且嚴。\"此亦取其甜耳。世人慕名忘味，甘心荼苦者，果何謂哉。","sortOrder":23},
  {"id":"s_work_tddn_15_24","chapterId":"ch_work_tddn_15","text":"又記涪翁在戎州日，過蔡次律家，小軒外植餘甘子，乞名於翁，因名之曰味諫軒。其後王宣子予以橄榄送翁，翁賦雲：\"方懷味諫軒中果，忽見金盤橄榄來，想見餘甘有瓜葛，苦中真味晚方回。\"然則二物亦可名之為諫果也。","sortOrder":24},
  {"id":"s_work_tddn_15_25","chapterId":"ch_work_tddn_15","text":"○姚斡父雜文","sortOrder":25},
  {"id":"s_work_tddn_15_26","chapterId":"ch_work_tddn_15","text":"姚熔，字父，號秋圃，合沙老儒也，餘幼嘗師之。記誦甚精，著述不苟，潦倒餘六旬，仅以晚科主天台黃巖學，期年而殂。餘嘗得其雜著數篇，議論皆有思致。今散亡之餘，仅存一二，懼复失墜，因錄之以著餘拳拳之懷。","sortOrder":26},
  {"id":"s_work_tddn_15_27","chapterId":"ch_work_tddn_15","text":"《喻白蚁文》雲：\"物之不靈，告以話言而弗聽，俗所謂對馬牛而誦經是已。雖然，群生之類，皆含佛性，皆具天機。百舌能語，白鷺能棋，伯牙絃清而魚聽，海翁機露而鷗疑，害稼之蝗知卓茂，害人之鱷識昌黎，若此之類，言可喻，理可化，安可例以馬牛而待之。况夫蝼蚁至微，微而有知。自國於大槐以來，則有君臣尊卑。南柯一夢，言語與人通，井邑與人同。人但見其往來憧憧，而不知其市聲訌訌。固自有大小長幼之序，前呼後唤之响，默傳於寂然無哗之中。一种俱白，號曰地虎，族類蕃昌，其來自古。賦性至巧，累土為室，有觜至刚，嚙木為糧。吾嘗窥其窟穴矣，深閨邃閣，千門萬戶，離宮別馆，复屋修廊。五里短亭，十里長亭，缭繞乎其甬道；五步一樓，十步一閣，玲瓏乎其蜂房。嗟爾之巧則巧矣，盛則盛矣，然卵生羽化，方孳育而未息，鑽椽穴柱，不盡嚼而不已。遂使修廊為之空洞，廣厦為之頹圮。夫人營創，亦雲難矣，上棟下宇，欲維安止，爾乃鳩居之而不恤，蠶食之而無恥，天下其寧有是理。餘備歷险阻，抽事生涯，造物者計尺寸而與之地，较锱銖而賦之财。苟作數椽，不擇美材，既杉椤之無有，惟梓松之是裁，正爾辈之所慕，逐馨香而俱來，苟能飽爾之口腹，豈不岌岌乎殆哉？雖然，爾形至微，性具五常；其居親親，無閨門同氣之斗，近於仁；其行濟濟，有君子遜畔之風，近於禮；有事則同心协力，不約而競集，號令信也；未雨則含沙負土，先事而綢缪，智識靈也；其徒羽化，則空穴餞之於外，有同室之義也。既靈性之不泯，宜善言之可施，餘之諦創爾所見，餘之艱難爾宜知。今與爾畫地為界，自東至西十丈有奇，自南至北其數倍蓰，請种族類以他適，毋入范围而肆窥。苟諄諄而莫聽，是對馬牛而誦經，其去畜類也幾希。以酒酹地，爾其知之。\"又效柳河東《三戒》作《三說》，其一日《福之馬嘉魚》，雲：\"海有魚曰馬嘉，銀膚燕尾，大者视兒，脔用火熏之可致遠，常淵潛不可捕。春夏乳子，則隨潮出波上，漁者用此時帘而取之。帘為疏目，廣袤數十尋，兩舟引張之，缒以鐵，下垂水底。魚過者，必鑽觸求進，愈觸愈束愈怒，則頰張鬣舒，鉤著其目，致不可脱。向使觸網而能退却，則悠然逝矣。知進而不知退，用罹烹醢之酷，悲夫！\"","sortOrder":27},
  {"id":"s_work_tddn_15_28","chapterId":"ch_work_tddn_15","text":"《江淮之蜂蟹》雲：\"淮北蜂毒，尾能殺人，江南蟹雄，螯堪敵虎；然取蜂兒者不論斗，而捕蟹者未聞血指也。蜂窟於土或木石，人蹤跡得其處，則夜持烈炬臨之。蜂空群赴焰，盡殪，然後連房刳取。蟹處蒲苇間，一燈水滸，莫不郭索而來，悉可俯拾。惟知趨炎而不安其所，其陨也固宜。\"","sortOrder":28},
  {"id":"s_work_tddn_15_29","chapterId":"ch_work_tddn_15","text":"《蜀封溪之猩猩》雲：\"猩猩人面能言笑，出蜀封溪山，或曰交趾。血以赭，色終使不渝。嗜酒喜屐，人以所嗜陳野外而聯絡之，伏伺其旁。猩猩見之，知為餌己，遂斥詈其人姓名，若祖父姓名，又且相戒毋墮奴辈計中，携儔唾骂而去。去後复顧，因相謂曰：'盍试嘗之。'既而染指知味，則冥然忘夙戒，相與沾濡径醉，相喜笑，取屐加足。伏發，往往顛連頓仆，掩群無遺。呜呼！明知而明犯之，其愚又益甚矣。\"","sortOrder":29},
  {"id":"s_work_tddn_15_30","chapterId":"ch_work_tddn_15","text":"○繼母服","sortOrder":30},
  {"id":"s_work_tddn_15_31","chapterId":"ch_work_tddn_15","text":"何自然本何佾德顯之子，其母姚氏死，即出繼何修德扬。後佾再娶周氏，及自然為中司日，周氏死，自然以不逮事母，審合解官，申心丧。下禮官議，以為母無親繼之別，朝廷不以為然，复下給舍台諫議。太學生朱九成等，各上台諫書，論其當去。集議既上，雖以為禮有可疑，義當從厚，合聽解官。然竟以禮律不載，無所折衷。","sortOrder":31},
  {"id":"s_work_tddn_15_32","chapterId":"ch_work_tddn_15","text":"自然去後數日，書库官方庭堅於《隋書·劉子翊傳》，永寧令李公孝，四歲丧母，九歲外繼，其後父更別娶，後母至是而亡。河間劉炫以無撫育之恩，議不解任。子翊時為侍御史，驳之曰：\"傳雲：'繼母如母。'與母同也。\"又曰：\"為人後者，為其父母期。按期者自以本生，非殊親之與繼也。\"又曰：\"親繼既等，心丧不殊。\"又曰：\"如謂繼母之來，在子出之後，製有淺深，則出後之人，所後者初亡，後之者始至，此复可以無撫育之恩，而不服重乎？\"又曰：\"苟以母養之恩，始成母子，則恩由彼至，服自己來，則慈母如母，何待父命？\"又曰：\"繼母本以名服，豈藉恩之厚薄也。\"又曰：\"炫敢违禮乖令，侮聖賢法。使出後之子，無情於本生，名義之分，有污於風俗。\"事奏，竟從子翊之議。禮官具白於廟堂，議乃定。乃知讀書不多，不足以斷疑事也。","sortOrder":32},
  {"id":"s_work_tddn_15_33","chapterId":"ch_work_tddn_15","text":"○食牛報","sortOrder":33},
  {"id":"s_work_tddn_15_34","chapterId":"ch_work_tddn_15","text":"曾鳳朝陽，庐陵人，餘嘗與之同寮。忽以疾告，數日，餘往問之，因雲：\"昔年病傷寒，旬餘不解。昏睡中，忽覺為牛所吞，境界陡黑，知此身已墮牛腹中。於是矍然曰：'身不足惜，如老母何！'因發誓，自此复見天日，當終身不食太牢。悚然驚寤，流汗如雨，疾遂良愈。持戒已十年矣，昨偶飲乡人家，具牛炙甚美。朋舊交勉之，忍饞不禁，為之破戒，歸即得疾。畴昔之夜，夢如往年，恐懼痛悔，以死自誓，今幸汗解矣。\"餘聞其說異之，且嘗見傳記小說所載食牛致疾事極眾，然未有耳目所接如此者。餘家三世不食牛，先妣及餘皆禀賦素弱，自少至老多病。然瘟疫一證，非惟不染，雖奴婢辈亦复無之，益信朝陽之說為不誣。因併著之，以為世戒。","sortOrder":34},
  {"id":"s_work_tddn_16_1","chapterId":"ch_work_tddn_16","text":"●卷十五","sortOrder":1},
  {"id":"s_work_tddn_16_2","chapterId":"ch_work_tddn_16","text":"○曲壮闵本末","sortOrder":2},
  {"id":"s_work_tddn_16_3","chapterId":"ch_work_tddn_16","text":"曲端字平甫，镇戎軍人，知書善屬文，作字奇伟，長於兵略，屢戰有聲。知延安府時，王庶節製陝西六路軍馬，遂授端吉州团練使、節製司都統製。端雅不欲屬庶，及寇犯陝西，庶召端，則以未受命辭。敵知端、庶不协，併兵寇延，庶督端為援，端以為救延，不如全陝西，乃遣吳攻華州。既而延安陷，庶無所歸，遂以百騎馳至端軍。端以戎服見，問庶延安失守状曰：\"節製固知愛身，不知為天子愛城乎？\"庶曰：\"吾數令不從，誰其愛身者？\"端怒曰：\"在耀州屢陳軍事，不一見聽，何也？\"乃拘其官屬，奪其節製司印。既而以擒史斌功，遷康州防御使、涇原路經略安撫使、知延安府。端不欲往，朝廷疑有叛意，遂以御營提舉召，端疑不行。會張浚宣撫川、陝，以端有威聲，承製拜端威武大將軍、宣州觀察使、宣撫司都統製、知渭州，軍士歡聲如雷。是時端與吳皆有重名，陝西人為之語曰：\"有文有武是曲大，有謀有勇是吳大。\"娄室寇州日，端屢戰皆捷，至白店原，撒離喝乘高望之，懼而號泣，彼中目之為\"啼哭郎君\"，其為敵所畏如此。","sortOrder":3},
  {"id":"s_work_tddn_16_4","chapterId":"ch_work_tddn_16","text":"既而浚欲大舉，未测其意，先使張彬往觇之曰：\"公常患諸路兵不合，财不足。今宣撫司兵。已合，财已足，娄室以孤軍深入，我合諸路攻之不難，萬一粘罕併兵而來，何以待之？\"端曰：\"不然，兵法先较彼己，今敵可勝，止娄室孤軍。然將士輕銳，不减前日，我不過止合五路兵耳，然將士無以大異於前。兼敵之入寇，因糧於我，我常為客，彼常為主。今當反之，按兵據险，時出偏師以扰其耕。彼不得耕，必將取糧於河東，是我為主彼為客。不一二年間，必自困毙，可一舉而滅也。萬一輕舉，後忧方大。\"彬以其言复命，浚不悅。","sortOrder":4},
  {"id":"s_work_tddn_16_5","chapterId":"ch_work_tddn_16","text":"金犯環慶，端遣吳拒之彭店原，戰少却，乃劾违節製。其秋，兀術窥江淮，浚議出師，會諸將議所從，端力以為不然，須十年乃可。端既與浚異趣，時王庶為宣撫司參謀，與端有宿怨，因谮於浚曰：\"端有反心久矣，盍早圖之。\"浚積前疑，复聞庶言，大怒，竟以彭原事罢其兵柄與祠，再謫海州团練副使，萬安軍安置。是時，陝西軍民皆恃端為命，及為庶谮，無罪而貶，軍情大不悅。是年，浚大舉，軍至富平縣。將戰，乃伪立前軍都統製曲端旗以懼之。娄室曰：\"聞曲將軍已得罪，必绐我也。\"遂擁軍骤至，軍遂大潰。浚心愧其言，而欲慰人望，乃下令以富平之役，涇原軍出力最多，既却退之後，先自聚集，皆前帥曲端訓練有方，遂叙复左武大夫，興州居住。紹興初，又叙營州刺史，與祠，徙阆州。浚亦自興州移司阆州，欲复用端。","sortOrder":5},
  {"id":"s_work_tddn_16_6","chapterId":"ch_work_tddn_16","text":"既憾之，且懼端复起，乃言曰：\"曲端再起，必不利於張公。\"王庶又從而谮之，以端嘗作詩雲：\"不向關中圖事業，却來江上泛扁舟。\"舉此以為指斥。浚入其說，且以張中孚、李彦琪，趙彬降敵，疑端知其謀，於是徙端恭州，置獄，命武臣康隨為夔路提刑鞫治。康隨者，先知懷德軍，盜用库金，為端所劾。時武臣提刑废已久，浚特以命隨。端既赴逮，知必死，仰天長吁，指其所乘戰馬鐵象雲：\"天不欲复中原乎？惜哉！\"泣數行下，左右皆泣。初至，獄官不知何人，日盛服候之，如事上官之禮，端甚訝之。一日，其人忽前雲：\"將軍功臣，朝廷所知，决無他慮。若欲早出，第手書一病状，獄司即以申主，便可凭藉出矣。\"端欣然引筆書之，甫就，獄官遽卷懷而去。是晚，即進械，坐之鐵籠，炽火逼之，殊極惨惡。端渴甚求飲，與之酒，九竅流血而死，年四十一，時紹興四年八月三日丁卯申時也。陝西軍士，皆流涕怅恨，多叛去者。","sortOrder":6},
  {"id":"s_work_tddn_16_7","chapterId":"ch_work_tddn_16","text":"浚尋得罪，詔追复端宣州觀察使。製曰：\"頃失意於權臣，卒下獄而譴死，恩莫追於三宥，人將贖以百身。\"其後金歸河南之日，又詔謚端壮闵。製曰：\"屬委任之非人，致刑誅之橫被，興言及此，流涕何追！\"","sortOrder":7},
  {"id":"s_work_tddn_16_8","chapterId":"ch_work_tddn_16","text":"端為涇原都統日，有叔為偏將，戰败誅之。既乃發丧，祭之以文曰：\"呜呼！斬副將者，涇原統製也，祭叔者，侄曲端也，尚享！\"一軍畏服。其紀律極嚴，魏公嘗按视端軍，端執挝以軍禮見，旁無一人。公異之，謂欲點视，端以所部五軍籍進。公命點其一部，於廷間开籠縱一鴿以往，而所點之軍隨至，張為愕然。既而欲盡觀，於是悉縱五鴿，則五軍頃刻而集，戈甲煥燦，旗幟精明，魏公雖奖，而心實忌之。在蜀日，嘗有詩雲：\"破碎江山不足論，何時重到渭南村。一聲長嘯東風里，多少人歸未斷魂。\"亦可見其志也。","sortOrder":8},
  {"id":"s_work_tddn_16_9","chapterId":"ch_work_tddn_16","text":"至今西北故老，尚能言其冤。而《四朝國史》端本傳之論，乃曰：\"曲端之死，時論或以為冤，然觀其狠愎自用，輕视其上，縱使得志，終亦難御，况動违節製，夫何功之可言乎？\"此雖史臣為魏公庇，然失其實矣。信如所言，則秦桧之殺嶽飛，亦不為過。或又比之孔明斬馬謖，尤無謂也。直筆之難也，久矣，惜哉！","sortOrder":9},
  {"id":"s_work_tddn_16_10","chapterId":"ch_work_tddn_16","text":"○浑天儀地動儀","sortOrder":10},
  {"id":"s_work_tddn_16_11","chapterId":"ch_work_tddn_16","text":"舊京浑天儀凡四座，每座約用銅二萬斤。至道儀在测验浑儀所，皇祐儀在翰林天文局，熙寧儀在太史局天文院，元祐儀在合台。南渡後，工部員外郎袁正功嘗獻木樣，詔工部折半製造，計用銅八千四百餘斤，後不克成。至紹興七年，嘗自製小樣。十四年，令內侍邵諤領其事，其一留太史局司天台，其一留秘書省测验所，皆精銅為之，工致特甚，然比之舊京者，不能及其半也。","sortOrder":11},
  {"id":"s_work_tddn_16_12","chapterId":"ch_work_tddn_16","text":"按浑天儀始於洛下閎，或以為璣玉衡之遺法，非也。其後贾逵、張衡、斛蘭、李淳風、梁令瓒、僧一行以下皆能之，獨有候風地震之器曰地動儀者無傳焉。按《漢·張衡傳》，此儀以精銅為之，其器圓径八尺，形似酒樽，中有都柱，旁行八道，施關發機。外有八龍，首衔銅丸，每龍作一蟾蜍，仰首張口而承之。機關巧製，皆在樽中。龍必致九州地分，如遇某州分地動，則龍衔之丸，即墜蟾蜍口中，乃铿然有聲。司候者占之，則知某地分震動矣。","sortOrder":12},
  {"id":"s_work_tddn_16_13","chapterId":"ch_work_tddn_16","text":"《北史》，信都芳明算術，有巧思，聚浑天欹器、地動銅壶、刻漏、候風諸巧事，令算之，皆無遺策。隋臨孝恭，嘗著《地動遺經》一卷，今無傳焉。然以理揆之，天文有常度可尋，時刻所至，不差分毫，以浑天测之可也。若地震則出於不测，蓋陰陽相薄使然，亦猶人之一身，血氣或有順逆，因而肉目動耳。氣之所至則動，氣所不至則不動。而此儀置之京都，與地震之所了不相關，氣數何由相薄，能使銅龍驤首吐丸也？細尋其理，了不可得，更當訪之識者可也。","sortOrder":13},
  {"id":"s_work_tddn_16_14","chapterId":"ch_work_tddn_16","text":"○腹笥","sortOrder":14},
  {"id":"s_work_tddn_16_15","chapterId":"ch_work_tddn_16","text":"崑山白莲花寺，乃陆魯望舍宅之所，後有祠堂像設，皆當時物。鹹淳中，盛氏子醉遊寺中，因仆其像於水，則滿腹皆魯望平生詩文親稿也。寺僧頌於郡，時太守倪普亦怒之，遂從徒坐，而更塑其像。雖可少雪天隨之辱，然無复當時之腹稿矣。","sortOrder":15},
  {"id":"s_work_tddn_16_16","chapterId":"ch_work_tddn_16","text":"川南景德寺，為南渡宗子聚居之地。大殿皆椤木為之，經數百年，略不欹傾，俗傳以為神匠所為，佛像尤古。鹹淳辛未三月，火忽起自佛腹，其中藏經數百卷，多五代及國初時人手寫，皆垂碧紙，金銀書。間有舍利、珠玉、金銀錢之類，多為宗子所得。嘗見一仆得金銀書《心經》一囊，凡十卷，長仅二寸，卷首各繪佛像，亦頗極精妙。後經笥一旦遂空，亦竟莫知火起之由，豈釋氏所謂劫火者乎？","sortOrder":16},
  {"id":"s_work_tddn_16_17","chapterId":"ch_work_tddn_16","text":"○龟溪二女貴","sortOrder":17},
  {"id":"s_work_tddn_16_18","chapterId":"ch_work_tddn_16","text":"隆國黃夫人，湖州德清縣人。初入魏峻叔高家，既出，复歸李仁本，媵其女以入榮邸。時嗣王與{艹丙}苦無子，一幸而得男，是為度宗。然自處極謙抑，雖骤貴盛，每遇邸第親戚，至不敢坐。常以奶子自稱，人亦以此名之，或者有魏奶子之滂，其實不然也。","sortOrder":18},
  {"id":"s_work_tddn_16_19","chapterId":"ch_work_tddn_16","text":"秦齊國夫人胡氏，亦同邑人，相去才數里。贾涉濟川以製置，少日，舟過龟溪，見婦人浣衣者，偶盼之，因至其家。問夫何在，曰：\"未歸。\"語稍洽，調之曰：\"肯相從乎？\"欣然惟命。及夫還，扣之，亦無難色，遂携以歸。既而生似道，未幾，出嫁為民妻，似道少長，始奉以歸。性極嚴毅，似道畏之。當景定、鹹淳間，屢入禁中，隆國至同寢處，恩寵甚渥，年至八十有三。上方賜秘器及冰腦各五百兩，赙銀絹四千兩匹，命中使護葬，帥漕供費，凡兩輟朝，賜謚柔正，又賜功德寺及田六千畝，可謂盛極矣。故一邑產二女貴人，前此所未有也。","sortOrder":19},
  {"id":"s_work_tddn_16_20","chapterId":"ch_work_tddn_16","text":"○算歷約法","sortOrder":20},
  {"id":"s_work_tddn_16_21","chapterId":"ch_work_tddn_16","text":"古有數九九之語，蓋自至後起，數至九九，則春已分矣，如至後一百六日為寒食之類也。餘嘗聞判太史局邓宗文雲：\"豈特此為然，凡推算皆有約法。\"《推閏歌括》雲：\"欲知來歲國，先算至之餘，更看大小盡，决定不差殊。\"謂如來歲合置閏，止以今年冬至後餘日為率。且以今年十一月二十二日冬至，則本月尚餘八日，則來年之閏，當在八月，或小盡，則止餘七日，則當閏七月。若冬至在上旬，則以望日為斷，十二日足，則复起一數焉。","sortOrder":21},
  {"id":"s_work_tddn_16_22","chapterId":"ch_work_tddn_16","text":"《推節氣歌括》雲：\"中氣與節氣，但有半月隔，若要知仔細，兩時零五刻。\"謂如正月甲子，子時初刻立春，則數至己卯日寅時正一刻，則是雨水節也。《推立春歌括》雲：\"今歲先知來歲春，但看五日三時辰。\"謂如今年甲子日子時立春，則明年合是己巳日卯時立春。若夫刻數，則用前法推之。凡朔、望，大小盡算，悉有歌括，惜乎不能盡記。然此亦歷家之淺事耳，若夫精微，則非布算乘除不可也。","sortOrder":22},
  {"id":"s_work_tddn_16_23","chapterId":"ch_work_tddn_16","text":"○玉照堂梅品","sortOrder":23},
  {"id":"s_work_tddn_16_24","chapterId":"ch_work_tddn_16","text":"梅花為天下神奇，而詩人尤所酷好。淳熙歲乙巳，予得曹氏荒圃於南湖之濱，有古梅數十，散漫弗治。爰輟地十畝，移种成列。增取西湖北山別圃江梅，合三百餘本，筑堂數間以臨之。又挟以兩室，東植千葉緗梅，西植紅梅各一二十章，前為軒楹如堂之數。花時居宿其中，環絜辉映，夜如對月，因名曰玉照。复开涧環繞，小舟往來，未始半月舍去，自是客有遊桂隱者，必求觀焉。頃亚太保周益公秉鈞，予嘗造東閣，坐定者首顧予曰：\"一棹径穿花十里，滿城無此好風光。\"人境可見矣！蓋子舊詩尾句，眾客相與歆艳，於是遊玉照者，又必求觀焉。值春凝寒，反能留花，過孟月始盛。名人才士，題詠層委，亦可謂不負此花矣。但花艳併秀，非天時清美不宜；又標韻孤特，若三闾大夫，首陽二子，寧槁山泽，終不肯ぽ首屏氣，受世俗湔拂。間有身親貌悅，而此心落落不相領會；甚至於污亵附近，略不自揆者。花雖眷客，然我辈胸中空洞，幾為花呼叫稱冤，不特三叹、屢叹、不一叹而足也。因審其性情，思所以為奖護之策，凡數月乃得之。今疏花宜稱、憎嫉、榮寵、屈辱四事，總五十八條，揭之堂上，使來者有所警省。且世人徒知梅花之貴，而不能愛敬也。使予之言，傳聞流誦，亦將有愧色雲。紹興甲寅人日約斋居士書。","sortOrder":24},
  {"id":"s_work_tddn_16_25","chapterId":"ch_work_tddn_16","text":"○花宜稱凡二十六條","sortOrder":25},
  {"id":"s_work_tddn_16_26","chapterId":"ch_work_tddn_16","text":"澹陰。晓日。薄寒。細雨。輕煙。佳月。夕陽。微雪。　晚霞。　珍禽。　孤鶴。清溪。　小桥。　竹邊。　松下。　明窗。　疏篱。蒼崖。　绿苔。　銅瓶。　紙帳。　林間吹笛。膝上橫琴。　石枰下棋。　扫雪煎茶。　美人淡妆戴。","sortOrder":26},
  {"id":"s_work_tddn_16_27","chapterId":"ch_work_tddn_16","text":"△花憎嫉凡十四條","sortOrder":27},
  {"id":"s_work_tddn_16_28","chapterId":"ch_work_tddn_16","text":"狂風。連雨。烈日。苦寒。丑婦。俗子。老鴉。惡詩。　談時事。　論差除。　花径喝道。　對花張緋幕。　賞花動鼓板。　作詩用調羹驿使事。","sortOrder":28},
  {"id":"s_work_tddn_16_29","chapterId":"ch_work_tddn_16","text":"△花榮寵凡六條","sortOrder":29},
  {"id":"s_work_tddn_16_30","chapterId":"ch_work_tddn_16","text":"主人好事。賓客能詩。列燭夜賞。名筆傳神。专作亭馆。　花邊歌佳詞。","sortOrder":30},
  {"id":"s_work_tddn_16_31","chapterId":"ch_work_tddn_16","text":"△花屈辱凡十二條","sortOrder":31},
  {"id":"s_work_tddn_16_32","chapterId":"ch_work_tddn_16","text":"俗徒攀折。主人慳鄙。种富家園內。與粗婢命名。蟠結作屏。　賞花命猥妓。　庸僧窗下种。　酒食店內插瓶。　树下有狗屎。　枝下曬衣裳。　青紙屏粉畫。　生猥巷秽溝邊。","sortOrder":32},
  {"id":"s_work_tddn_16_33","chapterId":"ch_work_tddn_16","text":"昔義山《雜纂》內，有殺風景等語，今梅品實權舆於此。約斋名，字功父，循王諸孫，有吏才，能詩，一時所交皆名辈。予嘗得其園中亭榭名，及一歲遊適之目，名《賞心樂事》者，已載之《武林舊事》矣。今止書其賞牡丹及此二則雲。","sortOrder":33},
  {"id":"s_work_tddn_16_34","chapterId":"ch_work_tddn_16","text":"○律歷","sortOrder":34},
  {"id":"s_work_tddn_16_35","chapterId":"ch_work_tddn_16","text":"沈存中雲，近世精於歷者，莫若衛朴，雖一行亦不及之。《春秋》日食三十六，諸歷通验，密者不過得二十六，惟一行得二十七，朴乃得三十五。朴能不用推算古今日月食，但口誦乘除，不差一算。凡古歷算數，令人就耳一讀，即能暗誦旁通，縱橫誦之。嘗令人寫歷書，寫訖，令附耳讀之，有差一算者，讀至其處，則曰：\"此誤某字。\"其精如此。大乘除皆不下照位，運筹如飛，人眼不能逐。人有故移其一算者，朴自上至下，手循一遍，至移算處，則檢正而去。熙寧中，撰《奉元歷》，以無候簿，未能盡其數。自言其得六七而已，然已密於他歷矣。至姚虞孫乃出新意，用藝祖受命之年，即位之日，元用庚辰，日起己卯，號《紀元歷》。於是立朔既差，定腊亦舛，日食亦皆不验，未幾遂更焉。宣和間，妄人方士魏漢津唱為黃帝、夏禹以聲為律身為度之說，不以黍，而用帝指。凡中指之中寸三，次指之中寸三，小指之中寸三，合而為九，為黃鐘律。又雲：\"中指之径围為容盛，則度量權衡皆自此出焉。\"或難之曰：\"上春秋富，手指後或不同，奈何？\"复為之說曰：\"請指之歲，上適年二十四，得三八之數，是為太蔟、人統，過是，則寸有餘，不可用矣。\"其敢為期誕也如此，然終於不可用而止。此事前所未有，於理亦不可誣。小人欺罔取媚，而世主大臣，方甘心受悔而不悟，可發識者一笑也。","sortOrder":35},
  {"id":"s_work_tddn_16_36","chapterId":"ch_work_tddn_16","text":"○張氏《十詠圖》","sortOrder":36},
  {"id":"s_work_tddn_16_37","chapterId":"ch_work_tddn_16","text":"先世舊藏吳興張氏《十詠圖》一卷，乃張子野圖其父維平生詩，有十首也。其一，《太守馬太卿會六老於南園》雲：\"賢侯美化行南國，華發欣欣奉宴娱。政績已聞同水薤，恩辉遂喜及桑榆。休言身外榮名好，但恐人間此會無。他日定知傳好事，丹青寧羨《洛中圖》。\"","sortOrder":37},
  {"id":"s_work_tddn_16_38","chapterId":"ch_work_tddn_16","text":"其二，《庭鶴》雲：\"戢翼盤桓傍小庭，不無清夜夢煙汀。靜翘月色一团素，閒啄苔錢數點青。終日稻粱聊自足，滿前雞鶩漫相形。已隨秋意歸詩筆，更與幽栖上畫屏。\"","sortOrder":38},
  {"id":"s_work_tddn_16_39","chapterId":"ch_work_tddn_16","text":"其三，《玉蝴蝶花》雲：\"雪朵中間蓓蕾齊，骤聞尤覺繡工遲。品高多說琼花似，曲妙誰將玉笛吹。散舞不休零晚树，团飛無定撼風枝。漆園如有須為夢，若在藍田种更宜。\"","sortOrder":39},
  {"id":"s_work_tddn_16_40","chapterId":"ch_work_tddn_16","text":"其四，《孤帆》雲：\"江心雲破處，遙見去帆孤。浪闊疑升漢，風高若泛湖。依微過遠屿，仿佛落荒芜。莫問乘舟客，利名同一途。\"","sortOrder":40},
  {"id":"s_work_tddn_16_41","chapterId":"ch_work_tddn_16","text":"其五，《宿清江小舍》。破損，仅存一句雲：\"菰葉青青绿荇齊。\"","sortOrder":41},
  {"id":"s_work_tddn_16_42","chapterId":"ch_work_tddn_16","text":"其六，《歸燕》雲：\"社燕秋歸何處乡，群雏齊老稻青黃。猶能時暫栖庭树，漸覺稀疏度苑牆。己任風庭下帘幕，却隨煙艇過瀟湘。前春認得安巢所，應免差池揀杏梁。\"","sortOrder":42},
  {"id":"s_work_tddn_16_43","chapterId":"ch_work_tddn_16","text":"其七，《聞砧》雲：\"遙野空林砧杵聲，淺沙栖雁自相鳴。西風送响暝色靜，久客感秋愁思生。何處征人移塞帳，即時新月落江城。不知今夜捣衣曲，欲寫秋閨多少情。\"","sortOrder":43},
  {"id":"s_work_tddn_16_44","chapterId":"ch_work_tddn_16","text":"其八，《宿後陳莊》雲：\"腊冻初开苕水清，煙村遠郭漫吟行。滩頭斜日凫鷺队，枕上西風鼓角聲。一棹寒燈隨夜釣，滿犁膏雨趁春耕。誰言五福仍須富，九十年餘樂太平。\"","sortOrder":44},
  {"id":"s_work_tddn_16_45","chapterId":"ch_work_tddn_16","text":"其九，《送丁遜秀才赴舉》雲：\"鵬去天池鳳翼隨，風雲高處約先飛。青袍賜宴出關近，帶取琼林春色歸。\"","sortOrder":45},
  {"id":"s_work_tddn_16_46","chapterId":"ch_work_tddn_16","text":"其十，《貧女》雲：\"荆簪掠鬢布裁衣，水鑒雖明亦懶窥。數畝秋禾滿家食，一機官帛幾梭絲。物為貴寶天應與，花有秋香春不知。多少年來豪族女，總教時樣畫蛾眉。\"","sortOrder":46},
  {"id":"s_work_tddn_16_47","chapterId":"ch_work_tddn_16","text":"孫覺莘老序之雲：\"富貴而寿考者，人情之所甚慕，貧賤而天短者，人情之所甚哀；然有得於此者，必遺於彼。故寧處康強之貧，寿考之賤，不願多藏而病忧，顯榮而天短也。赠尚書刑部侍郎張公讳維，吳興人。少年學書，貧不能卒業，去而躬耕以為養。善教其子，至於有成。平居好詩，以吟詠自娱。浮遊闾里，上下於溪湖山穀之間，遇物發興，率然成章，不事雕琢之巧，采繪之華，而雅意自得。徜徉閒肆，往往與異時處士能詩者為辈。蓋非無忧於中，無求於世，其言不能若是也。公不出仕，而以子封至正四晶，亦可謂貴；不治職，而受祿養以終其身，亦可謂富；行年九十有一，可謂寿考。夫享人情之所甚慕，而违其所哀，無忧無求，而見之吟詠，則其自得而無怨懟之辭，萧然而有沉澹之思，其亦宜哉。公卒十八年，公子尚書都官郎中先亦致仕家居。取公平生所自愛詩十首，寫之缣素，號《十詠圖》，傳示子孫，而以序見屬。餘既愛侍郎之寿，都官之孝，為之序而不辭。都官字子野，蓋其年八十有二雲。\"","sortOrder":47},
  {"id":"s_work_tddn_16_48","chapterId":"ch_work_tddn_16","text":"此事不詳於郡志，而張維之名亦不顯，故人少知者。會直斋陳振孫貳卿方修《吳興志》，讨摭舊事，見之大喜。遂傳其圖，且詳考顛末，為之跋雲：\"慶歷六年，吳興郡守宴六老於南園，酒酣賦詩，安定胡先生瑗教授湖學，為序其事。六人者，工部侍郎郎簡年七十九，司封員外郎范說年八十六，衛尉寺丞張維年九十一，俱致仕。劉餘慶年九十二，周守中年九十五，吳琰年七十二，皆有子弟列爵於朝。劉，殿中丞述之仲父；周，大理丞頌之父；吳，大理丞知幾之父也。詩及序刻石園中，園废，石亦不存。其事見《圖經》及《安定言行錄》中。餘嘗考之，郎簡，杭人也，或嘗寓於湖。范說，鹹平三年進士，同學究出身。周頌，天聖八年進士。劉、吳盛族，述與知幾皆有名跡可見，獨張維無所考。近周明叔史君得古畫三幅，號《十詠圖》者，乃維所作詩也。首篇即南園宴集所賦，孫覺莘老序之，其略雲雲，於是始知維為子野之父也。時熙寧五年，歲在壬子，逆數而上八十二年，子野之生，當在淳化辛卯，其父享年九十有一，正當為守。會六老之年，實慶歷丙戌。逆數而上九十一年，則周世宗顯德丙辰也。後四年宋興，自是日趨太平極盛之世，及於熙寧、元丰，再更甲子矣。子野於其間擢儒科，登無仕，為時聞人。赠其父官四品，仍父子皆耄期，流風雅韻，使人遐想慨慕不能已，可謂吾乡衣冠之盛事矣！世固知有子野而不知有其父也。自慶歷丙戌後十八年，子野為《十詠圖》，當治平甲辰。又後八年，孫莘老為太守為之作序，當熙寧壬子。又後一百七十七年，當淳祐己酉，其圖為好古博雅君子所得。會餘方緝《吳興人物志》，見之如獲珙璧，因細考而詳錄之，庶幾不朽於世。其詩亦清麗閒雅，如'滩頭斜日凫鷺队，枕上西風鼓角聲。'又'花有秋香春不知'，皆佳句也。子野之墓在卞山多寶寺，今其後影响不存矣。此圖之獲，豈不幸哉？\"本朝有兩張先，皆字子野。其一博州人，天聖三年進士，欧陽公為作墓志；其一天聖八年進士，則吾州人也。二人名、姓、字偶皆同，而又適同時，不可不知也。且賦詩雲：\"平生聞說張三影，十詠誰知有乃翁。逢世升平百年久，與齡耆艾一家同。名賢叙述文章好，勝事流傳繪素工，遐想盛時生恨晚，恍如身在畫圖中。\"南園故址在今南門內，牟存叟端平所居是也。其地尚為張氏物，先君為經營得之，存叟大喜，亦常賦五絕句，其一雲：\"買家喜傍水晶宮，正是南園故址中。我欲筑堂名六老，追還慶歷太平風。\"蓋紀實也。餘家又偶藏子野詩一帙，名《安六集》，舊京本也。乡守楊嗣翁見之，因取刻之郡斋。適二事皆出餘家，似與子野父子有緣耳。","sortOrder":48},
  {"id":"s_work_tddn_16_49","chapterId":"ch_work_tddn_16","text":"○耿聽聲","sortOrder":49},
  {"id":"s_work_tddn_16_50","chapterId":"ch_work_tddn_16","text":"耿聽聲者，兼能嗅衣物以知吉凶貴賤。德寿聞其名，取宮人扇百餘，雜以上及中宮所御，令小黃門持扣之。耿嗅至後扇雲：\"此聖人也，然有陰氣。\"至上扇，乃呼萬歲！上奇之，呼入北宮，又取妃嫔珠冠十數示之。至一冠，奏曰：\"此有尸氣。\"時張貴妃薨，此其故物也。後居候朝門內。","sortOrder":50},
  {"id":"s_work_tddn_16_51","chapterId":"ch_work_tddn_16","text":"夏震微時，嘗為殿巖饋酒於耿，耿聞其聲，知其必貴，遂以其女妻其子，子复娶其女。時郭棣為殿帥，耿謁之曰：\"君部中有三節度使，他日皆為三衙。\"扣為何人，則曰：\"周虎、彭辂、夏震也。\"虎、辂時皆為將官，獨震方為帳前佩印官。郭曰：\"周、彭地步，或未可知，震安得遽爾乎？\"耿曰：\"吾所見如此，可必也。\"耿因為三人結為義兄弟。","sortOrder":51},
  {"id":"s_work_tddn_16_52","chapterId":"ch_work_tddn_16","text":"一日，耿謂虎曰：\"吾數夜聞軍中金鼓有殺聲，兵將動，君三人皆當由此而顯矣。\"未幾，开禧出師，虎守和州，辂為金州統戎，皆以功受賞。震則以誅韓功，相繼獲殿巖，虎亦為帥，皆立節度使班，悉如耿之言。","sortOrder":52},
  {"id":"s_work_tddn_16_53","chapterId":"ch_work_tddn_16","text":"○周陆小詞","sortOrder":53},
  {"id":"s_work_tddn_16_54","chapterId":"ch_work_tddn_16","text":"周平園嘗出使，過池陽，太守趙富文彦博召飲。籍中有曹盼者，絜白純靜，或病其讷而不穎，公為賦梅以見意雲：\"踏白江梅，大都玉软酥凝就。雨肥霜逗，癡挨閨房秀。莫待冬深，雪壓風欺後。君知否？却嫌伊瘦，又怕伊亻孱亻愁。\"酒酣，又出家姬小琼舞以侑歡，公又賦一阕雲：\"秋夜乘槎，客星容到天孫渚。眼波微註，將謂牵牛渡。見了還非，重理霓裳舞。雖無誤，幾年一遇，莫訝周郎顧。\"范石湖嘗雲：\"朝士中妹麗有三杰。\"謂韓無咎、晁伯如家姬及小琼也。禁中亦聞之。異時有以此事中傷公者，阜陵亦為一笑。","sortOrder":54},
  {"id":"s_work_tddn_16_55","chapterId":"ch_work_tddn_16","text":"陆放翁在蜀日，有所盼，嘗賦詩雲：\"碧玉當年未破瓜，學成歌舞入侯家。如今憔悴蓬窗底，飛上青天妒落花。\"出蜀後，每懷舊遊，多見之賦詠，有雲：\"金鞭珠彈憶春遊，萬里桥東罨畫樓。夢倩晓風吹不斷，書凭春雁寄無由。鏡中顏鬢今如此，席上賓朋好在否？箧有吳箋三百个，擬將細字寫春愁。\"又雲：\"裘馬清狂錦水濱，最繁華地作閒人。金壶投箭消長日，翠袖傳杯領好春。幽鳥語隨歌處拍，落花鋪作舞時茵。悠然自適君知否？身與浮名孰重輕。\"又以此詩概括作《風入松》雲：\"十年裘馬錦江濱，酒隱紅尘。黃金選勝鶯花海，倚疏狂，驅使青春。弄笛魚龍盡出，題詩風月俱新。自怜華發滿紗巾，猶是官身。鳳樓曾記當年語，問浮名，何似身親？欲寫吳箋說與，这回真个閒人。\"前辈風流雅韻，猶可想見也。","sortOrder":55},
  {"id":"s_work_tddn_17_1","chapterId":"ch_work_tddn_17","text":"●卷十六","sortOrder":1},
  {"id":"s_work_tddn_17_2","chapterId":"ch_work_tddn_17","text":"○三高亭記改本","sortOrder":2},
  {"id":"s_work_tddn_17_3","chapterId":"ch_work_tddn_17","text":"三高亭，天下絕景也，石湖老仙一記，亦天下奇筆也。餘嘗見當時手稿，揩摩抉剔，如洗玉浣錦，信前辈作文不憚於改如此。因詳書於此，與同志評之。記雲：","sortOrder":3},
  {"id":"s_work_tddn_17_4","chapterId":"ch_work_tddn_17","text":"\"乾道三年二月，吳江縣新作三高祠成。三高者：越上將軍姓范氏，是為鴟夷子皮；晉大司馬東曹椽姓張氏，是為江東步兵；唐赠右補闕姓陆氏，是為甫里先生。三君者不併世，而鴟夷子皮又嘗一用人之國，名大功顯而去之。季鷹、魯望，萧然瞿儒。使有為於當年，其所成就，固不可渝度。要皆得道見微，脱屣天刑，清風峻節，相望於松江、太湖之上，故天下同高之。而吳江之邑人，獨私得奉嘗以夸於四方，若曰吾東家邱雲爾。邑大夫趙伯虛勤勞其邑，百废具舉，以故祠為陋，將改作，於是歸老之士乡老王份，獻其地雪滩，左具區，右笠泽，號稱勝絕。乃筑堂於其上，告遷於像而奠焉。又屬石湖郡人范成大為之辭（識）噫！（傳曰）不有君子，其能國乎？今乃自放寂寞之濱，掉頭而弗顧，人又從而以為高，豈盛际之所願哉！後之人高三君之風，而跡（尚論）其所以去，為世道計者，可以懼思過半矣。至於豪杰之士，或肆志乎軒冕（尸祝而社稷莫之能說），宴安流連，卒悔於後者，亦將有感於斯堂，而某何足以述之？然（獨嘗怪）屈平既（淵潛以）從彭鹹，而桂丛之賦，猶召隱士（淮南小山猶為作隱士之賦）。疑若幽隱處林薄，不死而仙。况如三君蝉蜕溷濁，得全於天者。嘗试倚楹而望，水光浮空，雲日下上，風帆煙艇，飄忽晦明。意必往來其間（某），何足以見之，故效（援）小山（故事）作歌三章以招焉。遂從而歌曰：'若有人兮扁舟泛，怃亂五湖兮遠遊，眾芳媚兮高丘，獨君兮不可留。長風積兮波浪白（吹泽國），荡搖空明兮南北一色（浪波稽天兮南北一色）。鏡萬里荡空碧兮鞭魚龍，列星剡剡兮一下其孤蓬，渺顧懷兮斯路，與涼月兮入沧浦（君之旗兮獵獵，紅梁千丈兮可以舣楫。餞東流兮怅雲海，悠悠我思兮君無遠邁）。戰爭蜗角兮昨夢一笑，水雲得意兮垂虹可以舣棹。仙之人兮寿無涯，樂哉垂虹兮去复來。'載歌曰：'若有人兮橫大江，秋風起兮歸故乡。鸿冥飛兮白鷗舞，吳波鱗鱗兮在下。嗟人胡為兮天地四方，樂莫樂兮（美元度兮）吾之土。脍修鱸兮雪飛，登菰莼兮Ρ之。水仙濱兮胥命，君可望兮不可追（驅疾霆兮驷奔雲，宛一息江之濱）。ぽ倒景兮揮碧，寥矣宴息兮江之皋。べ苹堂兮庑杜若，一杯之酒兮我為材酌。'又歌曰：'若有一人兮北江之渚，披雪而兮煙雨。绿蔬兮莎棘，歲婉晚兮何以續君食。亻面五鼎兮腥腐，羞三（石）泉兮終古。（乌鳥飛兮擇君屋，歸來故墟兮蒼煙疏木。擢{艹立}泽兮径秋荷，漭洞庭兮一波。訪故人兮安在？）千秋風露兮歸來故墟，月明無人兮蒼石與語。牛宮洳兮生蒲荷，潮西東兮下田一波。訪南涇兮鄰曲，山川良是兮丘垅。多稼（石田）九畹兮今其刈，聊舂容兮茲里。'\"不見初草，何以知後作之工，觀前辈著述，而探其用意改定，思過半矣。","sortOrder":4},
  {"id":"s_work_tddn_17_5","chapterId":"ch_work_tddn_17","text":"攻愧有《讀三高祠記詩》曰：\"三高之風天與高，三高之靈或可招，小山之後無此作，具區、笠泽空寥寥。幾從垂虹荡双槳，寓目沧波獨怊怅。筆端不倒三峡流，欲遽招之恐長往。前身陶朱今董狐，襟袍磊落吞江湖。瑰詞三章妙天下，大書深刻江之隅。我來誦詩凛生氣，若有人兮在江水，扁舟獨釣鲐鱸魚，茶竈筆床歸甫里。先生固是邱壑人，只今方迫功與名，謝公掩鼻恐未免，便看林藪生風雲。他年事業滿彝鼎，乞身歸來坐佳境，不嫌俗士三斗尘，容我漁蓑理煙艇。\"時范公方為吏部郎也。","sortOrder":5},
  {"id":"s_work_tddn_17_6","chapterId":"ch_work_tddn_17","text":"○崑命元龟辨證本末","sortOrder":6},
  {"id":"s_work_tddn_17_7","chapterId":"ch_work_tddn_17","text":"嘉定初元，史忠獻弥遠拜右丞相，相麻，翰林權直陳晦之筆也，有\"崑命元龟，使宅百揆\"之語。時倪文節思知福州，即具申朝省，謂\"崑命元龟\"，此乃舜、禹揖遜授受之語，見於《大禹謨》，非僻書也。據《漢書·董賢為大司馬册文》雲\"允執其中\"，萧鹹謂此乃尧禪舜之文，非三公故事。今\"崑命元龟\"，與\"允執其中\"之詞何以異？若聖上初無是意，不知詞臣何從而援引此言，受此麻者，豈得安然而不自明乎？給舍台諫，又豈得不辨白此事乎？竊見曩之詞臣，以聖之清聖之和褒譽韓胄，以有文事有武備褒譽蘇師旦，然亦未敢用人臣不當用之語。昔欧陽修論韓琦、富弼、范仲淹立党事，在為河北轉運使時，故敢援此以為比，乞行貼麻。","sortOrder":7},
  {"id":"s_work_tddn_17_8","chapterId":"ch_work_tddn_17","text":"吏相得之甚駭，遂拜表繳奏，且謂當時惟知恭聽王言，所有製詞，合取會詞臣，合與不合貼麻。時陳晦已除侍御吏，遂具奏之。其詞內雲：\"茲方艱於論相，顧無異於象賢。崑命元龟，使宅百揆，此蓋演述陛下卜相之意甚明，而思乃以為人臣不當用之語。臣觀《尚書》所稱'師錫帝曰虞舜'與'乃言底可績'者，其上下文顯是揖遜授受之語；而孫近《行趙鼎製》雲'由師錫之公'，蒋芾《行洪適製》雲'用符師錫之公'。陳誠之《行沈該製》雲'言皆可績，佥曰汝諧'，從《大禹謨》之文：'惟口出好興戎，朕言不再。禹曰：枚卜功臣，惟吉之從。帝曰：禹！官占惟先蔽志，崑命元龟，朕志先定，詢謀佥同，鬼神其依，龟筮协從，卜不習吉。禹拜稽首固辭，帝曰：毋！惟汝諧。'今以本朝宰相製詞考之，《呂夷簡製》曰：'或營求方獲，或枚卜乃從。'《富弼製》曰：'遂膺枚卜，實契具瞻。'《王钦若製》曰：'廟堂虛位，龟筮协謀。'《曾公亮製》曰：'拂龟而見祥，端而定製，稽用師言之錫，進居台路之元。'《陳執中製》曰：'考嘉績而惟茂，质枚卜以佥同。'《趙鼎製》曰：'龟弗克违，既验詢謀之协。'《陳伯康製》曰：'詢於佥言，蔽自朕志。'無非用《大禹謨》此一段中語，此類甚多，不敢盡舉。唐人作《韦見素相製》曰：'爾惟不矜，朕志先定。'此兩全句，皆用禹事。本朝蘇軾草《賜范純仁詔》，亦曰：'蔽自朕志。'《賜文彦博詔》亦曰：'朕命不再。'至於歷试諸艱，蓋尧、舜事。軾於呂大防、胡宗愈詔，屢用'厲试'二字，然臣不敢援此為例，恐未是命龟的證。國初，趙普拜相，製曰：'詢於元龟，歷選群後。'又有甚的切者，唐元和中，裴度拜相，製曰：'人具爾瞻，天方赉予，崑命元龟，爰立作相。'雲雲。古人舉事無大小，未嘗不命龟，如《洪范》、《周禮》、《左傳》，皆可考也。今思乃以董賢册文'允執其中'為比，以聖上同之漢哀雲雲。凡臣所陳，事理甚明，所有已降相麻，即不合貼改。\"","sortOrder":8},
  {"id":"s_work_tddn_17_9","chapterId":"ch_work_tddn_17","text":"繼得旨：陳晦援證明白，無罪可待，倪思輕侮朝廷，肆言誣罔，可特降兩官。其後文節作辨析一状甚詳，又专作一書曰《崑命元龟說》，備載始末。然一時公論，多以文節出位而言，近於忿激。而陳之論辨雖詳，終不若不用之為佳也。此事葉靖逸雖載之《聞見錄》，略甚，今因詳書本末雲。","sortOrder":9},
  {"id":"s_work_tddn_17_10","chapterId":"ch_work_tddn_17","text":"○詩道否泰","sortOrder":10},
  {"id":"s_work_tddn_17_11","chapterId":"ch_work_tddn_17","text":"詩道否泰，亦各有時。政和中，大臣有不能詩者，因建言，詩為元祐學術，不可行。時李彦章為中丞，承望風旨，遂上章論淵明、李、杜而下皆貶之，因詆黃、張、晁、秦等，請為科禁。何清源至修入令式，諸士庶習詩賦者杖一百。聞喜例賜詩，自何文縝後，遂易為詔書訓戒。是歲冬，初雪，太上皇喜甚。吳居厚首作詩三篇以獻，謂之口號，上和賜之。自是聖作時出，訖不能禁，而陳簡斋遂以《墨梅》詩擢置馆閣焉。","sortOrder":11},
  {"id":"s_work_tddn_17_12","chapterId":"ch_work_tddn_17","text":"寶慶間，李知孝為言官，與曾極景建有隙，每欲尋衅以報之。適極有春詩雲：\"九十日春晴景少，百千年事亂時多。\"刊之《江湖集》中；因复改劉子《汴京紀事》一聯為極詩雲：\"秋雨梧桐皇子宅，春風楊柳相公桥。\"初，劉詩雲：\"夜月池台王傅宅，春風楊柳太師桥。\"今所改句，以為指巴陵及史丞相。及劉潛夫《黃巢戰場》詩雲：\"未必朱三能跋扈，都緣鄭五欠經纶。\"遂皆指為謗訕，押歸聽讀。同時被累者，如敖陶孫、周文璞、趙師秀，及刊詩陳起，皆不得免焉。於是江湖以詩為讳者兩年。其後史衛王之子宅之，婿趙汝梅，頗喜談詩，引致黃簡、黃中、吳仲孚諸人。洎趙崇和進《明堂禮成》詩二十韻，於是詩道复昌矣。","sortOrder":12},
  {"id":"s_work_tddn_17_13","chapterId":"ch_work_tddn_17","text":"○贾島佛","sortOrder":13},
  {"id":"s_work_tddn_17_14","chapterId":"ch_work_tddn_17","text":"唐李洞字子江，苦吟有聲。慕贾浪仙之詩，遂鑄其像事之，誦贾島佛不絕口，時以為異。","sortOrder":14},
  {"id":"s_work_tddn_17_15","chapterId":"ch_work_tddn_17","text":"五代孫晟初名鳳，又名忌，好學，尤長於詩。為道士，居庐山簡寂宮。嘗畫贾島像置屋壁，晨夕事之，人以為妖。","sortOrder":15},
  {"id":"s_work_tddn_17_16","chapterId":"ch_work_tddn_17","text":"蓋酸鹹之嗜，固有異世而同者，長江簿何以得此於人哉！凡人著書立言，正不必求合於一時，後世有扬子雲將自知之。","sortOrder":16},
  {"id":"s_work_tddn_17_17","chapterId":"ch_work_tddn_17","text":"○菊花新曲破","sortOrder":17},
  {"id":"s_work_tddn_17_18","chapterId":"ch_work_tddn_17","text":"思陵朝，掖庭有菊夫人者，善歌舞，妙音律，為仙韶院之冠，宮中號為菊部頭。然頗以不獲际幸為恨，既而稱疾告歸。宦者陳源以厚禮聘歸，蓄於西湖之適安園。一日，德寿按《梁州曲舞》，屢不稱旨。提舉官關禮知上意不樂，因從容奏曰：\"此事非菊部頭不可。\"上遂令宣唤，於是再入掖禁，陳遂憾怅成疾。有某士者，頗知其事，演而為曲，名之曰《菊花新》以獻之，陳大喜，酬以田宅金帛甚厚，其譜則教坊都管王公謹所作也。陳每聞歌，辄淚下不勝情，未幾物故。園後歸重華宮，改名小隱園。孝宗朝，拨賜張貴妃，為永寧崇福寺雲。","sortOrder":18},
  {"id":"s_work_tddn_17_19","chapterId":"ch_work_tddn_17","text":"○潘陳同母","sortOrder":19},
  {"id":"s_work_tddn_17_20","chapterId":"ch_work_tddn_17","text":"陳了翁之父尚書，與潘良貴義榮之父，情好甚密。潘一日謂陳曰：\"吾二人官職年齒，种种相似，獨有一事不如公，甚以為恨。\"陳問之，潘曰：\"公有三子，我乃無之。\"陳曰：\"吾有一婢已生子矣，當以奉借。它日生子即見還。\"即而遣至，即了翁之母也。未幾生良貴，後其母遂往來兩家焉。一母生二名儒，亦前所未有。事見羅春伯《聞見錄》。","sortOrder":20},
  {"id":"s_work_tddn_17_21","chapterId":"ch_work_tddn_17","text":"○省、状元同郡","sortOrder":21},
  {"id":"s_work_tddn_17_22","chapterId":"ch_work_tddn_17","text":"掄魁、省元同郡，自昔以為盛事。熙寧癸丑，省元邵刚、状元餘中皆毗陵人。淳熙丁未，省元湯、状元王容皆長沙人。紹熙癸丑，省元徐邦憲、状元陳亮皆婺州人。紹熙庚戌，省元錢易直、状元餘复皆三山人。寶慶丙戌，省元趙時睹、状元王會龍皆天台人。紹定己丑，省元陳松龍、状元黃朴皆福人。至淳祐甲辰，省元徐霖、状元留夢炎，皆三衢人。一時士林歆羨，以為希闊之事。時外舅楊彦瞻以工部郎守衢，遂大書状元坊以表其闾，既以為未足，則又揭双元坊以夸大之，乡曲以為至榮。二公不欲其成，各以書為謝，且辭焉。彦瞻答之，略雲：嘗聞前辈之言曰：\"吾乡昔有及第奉常而歸，旗者、鼓者、饋者、迓者、往來而觀者，闐路骈陌如堵牆。既而閨門贺焉，宗族贺焉，姻者、友者、客者交駕焉。至於仇者，亦茹恥羞愧而贺且謝焉。獨鄰居一室，扃遠引，若避寇然，餘因怪而問之，愀然曰：'所貴乎衣錦之榮者，謂其得時行道也，將有以庇吾乡里也。今也，或竊一名，得一官，即起朝富暮貴之想。名愈高，官愈穹，而用心愈缪。武斷者有之，兼併者有之，庇奸慝持州縣者有之，是一身之榮，一害之增也。其居日以廣，鄰居日以蹙。吾將入山林深密之地以避之，是可弔，何以贺為？'\"吾聞而異其言，因默識而謹書之。凡交遊間，必道此語相訓切，而非心相知者，不道也。執事於不肖，可謂心相知，而不以告，罪也。且今日此扁之揭，所以獨異於尋常者，蓋仆之望於執事者亦異焉。人於此時，每以諛獻，仆乃獨以忠告，非求異於人也，所冀進執事之德，成執事之器也。執事不以仆之言為然則已，若以為然，則是扁之揭，可以無愧矣。前之不贺者，必將先眾人而贺矣。今冠南宮者，執事友也，幸亦以是語之。","sortOrder":22},
  {"id":"s_work_tddn_17_23","chapterId":"ch_work_tddn_17","text":"二公得書，為之悚然。其後徐以道學名，留以功業顯，或者此書有以啟發之乎？","sortOrder":23},
  {"id":"s_work_tddn_17_24","chapterId":"ch_work_tddn_17","text":"○金刚鑽","sortOrder":24},
  {"id":"s_work_tddn_17_25","chapterId":"ch_work_tddn_17","text":"玉人攻玉，必以邢河之沙，其镌鏤之具，必用所謂金刚鑽者。形如鼠粪，色青黑如鐵如石。相傳產西域諸國，或謂出回紇國。往往得之河北沙碛間鷙鳥海東青所遺粪中，然竟莫知為何物也。蓋天下至堅者莫如玉，古者，惟锟钅吾刀可以切之。今此物功用乃與锟钅吾均，其堅可知矣。","sortOrder":25},
  {"id":"s_work_tddn_17_26","chapterId":"ch_work_tddn_17","text":"貞觀中有婆羅門言得佛齒，所击無堅物。時傅奕方臥病，謂其子曰：\"是非佛齒。吾聞金刚石至堅，物不能敵，惟羚羊角能破，汝可往击之。\"果應手而碎。是知此物，自昔亦罕知者矣。","sortOrder":26},
  {"id":"s_work_tddn_17_27","chapterId":"ch_work_tddn_17","text":"○多藏之戒","sortOrder":27},
  {"id":"s_work_tddn_17_28","chapterId":"ch_work_tddn_17","text":"王黼盛時，库中黃雀自地積至棟，凡滿二楹。蔡京對客，令點檢蜂兒見在數目，得三十七秤。童貫既败，籍其家，得剂成理中丸幾千斤，傳紀載之，以為談柄。","sortOrder":28},
  {"id":"s_work_tddn_17_29","chapterId":"ch_work_tddn_17","text":"近者，官籍贾似道第果子库，糖霜凡數百瓮，官吏以為不可久留，難載帳目，遂輦弃湖中，軍卒辈或乘時竊出，則他物稱是可想矣。\"胡椒八百斛，領軍鞋一屋\"，不足多也。","sortOrder":29},
  {"id":"s_work_tddn_17_30","chapterId":"ch_work_tddn_17","text":"○理、度議謚","sortOrder":30},
  {"id":"s_work_tddn_17_31","chapterId":"ch_work_tddn_17","text":"理宗未拊，議謚，朝堂或擬曰景、曰淳、曰成、曰文，最後曰禮。議既定矣，或謂與亡金伪謚同，且古有婦人號禮宗者，遂易之曰理。蓋以聖性崇尚理學，而天下道理最大，於是人無間言。而不知理字析文取義，乃四十一年王者之象，可謂請謚於天矣。","sortOrder":31},
  {"id":"s_work_tddn_17_32","chapterId":"ch_work_tddn_17","text":"度宗初議謚，或擬純字，則謂有屯之象；或擬實字，則宗實乃英宗舊名；或擬正字，則有一止之嫌，後遂定為端文明武景孝皇帝。先是皇姊因漢國長公主在先朝已謚端孝，今與廟號上下字暗合，豈偶然哉？","sortOrder":32},
  {"id":"s_work_tddn_17_33","chapterId":"ch_work_tddn_17","text":"理宗生母全夫人謚慈憲，殊不知伪齊劉豫母亦謚慈憲，當時考不及此，何耶？","sortOrder":33},
  {"id":"s_work_tddn_17_34","chapterId":"ch_work_tddn_17","text":"○謝太後","sortOrder":34},
  {"id":"s_work_tddn_17_35","chapterId":"ch_work_tddn_17","text":"寿和謝太後方選進時，史衛王夜夢謝魯王深甫衣金紫求見，致祷再三，以孫女為托，及明，則謝後至。是歲，天台郡元夕，有鵲巢燈山間，眾頗驚異。識者以為鵲巢乃後妃之祥，是歲謝果正中宮之位。","sortOrder":35},
  {"id":"s_work_tddn_17_36","chapterId":"ch_work_tddn_17","text":"鹹淳間，福邸涼堂初成，有鵲巢於前庑，賓客交慶，至有形之歌詩者。殊不知野鳥入室，不祥莫甚，安得與前事為比雲。","sortOrder":36},
  {"id":"s_work_tddn_17_37","chapterId":"ch_work_tddn_17","text":"○北令邦","sortOrder":37},
  {"id":"s_work_tddn_17_38","chapterId":"ch_work_tddn_17","text":"《渑水燕談》載契丹國產大鼠曰毗狸，形類大鼠而足短極肥。其國以為殊味，穴地取之，以供國王之膳，自公相以下，皆不得嘗，常以羊乳飼之。頃北使嘗携至京，烹以進御，本朝使其國者，亦皆得食之，蓋極珍重之也。","sortOrder":38},
  {"id":"s_work_tddn_17_39","chapterId":"ch_work_tddn_17","text":"浮休《使遼錄》亦謂有令邦者，以其肉一脔，置之食物之鼎，則立糜烂，是以愛重。陆氏《舊聞》雲：\"状類大鼠，極肥盾，甚畏日，為隙光所射辄死。\"《續揮犀》載刁約使契丹，戲為詩雲：\"押燕移離畢，看房贺跋支。餞行三匹裂，密賜十毗狸。\"如鼠而大，穴居食果穀，味若犭屯而脆，契丹以為珍膳。數說皆微有異同，要之即此一物，亦竹犭留、獾狸之類耳。近世乃不聞有此，扣之北客，亦多不知，何耶？","sortOrder":39},
  {"id":"s_work_tddn_17_40","chapterId":"ch_work_tddn_17","text":"○降仙","sortOrder":40},
  {"id":"s_work_tddn_17_41","chapterId":"ch_work_tddn_17","text":"降仙之事，人多疑為持箕者狡狯以愚旁觀，或宿構詩文托為仙語，其實不然，不過能致鬼之能文者耳。餘外家諸舅，喜為此戲，往往所降多名士，詩亦粗可讀，至於書體文势，亦各近似其人。一日，元毖舅諸姬，戲以紈扇求詩，遂各題小詞於上，仍寓姬之名於內，行草相間有可觀者。","sortOrder":41},
  {"id":"s_work_tddn_17_42","chapterId":"ch_work_tddn_17","text":"紹興斜桥客邸有請紫姑者，命舻為題，詩雲：\"寒巖雪壓松枝折，斑斑剝盡青虬血。運斤巧匠斫削成，劍脊半开魚尾裂。五湖仙子多奇致，欲駕神舟探仙穴。碧雲不動晓山橫，數聲搖落江天月。\"","sortOrder":42},
  {"id":"s_work_tddn_17_43","chapterId":"ch_work_tddn_17","text":"湖學甲子歲科舉後，士友有請仙問得失者，賦詞雲：\"凄涼天氣，凄涼院宇，凄涼時候。孤鸿叫斜月，寒燈伴殘漏。落盡梧桐秋影瘦，鑒古畫眉難就。重陽又近也，對黃花依舊。\"此人竟失舉。","sortOrder":43},
  {"id":"s_work_tddn_17_44","chapterId":"ch_work_tddn_17","text":"淳祐間，有降仙於杭泮者，或以鬼議之，大書一詩雲：\"眼前青白誰知我，口里雌黃一任君。縱使挟山可超海，也須覆雨更番雲。\"或以功名為問，答曰：\"朝經暮史無間日，北履南鞭知幾年。踐履未能求實地，榮枯何必問青天。\"報其相譏也。","sortOrder":44},
  {"id":"s_work_tddn_17_45","chapterId":"ch_work_tddn_17","text":"又董無益嘗記女仙三絕句雲：\"柳條金懶不勝鴉，青粉牆邊道韞家。燕子未來春寂寞，小窗和雨夢梨花。\"\"松影侵壇琳觀靜，桃花流水石桥寒。東風吹過双蝴蝶，人倚危樓第幾蘭。\"\"屈曲蘭幹月半規，藕花香澹水漪漪。分明一夜文姬夢，只有青团扇子知。\"亦可喜也。","sortOrder":45},
  {"id":"s_work_tddn_17_46","chapterId":"ch_work_tddn_17","text":"友人姚天泽亦善此。時先君需清湘次，因至外塾觀子弟捧箕。忽大書曰：詩赠周邦君，雲：\"謝公樓上春光好，五馬行春人未老。鬱孤台上墨未幹，手捧詔書入黃道。\"先子為一笑，然莫知為何等語也。未幾，易守臨汀，首披郡志，則舊有謝公樓，所謂\"謝公樓上好美酒，三百青銅買一斗\"者，與前語適符。然鬱孤台以後語，竟亦不验。","sortOrder":46},
  {"id":"s_work_tddn_17_47","chapterId":"ch_work_tddn_17","text":"又宋慶之寓永嘉時，遇詔歲，乡士從之結課者頗眾。適逢七夕，學徒醵飲，有僧法辨者在焉。辨善五星，每以八煞為說，時人號為辨八煞。酒邊一士致仙扣试事，忽箕動，大書文章伯降，宋怪之，漫雲：\"姑置此，且求一七夕新詞如何？\"复請韻，宋指辨雲：\"以八煞為韻。\"意欲困之也。忽運箕如飛，大書《鵲桥仙》一阕雲：\"鸞舆初駕，牛車齊發，隱隱鵲桥咿軋。尤雲雨正歡浓，但只怕來朝初八。霞垂彩幔，月明銀燭，馥鬱香喷金鸭。年年此际一相逢，未審是甚時結煞。\"亦警敏可喜。","sortOrder":47},
  {"id":"s_work_tddn_17_48","chapterId":"ch_work_tddn_17","text":"又聞李和父雲：\"向嘗於貴家觀降仙，扣其姓名，不答。忽作薛稷體大書一詩雲：'猩袍玉帶落邊尘，幾見東風作好春。因過江南省宗廟，眼前誰是舊京人。'捧箕者皆悚然驚散，知為淵聖在天之靈。\"真否固未可知，然每讀為之凄然。","sortOrder":48},
  {"id":"s_work_tddn_17_49","chapterId":"ch_work_tddn_17","text":"○文莊公滑稽","sortOrder":49},
  {"id":"s_work_tddn_17_50","chapterId":"ch_work_tddn_17","text":"外大父文莊章公，自少好雅絜，性滑稽；居一室必汛埽巧飾，陳列琴書，親朋或譏其齷齪無遠志。一日，大書素屏雲：\"陳蕃不事一室，而欲扫除天下，吾知其無能為矣！\"識者知其不凡。後入太學為集正，嘗置酒，揭饌单於爐亭，品目多異。其間有大鵬卵者最奇，其大如瓜，片切大盤中。眾皆駭愕，不知何物。好事者窮詰之；其法乃以凫彈數十，黃白各聚一器。先以黃入羊胞蒸熟，次复入大猪胞，以白實之，再蒸而成。嘗迎駕於觀桥，戲以書句為隱語雲：\"仰觀天文，俯察地理，吾嘗終日不食，終夜不寢，以思無益，不如學也。\"眾皆莫测，公笑雲：\"乃此桥華表柱木鸛爾。\"其他善戲多類此。","sortOrder":50},
  {"id":"s_work_tddn_17_51","chapterId":"ch_work_tddn_17","text":"其後居兩製，登政第，有《嘉林集》百卷。間作小詞，極有思致。先妣能口誦數阕，《小重山》雲：\"柳暗花明春事深，小蘭紅，芍藥已抽簪。雨餘風软碎鳴禽，遲遲日，猶帶一分陰。","sortOrder":51},
  {"id":"s_work_tddn_17_52","chapterId":"ch_work_tddn_17","text":"把酒莫沉吟，身閒無个事，且登臨。舊遊何處不堪尋，無尋處，惟有少年心。\"今家集已不复存，而外家凋謝殆盡。暇日追憶書之，以寄餘《凯風》、\"寒泉\"之思雲。","sortOrder":52},
  {"id":"s_work_tddn_17_53","chapterId":"ch_work_tddn_17","text":"○腹腴","sortOrder":53},
  {"id":"s_work_tddn_17_54","chapterId":"ch_work_tddn_17","text":"餘讀杜詩\"偏勸腹腴愧少年\"，喜其知味。坡詩亦雲：\"更洗河豚烹腹腴。\"黃詩亦雲：\"故園漁友脍腹腴。\"又雲：\"飛雪堆盤脍腹腴。\"按《禮記·少儀》雲：\"羞濡魚者進尾，冬右腴。\"註雲：\"腴，腹下也。\"《周禮疏》：\"燕人脍魚方寸，切其腴以啖所貴。引以證無，無亦腹腴。\"《前漢》：\"九州膏腴。\"師古註雲：\"腹下肥白曰腴。\"","sortOrder":54},
  {"id":"s_work_tddn_17_56","chapterId":"ch_work_tddn_17","text":"\"花竹幽窗午夢長，此中與世暫相忘。華山處士如容見，不觅仙方觅睡方。\"然則睡亦有方邪？希夷之說，不過謂舉世以為息魂離神不動耳。《遺教經》乃有\"煩惱毒蛇，睡在汝心，睡蛇既出，乃可安眠\"之語。近世西山蔡季通有睡訣雲：\"睡侧而屈，覺正而伸，早晚以時。先睡心，後睡眼。\"晦庵以為此古今未發之妙。然睡心、睡眼之語，本出《千金方》，季通特引此說，晦庵偶未之記耳。","sortOrder":56},
  {"id":"s_work_tddn_17_57","chapterId":"ch_work_tddn_17","text":"○性所不喜","sortOrder":57},
  {"id":"s_work_tddn_17_58","chapterId":"ch_work_tddn_17","text":"人各有好惡，於書亦然。前辈如杜子美不喜陶詩，欧陽公不喜杜詩，蘇明允不喜扬子，坡翁不喜《史記》。王充作《刺孟》，冯休著《删孟》，司馬公作《疑孟》，李泰伯作《非孟》，晁以道作《詆孟》，黃次作《評孟》；若酸、鹹嗜好，亦各自有所喜。非若今人之胸中無真識，隨時好惡，逐人步趨而然者。且以孟、扬、馬遷、陶、杜異世，遇諸名公，尚有所不合。今乃欲以區區之文，以求識賞於當世不具耳目之人，難矣哉！後世子雲之論，真名言也。","sortOrder":58},
  {"id":"s_work_tddn_17_59","chapterId":"ch_work_tddn_17","text":"○黃門","sortOrder":59},
  {"id":"s_work_tddn_17_60","chapterId":"ch_work_tddn_17","text":"世有男子雖娶婦而終身無嗣育者，謂之天閹，世俗則命之曰黃門。晉海西公嘗有此疾，北齊李庶生而天閹。","sortOrder":60},
  {"id":"s_work_tddn_17_61","chapterId":"ch_work_tddn_17","text":"按《黃帝針經》曰：\"有具傷於陰，陰氣絕而不起，陰不能用，然其須不去，宦者之獨去，何也？願聞其故。岐伯曰：'宦者去其宗筋，傷其冲脈，血泻不复，皮膚內結，唇口不榮，故須不生。'黃帝曰：'有其天宦者，未嘗被傷，不脱於血，然其須不生，何耶？'岐伯曰：'此天之所不足，其任冲不盛，宗筋不成，有氣無血，唇口不榮，故須不生。'\"","sortOrder":61},
  {"id":"s_work_tddn_17_62","chapterId":"ch_work_tddn_17","text":"又《大般若經》載五种黃門雲：\"梵言扇搋（音丑背切》半釋迦，唐言黃門，其類有五：一日半釋迦，總名也，有男根，用而不生子。二曰伊利沙半釋迦，此雲妒，謂見他行欲即發，不見即無，亦具男根，而不生子。三曰扇搋半釋迦，謂本來男根不滿，亦不能生子。四曰博叉半釋迦，謂半月能男，半月不能男。五曰留拿半釋迦，此雲割，謂被割刑者。此五种黃門，名為人中惡趣受身處。\"然《周禮·奄人》鄭氏註雲：\"奄，真氣藏者，謂之宦人。\"是皆真氣不足之所致耳。","sortOrder":62},
  {"id":"s_work_tddn_17_63","chapterId":"ch_work_tddn_17","text":"○馬塍藝花","sortOrder":63},
  {"id":"s_work_tddn_17_64","chapterId":"ch_work_tddn_17","text":"馬塍藝花如藝粟，橐馳之技名天下。非時之品，真足以侔造化，通仙靈。凡花之早放者，名曰堂（或作塘）花。其法以紙飾密室，凿地作坎，缏竹置花其上，粪土以牛溲硫黃，盡培溉之法。然後置沸湯於坎中，少候，湯氣薰蒸，則扇之以微風，盎然盛春融淑之氣，經宿則花放矣。若牡丹、梅、桃之類無不然，獨桂花則反是。蓋桂必涼而後放，法當置之石洞巖窦間，暑氣不到處，鼓以涼風，養以清氣，竟日乃开。此雖揠而助長，然必適其寒溫之性，而後能臻其妙耳。","sortOrder":64},
  {"id":"s_work_tddn_17_65","chapterId":"ch_work_tddn_17","text":"餘向留東西馬塍甚久，親聞老圃之言如此。因有感曰：草木之生，欲遂其性耳。封植矯揉，非時敷榮，人方詫賞之不暇，噫！是豈草木之性哉！","sortOrder":65},
  {"id":"s_work_tddn_18_1","chapterId":"ch_work_tddn_18","text":"●卷十七","sortOrder":1},
  {"id":"s_work_tddn_18_2","chapterId":"ch_work_tddn_18","text":"○楊凝式僧净端","sortOrder":2},
  {"id":"s_work_tddn_18_3","chapterId":"ch_work_tddn_18","text":"楊凝式居洛日，將出遊，仆請所之，楊曰：\"宜東遊廣愛寺。\"仆曰：\"不若西遊石壁寺。\"凝式曰：\"姑遊廣愛。\"仆又以石壁為請，凝式曰：\"姑遊石壁。\"聞者為之撫掌。","sortOrder":3},
  {"id":"s_work_tddn_18_4","chapterId":"ch_work_tddn_18","text":"吳山僧净端，道解深妙，所謂端師子者，章申公極愛之。乞食四方，登舟，旋問何風，風所向即從之，所至人皆樂施。蓋楊出無心，而端出委順，跡不同而意則同也。","sortOrder":4},
  {"id":"s_work_tddn_18_5","chapterId":"ch_work_tddn_18","text":"○奇對","sortOrder":5},
  {"id":"s_work_tddn_18_6","chapterId":"ch_work_tddn_18","text":"對偶小技，然亦非易事也。前辈所載已多，今擇所未書而可喜者數聯於此，為多聞之一助。","sortOrder":6},
  {"id":"s_work_tddn_18_7","chapterId":"ch_work_tddn_18","text":"義經六子艮巽坎兑震離，周禮一書天地春秋冬夏。","sortOrder":7},
  {"id":"s_work_tddn_18_8","chapterId":"ch_work_tddn_18","text":"龟從筮從卿士從庶民從，人相我相眾生相寿者相。","sortOrder":8},
  {"id":"s_work_tddn_18_9","chapterId":"ch_work_tddn_18","text":"善待問者如撞鐘小應小大應大，措天下者猶置器安則安危則危。","sortOrder":9},
  {"id":"s_work_tddn_18_10","chapterId":"ch_work_tddn_18","text":"左氏公羊梁春秋三傳，卦爻系辭彖象大易一經。","sortOrder":10},
  {"id":"s_work_tddn_18_11","chapterId":"ch_work_tddn_18","text":"五刑之屬三千大過小過，一門之聚百指家人同人。","sortOrder":11},
  {"id":"s_work_tddn_18_12","chapterId":"ch_work_tddn_18","text":"知我春秋罪我春秋誰譽誰毀，待以國士報以國士為己為人。","sortOrder":12},
  {"id":"s_work_tddn_18_13","chapterId":"ch_work_tddn_18","text":"迅雷風烈烈風雷雨，絕地天通通天地人。","sortOrder":13},
  {"id":"s_work_tddn_18_14","chapterId":"ch_work_tddn_18","text":"紀信韓信假帝假王，仲尼牟尼大聖大覺。","sortOrder":14},
  {"id":"s_work_tddn_18_15","chapterId":"ch_work_tddn_18","text":"蝉以翼鳴不啻若自其口出，龍將角聽謂其不足於耳欤。","sortOrder":15},
  {"id":"s_work_tddn_18_16","chapterId":"ch_work_tddn_18","text":"司馬相如蔺相如果相如否，長孫無忌費無忌能無忌乎。","sortOrder":16},
  {"id":"s_work_tddn_18_17","chapterId":"ch_work_tddn_18","text":"人有七情喜怒哀懼愛惡欲，經存六藝詩書禮樂易春秋。","sortOrder":17},
  {"id":"s_work_tddn_18_18","chapterId":"ch_work_tddn_18","text":"九州既別冀兖青徐扬荆豫雍梁，一道相傳尧舜禹湯文武周孔孟。","sortOrder":18},
  {"id":"s_work_tddn_18_19","chapterId":"ch_work_tddn_18","text":"正月六月七月十月之交，北風晨風凯風終風且а。","sortOrder":19},
  {"id":"s_work_tddn_18_20","chapterId":"ch_work_tddn_18","text":"孟軻好學師孔子之孫子思，文後興仁由太王以至王季。","sortOrder":20},
  {"id":"s_work_tddn_18_21","chapterId":"ch_work_tddn_18","text":"張良借箸前筹恨不食食其之肉，陳平刻木為女果能冒冒頓之围。","sortOrder":21},
  {"id":"s_work_tddn_18_22","chapterId":"ch_work_tddn_18","text":"下七十二之齊城凭三寸舌，退一百萬之秦寇用八千兵。","sortOrder":22},
  {"id":"s_work_tddn_18_23","chapterId":"ch_work_tddn_18","text":"柴也愚參也魯師也辟顏氏其庶幾乎，夷之清尹之任惠之和孔子集大成也。","sortOrder":23},
  {"id":"s_work_tddn_18_24","chapterId":"ch_work_tddn_18","text":"妙法法因因果寺金輪金刚（錢塘寺名），中和和丰丰樂桥銀杓銀瓮（錢塘酒樓）。","sortOrder":24},
  {"id":"s_work_tddn_18_25","chapterId":"ch_work_tddn_18","text":"夫子天尊大士頭上不同，宮妃宦寺官人腰間各別。","sortOrder":25},
  {"id":"s_work_tddn_18_26","chapterId":"ch_work_tddn_18","text":"邹孟子吳孟子寺人孟子一男一女一不男不女，周宣王齊宣王司馬宣王一君一臣一不君不臣。","sortOrder":26},
  {"id":"s_work_tddn_18_27","chapterId":"ch_work_tddn_18","text":"調羹止渴梅全文武之才，學舞貪眠柳盡悲歡之態。","sortOrder":27},
  {"id":"s_work_tddn_18_28","chapterId":"ch_work_tddn_18","text":"方丈四方方四丈南北東西，试場三试试三場經賦論策。","sortOrder":28},
  {"id":"s_work_tddn_18_29","chapterId":"ch_work_tddn_18","text":"朝登箕子之峰危如累卵，夜宿丈人之馆安若泰山。","sortOrder":29},
  {"id":"s_work_tddn_18_30","chapterId":"ch_work_tddn_18","text":"觀音大士妙音梵音海潮音，諸相如來人相我相眾生相。","sortOrder":30},
  {"id":"s_work_tddn_18_31","chapterId":"ch_work_tddn_18","text":"龍飛策士状元龍省元龍（度宗龍飛榜，陳文龍為廷魁，胡躍龍為省元）；虎帳得人殿帥虎步帥虎（時范文虎為殿帥，孫虎臣為步帥）。","sortOrder":31},
  {"id":"s_work_tddn_18_32","chapterId":"ch_work_tddn_18","text":"○笙炭","sortOrder":32},
  {"id":"s_work_tddn_18_33","chapterId":"ch_work_tddn_18","text":"趙元父祖母齊安郡夫人徐氏，幼隨其母入吳郡王家，又及入平原郡王家，嘗談兩家侈盛之事，歷歷可聽。其後翠堂七楹，全以石青為飾，故得名。专為諸姬教習聲伎之所，一時伶官樂師，皆梨園國工也。吹彈舞拍，各有總之者，號為部頭。每遇節序生辰，則旬日外依月律按试，名曰小排當，雖中禁教坊所無也。只笙一部，已是二十餘人。自十月旦至二月終，日給焙笙炭五十斤，用錦熏籠藉笙於上，复以四和香熏之。蓋笙簧必用高麗銅為之，〈青色〉以绿蠟，簧暖則字正而聲清越，故必用焙而後可。陆天隨詩雲：\"妾思冷如簧，時時望君暖。\"樂府亦有簧暖笙清之語，舉此一事，餘可想見也。〈青色〉字，韻書：\"千定切，音請。\"註：\"〈青色〉，青果色也。\"蓋藏果者，必以銅青故耳。","sortOrder":33},
  {"id":"s_work_tddn_18_34","chapterId":"ch_work_tddn_18","text":"○徐謂禮相術","sortOrder":34},
  {"id":"s_work_tddn_18_35","chapterId":"ch_work_tddn_18","text":"徐謂禮嘗涉獵袁、李之書，自夸閱人貴賤多奇中。與贾師憲丞相為姻聯，贾時年少，荒於飲博，其生母胡夫人苦之。扣徐曰：\"兒子跌宕若此，以君相法言之，何如？\"徐曰：\"夫人勿多忧，異日必可作小郡太守。\"母喜而記其言。他日贾居相位，徐以親故求進，久之不遂。贾母為言之，贾不獲已，答曰：\"徐親骨相寒薄，止可作小郡太守耳。\"遂以上饒郡與之，以終其身，蓋深衔前言也。然師憲日常馳馬出遊湖山，小憩栖霞嶺下。忽有布裘道者瞪视曰：\"官人可自愛重，將來功名不在韓魏公下。\"贾意其見侮，不顧而去。既而醉博平康，至於破面。他日，复遇道者，頓足驚叹曰：\"可惜！可惜！天堂已破，必不能令終矣。\"其後悉验。","sortOrder":35},
  {"id":"s_work_tddn_18_36","chapterId":"ch_work_tddn_18","text":"○鹹淳三事","sortOrder":36},
  {"id":"s_work_tddn_18_37","chapterId":"ch_work_tddn_18","text":"鹹淳癸酉夏，邊遽日聞，既而襄州失守，朝野震動。荆阃李庭芝祥父乞贾平章用張魏公、趙忠簡故事，建督於京，贾則請親行邊。疏凡屢上，朝紳學士上書者無虛日，或欲留行，或贊开督。其後遂置機速房，专行密院急切之事。且大开言路，以集眾思，於是言事獻策者，益紛紛然。","sortOrder":37},
  {"id":"s_work_tddn_18_38","chapterId":"ch_work_tddn_18","text":"漢嘉布衣楊安宇者，狂生也，自謂知兵，獻言於朝，遂送機速房看詳。都司許自節擬本房，知其狂妄，遂侮笑之。安宇不勝其憤，遂上書痛詆自書短，且謂其操乡音秽談，一時傳以為笑。會奉口有米局之变，京尹吳益區處失當，於是左史李珏自經筵直前論之，吳遂斥出。時好事者為之語曰：\"左史直前論大尹，草茅上疏詆都司。\"","sortOrder":38},
  {"id":"s_work_tddn_18_39","chapterId":"ch_work_tddn_18","text":"時方詔歲，贾公欲優學舍以邀譽，乃以校尉告身，錢帛等俾京庠擬试。時黃文昌方自江阃入為京尹，益增賞格，雖末缀，猶獲數百千，於是群四方之士，试者紛然。時襄、郢已失，江、淮日以遽告，有無名子作詩，揭之试所雲：\"鼙鼓驚天動地來，九州赤子哭哀哀。廟堂不問平戎策，多把金錢媚秀才。\"邏之，竟不得其人而止。","sortOrder":39},
  {"id":"s_work_tddn_18_40","chapterId":"ch_work_tddn_18","text":"○龚孟钅癸策問","sortOrder":40},
  {"id":"s_work_tddn_18_41","chapterId":"ch_work_tddn_18","text":"癸酉歲，慶元秋试，兩浙運司幹官臨川龚孟讠阎為考官。龚道出慈溪，忽夢有人以杯酒飲之，且作\"四\"字於掌中。晓起，便覺目视荒荒。及入院發策，第一道中誤以一祖十三宗為十四宗。於是士子大哄，径排试官房舍，悉遭棰辱，至有負笈而逃者，龚偶得一兵負去而免。","sortOrder":41},
  {"id":"s_work_tddn_18_42","chapterId":"ch_work_tddn_18","text":"劉製使良貴親至院外撫諭，遂權宜以策題第二道為首篇，續撰其三，久之始定。於是好事者作隔聯雲：\"龚運幹出題疏脱，以十三宗作十四宗；劉製使下院調停，用第二道為第一道。\"龚後為計使所劾。","sortOrder":42},
  {"id":"s_work_tddn_18_43","chapterId":"ch_work_tddn_18","text":"明年秋，度宗賓天，於是十四宗之語遂验。","sortOrder":43},
  {"id":"s_work_tddn_18_44","chapterId":"ch_work_tddn_18","text":"○景定行公田","sortOrder":44},
  {"id":"s_work_tddn_18_45","chapterId":"ch_work_tddn_18","text":"景定三年壬戌，贾師憲丞相欲行富國強兵之策。是時劉良貴為都漕尹天府，吳势卿餉淮東，入為浙漕，遂交贊公田之事。欲先行之浙右，候有端緒，則諸路仿行之。於是殿院陳尧道、正言曹孝慶等合奏，謂限田之法，自昔有之。買官戶逾限之田，嚴歸併飛走之弊，回買官田，可得一千萬畝，則每歲六七百萬之入，其餘軍餉沛然有餘。可免和籴，可以餉軍，可以住造楮幣，可平物价，可安富室。一事行而五利興，實為無窮之利。御筆批依，而買田之事起矣。","sortOrder":45},
  {"id":"s_work_tddn_18_46","chapterId":"ch_work_tddn_18","text":"時势卿已死，良貴獨任提領之職，以太府丞陳為簡閱官以副之。且乞內批下都省，嚴立賞罰，究歸併之弊。然上意終出勉強，內批雲：\"永免和籴，無如買逾限之田為良法。然東作方興，權俟秋成，續議施行。\"則上意蓋可見矣。贾相憤然以去就爭之，於是再降聖旨雲：\"買田永免和籴，自是良法美意，要當始於浙西，庶他路视為則也。所在利病，各有不同，行移難於一律，可令三省照此施行。\"既而贾相內引，入札力言其便，御筆遵依，轉札侍從、台諫、給舍、左右司、三省，奉行惟謹焉。贾相遂先以自己浙西萬畝為官田表倡，嗣榮王繼之，浙西師機趙孟奎亦申省自陳投賣。自是朝野卷舌，噤不敢發一語。獨禮書夕郎徐經孫一疏，力陳買田之害，言多剀切，竟不付外。遂四乞休致，而寂無和之者。先是議以官品逾限田外回買立說，此猶有抑強嫉富之意。既而轉為派買之說，除二百畝已下免行派買外，餘悉各買三分之一，及其後也，雖百畝之家亦不免焉。立价以租一石者偿十八界四十楮，不及石者，价隨以减。買數少者，則全支楮券，稍多則銀券各半，又多則副以度牒，至多則加以登仕、將仕、校尉、承信、承節、安人、孺人告身。准直以登仕三千楮，將仕千楮，許赴漕试，校尉萬楮，承信萬五千，承節二萬，則理為進納，安人四千，孺人二千，此則幾於白没矣。遂檄府丞陳往湖、秀，將作丞廖邦杰往常、润，任督催之職。六郡則又有专官；平江則知郡包恢，撫參成公策。嘉興則知郡潘墀，撫幹李補，寓公焦煥炎。安吉則知郡謝奕焘，寓公趙與，撫幹王唐，臨安察判馬元演。常州則知郡洪キ，運屬劉子耕。镇江則知郡章垌，漕司准遣鄭夢熊。江陰則知軍楊珏，准遣謝司戶黃仲。併俟竣事，各轉一官。選人减一，前守臣併以主管公田系衔。既而提領劉佐司劾罢嘉興宰段浚、宜興宰葉哲佐以不即奉行之罪。又按長洲宰何九齡追毀告身，永不收叙。以不合出給官由令田主包納，失田業相維之初意。至五月，乃命江陰、平江隸浙西憲司，安吉、嘉興隸兩浙漕司，常州、镇江隸總所。每歲秋租，输之官仓，特與减饒二分，或水旱，則別議收數。遂立四分司：王大呂，平江；方夢玉，嘉興；董楷，安吉；黃震，镇江、常州、江陰三郡。初以選人為之，任滿理為須入。州、縣、乡、都，則分差莊官以富饒者充應，兩年一替。每乡創官莊一所，每租一石，明减二斗，不許多收斛面。約束雖嚴詳，而民之受害亦不少。其間毗陵、澄江，一時迎合，止欲買數之多。凡六斗、七斗者，皆作一石。及收租之际，元額有虧，則取足於田主，以為無窮之害。或內有硗瘠及租佃顽惡之處，又從而责換於田主，其害尤惨。時中書劉震孫與京尹魏克愚，湖邊倡和詞語，偶犯時忌，則隨命劾去之。","sortOrder":46},
  {"id":"s_work_tddn_18_47","chapterId":"ch_work_tddn_18","text":"甲子秋，彗見，求言。公卿、大夫、士庶始得以伸田里愁叹不平於上，然至此業已成矣。贾相遂力辨人言，丐辭相位。御筆答雲：\"言事易，任事難，自古然也。使公田之策不可行，則卿建議之始，朕已沮之矣。惟其上可以免朝廷造楮幣之費，下可以免浙右和籴之扰，公私兼濟，所以命卿决意舉行之。今業已成矣，一歲之軍餉，皆仰給於此。若遽因人言而罢之，雖可以快一時之異議，其如國計何？如軍餉何？卿既任事，亦當任怨，禮義不愆，何恤人言。卿宜安心奉職，毋孤朕倚毗之意。\"自此公論頗沮，而劉良貴以人言藉藉，遂陳括田之勞，乞從罢免，不允。","sortOrder":47},
  {"id":"s_work_tddn_18_48","chapterId":"ch_work_tddn_18","text":"至鹹淳戊辰正月，遂罢莊官，改為召佃。或一二千，或數百畝，召人承佃，自耕自种，自運自納，止令分司任责拘催。凡承佃之家，复以二分優之。且以既罢莊官，則分司恐難任责，平江增差催督官三員，安吉、嘉興各一員，常州二員，镇江、江陰共一員，從各分司奏辟。時提領官編修黃夢炎也。既而常、润分司劉子澄力陳毗陵向來多買虛數之弊，遂下提領所，径將常州公租拨隸淮東總領所催納。殊不知朝廷既不可催，總所又可催乎？","sortOrder":48},
  {"id":"s_work_tddn_18_49","chapterId":"ch_work_tddn_18","text":"當是時人不敢言而敢怨，南康江天錫以入奏而罢言職，教授謝枋得以發策而遭貶斥，大社令杜淵、太常簿陆逵、國子簿謝章，皆於論對及之，或逐去，或補外。至乙亥春，贾既去國，北軍已抵升、润，察院季可奏乞罢公田之籍，以收農心。謂\"此事苛扰，民皆破家荡產，怨入骨髓。若盡還原主，免索原錢而除其籍，庶使浙西之人，永絕公田之苦。\"然而仅放欠租，季遂再奏，始有旨雲：\"公田之創，非理宗之本意。稔禍召怨，最為民苦，截日住罢。其田盡給付原佃主，仰率租戶、義兵，會合防拓。\"其後勘會，謂招兵非便。且其田當還業主，於种戶初無相幹。秋成在邇，餉軍方急，合且收租一年。其還田指揮，候秋成後集議施行。有旨將平江、嘉興、安吉公田，照指揮蠲放，却從朝廷照净催米數回籴。其錢一半給佃主，一半給种戶，以溥實惠，然則業主竟無與矣。只業主、佃主之分，當時用事者亦不能晓，况大於此者？然邊遽日急，是時仍收公租，還田之事，竟不及行，呜呼悲哉！昔隋凿汴渠，以召民怨，乃為宋漕運之利。今宋奪民田以失人心，乃為大元餉軍之利。古今害民興利之事，於此亦可鑒矣，於戲悲哉！","sortOrder":49},
  {"id":"s_work_tddn_18_50","chapterId":"ch_work_tddn_18","text":"○景定彗星","sortOrder":50},
  {"id":"s_work_tddn_18_51","chapterId":"ch_work_tddn_18","text":"景定五年甲子七月初二日甲戌，御筆作初三日乙亥，彗見東方柳宿，光芒ピ赫，昭示天变。太史占雲：\"彗出柳度，為兵丧，為旱，為亂，為夷狄，為大臣貶。\"乾象占雲：\"彗，妖星也。所出形状各異，其殃一也。\"彗，木類，除舊布新之象，主兵疫之灾。一曰埽星，小者數寸，長或竟天，兵起、大水，除舊布新。按彗本無光，借日為光。夕見則東指，晨見則西指，皆隨日光芒所及則為灾。丁丑，避殿减膳，下詔责己，求直言，大赦天下。御史朱貔孫，正言朱應元，察官程元嶽、饒應龍合台奏章，乞消弭挽回，皆常談也。","sortOrder":51},
  {"id":"s_work_tddn_18_52","chapterId":"ch_work_tddn_18","text":"己卯，贾丞相似道，楊參政棟，葉同知夢鼎，姚佥書希得奏事。上曰：\"彗出於柳，彰朕不德，夙夜疚心，惟切危懼。\"宰臣奏：\"陛下勤於求治，有年於茲，庸有闕失。今謫見於天，實臣等辅政無状所致，上貽聖忧。臣見具疏乞罢免，庶可以上弭天灾。\"上曰：\"正當相與講求闕失，上回天意。\"庚辰，贾右相第一疏乞罢免，以塞灾咎，五疏皆不允。","sortOrder":52},
  {"id":"s_work_tddn_18_53","chapterId":"ch_work_tddn_18","text":"班行應詔言事者，秘書郎文及肩首言公田之事雲：\"君德極璋之粹，而玷君德者，莫大於公田，東南民力竭矣。公田創行，將以足軍储，救楮弊，蠲和籴也。奉行太過，限田之名，一变而為併戶，又变而為換田。耕夫失業以流離，田主無辜而拘系，此彗妖之所以示变也。\"","sortOrder":53},
  {"id":"s_work_tddn_18_54","chapterId":"ch_work_tddn_18","text":"大府丞楊巽，殿講趙景緯，吏部侍郎留夢炎，禮部侍郎直院馬廷鸞，皆應詔上封事。給事禮書牟子才疏，援引漢、唐以至本朝彗变灾異，極其詳贍。起居郎太子侍讀李伯玉，則援三說雲：\"鹹平，彗出室北，呂端有兵謀不精之言，今日當嚴邊備。熙寧中，彗出東井，富弼、張方平，皆言新法不便，今日當先罢浙西換田局。崇寧彗出西方，則詔除党籍，且复左降人官。今开慶誤國之人，罪惡滔天，有一時風聞劾逐者，則乞斟酌宽貸施行，以昭聖主宽仁之量。\"又雲：\"今言路既开，中外大小之臣，必將空臆畢陳。惟陛下明聖，大臣忠亮，有以容受，不以為罪，天下幸甚。\"","sortOrder":54},
  {"id":"s_work_tddn_18_55","chapterId":"ch_work_tddn_18","text":"浙漕主管文字呂撫有上化地書，秘監高斯得奉祠於有應詔疏，大概以為：\"非朝廷大失人心，何以致天怒如此之烈？庚申、辛酉之間，大小之臣，追勒遷放無虛月，忠厚之泽幾盡矣。士大夫以仕進為業，今使刻薄小人，吹毛求疵，動觸新製。公田肆扰，陛下知其非計，有待秋成舉行之旨，而督促者。悍然不顧也。市舶盡利而蕃夷怨，鹽榷太密而商旅怨。群臣附下罔上，虛美溢譽，人怨天怒，不至於彗星不止也。且灾異策免三公，视為常事。丙申雷变，陛下一日黜二相，今彗見之與雷發相去，何翅十百千萬哉？\"","sortOrder":55},
  {"id":"s_work_tddn_18_56","chapterId":"ch_work_tddn_18","text":"王端明龠奉祠里居，亦有疏，言：\"戚畹嬖幸，遍居畿辅，借應奉之名，肆誅剝之虐，監司不敢誰何，台諫不敢論列。民不勝苦，起而弄兵，三衢之寇是也。公田之行，本欲免和籴，和籴數少，而人己相安，公田數多，而人為創見，千弊萬蠹，田里骚然。天筆載頒，一則曰業已成，一則曰當任怨。且求言之詔甫頒，而拒言之令已出，皇天監臨，可厚誣哉。\"","sortOrder":56},
  {"id":"s_work_tddn_18_57","chapterId":"ch_work_tddn_18","text":"自是三學京庠，投匦上書者日至。太學生吳綺、許求之等書有雲：\"雷霆，天怒也，骤击而旋收。日蚀，天怒也，俄晦而隨明。暴風飄雨，天怒也，而不能以終日。今彗之示变，已渝旬浃月，陛下恐懼修省，靡所不至，而天怒猶未回，非陛下不知省悟也，抑誤陛下者，未有所畏也。\"且併及市舶、公田之害雲。又有陳夢斗、陳紹中等書，沈震孫、范鑰、李極等書，宗庠則有胡標與周必礻龠等書。立禮斋生謝禹則獨為一書，大抵皆及公田、市榷等事。又有武學生杜士賢等書，謂：\"都司之職，操垄斷之權，以专使之遣，奪番商之利。百姓皆與蹙廟堂，歌頌太平，人不可欺，天可欺乎？今之秉鈞軸者，前日之功固伟矣，今日之過未盡掩，阃外之事固優矣，阃內之责未盡塞。以戎虜待庶民不可也，以軍政律士類不可也，以肥家之法經國不可也，盍亦退自省悟，以回天变乎？\"又京庠唐隸、楊坦等一書，謂：\"大臣德不足以居功名之高，量不足以展經纶之大，率意紛更，殊駭觀聽。七司條例，悉從更变，世胄延賞，巧摘瑕疵。薪茗拓藏，香椒積壓，與商贾爭微利。強買民田，貽禍浙右，自今天下無稔歲，浙路無富家矣。夹袋不收拾人才，而遍储賤妓之姓名；化地不斡旋陶冶，而務行非僻之方術。縱不肖之駿弟，以卿月而醉風月於花衢；籠博奕之舊徒，以秋壑而壓溪壑之淵藪。踏青泛绿，不思闾巷之萧條；醉酿飽鮮，遑恤物价之騰踴。劉良貴，賤丈夫也，乃深倚之以扬鷹犬之威；董宋臣，巨奸宄也，乃優縱之以出虎兕之柙。人心怨怒，致此彗妖，誰秉國鈞，盍執其咎。方且抗章誣上，文過飾非，借端拱禍败不應之說以力解，亂而至此，怨而至此。上幹天怒，彗星埽之未幾，天火又從而灾之，其尚可扬扬入政事堂耶？\"一時諸書，獨此與京庠萧規者言之太訐。於是左司劉良貴申省，力辨公田任事之謗，且乞敷奏令公卿士庶條具救楮、免籴、罢公田之策，且作勘會，免公田逃亡米三萬餘石。贾相遂入奏雲：\"近者應詔所言，公論交责，若駕虛辭報私憾等語，是非自不可掩。獨類部法買公田，同然一辭，以為犯大不韙，詳叙顛末以聞。欲望聖慈於臣所類部法，則下之吏部長式，詳加參定。或有出己意削舊典之實，則申明而删除之。於臣所買公田，則乞下之公卿大夫，更行博議。必得足軍餉、免和籴、住造楮之策，則采錄而施行之。臣當委心以聽，奉身以退，徐請譴责，以戒為臣之缪於國者。\"遂有旨宣諭檢院官，星变求言：\"照典故氐及中外大小臣僚，見之詔書可考。近來諸學士人，不體舊規，以前廊為首，乃有懷私意動搖大臣者。不知祖宗三百年間，曾有士人上書而去宰相者乎？今後切宜詳審，然後投進。\"","sortOrder":57},
  {"id":"s_work_tddn_18_58","chapterId":"ch_work_tddn_18","text":"檢院朱備坐，宣諭旨揮申國子監司成吳堅翁，合委胄丞徐宗斗，會學前廊轉諭諸生；而前廊回申，以為上書以前廊為首，此出於丙辰方大猷之私意，以為鉗製之法，非盛時所宜用也。紛紛之議，直至八月之末，彗光稍殺，應詔者方稍止。丁未，宰執拜表，恭請皇帝御正殿复常膳，三表而後從。九月，以京學士人萧規、唐棣、葉李、呂宙之、姚必得、陳子美、錢育、趙從龍、胡友开等，不合謗訕生事，送臨安府追捕勘證，議罪施行各有差，自是中外結舌焉。","sortOrder":58},
  {"id":"s_work_tddn_18_59","chapterId":"ch_work_tddn_18","text":"孟冬，朝饗如常時，十月乙丑，忽聞聖躬不豫，降詔求医，丁卯，遺詔升遐。而金銀關子之令乘時頒行，換易十七界楮券。物价自此騰涌，民生自此憔悴矣。彗变首尾凡四月，妖禍之應，如响斯答，孰謂天道高遠乎？","sortOrder":59},
  {"id":"s_work_tddn_18_60","chapterId":"ch_work_tddn_18","text":"○琼花","sortOrder":60},
  {"id":"s_work_tddn_18_61","chapterId":"ch_work_tddn_18","text":"扬州後土祠琼花，天下無二本，絕類聚八仙，色微黃而有香。仁宗慶歷中，嘗分植禁苑，明年辄枯，遂复載還祠中，敷榮如故。淳熙中，寿皇亦嘗移植南內，逾年，憔悴無花，仍送還之。其後，宦者陳源命園丁取孫枝移接聚八仙根上遂活，然其香色則大减矣，杭之褚家塘琼花園是也。今後土之花已薪，而人間所有者，特當時接本仿佛似之耳。","sortOrder":61},
  {"id":"s_work_tddn_18_62","chapterId":"ch_work_tddn_18","text":"○嚼蝨","sortOrder":62},
  {"id":"s_work_tddn_18_63","chapterId":"ch_work_tddn_18","text":"餘負日茅簷，分漁樵半席。時見山翁野媪，扪身得蝨則致之口中，若將甘心焉，意甚惡之。然揆之於古，亦有說焉。應侯謂秦王曰：\"得宛，臨流陽夏，斷河內，臨東陽邯鄲，猶口中蝨。\"王莽校尉韓威曰：\"以新室之威，而吞胡虜，無異口中蚤蝨。\"陳思王著論亦日：\"得蝨者，莫不靡刂之齒牙，為害身也。\"三人者，皆當時貴人，其言乃爾，則野老嚼蝨，蓋亦自有典故，可發一笑。","sortOrder":63},
  {"id":"s_work_tddn_18_64","chapterId":"ch_work_tddn_18","text":"○姓名相戲","sortOrder":64},
  {"id":"s_work_tddn_18_65","chapterId":"ch_work_tddn_18","text":"前辈有以姓名為戲者，如陳亚有心、蔡襄無口之類甚多。劉嘗戲王觌雲：\"公何故見賣？\"王答曰：\"賣公直甚分文。\"","sortOrder":65},
  {"id":"s_work_tddn_18_66","chapterId":"ch_work_tddn_18","text":"近楊平舟棟以枢掾出守莆田，劉克莊潛夫，弟希仁，俱以史官里居。郡集，寓公王曜軒邁戲之雲：\"大編修，小編修，同赴編修之會。\"後村雲：\"欲屬對不難，不可見怒。\"王願聞之，乃雲：\"前通判，後通判，但聞通判之名。\"蓋王凡五得ヘ而不上雲。王又嘗調後村雲：\"十兄，二十年前何其壮，二十年後何其不壮。\"劉應之曰\"二畫，二十年前何其遇，二十年後何其不遇。\"此善謔也。","sortOrder":66},
  {"id":"s_work_tddn_18_67","chapterId":"ch_work_tddn_18","text":"○朱唐交奏本末","sortOrder":67},
  {"id":"s_work_tddn_18_68","chapterId":"ch_work_tddn_18","text":"朱晦庵按唐仲友事，或雲呂伯恭嘗與仲友同書會，有隙，朱主呂故抑唐，是不然也。蓋唐平時恃才輕晦庵，而陳同父頗為朱所進，與唐每不相下。同父遊台，嘗狎籍妓，嘱唐為脱籍，許之。偶郡集，唐語妓雲：\"汝果欲從陳官人邪？\"妓謝，唐雲：\"汝須能忍飢受冻乃可。\"妓聞，大恚。自是陳至妓家，無复前之奉承矣。","sortOrder":68},
  {"id":"s_work_tddn_18_69","chapterId":"ch_work_tddn_18","text":"陳知為唐所賣，亟往見朱。朱問：\"近日小唐雲何？\"答曰：\"唐謂公尚不識字，如何作監司？\"朱衔之，遂以部內有冤獄，乞再巡按。既至台，適唐出迎少稽，朱益以陳言為信，立索郡印，付以次官，乃摭唐罪具奏，而唐亦作奏馳上。時唐乡相王淮當軸，既進呈，上問王，王奏：\"此秀才爭閉氣耳。\"遂兩平其事，詳見周平園、王季海日記。而朱門諸賢所著《年譜》、《道統錄》，乃以季海右唐而併斥之，非公論也。其說聞之陳伯玉式卿，蓋親得之婺之諸呂雲。","sortOrder":69},
  {"id":"s_work_tddn_19_1","chapterId":"ch_work_tddn_19","text":"●卷十八","sortOrder":1},
  {"id":"s_work_tddn_19_2","chapterId":"ch_work_tddn_19","text":"○晝寢","sortOrder":2},
  {"id":"s_work_tddn_19_3","chapterId":"ch_work_tddn_19","text":"\"飽食缓行初睡覺，一甌新茗侍兒煎。脱巾斜倚繩床坐，風送水聲來枕邊。\"丁崖州詩也。\"細書妨老讀，長箪愜昏眠。取簟且一息，抛書還少年。\"半山翁詩也。\"相對蒲团睡味長，主人與客兩相忘。須臾客去主人覺，一半西窗無夕陽。\"放翁詩也。\"讀書已覺眉稜重，就枕方欣骨節和。睡起不知天早晚，西窗殘日已無多。\"吳僧有規詩也。\"老讀文書興易阑，須知養病不如閒。竹床瓦枕虛堂上，臥看江南雨後山。\"呂榮陽詩也。\"紙屏瓦枕竹方床，手倦抛書午夢長。睡起莞然成獨笑，數聲漁笛在沧浪。\"蔡持正詩也。","sortOrder":3},
  {"id":"s_work_tddn_19_4","chapterId":"ch_work_tddn_19","text":"餘習懶成癖，每遇暑晝，必須偃息。客有嘲孝先者，必哦此以自解。然每苦枕熱，展轉數四。後見前辈言，荆公嗜睡，夏月常用方枕。或問何意，公雲：\"睡氣蒸枕熱，則轉一方冷處。\"此非真知睡味，未易語此也。杜牧有睡癖，夏侯隱號睡仙，其亦知此乎？","sortOrder":4},
  {"id":"s_work_tddn_19_5","chapterId":"ch_work_tddn_19","text":"雖然，宰予晝寢，夫子有朽木粪土之語。嘗見侯白所註《論語》，謂\"晝\"字當作\"畫\"字，蓋夫子惡其畫寢之侈，是以有朽木粪牆之語。然侯白，隋人，善滑稽，嘗著《啟顏錄》，意必戲語也。及觀昌黎《語解》，亦雲\"晝寢\"當作\"畫寢\"，字之誤也。宰予，四科十哲，安得有晝寢之责，假或偃息，亦未至深誅。若然，則吾知免矣。","sortOrder":5},
  {"id":"s_work_tddn_19_6","chapterId":"ch_work_tddn_19","text":"○宜興梅冢","sortOrder":6},
  {"id":"s_work_tddn_19_7","chapterId":"ch_work_tddn_19","text":"嘉熙間，近屬有宰宜興者，縣斋之前，紅梅一树，極美麗華粲，交陰半畝。花時，命客飲其下。一夕，酒散月明，獨步花影，忽見紅裳女子，輕妙綽約，瞥然過前，躡之數十步而隱。自此恍然若有所遇，或酣歌晤言，或癡坐竟日，其家忧之。","sortOrder":7},
  {"id":"s_work_tddn_19_8","chapterId":"ch_work_tddn_19","text":"有老卒頗知其事，乘間白曰：\"昔聞某知縣之女有殊色，及笄，未適而夭。其家遠在湖湘，因藁葬於此，树梅以識之。畴昔之夜所見者，豈此乎？\"遂命發之，其棺正蟠絡老梅根下，兩樯微蚀，一竅如錢，若蛇鼠出入者。啟而视之，顏貌如玉。妆飾衣衾，略不少損，真國色也。趙見，為之惘然心醉。舁至密室，加以茵藉，而四體亦和柔，非尋常僵尸之比，於是每夕與之接焉。既而氣息忄然，疲ぃ不可治文書。其家乃乘間穴壁取焚之，令遂屬疾而殂，亦雲異哉。嘗見小說中所載寺僧盜婦人尸置夹壁中私之，後其家知，状訟於官，每疑無此理。今此乃得之親舊目击，始知其說不妄。然《通鑒》所載，赤眉發呂後陵，污辱其尸有致死者，蓋自昔固有此異矣。","sortOrder":8},
  {"id":"s_work_tddn_19_9","chapterId":"ch_work_tddn_19","text":"○莫子及泛海","sortOrder":9},
  {"id":"s_work_tddn_19_10","chapterId":"ch_work_tddn_19","text":"吳興莫汲子及，始受世泽為铨试魁，既而解试、省试、廷對，皆居前列，一時名聲籍甚。後為學官，以語言獲罪，南遷石龍。地併海，子及素負邁往之氣，暇日，具大舟，招一時賓友之豪，泛海以自快。將至北洋，海之尤大處也，舟人畏不敢進。子及大怒，胁之以劍，不得已從之。及至其處，四顧無际。須臾，風起浪涌，舟掀簸如桔槔。見三魚，皆長十餘丈，浮弄日光。其一若大鲇状，其二状類尤異，眾皆戰栗不能出語。子及命大白連酌，賦詩數絕，略無懼意，興盡乃返。其一絕雲：\"一風點破碧落界，八面展盡虛無天。也樓長嘯海波闊，今夕何夕吾其仙。\"","sortOrder":10},
  {"id":"s_work_tddn_19_11","chapterId":"ch_work_tddn_19","text":"○薰風聯句","sortOrder":11},
  {"id":"s_work_tddn_19_12","chapterId":"ch_work_tddn_19","text":"唐文宗詩曰：\"人皆苦炎熱，我愛夏日長。\"柳公權續雲：\"薰風自南來，殿閣生微涼。\"或者惜其不能因詩以諷，雖坡翁亦以為有美而無箴，故為續之雲：\"一為居所移，苦樂永相忘。願言均此施，清陰分四方。\"餘謂柳句正所以諷也。蓋薰風之來，惟殿閣穆清高爽之地始知其涼。而征夫耕叟，方奔馳作勞，低垂喘汗於黃尘赤日之中，雖有此風，安知所謂涼哉？此與宋玉對楚王曰\"此謂大王之風耳，庶人安得而共之者\"同意。","sortOrder":12},
  {"id":"s_work_tddn_19_13","chapterId":"ch_work_tddn_19","text":"○漢唐二祖少恩","sortOrder":13},
  {"id":"s_work_tddn_19_14","chapterId":"ch_work_tddn_19","text":"漢高祖與項羽戰於彭城，大败，势甚急，跋魯元公主、惠帝弃之。夏侯婴為收載行，高祖怒，欲殺婴者十餘。借使高祖一時事急，不能存二子而弃之，他人能為收載，豈不幸甚？方當德之，何至怒而欲斬之乎？","sortOrder":14},
  {"id":"s_work_tddn_19_15","chapterId":"ch_work_tddn_19","text":"唐高祖起兵汾晉時，建成、元吉、楚哀王智雲，皆留河東護家。隋購之急，建成、元吉能間道赴太原，而智雲以幼不能逃，為吏所誅。亦豈不能少缓須臾，以須其至，而後起兵哉？","sortOrder":15},
  {"id":"s_work_tddn_19_16","chapterId":"ch_work_tddn_19","text":"二祖皆創業之君，而於父子之義，其薄若此，豈圖大事者，不暇顧其家乎？彼唐祖者，直墮世民之計，猶可恕也，若漢祖則杯羹之事，尚忍施之乃翁，何有於兒女哉？","sortOrder":16},
  {"id":"s_work_tddn_19_17","chapterId":"ch_work_tddn_19","text":"○《史記》無燕昭筑台事","sortOrder":17},
  {"id":"s_work_tddn_19_18","chapterId":"ch_work_tddn_19","text":"王文公詩雲：\"功謝萧規慚漢第，恩從隗使愧燕台。\"然《史記》止雲：\"為隗改筑宮而師事之。\"初無\"台\"字。而李白詩有\"何人為筑黃金台\"之語，吳虎臣《漫錄》，以此為據。","sortOrder":18},
  {"id":"s_work_tddn_19_19","chapterId":"ch_work_tddn_19","text":"按《新序》、《通鑒》亦皆雲\"筑宮\"，不言\"台\"也。然李白屢慣用黃金台事，如\"誰人更埽黃金台\"，\"燕昭延郭隗，遂筑黃金台\"，\"埽洒黃金台，招邀廣平客\"，\"如登黃金台，遙謁紫霞仙\"，\"侍宴黃金台，傳觴青玉案\"。杜甫亦有\"楊梅結義黃金台\"，\"黃金台貯賢俊多\"。柳子厚亦雲：\"燕有黃金台，遠致望諸君。\"《白氏六帖》有：\"燕昭王置千金於台上，以延天下士，謂之黃金台。\"此語唐人相承用者甚多，不特本於白也。","sortOrder":19},
  {"id":"s_work_tddn_19_20","chapterId":"ch_work_tddn_19","text":"又按《唐文粹》，有皇甫松《登郭隗台》詩。又梁任《述異記》：\"燕昭為郭隗筑台，今在幽州燕王故城中。土人呼賢士台，亦為招賢台。\"然則必有所謂台矣。後漢孔文舉《論盛孝章書》曰：\"昭筑台以延郭隗。\"然皆無黃金字。宋鮑照《放歌行》雲：\"豈伊白屋賜，將起黃金台。\"然則黃金台之名，始見於此。李善註引王隱《晉書》：\"段匹讨石勒，屯故燕太子丹黃金台。\"又引《上穀郡圖經》曰：\"黃金台在易水東南十八里，昭王置千金台上，以延天下士。\"且燕台事多以為昭王，而王隱以為燕丹，何也？餘後見《水經註》雲：\"固安縣有黃金台，耆舊言昭王禮賢，廣延方士，故修建下都，馆之南陲。燕昭創於前，子丹踵於後\"雲雲，以此知王隱以為燕丹者，蓋如此也。","sortOrder":20},
  {"id":"s_work_tddn_19_21","chapterId":"ch_work_tddn_19","text":"○《孟子》三宿出晝","sortOrder":21},
  {"id":"s_work_tddn_19_22","chapterId":"ch_work_tddn_19","text":"高郵有老儒黃彦知謂：\"孟子去齊，三宿而出晝。讀如晝夜之晝，非也。《史記·田单傳》載：'燕初入齊，聞晝邑之人王賢。'劉熙註雲：'齊西南近邑，音獲。'故孟子三宿而出，時人以為濡滯也。\"此說甚新而有據。然予觀《說苑》，則以為蓋邑人王。且齊有蓋大夫王歡（《公孫丑》下），而陳仲子兄食采於蓋，其入萬鐘（《滕文公》下），則齊亦自有蓋邑，又與晝邑不同矣。《通鑒》晝音，司馬康釋音胡卦切，亦曰西南近邑，复不音獲，何耶？","sortOrder":22},
  {"id":"s_work_tddn_19_23","chapterId":"ch_work_tddn_19","text":"○方大猷獻屋","sortOrder":23},
  {"id":"s_work_tddn_19_24","chapterId":"ch_work_tddn_19","text":"楊駙馬賜第清湖，巨董宋臣領營建之事，遂拓四旁民居以廣之。其間最逼近者，莫如太學生方大猷之居。意其必雄據，未易與語。一日，具禮物往訪之。方延入坐，未敢有請，方遽雲：\"今日內轄相訪，得非以小屋近牆欲得之否？\"愕不复對，方徐曰：\"內轄意謂某太學生，必將梗化，所以先蒙見及，某便當首獻作倡。\"就案即書契與之。以成契奏知，穆陵大喜，视其直數倍酬之。方作表謝，有雲：\"普天之下，莫非王土；一毫以上，悉出君恩。\"（上《毛詩》，下東坡《謝表》，併全句）自此擢第登朝，皆由此径而梯焉。","sortOrder":24},
  {"id":"s_work_tddn_19_25","chapterId":"ch_work_tddn_19","text":"○長生酒","sortOrder":25},
  {"id":"s_work_tddn_19_26","chapterId":"ch_work_tddn_19","text":"穆陵晚年苦足弱，一日經筵，宣諭贾師憲曰：\"聞卿有長生酒甚好，朕可飲否？\"贾退，遂修製具方併進，亦不過用川乌、牛膝等數味耳。內轄李忠辅適在旁，奏曰：\"藥性涼燥未可知，容臣先嘗，然後取旨進御。\"嫉之者轉聞於贾，贾深衔之，而未有以發也。","sortOrder":26},
  {"id":"s_work_tddn_19_27","chapterId":"ch_work_tddn_19","text":"先是北關劉都仓，家富無嗣，嘗立二子。劉先死，長者欲逐其後立子，於是托其所親檢議所吏劉炳百萬缗，介謝堂節使，轉求聖旨下天府逐之，至是已涉數歲，贾始知之，時鹹淳初年也。遂嗾其出子，以為李忠辅伪作聖旨，訟之於官，詞雖不及謝，而謝甚窘懼，於是以實訴之於贾，贾笑曰：\"節度無慮。\"越日，則忠辅追毀遷謫之命下，以實非其罪也，蓋師憲借此以報其嘗藥之忿耳。","sortOrder":27},
  {"id":"s_work_tddn_19_28","chapterId":"ch_work_tddn_19","text":"○开運靖康之禍","sortOrder":28},
  {"id":"s_work_tddn_19_29","chapterId":"ch_work_tddn_19","text":"靖康之禍，大率與开運之事同。一時紀載雜書極多，而最無忌憚者，莫若所謂《南燼紀聞》。其說謂出帝之事，欧公本之王淑之私史。淑本小吏，其家為出帝所殺，遁入契丹。洎出帝黃龍之遷，淑時為契丹諸司，於是文移郡縣，故致其飢寒，以逞宿怨，且述其幽辱之事，書名《幽懿錄》，比之周幽、衛懿。然考之五代新舊史，初無是說，安知非托子虛以欺世哉？其妄可見矣。","sortOrder":29},
  {"id":"s_work_tddn_19_30","chapterId":"ch_work_tddn_19","text":"《南燼》言二帝初遷安肅軍，又遷雲州，又遷西江州，又遷五國城，去燕凡三千八百餘里，去黃龍府二千一百里，其地乃李陵戰败之所。後又遷西均從州，乃契丹之移州。今以當時他書考之，其地里遠近，皆大缪不經，其妄亦可知。且謂此書乃阿計替手錄所申金國之文，後得之金國貴人者。又雲：\"阿計替本河北棣州民，陷金。自東都失守，金人即使之隨二帝入燕，又使同至五國城，故首尾備知其詳。\"及考其所載，則無非二帝胸臆不可言之事，不知阿計替何從知之。且金人之情多疑，所至必易主者守之，亦安肯使南人終始追隨乎？且阿計替於二帝初無一日之恩，何苦毅然歷险阻，犯嫌疑，極力保護而不舍去。且二帝方在危亡哀痛之秋，何暇父子賦詩為樂，阿計替又何暇筆之書乎？此其缪妄，固不待考而後見也。意者，為此書之人，必宣政間不得志小人，造為凌辱猥之事而甘心焉。此禽獸之所不忍為，尚忍言之哉。餘懼夫好奇之士，不求端末而輕信其言，故書以祛後世之惑雲。","sortOrder":30},
  {"id":"s_work_tddn_19_31","chapterId":"ch_work_tddn_19","text":"○近世名医","sortOrder":31},
  {"id":"s_work_tddn_19_32","chapterId":"ch_work_tddn_19","text":"近世江西有善医號嚴三點者，以三指點間知六脈之受病，世以為奇，以此得名。餘按诊脈之法，必均調自己之息，而後可以候他人之息。凡四十五動為一息，或過或不及，皆為病脈。故有二败、三遲、四平、六數、七極、八脱、九死之法。然則察脈固不可以仓卒得之，而况三點指之間哉？此餘未敢以為然者也。或謂其別有觀形察色之術，姑假此以神其術，初不在脈也。","sortOrder":32},
  {"id":"s_work_tddn_19_33","chapterId":"ch_work_tddn_19","text":"紹興間，王繼先號王医師，馳名一時。繼而得罪，押往福州居住。族叔祖宮教，時赴長沙ヘ，素識其人，適邂逅旅舍，小酌以慰勞之，因求察脈。王忽愀然曰：\"某受知既久，不敢不告。脈證頗異，所謂脈病人不病者，其應當在十日之內，宜亟反轅，尚可及也。\"因泣以別。時宮教康強無疾，疑其為妄，然素信其術，於是即日回轅。仅至家數日而殂，亦可謂異矣。","sortOrder":33},
  {"id":"s_work_tddn_19_34","chapterId":"ch_work_tddn_19","text":"又嘗聞陳體仁端明雲：\"紹熙間，有医邢氏，精藝絕異。時韓平原知閣門事，將出使，俾之诊脈，曰：'和平無可言，所可忧者，夫人耳。知閣回轺日，恐未必可相見也。'韓妻本無疾，怪其妄誕不倫，然私忧之。洎出疆甫數月，而其妻果殂。又朱丞相勝非子婦偶小疾，命视之，邢曰：'小疾耳，不藥亦愈。然自是不宜孕，孕必死。'其家以為狂言。後一歲，朱婦得男，其家方有抱孫之喜，未弥月而婦疾作。急遣召之，堅不肯來曰：'去歲已嘗言之，势無可療之理。'越宿而婦果殂。\"餘謂古今名医多矣，未有察夫脈而知妻死，未孕而知產亡者，呜呼！神矣哉！","sortOrder":34},
  {"id":"s_work_tddn_19_35","chapterId":"ch_work_tddn_19","text":"○前辈知人","sortOrder":35},
  {"id":"s_work_tddn_19_36","chapterId":"ch_work_tddn_19","text":"前辈名公鉅人，往往有知人之明。如馬尚書亮之於呂許公、陳恭公，曾諫議致尧之於晏元獻，呂許公之於文潞公，夏英公之於庞穎公，皆自布衣小官時，即許以元宰之貴，蓋不可一二數。初非有袁、李之術，特眼力高，閱人多故爾。史傳所載，以為名談。","sortOrder":36},
  {"id":"s_work_tddn_19_37","chapterId":"ch_work_tddn_19","text":"近世如史忠獻弥遠、趙忠肅方亦未易及。忠獻當國日，待族党加嚴。猶子嵩之子申，初官棗陽戶曹，方需遠次，適乡里有佃客邂逅致死者，官府連逮急甚，欲求援於忠獻，而莫能自通，遂夤緣轉聞，因得一見。留飯終席，不敢發一語。忽問：\"何不赴棗陽闕？\"以尚需次對，忠獻曰：\"可亟行，當作書與退翁矣。\"（陳賅時為京西阃）子申拜謝，因及前事，公曰：\"吾已知之，第之官勿慮也。\"公平昔嚴毅少言，遂謝而退。少間，公元姬林夫人因扣之，公曰：\"勿輕此子，異日當據我榻也。\"其後信然。又趙葵南仲通判庐州日，翟朝宗方守郡，公素不樂之，遂千堂易合入闕。俟呼召於賓庑候見者數十人，皆謝去，獨召兩都司及趙延入小閣會食。且出兩金盒，貯龍涎、冰腦，俾坐客隨意之。次至趙，即舉二合盡投炽炭中，香霧如雲，左右皆失色。公亟索飯送客，命大程官俾趙聽命客次，人皆危之。既而出札知滁州，填見闕命之任，而信公平生功業，實肇於此焉。又趙忠肅开京西阃日，鄭忠定丞相清之初任夷陵教官，首詣台參。鄭素癯瘁，若不勝衣，趙一見即異待之。延入中堂，出三子，俾執師弟子禮，局不自安，旁觀怪之。即日免衙參等禮以行，复命諸子餞之前途，且各出《雲萍錄》書之而去。他日，忠肅問諸郎曰：\"鄭教如何？\"長公答曰：\"清固清矣，恐寒薄耳。\"公笑曰：\"非爾所知。寒薄不失為太平宰相。\"後忠肅疾革，諸子侍侧，顧其長曰：\"汝讀書可喜，然不過監司太守。\"次語其仲范曰：\"汝須开阃，終無結果。三哥葵甚有福，但不可作宰相耳。\"時帳前提舉官趙勝，素與都統製扈再興之子不协，泣而言曰：\"萬一相公不讳，趙勝必死於扈再興之手，告相公保全。\"時京西施漕（上饒人，名未詳）偶在旁，公笑謂施曰：\"趙勝會做殿帥，扈再興安能殺之？\"其後所言，無一不验。","sortOrder":37},
  {"id":"s_work_tddn_19_38","chapterId":"ch_work_tddn_19","text":"○趙信國辭相","sortOrder":38},
  {"id":"s_work_tddn_19_39","chapterId":"ch_work_tddn_19","text":"淳祐甲辰，杜清獻范薨，遊清獻以拜右揆，趙葵南仲枢使、陳к子華參政，皆一時宿望。明年四月，遊相以大觀文奉內祠侍讀。既而趙公出督江淮、荆、襄、湖北軍馬，陳公以知院帥長沙，遂再相。鄭忠定清之、王伯大、吳潛，併為佥枢。乙巳，趙公兼江東帥、知建康、留鑰，趙希憲以禮書督府參贊兼江漕，淮帥丘山甫嶽仍兼參謀，且頒御筆雲：\"趙葵兼資文武，协辅國家，領使洪枢，视師戒道，權不可不专。申檄處置，貴合時宜，一應軍行調度，併聽便宜施行。所有恩數，眠儀宰路。\"公既威名夙著，邊陲晏然。中間屢乞結局，不允。明年，遣隨軍轉運舒泽民滋，入白廟堂，許令帶職入觐。公力辭召命，且雲：\"更當支吾一冬，來春解嚴，容歸田里。\"朝廷許之。","sortOrder":39},
  {"id":"s_work_tddn_19_40","chapterId":"ch_work_tddn_19","text":"明年，北軍大入，因复留行府，措置戰守焉。中書陆德舆載之轉對疏，以為：\"去歲泗州大捷，彼方丧胆落魄。今春淮水涨溢，欲來不可。涉冬而春，邊镇寧謐。近者駭言寇至，張大其說，或雲到儀真之境者，止五六十騎耳。\"趙公聞之，大不能堪，封章屢上，力辨此謗。且雲：\"今年北軍之入，系四大頭項：一曰察罕（河西人），二日大納，三日黑點，四曰別出古（併韃）。號四萬，實三萬餘；馬，人各三匹，約九萬匹。惟恐有勞聖慮，前後具奏，一則曰宽聖慮，二則曰宽忧顧。臣領舟師往來應敵，未嘗有一語張大。今觀陆德舆奏疏，實駭所聞。伏乞委德舆親至維扬，審是虛實。臣當躬率騎士，護送入城，便見真妄。\"於是朝廷以載之之言為過，遂為調停，寢其事焉。未幾，工部尚書徐清叟進故事，亦譏其辟屬之濫，趙公愈不自安。","sortOrder":40},
  {"id":"s_work_tddn_19_41","chapterId":"ch_work_tddn_19","text":"是歲閏二月，鄭忠定拜太師，趙公拜右相，所有督府，日下結局。遂差右司陳夢斗宣赴都堂治事，而陳辭以此貂之職不行，遂改差御藥謝昌祖往焉。夕郎趙以犬复有不肯書牍之意，事雖不行，而公之歸興不可遏矣。屢騰免牍，且引其父忠肅遺言不許入相之說以告，且雲：\"寧得罪以過嶺，難违訓以入朝。\"御筆不允，降宣趣行。時陆載之方居翰苑，以嫌不草詔，遂改命盧壮父武子為之。時趙公各通從官書，謂元科降簿內，尚餘新楮四百餘萬，銀絹度牒併不支動，且言决不可來之意。常時從官作宰相書，例有先生之稱，至是皆去之。獨趙汝騰茂實尚書答書雲：\"大丞相高風立懦，力疏辭榮。昔司馬公固遜密府，近崔清獻苦却宰席，書之史册，併公而三，甚盛休。\"而其微意亦可見也。","sortOrder":41},
  {"id":"s_work_tddn_19_42","chapterId":"ch_work_tddn_19","text":"公歸計既决，遂申朝庭，於三月二十四日散遣將士，取道歸伏田里。所有新除恩命，决不敢祗受。既而與告复召，然公終不來矣。至明年三月，御筆：\"趙葵恳辭相位，終始弗渝，使命趣召，亦既屢矣。奏陳確論，殆逾一期。朕眷倚雖切，不能強其從也。姑畀內祠，以便咨訪。可除觀文殿大學士、醴泉觀察使兼侍讀。\"後以疾丐外祠甚力，遂以特進判長沙，凡五辭，得請奉祠，径歸溧陽里第焉。蓋一時紳，方以理學科名相高，其视軍旅金穀等，為俗吏粗官。公能知幾勇退，不激不污，可謂善保功名者矣。","sortOrder":42},
  {"id":"s_work_tddn_19_43","chapterId":"ch_work_tddn_19","text":"○琴繁聲為鄭衛","sortOrder":43},
  {"id":"s_work_tddn_19_44","chapterId":"ch_work_tddn_19","text":"往時，餘客紫霞翁之門。翁知音妙天下，而琴尤精詣。自製曲數百解，皆平淡清越，灝然太古之遺音也。复考正古曲百餘，而異時官譜諸曲，多黜削無餘，曰：\"此皆繁聲，所謂鄭衛之音也。\"","sortOrder":44},
  {"id":"s_work_tddn_19_45","chapterId":"ch_work_tddn_19","text":"餘不善此，頗疑其言為太過。後讀《東漢書》，宋弘荐桓谭，光武令鼓琴，愛其繁聲，弘曰：\"荐谭者，望能忠正导主。而令朝廷耽悅鄭聲，臣之罪也。\"是蓋以繁聲為鄭聲矣。又《唐國史補》，於ν令客彈琴，其嫂知音，曰：\"三分中，一分筝聲，二分琵琶，全無琴韻。\"則新繁皆非古也。始知紫霞翁之說為信然。翁往矣，回思著唐衣，坐紫霞樓，調手製閒素琴（第一），作新製《琼林》、《玉树》二曲，供客以玻璃瓶插花，飲客以玉缸春酒（翁家酿名），笑語竟夕不休，猶昨日事。而人琴俱亡，冢上之木已拱矣，悲哉！","sortOrder":45},
  {"id":"s_work_tddn_19_46","chapterId":"ch_work_tddn_19","text":"○章氏玉杯","sortOrder":46},
  {"id":"s_work_tddn_19_47","chapterId":"ch_work_tddn_19","text":"嘉泰間，文莊章公以右史直禁林。時宇文紹節挺臣為司諫，指公為謝深甫子肅丞相之党，出知溫陵。既而公入為言官，遍歷三院，為中執法。時挺臣以京湖宣撫使知江陵府，入觐，除端明學士，径跻宥府。而挺臣懷前日之疑，次且不敢拜。文莊識其意，乃抗疏言：\"公論出一時之見，豈敢以報私憾，乞趣紹節就職。\"未幾，公亦登政地，相得甚歡。","sortOrder":47},
  {"id":"s_work_tddn_19_48","chapterId":"ch_work_tddn_19","text":"一日，宴聚，公出所藏玉杯侑酒，色如截肪，真於闐產也，坐客皆夸賞之。挺臣忽旁睨微笑曰：\"異哉！先肅悯公虛中使金日，嘗於燕山獲玉盤，径七寸餘，瑩絜無纖瑕，或以為宣和殿故物，平日未嘗示人，今觀此色泽殊近似之。\"於是坐客鹹願快睹，趣使取之。既至，則玉色製作無毫發異，真合璧也。蓋元為一物，中分為二耳。眾客驚詫，以為幹钅耶之合不足多也。公因舉杯以赠挺臣，而挺臣复欲以盤奉公，相與遜讓者久之，不决。時李璧季章在坐，起曰：\"以盤足杯者，於事為順，佥書不得辭也。\"公遂謝而藏之，以他物為報。餘髫侍二親，常於元毖舅氏膝下聞此事，惜不一見之。其後聞為有力者負之而去，莫知所終。","sortOrder":48},
  {"id":"s_work_tddn_19_49","chapterId":"ch_work_tddn_19","text":"○二張援襄","sortOrder":49},
  {"id":"s_work_tddn_19_50","chapterId":"ch_work_tddn_19","text":"襄、樊自鹹淳丁卯被围以來，生兵日增。既筑鹿門之後，水陆之防日密。又筑白河、虎頭及鬼關於中，以梗出入之道。自是孤城困守者凡四五歲，往往扼關隘不克進，皆束手视為弃物。所幸城中有宿储可堅忍，然所乏鹽、薪、布帛為急。時張漢英守樊城，募善泅者，置蠟書髻中，藏積草下，浮水而出。謂鹿門既筑，势須自荆、郢進援。既至隘口，守者見積草頗多，鉤致欲為焚爨用，遂為所獲，於是郢、邓之道复絕矣。","sortOrder":50},
  {"id":"s_work_tddn_19_51","chapterId":"ch_work_tddn_19","text":"既而荆阃移屯舊郢州，而諸帥重兵皆駐新郢及均州河口以扼要津。又重賞募死士，得三千人，皆襄、郢、西山民兵之驍悍善戰者。求將久之，得民兵部官張順、張貴（軍中號張貴為矮張），所謂大張都統、小張都統者，其智勇素為諸軍所服。先於均州上流名中水峪立硬寨，造水哨，輕舟百艘，每艘三十人，鹽一袋，布二百。且令之曰：\"此行有死而已，或非本心，亟去，毋败吾事。\"人人感激思奋。是歲五月，漢水方生，於二十二日，稍進团山下，越二日，又進高頭港口結方陣。各船置火槍、火炮、炽炭、巨斧、劲弩。夜漏下三刻，起碇出江，以紅燈為號。貴先登，順為殿，乘風破浪，径犯重围。至磨洪滩以上，敵舟布滿江面，無罅可入。鼓勇乘銳，凡斷鐵ㄌ、攒弋數百，屯兵雖眾，盡皆披靡避其鋒。轉戰一日二十餘里，二十五日黎明，乃抵襄城。城中久絕援，聞救至，人人踴躍，氣百倍。及收軍點视，則獨失張順，軍中為之短氣。越數日，有浮尸溯流而上。被介胄，執弓矢，直抵浮梁，视之，順也。身中四槍六箭，怒氣勃勃如生，軍中驚以為神，結冢斂葬，立廟祀之。然自此围益密，水道連鎖數十里，以大木下撒星樁，雖魚鱉不得度矣。","sortOrder":51},
  {"id":"s_work_tddn_19_52","chapterId":"ch_work_tddn_19","text":"外势既蹙，貴乃募壮士至夏節使軍求援。得二人，能伏水中數日不食，使持書以出。至樁若柵，則腰鋸斷之。径達夏軍，得報而還。許以軍五千駐龍尾洲以助夹击。刻日既定，貴提所部軍點视登舟，失帳前親隨一人，乃宿來有過遭撻者。貴驚叹曰：\"吾事泄矣！然急出，或未及知耳。\"乃乘夜鼓噪，冲突斷ㄌ，破围前進，眾皆辟易。既度险要之地，時夜半天黑，至小新城，敵方覺，遂以兵數萬邀击之。貴又為無底船百餘艘，中立旗幟，各立軍士於兩舷以誘之，敵皆競躍以入，溺死者萬餘，亦昔人未出之奇也。至鉤林滩，將近龍尾洲，遠望軍船櫛櫛，旗幟紛紜。貴軍皆喜躍，舉流星火以示之。軍船見火，皆前相迎，逮势近欲合，則來舟北軍也。蓋夏軍前二日，以風雨驚疑，退屯三十里矣。北軍蓋得逃卒之報，遂據洲上，以逸待勞。至是，既不為備，殺傷殆盡。貴身被數十創，力不支，遂為生得，至死不屈，此是歲十一月十七日夜也。北軍以四降卒舆尸至襄，以示援絕，且諭之降。呂帥文煥盡斬四卒，以貴附葬順冢，為立双廟，尸而祝之，以比巡、遠。明年正月十三日樊城破，三月十八日，襄陽降，此天意，非人力也。同時有武功大夫范大順者，與順、貴同入襄。及襄城降，仰天大呼曰：\"好漢誰肯降？便死也做忠義鬼。\"就所守地分自縊而死。又有右武大夫、馬軍統製牛富，樊城守御，立功尤多。城降之际，傷重不能步，乃就戰樓，觸柱數四，投身火中而死。","sortOrder":52},
  {"id":"s_work_tddn_19_53","chapterId":"ch_work_tddn_19","text":"此事親得之襄州、順化老卒，參之眾說，雖有微異，而大意則同。不敢以文害辭没其實，因直書之，以備異時之傳忠義者雲。","sortOrder":53},
  {"id":"s_work_tddn_20_1","chapterId":"ch_work_tddn_20","text":"●卷十九","sortOrder":1},
  {"id":"s_work_tddn_20_2","chapterId":"ch_work_tddn_20","text":"○嘉定寶玺","sortOrder":2},
  {"id":"s_work_tddn_20_3","chapterId":"ch_work_tddn_20","text":"贾涉為淮東製阃日，嘗遣都統司計議官趙拱往河北蒙古軍前議事。久之。拱歸，得其大將扑鹿花所獻\"皇帝恭膺天命之寶\"玉玺一座，併元符三年寶樣一册，及镇江府諸軍副都統製翟朝宗所獻寶檢一座，併繳進於朝。詔下禮部太常寺讨論受寶典禮，此嘉定十四年七月也。是歲十一月詔曰：\"乃者，山東、河北，連城慕義，殊方效順，肅奉玉寶來獻於京。质理溫純，篆刻精古。文曰'皇帝恭膺天命之寶'，暨厥圖册，登載燦然，實惟我祖宗之舊。繼獲玉檢，其文亦同，雲雲。天其申命用休，朕曷敢不承。其以來年元日，受寶於大慶殿。\"遂命奉安玉寶於天章閣，具奏告天地、宗廟、社稷。明年正月庚戌朔，御大慶殿受寶，大赦天下。應監司帥守，併許上表進貢稱贺。推恩文武官，各進一秩，大犒諸軍，三學士人併推恩有差。具命禮官裒集受寶本末，藏之秘閣。能文之士如朱中美、錢、謝耘等數十人，作為頌詩，以鋪張盛美。四方士子，骈肩累足而至，學舍至無所容。蓋當國者，方粉飾太平，故一時恩賞，實為冒濫。","sortOrder":3},
  {"id":"s_work_tddn_20_4","chapterId":"ch_work_tddn_20","text":"有士子作書貽葛司成雲：\"竊惟國學，天子储養卿相之地。中興以來，冠帶雲集，英俊日盛，可以培植國家無疆之基。自开禧之初，迄更化之後，天下公論，不歸於上之人，多歸於兩學之士。凡政令施行之舛，除拜黜陟之偏，禁庭私謁之過，涉於國家盛衰之計，公論一鳴，兩學雷動。天子虛己以聽之，宰相俯首而信之，天下傾心而是之。由是四方萬里，或聞兩學建議，父告其子，兄告其弟，師告其徒，必得其說，互相歆艳，謂不負所學，豈不取重於當世哉？邇來寶玺上進，皇上以先皇舊物，聖子神孫膺此天命之寶，慰答在天之靈，不得不侈烈祖之珍符，為今日之榮觀也。草茅之士，興起於山林寂寞之濱，形容於篇章歌頌之末，其誠可念。若兩學之士，榮進素定，固當自信其所學，自勉其所守，安於義命可也。紛紛而來，不恤道路風霜之惨，喁喁相告，朱朱相呼。僥幸恩賞之蕃庶，冀望非常之盛典。甚至千數百人，饕餮廪粟，枕籍斋舍，廉恥俱丧，了無靦顏，或挺身獻頌，或走謁朝貴，小小利害，其趨若市。公論將何以賴，天下將何以望哉？傳之三辅，豈不貽笑於識字之程大卿乎？傳之遠方，豈不貽笑於任子之胡尚書兄弟乎？傳之邊陲，豈不貽笑於異類之趙珙乎？傳之地下，豈不貽笑於舊尹之趙尚書乎？三十年忠谠之論，一日埽地，三十年流傳之稿，一焚可盡矣，假使聖朝頒曠荡之恩，一视天下之士，通行免舉，諉有可說。苟惟兩學之士，獨沾免舉之渥，則非特柄國者，欲鉗天下公論之口，而三學之士，適自鉗其口耳，豈不惜哉！恭惟大司成天下英俊之師表，願以公論所在，誨之以安義命而知進退，勉之以崇名節而黜浮競。爵祿，天下之公器也，豈顽钝亡恥者可攫也。《傳》曰：'士之致遠先器識。'器識卑下，則它日立朝，必無可觀者矣。舍其所重，就其所輕，喑其所長，鳴其所短，三尺之童，亦羞為之。昔陳東以直言而死，今李誠之以守城而死，二公皆學校之士也，足以為萬世之名節。以今日一免解之輕，遽失吾萬世公論之重，必無有如陳之直言、李之忠節者矣。元氣能有幾邪？願大司成續而寿之。\"","sortOrder":4},
  {"id":"s_work_tddn_20_5","chapterId":"ch_work_tddn_20","text":"既而宗室猶以推賞太輕，至揭榜朝天門雲：\"寶玺，國之重器也，興衰系焉；同姓，國之至親也，休戚生焉。靖康之际，國步多難。我祖我父，一心王室，不死於兵，則死於敵，不死於敵，則死於盜賊；若子若孫，呼天號地，此恨難磨。苟存喘息於東南，期雪我祖我父萬古之痛而後已。仰惟今日，故疆复矣，寶镇歸矣，此正酾酒弔魂、慰生勞死之秋，其為踴躍，曷啻三百。聖恩汪，周遍寰宇。監司郡守，奉表推恩，文武兩學，通籍免解，侍班選人，特與趱放。不惟文武百僚轉官，而未铨任子，亦與轉官；不惟特科無及者出官，而三十年特科五等人亦出官。加恩異姓，悉逾覃霈。即彼验此，凡同姓一請者，便可援以補官，再請者，亦可援以廷對。今散恩誕布宗子，已請者各免本等解一次，四舉者補下州文學，五舉者補迪功郎。由是而觀，不惟親疏無別，而異姓反優於同姓，天子之子孫，反不若公卿大夫之子孫。痛念昔者，是玺之亡，宗室與之俱亡，而異姓自若也。今日是玺之得，推恩異姓，种种優渥，而同姓則反薄其恩。忧則與之同忧，喜則不與之同喜，人情豈如是乎？况比年科甲，已非若祖宗之優，今日恩霈，又非若祖宗之厚。凡我國家，有一毫恩及同姓者，日以削，王家枝葉，剪伐弗恤，是皆權要之私憾耳。投鼠忌器，何忍於斯？興言及此，涕淚交垂，識者旁觀，寧不感動？中興以來，推恩同姓，止有一舉兩舉之分，初無四舉五舉之別，止有將仕免省之異，初無文學迪功之名。累朝是守，按為典章。經今百年，未偿辄变。今來五舉與迪功郎，四舉與文學，其视免省，何啻倍蓰。而省试仅以六十五名為額，來歲以免解到省者，其數甚多。是雖當免舉，實殿舉也，殆與其他免解受實惠者，萬萬不侔。我辈當念祖父淪亡之痛，协心戮力，仰扣廟堂，體念同姓，舉行舊典。勿以事已定而沮其志，勿以天聽高而泯其說。使我辈得以慰祖父九地之靈，而子孫得蒙國家無窮之福，宗英其念之。\"是時不轉官賞者，朝中士惟陳貴謙、陳宓。在學不願推恩者，茅匯征一人而已。","sortOrder":5},
  {"id":"s_work_tddn_20_6","chapterId":"ch_work_tddn_20","text":"按：\"恭膺天命之寶\"，真宗初即位所製，其後每朝效之，易世則藏之。靖康之变，金人取玉寶十有四以去，此寶居其二焉。其一則哲宗元符三年所製，其一則钦宗靖康元年所製也。及金人內亂南遷，寶玉多為蒙古所取。當時識者，謂此物不宜鋪張。是以參政鄭昭先有可弔不可贺之論。時學士院權直盧祖皋草詔，乃径用元符故事，殊不知哲宗以元符元年進寶，至三年崩，識者忧之。今以嘉定十五年受寶，至十七年閏八月而寧宗崩。事有適相符者，敢併紀於此雲。","sortOrder":6},
  {"id":"s_work_tddn_20_7","chapterId":"ch_work_tddn_20","text":"○鬼車鳥","sortOrder":7},
  {"id":"s_work_tddn_20_8","chapterId":"ch_work_tddn_20","text":"鬼車，俗稱九頭鳥。陆長源《辨疑志》又名渠逸鳥。世傳此鳥昔有十頭，為犬噬其一，至今血滴人家，能為灾咎。故聞之者，必叱犬滅燈，以速其過。泽國風雨之夕，往往聞之。六一翁有詩，曲盡其悲哀之聲，然鮮有睹其形者。淳熙間，李寿翁守長沙日，嘗募人捕得之。身圓如箕，十ㄕ環簇。其九有頭，其一獨無，而鮮血點滴，如世所傳。每ㄕ各生兩翅，當飛時，十八翼霍霍競進，不相為用，至有爭拗折傷者。","sortOrder":8},
  {"id":"s_work_tddn_20_9","chapterId":"ch_work_tddn_20","text":"景定間，周漢國公主下降，賜第嘉會門之左，飛樓复道，近接禁御。貴主嘗得疾，一日，正晝，忽有九頭鳥踞主第捣衣石上，其状大抵類野凫而大如箕。哀鳴啾啾，略不見憚，命弓射之，不中而去。是夕主薨，信乎其為不祥也，此餘親聞之副雲。","sortOrder":9},
  {"id":"s_work_tddn_20_10","chapterId":"ch_work_tddn_20","text":"○蘭亭詩","sortOrder":10},
  {"id":"s_work_tddn_20_11","chapterId":"ch_work_tddn_20","text":"永和蘭亭禊飲集者四十二人，人各賦詩，自右軍而下十一人，各成兩篇，郄曇、王丰而下十五人，各成一篇，然亦不過四言兩韻，或五言兩韻耳。詩不成而罰觥者十有六人，然其間如王獻之辈，皆一世知名之士，豈終日不能措一辭者？黃彻謂古人持重自惜，不輕率爾，恐貽久遠之譏，故不如不賦之為愈耳。餘則以為不然，蓋古人意趣真率，是日適無興不作，非若後世喋喋然，強聒於杯酒間以為能也。史載獻之嘗與兄徽之、操之，俱詣謝安，二兄多言，獻之寒溫而已。既出，客問優劣，安曰：\"小者佳。吉人之辭寡，以其少言，故雲。\"今王氏父子群從鹹集，而獻之詩獨不成，豈不平日靜退之故邪？","sortOrder":11},
  {"id":"s_work_tddn_20_12","chapterId":"ch_work_tddn_20","text":"○著書之難","sortOrder":12},
  {"id":"s_work_tddn_20_13","chapterId":"ch_work_tddn_20","text":"著書之難尚矣。近世諸公，多作考異、證誤、糾缪等書，以雌黃前辈，該贍可喜，而亦互有得失，亦安知無議其後者。程文簡著《演繁露》，初成，高文虎炳如嘗假觀，稱其博贍。虎子似孫續古，時年尚少，因竊窥之。越日，程索回元書，續古因出一帙曰《繁露詰》，其間多文簡所未載，而辨證尤詳。文簡雖盛賞之，而心實不能堪。或議其該洽有餘，而輕薄亦太過也。","sortOrder":13},
  {"id":"s_work_tddn_20_14","chapterId":"ch_work_tddn_20","text":"雖溫公著《通鑒》，亦不能免此。若漢景帝四年內，日食皆誤書於秋夏之交，甚至重复書楊彪賜之子於一年之間。至朱文公修《綱目》，亦承其誤而不自覺，而《綱目》之誤尤甚。唐肅宗朝，直脱二年之事。又自武德八年以後，至天祐之季，甲子併差。蓋紀載編摩，條目浩博，势所必至，無足怪者。","sortOrder":14},
  {"id":"s_work_tddn_20_15","chapterId":"ch_work_tddn_20","text":"劉羲仲，道原之子也。道原以史學自名，義仲世其家學，摘欧公《五代史》之訛說，為《糾谬》一書，以示坡公，公曰：\"往歲，欧公著此書初成，荆公謂餘曰：'欧公修《五代史》而不修《三國志》，非也，子盍為之乎？'餘因辭不敢當。夫為史者，網羅數千百載之事，以成一書，其間豈無小得失邪？餘所以不敢當荆公之托者，正畏如公之徒，掇拾於先後耳。\"","sortOrder":15},
  {"id":"s_work_tddn_20_16","chapterId":"ch_work_tddn_20","text":"《揮麈錄》雲：\"蜀人吳縝初登第，請於文忠，願預官屬，公不許，因作《糾誤》。\"豈別一書邪？","sortOrder":16},
  {"id":"s_work_tddn_20_17","chapterId":"ch_work_tddn_20","text":"○安南國王","sortOrder":17},
  {"id":"s_work_tddn_20_18","chapterId":"ch_work_tddn_20","text":"安南國王陳日者，本福州長樂邑人，姓名為謝升卿。少有大志，不屑為舉子業。間為歌詩，有雲：\"池魚便作鵬化，燕雀安知鸿鵠心？\"類多不羁語。好與博徒豪俠遊，屢竊其家所有，以資妄用，遂失愛於父。其叔乃特異之，每加回護。會兄家有姻集，羅列器皿頗盛，至夜，悉席卷而去，往依族人之仕湖湘者。至半途，呼渡，舟子所須未滿，殴之，中其要害。舟遽離岸，謝立津頭以俟。聞人言，舟子殂，因变姓名逃去。至衡，為人所捕。適主者亦閩人，遂陰縱之。至永州，久而無聊，授受生徒自給。","sortOrder":18},
  {"id":"s_work_tddn_20_19","chapterId":"ch_work_tddn_20","text":"永守林{巴土}，亦同里，頗善遇之。居無何，有邕州永平寨巡檢過永，一見奇之，遂挟以南。寨居邕、宜間，與交趾鄰近。境有弃地數百里，每博易，則其國貴人皆出為市。國相乃王之婿，有女亦從而來，見謝美少年，悅之，因請以歸。令试舉人，謝居首選，因納為婿。其王無子，以國事授相。相又昏老，遂以屬婿，以此得國焉。自後，屢遣人至閩訪其家，家以為事不可料，不與之通，竟以歲久難以訪問返命焉。其事得之陳合惟善佥枢雲。","sortOrder":19},
  {"id":"s_work_tddn_20_20","chapterId":"ch_work_tddn_20","text":"○贾氏前兆","sortOrder":20},
  {"id":"s_work_tddn_20_21","chapterId":"ch_work_tddn_20","text":"贾師憲柄國日，嘗夢金紫人相迎逢，旁一客謂之曰：\"此人姓鄭，是能製公之死命。\"時大鄭師望方用事，意疑其人，且姓與夢合，於是竟以他故擯逐之。及魯港失律，遠謫南荒，就紹興差官押送，則本州推官沈士圭，攝山陰尉鄭虎臣也。鄭，武弁，嘗為贾所惡，適有是役，遂甘心焉。","sortOrder":21},
  {"id":"s_work_tddn_20_22","chapterId":"ch_work_tddn_20","text":"贾臨行，置酒招二人，歷言前夢，且祈哀徼芘雲：\"向在維扬日，襄、邓間有人善相。一日來，值其跣臥，因叹惜再三。私謂客曰：'相公貴極人臣，而足心肉陷，是名猴形，恐異時不免有萬里行耳。'是知今日竄逐之事，雖滿盈招咎，蓋亦有數存焉。\"及抵清漳之次日，泣謂押行官曰：\"某夜來夢大不祥，才離此地，必死無疑，幸保全之。\"遂連三日，逗遛不行，而官吏追促之。離城五里許，小泊木綿庵，竟以疾殂，或謂虎臣有力焉。","sortOrder":22},
  {"id":"s_work_tddn_20_23","chapterId":"ch_work_tddn_20","text":"先是，林佥枢存孺父為贾所擯，謫之南州，道死於漳。漳有富民，蓄油杉甚佳。林氏子弟欲求，而价窮不可得，因撫其木曰：\"收取，收取，待留與贾丞相自用。\"蓋一時憤恨之語耳。至是，郡守與之經營，竟得此物以斂，可謂異矣。死生禍福，皆有定數，不可幸免也如此，事親聞之沈士圭雲。","sortOrder":23},
  {"id":"s_work_tddn_20_24","chapterId":"ch_work_tddn_20","text":"○明堂不乘辂","sortOrder":24},
  {"id":"s_work_tddn_20_25","chapterId":"ch_work_tddn_20","text":"度宗鹹淳壬子歲，有事於明堂。先一夕，上宿太廟。至晚，將登辂，雨忽骤至。大禮使贾似道欲少俟，而攝行宮使帶御器械胡顯祖，請用开禧之例，却辂乘輦，上性躁急，遽從之。閣民吏曹垓，竟引攝禮部侍郎陳伯大、張志立奏中嚴外辦，請上服通天冠，絳紗袍，乘逍遙輦入和寧門。似道以為既令百官常服從駕，而上乃盛服，不可。顯祖謂泥路水深，决難乘辂。既而雨霁，則上已乘輦而歸矣。既肆赦，似道即上疏出關，再疏言：\"嘉定間，三日皆雨，亦复登辂。用嘉定例尚放淳熙，用开禧之例，則是韓胄之所為。深恐萬世之下，以臣與胄等。\"於是必欲求去，而伯大、志立亦待罪，顯祖竟從追削，送饒州居住，曹垓黥斷，其子大中為閣職，亦降謫江陰。顯祖本太常寺禮直官，以女為美人，故骤遷至此雲。未幾，有旨，美人胡氏，追毀內命婦告，送妙净寺削發為尼。然踐刍忌器，或以為過。似道凡七疏辭位，竟出居湖曲賜第，用呂公著、乔行簡典故焉。按淳熙乙亥，明堂致斋太廟，而大雨終日。夜，有旨：\"來早更不乘辂，止用逍遙子詣文德殿致斋。應儀仗排立併放免。從駕官常服以從。\"大禮使趙雄密令勿放散，上聞之曰：\"若不霁，何施面目？\"雄語人曰：\"不過罪罢出北關耳。\"黃昏後雨止，中夜，內侍思恭傳旨御史台、閣門、太堂寺，仍舊乘辂，應有合行排辦事件，疾速施行。十五日拂明雨止，乘辂而歸。蓋自有典故，清切如此。而顯祖不知出此，乃妄援开禧韓胄當國時故事，故時相怒之尤甚也。","sortOrder":25},
  {"id":"s_work_tddn_20_26","chapterId":"ch_work_tddn_20","text":"○贾氏園池","sortOrder":26},
  {"id":"s_work_tddn_20_27","chapterId":"ch_work_tddn_20","text":"景定三年正月，詔以魏國公贾似道有再造功，命有司建第宅家廟，贾固辭，遂以集芳園及缗錢百萬賜之。園故思陵舊物，古木寿藤，多南渡以前所植者。積翠回抱，仰不見日，架廊叠磴，幽眇逶迤，極其營度之巧。猶以為未也，則隧地通道，抗以石梁。旁透湖濱，架百餘楹。飛樓層台，涼亭燠馆，華邃精妙。前揖孤山，後據葛嶺，兩桥映帶，一水橫穿，各隨地势以構筑焉。堂榭有名者曰蟠翠（古松）、雪香（古梅）、翠巖（奇石）、倚繡（雜花）、挹露（海棠）、玉蕊（琼花茶コ）、清勝（假山），已上集芳舊物。高宗御扁\"西湖一曲\"、\"奇勋\"。理宗御書\"秋壑\"、\"遂初容堂\"。度宗御書\"初陽精舍\"、\"熙然台\"、\"砌台\"。山之椒曰\"無邊風月\"、\"見天地心\"。水之濱曰：\"琳琅步\"、\"歸舟\"、\"早船\"。通名之曰後樂園。四世家廟，則居第之左焉。廟有記，一時名士擬作者數十，獨取平舟楊公棟者刊之石。又以為未足，則於第之左數百步瞰湖作別墅，曰光漾閣、春雨觀、養樂堂、嘉生堂。千頭木奴，生意瀟然，生物之府，通名之曰養樂園。其旁則廖群玉之香月鄰在焉。又於西陵之外，树竹千挺，架樓臨之，曰秋水觀、第一春、梅坞、剡船亭，侧通謂之水竹院落焉。後复葺南山水樂洞，賜園有聲在堂、介堂、愛此、留照、獨喜、玉淵、漱石、宜晚，上下四方之宇諸亭，據勝专奇，殆無遺策矣。","sortOrder":27},
  {"id":"s_work_tddn_20_28","chapterId":"ch_work_tddn_20","text":"其後，志之郡乘，從而為之辭曰：\"園囿一也，有藏歌貯舞，流連光景者；有曠志怡神，蜉蝣尘外者；有澄想遐觀，運量宇宙，而遊特其寄焉者。嘻！使園囿常興而無废，天下常治而無亂，非後天下之樂而樂者其誰能？\"呜呼！當時為此語者，亦安知俯仰之間，遽有荒田野草之悲哉！昔陆務觀作《南園記》於中原極盛之時，當時勉之以抑畏退休。今贾氏當國十有六年，諛之者，惟恐不極其至，况敢幾微及此意乎？近世以詩弔之者甚眾，吳人湯益一詩，頗為人所稱雲：\"檀板歌殘陌上花，過牆荆棘刺簷牙。指揮已失鐵如意，賜予寧存玉辟邪。败屋春歸無主燕，废池雨產在官蛙。木綿庵外尤愁絕，月黑夜深聞鬼車。\"李彭老一絕雲：\"瑤房錦榭曲相通，能幾番春事已空。惆怅舊時吹笛處，隔窗風雨剝青紅。\"","sortOrder":28},
  {"id":"s_work_tddn_20_29","chapterId":"ch_work_tddn_20","text":"○子固類元章","sortOrder":29},
  {"id":"s_work_tddn_20_30","chapterId":"ch_work_tddn_20","text":"諸王孫趙孟堅字子固，號彝斋，居嘉禾之廣陳。修雅博識，善筆札，工詩文，酷嗜法書。多藏三代以來金石名跡，遇其會意時，雖傾囊易之不靳也。又善作梅竹，往往得逃禪、石室之妙，於山水為尤奇，時人珍之。襟度瀟爽，有六朝諸賢風氣，時比之米南宮，而子固亦自以為不歉也。東西薄遊，必挟所有以自隨。一舟橫陳，仅留一席為偃息之地，隨意左右取之，撫摩吟諷，至忘寢食。所至，識不識望之，而知為米家書畫船也。","sortOrder":30},
  {"id":"s_work_tddn_20_31","chapterId":"ch_work_tddn_20","text":"庚申歲，客輦下，會菖蒲節，餘偕一時好事者邀子固，各携所藏，買舟湖上，相與評賞。飲酣，子固脱帽，以酒發，箕踞歌《離骚》，旁若無人。薄暮，入西泠，掠孤山，舣棹茂树間。指林麓最幽處瞪目絕叫曰：\"此真洪穀子、董北苑得意筆也。\"鄰舟數十，皆驚駭絕叹，以為真謫仙人。","sortOrder":31},
  {"id":"s_work_tddn_20_32","chapterId":"ch_work_tddn_20","text":"異時，萧千巖之侄滚，得白石舊藏五字不損本《禊叙》，後歸之俞寿翁家。子固复從寿翁善价得之，喜甚，乘舟夜泛而歸。至之卞山，風作舟覆，幸值支港，行李衣衾，皆淹溺無餘。子固方被濕衣立淺水中，手持《禊帖》示人曰：\"《蘭亭》在此，餘不足介意也。\"因題八言於卷首雲：\"性命可輕，至寶是保。\"蓋其酷嗜雅尚，出於天性如此。後終於提轄左帑，身後有嚴陵之命。其帖後歸之悅生堂，今复出人間矣。噫！近世求好事博雅如子固者，豈可得哉！","sortOrder":32},
  {"id":"s_work_tddn_20_33","chapterId":"ch_work_tddn_20","text":"○陳用賓夢放翁詩","sortOrder":33},
  {"id":"s_work_tddn_20_34","chapterId":"ch_work_tddn_20","text":"陳觀國字用賓，永嘉勝士也。丙戌之夏，寓越，夢訪餘於杭。壁間有古畫數幅，嚴壑耸峭，竹树茂密，瀑飛絕，匯為大池。池中菡萏方盛开，一翁曳杖坐巨石上，仰瞻飛鶴翔舞。煙雲空中，仿佛有字數行，體雜章草。其詞曰：\"水聲兮激激，雲容兮茸茸，千松拱绿，萬荷凑紅。爰宅茲巖，以逸放翁。屹萬仞與世隔，峻一極而天通。予乃控野鶴，追冥鸿，往來乎蓬萊之宮。披海氛而一笑，以觀九州之同。\"旁一人指雲：\"此放翁詩也。\"用賓驚悟，亟書以見寄。詩語清古，非思想之所及，異哉！","sortOrder":34},
  {"id":"s_work_tddn_20_35","chapterId":"ch_work_tddn_20","text":"○漢以前驚蟄為正月節","sortOrder":35},
  {"id":"s_work_tddn_20_36","chapterId":"ch_work_tddn_20","text":"餘嘗讀班史《歷》，至周三月二日庚申驚蟄，而有疑焉。蓋周建子為歲首，則三月為寅，今之正月也。雖今歷法亦有因置閏而驚蟄在寅之時，然多在既望之後，不應在月初而言二日庚申也。及考《月令章句》，孟春以立春為節，驚蟄為中。又自危十度至壁八度，謂之豕韦之次，立春、驚蟄居之，衛之分野。自壁八度至胃一度，謂之降娄之次，雨水、春分居之，魯之分野。然後知漢以前，皆以立春為正月節，驚蟄為中，雨水為二月節，春分為中也。至後漢，始以立春、雨水、驚蟄、春分為序。《爾雅》，師古於驚蟄註雲：\"今日雨水，於夏為正月，周為三月。\"於雨水註雲：\"今日驚蟄，夏為二月，周為四月。\"蓋可見矣。","sortOrder":36},
  {"id":"s_work_tddn_20_37","chapterId":"ch_work_tddn_20","text":"《史記·歷書》，亦為孟春冰泮啟蟄。《左傳》，桓公五年，啟蟄而郊。杜氏註以為夏正建寅之月。疏引《夏小正》曰，正月啟蟄。故漢初啟蟄為正月中，雨水為二月節。及太初以後，更改氣名，以雨水為正月中，驚蟄為二月節，以至於今。由是觀之，自三代以至漢初，皆以驚蟄為正月中矣。又漢以前，穀雨為三月節，清明為三月中，亦與今不同。併見《前志》。","sortOrder":37},
  {"id":"s_work_tddn_20_38","chapterId":"ch_work_tddn_20","text":"○後夫人進御","sortOrder":38},
  {"id":"s_work_tddn_20_39","chapterId":"ch_work_tddn_20","text":"梁國子博士清河崔靈恩撰《三禮義宗》，其說博核。其中有後、夫人進御之說甚詳，謾摭於此，以助多聞雲。","sortOrder":39},
  {"id":"s_work_tddn_20_40","chapterId":"ch_work_tddn_20","text":"凡夫人進御之義，從後而下十五日遍。其法自下而上，象月初生，漸進至盛，法陰道也。然亦不必以月生日為始，但法象其義所知。其如此者，凡婦人陰道，晦明是其所忌。故古之君人者，不以月晦及望御於內。晦者陰滅，望者爭明，故人君尤慎之。《春秋傳》曰：\"晦淫惑疾，明淫心疾，以辟六氣。\"故不從月之始，但放月之生耳。其九嫔已下，皆九人而御，八十一人為九夕。世婦二十七人為三夕，九嫔九人為一夕，夫人三人為一夕，凡十四夕。後當一夕，為十五夕。明十五日則後御，十六日則後复御，而下亦放月以下漸就於微也。諸侯之御，則五日一遍。亦從下始，漸至於盛，亦放月之義。其御則從侄娣而迭為之御，凡侄娣六人當三夕，二媵當一夕，凡四夕。夫人专一夕為五夕，故五日而遍，至六日則還從夫人，如後之法。孤卿大夫有妾者，二妾共一夕，內子专一夕。士有妾者，但不得专夕而已，妻則专夕。凡九嫔以下，女御以上，未滿五十者，悉皆進御，五十則止。後及夫人不入此例，五十猶御。故《內則》雲：\"妾年未滿五十者，必與五日之御。\"則知五十之妾，不得進御矣。卿、大夫、士妻妾進御之法，亦如此也。","sortOrder":40},
  {"id":"s_work_tddn_20_41","chapterId":"ch_work_tddn_20","text":"○有丧不舉茶托","sortOrder":41},
  {"id":"s_work_tddn_20_42","chapterId":"ch_work_tddn_20","text":"凡居丧者，舉茶不用托，雖曰俗禮，然莫晓其義。或謂昔人托必有朱，故有所嫌而然，要必有所據。宋景文《雜記》雲：\"夏侍中薨於京師，子安期他日至馆中，同舍謁見，舉茶托如平日，眾頗訝之。\"又平園《思陵記》，載阜陵居高宗丧，宣坐、賜茶，亦不用托。始知此事流傳已久矣。","sortOrder":42},
  {"id":"s_work_tddn_20_43","chapterId":"ch_work_tddn_20","text":"○清涼居士詞","sortOrder":43},
  {"id":"s_work_tddn_20_44","chapterId":"ch_work_tddn_20","text":"韓忠武王以元枢就第，絕口不言兵，自號清涼居士。時乘小騾，放浪西湖泉石間。一日，至香林園，蘇仲虎尚書方宴客，王径造之，賓主歡甚，盡醉而歸。明日，王餉以羊羔，且手書二詞以遺之。","sortOrder":44},
  {"id":"s_work_tddn_20_45","chapterId":"ch_work_tddn_20","text":"《臨江仙》雲：\"冬日青山瀟洒靜，春來山暖花浓，少年衰老與花同。世間名利客，富貴與貧窮。","sortOrder":45},
  {"id":"s_work_tddn_20_46","chapterId":"ch_work_tddn_20","text":"榮華不是長生藥，清閒不是死門風，勸君識取主人公。单方只一味，盡在不言中。\"","sortOrder":46},
  {"id":"s_work_tddn_20_47","chapterId":"ch_work_tddn_20","text":"《南乡子》雲：\"人有幾何般，富貴榮華總是閒。自古英雄都是夢，為官，寶玉妻兒宿業纏。年事已衰殘，鬢蒼蒼骨髓幹。不道山林多好處，貪歡，只恐癡迷誤了賢。\"","sortOrder":47},
  {"id":"s_work_tddn_20_48","chapterId":"ch_work_tddn_20","text":"王生長兵間，初不能書。晚歲忽若有悟，能作字及小詞。詩詞皆有見趣，信乎非常之才也。","sortOrder":48},
  {"id":"s_work_tddn_21_1","chapterId":"ch_work_tddn_21","text":"●卷二十","sortOrder":1},
  {"id":"s_work_tddn_21_2","chapterId":"ch_work_tddn_21","text":"○嶽武穆御軍","sortOrder":2},
  {"id":"s_work_tddn_21_3","chapterId":"ch_work_tddn_21","text":"嶽鵬舉征群盜，過庐陵，托宿廛市。质明，為主人汛埽門宇，洗涤盆盎而去。郡守供帳，餞別於郊。師行將絕，謁未得通。問大將軍何在，殿者曰：\"已雜偏裨去矣。\"其嚴肅如此，真可謂中興諸將第一。周洪道為追复製詞有雲：\"事上以忠，至不嫌於辰告；行師有律，幾不犯於秋毫。\"蓋實錄也。辰告者，謂嶽嘗上疏請建储雲。","sortOrder":3},
  {"id":"s_work_tddn_21_4","chapterId":"ch_work_tddn_21","text":"○莫氏別室子","sortOrder":4},
  {"id":"s_work_tddn_21_5","chapterId":"ch_work_tddn_21","text":"吳興富翁莫氏者，暮年忽有婢作娠。翁懼其嫗妒，且以年邁慚其子婦若孫，亟遣嫁之。已而得男，翁時歲給錢米繒絮不絕。其夫以鬻粉羹為業，子稍長，讠令羹於市。且十餘歲。莫翁告殂，里巷群不逞遂指為奇货，悉造婢家唁之。婢方哭，則謂之曰：\"汝富貴至矣，何以哭為？\"問其說，乃曰：\"汝之子，莫氏也。其家田園屋業，汝子皆有分，盍歸取之？不聽，則訟之可也。\"其夫婦皆曰：\"吾固知之，奈貧無資何？\"曰：\"我辈當貸汝。\"即為作數百千文約，且曰：\"我為汝經營，事濟則歸我。\"然實無一錢，止為作衰服被其子，使往，且戒曰：\"汝至靈帏，則大恸且拜，拜訖可亟出。人間汝，謹勿應，我辈當伺汝於屋左某家，即當告官可也。\"其子謹受教。","sortOrder":5},
  {"id":"s_work_tddn_21_6","chapterId":"ch_work_tddn_21","text":"既入其家，哭且拜，一家駭然辟易。嫗骂，欲殴逐之。莫氏長子亟前日：\"不可，是將破吾家。\"遂抱持之曰：\"汝非花樓桥賣羹之子乎？\"曰：\"然。\"遂引拜其母曰：\"此，母也，吾乃汝長兄也，汝當拜。\"又遍指其家人雲：\"此為汝長嫂，此為次兄若嫂，汝皆當拜。\"又指雲：\"此為汝長侄，此為次侄，汝當受拜。\"既畢，告去，曰：\"汝，吾弟，當在此撫丧，安得去？\"即命櫛濯，盡去故衣，便與諸兄弟同寢處。已，又呼其所生，喻之以月廪歲衣如翁在日，且戒以非時毋辄至，亦欣然而退。","sortOrder":6},
  {"id":"s_work_tddn_21_7","chapterId":"ch_work_tddn_21","text":"群小方聚委巷茶肆俟之，久不至。既而物色之，乃知已納，相视大沮，計略不得施。他日，投牒持券，訴其子負貸錢。郡逮莫嫗及其子問之，遂備陳首尾。太守唐少尉叹服曰：\"其子可謂有高識矣。\"於是盡以群小具獄，杖脊編置焉。（讠令，力丁切，炫聲也。）","sortOrder":7},
  {"id":"s_work_tddn_21_8","chapterId":"ch_work_tddn_21","text":"○耆英諸會","sortOrder":8},
  {"id":"s_work_tddn_21_9","chapterId":"ch_work_tddn_21","text":"前辈耆年硕德，閒居里舍，遊從詩酒之樂，風流雅韻，一時歆羨。後世想慕，繪而為圖，傳之好事，蓋不可一二數也。今姑據其表表者於此，致景行仰止之意雲。","sortOrder":9},
  {"id":"s_work_tddn_21_10","chapterId":"ch_work_tddn_21","text":"唐香山九老，則集於洛陽，樂天序之。胡杲（懷州司馬，年八十九）、吉杲（衛尉卿致仕，八十六）、劉真（磁州刺史，八十二）、鄭據（龍武長史，八十四）、盧慎（侍御史內供奉，八十二）、張浑（永州刺史，八十七）、白居易（刑部尚書致仕，七十四），所謂七人五百八十四者是也。又續會者二人，李元爽（洛中遺老，一百三十六歲）、僧如滿（九十五）。或又雲，狄兼謨（秘書監）、盧貞（河南尹）二人。以年未七十，雖與會而不及列雲。","sortOrder":10},
  {"id":"s_work_tddn_21_11","chapterId":"ch_work_tddn_21","text":"宋至道九老，則集於京師。張好問（太子中允，八十五）、李運（太常少卿，八十）、宋祺（丞相，七十九）、武允成（庐州節度副使，七十九）、吳僧贊寧（七十八）、魏丕（郢州刺史，七十六）、楊徽之（諫議大夫，七十五）、朱昂（水部郎中，七十一）、李（故相，七十）。然此集竟不成。","sortOrder":11},
  {"id":"s_work_tddn_21_12","chapterId":"ch_work_tddn_21","text":"至和五老，則杜衍（丞相，祁國公，八十）、王涣（禮部侍郎，九十）、畢世長（司農卿，九十四）、朱貫（兵部郎中，八十八）、冯平（駕部郎中，八十八）。時錢明逸留鑰睢陽，為之圖象而序之。","sortOrder":12},
  {"id":"s_work_tddn_21_13","chapterId":"ch_work_tddn_21","text":"元丰洛陽耆英會凡十有二人。富弼（丞相，韓國公，七十九）、文彦博（丞相，潞國公，七十七）、席汝言（司封郎中，七十七）、王尚恭（朝議大夫，七十六）、趙丙（太常少卿，七十五）、劉凡（秘書監，七十五）、冯行己（衛州防御使，七十五）、楚建中（天章待製，七十三）、王謹言（司農少卿，七十二）、王拱辰（檢校太尉，判大名府，以家居洛，願寓名會中，七十一）、張問（大中大夫，龍圖直閣，七十），司馬光（端明學士，兼翰林侍讀學士，六十四）用唐狄兼謨故事預焉，溫公序之，圖形妙覺僧舍，其後又改為真率會雲。","sortOrder":13},
  {"id":"s_work_tddn_21_14","chapterId":"ch_work_tddn_21","text":"吳興六老之會，則慶歷六年集於南園。郎簡（工部侍郎，七十七）、范銳（司封員外，六十六）、張維（衛尉寺丞，九十七，都管張先之父）、劉餘慶（殿中丞，九十二，述仲之父）、周守中（大理寺丞，九十，頌之父）、吳琰（大理寺丞，七十二，知幾之父）。時太守馬尋主之，胡安定教授湖學，為之序焉。","sortOrder":14},
  {"id":"s_work_tddn_21_15","chapterId":"ch_work_tddn_21","text":"吳中則元丰有十老之集，為盧革（大中大夫，八十二）、黃挺（奉議郎，八十二）、程師孟（正議大夫，集賢修撰，七十七）、鄭方平（朝散大夫，七十二）、闾丘孝終（朝議大夫，七十三）、章岵（蘇州太守，七十三）、徐九思（朝請大夫，七十三）、徐師闵（朝議大夫，七十三）、崇大年（承議郎，七十一）、張诜（龍圖直學，七十），米芾元章為之序焉。","sortOrder":15},
  {"id":"s_work_tddn_21_16","chapterId":"ch_work_tddn_21","text":"○紇石烈子仁詞","sortOrder":16},
  {"id":"s_work_tddn_21_17","chapterId":"ch_work_tddn_21","text":"开禧用兵，金人元帥紇石烈子仁領兵據濠梁，大書一詞於濠之ヘ廳壁間。詞名《上平南》，即《上西平》之調，雲：\"蠆鋒搖，螳臂振，舊盟寒。恃洞庭彭蠡狂澜。天兵小试，萬蹄一飲楚江幹。捷書飛上九重天，春滿長安。舜山川，周禮樂，唐日月，漢衣冠。洗五州妖氣關山。已平全蜀，風行何用一泥丸。有人傳喜日邊，都護先還。\"","sortOrder":17},
  {"id":"s_work_tddn_21_18","chapterId":"ch_work_tddn_21","text":"子仁蓋女真之能文者，故敢肆言無憚如此。","sortOrder":18},
  {"id":"s_work_tddn_21_19","chapterId":"ch_work_tddn_21","text":"○讀書聲","sortOrder":19},
  {"id":"s_work_tddn_21_20","chapterId":"ch_work_tddn_21","text":"昔有以詩投東坡者，朗誦之而請曰：\"此詩有分數否？\"坡曰：\"十分。\"其人大喜。坡徐曰：\"三分詩，七分讀耳。\"此雖一時戲語，然涪翁所謂\"南窗讀書吾伊聲\"，蓋善讀書者，其聲正自可聽耳。","sortOrder":20},
  {"id":"s_work_tddn_21_21","chapterId":"ch_work_tddn_21","text":"王沔字楚望，端拱初，參大政。上每试舉人，多令沔讀试卷。沔素善讀，縱文格下者，能抑扬高下，迎其辭而讀之，聽者忘厭。凡經讀者，每在高選。舉子凡納卷者，必祝之曰：\"得王楚望讀之，幸也。\"若然，則善於讀者，不為無助焉。","sortOrder":21},
  {"id":"s_work_tddn_21_22","chapterId":"ch_work_tddn_21","text":"○劉長卿詞","sortOrder":22},
  {"id":"s_work_tddn_21_23","chapterId":"ch_work_tddn_21","text":"劉震孫長卿號朔斋。知宛陵日，吳毅夫潛丞相方閒居，劉日陪午桥之遊，奉之亦甚至。嘗携具开宴，自撰樂語一聯雲：\"入則孔明，出則元亮，副平生自許之心；兄為東坡，弟為栾城，無晚歲相违之恨。\"毅夫大為击節。","sortOrder":23},
  {"id":"s_work_tddn_21_24","chapterId":"ch_work_tddn_21","text":"劉後以召還，吳餞之郊外，劉賦《摸魚兒》一詞為別，末雲：\"怕绿野堂邊，劉郎去後，誰伴老裴度。\"毅夫為之揮淚。繼遣一价，追和此詞，併以小奁侑之，送數十里外。啟之，精金百星也。前辈怜才賞音如此，近世所無。","sortOrder":24},
  {"id":"s_work_tddn_21_25","chapterId":"ch_work_tddn_21","text":"○慶元开慶六士","sortOrder":25},
  {"id":"s_work_tddn_21_26","chapterId":"ch_work_tddn_21","text":"慶元間，趙忠定去國，太學生周端朝、張道、徐范、蒋傳、林仲麟、楊宏中，以上書屏斥，遂得六君子之名。开慶間，丁大全用事，以法繩多士，陳宜中與權、劉黼聲伯、黃镛器之、林則祖興周、曾唯師孔、陳宗正學，亦以上書得謫，號六君子。","sortOrder":26},
  {"id":"s_work_tddn_21_27","chapterId":"ch_work_tddn_21","text":"至景定初，時相欲收士譽，悉上春官，併擢高第，時議或有異論。既而林則祖、陳宗先死，曾屢遭黜。三公者，相繼召试，居言路，出藩入從。鹹淳癸酉間，聲伯自海阃召為從官翰苑，與權自閩帥擢秋官居鎖闼，器之起家知庐陵兼仓部。是歲六月，正言郭閶劾器之雲：\"虛名多足以誤世，實德乃可以服人。\"又雲：\"黃镛偶儕六士，遂得虛名，昨守吳門，怪状百出。愧士不敢謁學，畏軍不敢閱武。暨綰郡符，复兼庾節，怪誕仍不可枚數矣。\"","sortOrder":27},
  {"id":"s_work_tddn_21_28","chapterId":"ch_work_tddn_21","text":"越宿，陳與權入奏曰：\"朝廷建官，本欲兼收實用；臣子事上，豈容徒竊虛名。倘公議有及於斯，雖頃刻難安於位。比觀諫坡造膝之抨彈，斥去庐陵治郡之無状，一皆公論，何預孤蹤。但首發虛名之誤世，上系國家；而明指六士以修言，已形辭色。蓋亦謂忝論思之數，將使自知進退之謀，欲乞特畀閒廪，以穆師言。\"詔不允雲：\"虛名誤世，辭氣若過於抑扬；實德服人，指意則有所歸重。援是求去，非朕攸聞。\"劉聲伯亦一再上疏求去，不允。","sortOrder":28},
  {"id":"s_work_tddn_21_29","chapterId":"ch_work_tddn_21","text":"郭不自安，乞罢言職者亦再，雲：\"直言無忌者諫之職，何敢容私；啭喉觸讳者語之窮，安能逆料？惟茲吉守，舊有直聲，惜其預六士之稱，不能終譽如此。今指其兩郡之政，謂之非虛名可乎？二臣何見，相繼引嫌。實自實，虛自虛，人品固難於概論；聞所聞，見所見，事理委無以相幹。\"亦不允其請。而陳疏至四五，且引書牍之嫌。御批雲：\"卿以不必疑之言，而申必欲去之請，如國體何？前詔謂虛名實德，各有所指，蓋盡之矣。書牍引嫌，勿書可也，何以去為？\"於是侍御陳堅節夫、豸官陳過聖觀共為一疏，乞申諭三臣，各安職守。而黃戶書萬石、陳兵書存、常戶侍、曹禮侍孝慶、倪刑侍曹、高工侍斯得、李右史珏、文左史复之共為一疏調停之，久而方定。知大體者，殊不然之。事久論定，虛名實德於人，亦可概見矣。","sortOrder":29},
  {"id":"s_work_tddn_21_30","chapterId":"ch_work_tddn_21","text":"○文臣帶左右","sortOrder":30},
  {"id":"s_work_tddn_21_31","chapterId":"ch_work_tddn_21","text":"紹興以來，文散階皆帶左右字，以別有無出身。惟嘗犯贓者則去之。劉岑季高得罪秦氏，坐贓废。後复官，去其左字，季高署衔，不以為愧也。孫觌仲益亦以贓罪去左字，但自稱晉陵孫某而已。至紹興末，复朝奉郎，乃始署衔。淳熙中，因趙善俊奏，又例去之。","sortOrder":31},
  {"id":"s_work_tddn_21_32","chapterId":"ch_work_tddn_21","text":"吳興有王孝嚴行先居城西，俗稱為王团練宅，蓋將种也。以冠登壬辰科，沾沾自喜，以帶左字為榮。時施士衡得求因忤魏道弼，坐贓失官。素負氣，殊以不帶左字為恥，而有詔盡去之。乡人嘲之曰：\"快殺施得求，愁殺王行先。\"","sortOrder":32},
  {"id":"s_work_tddn_21_33","chapterId":"ch_work_tddn_21","text":"○馬梁家姬","sortOrder":33},
  {"id":"s_work_tddn_21_34","chapterId":"ch_work_tddn_21","text":"會稽有富人馬生，以入粟得官，號馬殿幹。喜賓客，有姬美艳能歌，時出佐酒。客有梁縣丞者頗黠，因與之目成。一旦馬生殂，姬出，梁捐金得之。它日，置酒觴客，陳無損益之在坐。酒酣，舉杯屬梁曰：\"有俪語奉上。\"梁諦聽之，即琅然高唱曰：\"昔居殿幹之家，爰丧其馬；今入縣丞之室，毋逝我梁。\"一坐大呼笑，而主人怃然不樂。無幾，梁亦死焉。人尤無損之謔戲，然聞者亦可以警也。","sortOrder":34},
  {"id":"s_work_tddn_21_35","chapterId":"ch_work_tddn_21","text":"○山獭治箭毒","sortOrder":35},
  {"id":"s_work_tddn_21_36","chapterId":"ch_work_tddn_21","text":"世傳補助奇僻之品，有所謂山獭者，不知出於何時。謂以少許磨酒飲之，立验，然《本草》、《医方》皆所不載。止見《桂海虞衡志》雲：\"出宜州溪峒。\"峒人雲：\"獭性淫毒，山中有此物，凡牝獸悉避去。獭無偶，抱木而枯。\"峒獠尤貴重之。能解箭毒，中箭者，研其骨少許傅之，立消。一枚直金一兩。或得殺死者，功力劣。抱木枯死者，土人自稀得之。然今方術之士，售伪以愚世人者，類以鼠璞、猴胎為之，雖殺死者，亦未之見也。","sortOrder":36},
  {"id":"s_work_tddn_21_37","chapterId":"ch_work_tddn_21","text":"周子功嘗使大理，經南丹州，即此物所產之地，其土人號之曰插翘。極為貴重，一枚直黃金數兩。私货出界者，罪至死。方春時，犭女數千，歌嘯山穀，以尋藥挑菜為事。獭性淫，或聞婦人氣，必躍升其身，刺骨而入，牢不可脱，因扼殺而藏之。土人验之之法，每令婦人摩手極熱，取置掌心，以氣呵之，即然而動，蓋為陰氣所感故耳。然其地亦不常有，或累數歲得其一，則其人立可致富，宜中州之多伪也。","sortOrder":37},
  {"id":"s_work_tddn_21_38","chapterId":"ch_work_tddn_21","text":"○月忌","sortOrder":38},
  {"id":"s_work_tddn_21_39","chapterId":"ch_work_tddn_21","text":"俗以每月初五、十四、二十三日為月忌，凡事必避之，其說不經。後見衛道夫雲：\"問前辈雲，說此三日即《河圖數》之中宮五數耳，五為君象，故民庶不可用。\"此說頗有理，因圖於此。","sortOrder":39},
  {"id":"s_work_tddn_21_40","chapterId":"ch_work_tddn_21","text":"四（初四，十三，二十二日）。三（初三，十二，二十一日）。八（初八日，十七日）。","sortOrder":40},
  {"id":"s_work_tddn_21_41","chapterId":"ch_work_tddn_21","text":"九（初九日，十八日）。五（初五，十四，二十三日）。一（初一，初十，十九日）。","sortOrder":41},
  {"id":"s_work_tddn_21_42","chapterId":"ch_work_tddn_21","text":"二（初二，十一，二十日）。七（初七日，十六日）。六（初六日，十五日）。","sortOrder":42},
  {"id":"s_work_tddn_21_43","chapterId":"ch_work_tddn_21","text":"○張功甫豪侈","sortOrder":43},
  {"id":"s_work_tddn_21_44","chapterId":"ch_work_tddn_21","text":"張功甫，號約斋，循忠烈王諸孫，能詩，一時名士大夫，莫不交遊，其園池聲妓服玩之麗甲天下。嘗於南湖園作駕霄亭於四古松間，以巨鐵ㄌ懸之空半而羁之松身。當風月清夜，與客梯登之，飄搖雲表，真有挟飛仙、溯紫清之意。王簡卿侍郎嘗赴其牡丹會雲：\"眾賓既集，坐一虛堂，寂無所有。俄問左右雲：'香已發未？'答雲：'已發。'命卷帘，則異香自內出，鬱然滿坐。群妓以酒肴絲竹，次第而至。別有名姬十辈皆衣白，凡首飾衣領皆牡丹，首帶照殿紅一枝，執板奏歌侑觴，歌罢樂作乃退。复垂帘談論自如，良久，香起，卷帘如前。別十姬，易服與花而出。大抵簪白花則衣紫，紫花則衣鹅黃，黃花則衣紅，如是十杯，衣與花凡十易。所謳者皆前辈牡丹名詞。酒竟，歌者、樂者，無慮數百十人，列行送客。燭光香霧，歌吹雜作，客皆恍然如仙遊也。\"","sortOrder":44},
  {"id":"s_work_tddn_21_45","chapterId":"ch_work_tddn_21","text":"功甫於誅韓有力，賞不滿意。又欲以故智去史，事泄，謫象台而殂。","sortOrder":45},
  {"id":"s_work_tddn_21_46","chapterId":"ch_work_tddn_21","text":"○台妓嚴蕊","sortOrder":46},
  {"id":"s_work_tddn_21_47","chapterId":"ch_work_tddn_21","text":"天台營妓嚴蕊字幼芳，善琴弈歌舞、絲竹書畫，色藝冠一時。間作詩詞有新語，頗通古今。善逢迎，四方聞其名，有不遠千里而登門者。唐與正守台日，酒邊，嘗命賦紅白桃花，即成《如夢令》雲：\"道是梨花不是，道是杏花不是，白白與紅紅，別是東風情味。曾記、曾記，人在武陵微醉。\"與正賞之双缣。","sortOrder":47},
  {"id":"s_work_tddn_21_48","chapterId":"ch_work_tddn_21","text":"又七夕，郡斋开宴，坐有謝元卿者，豪士也，夙聞其名，因命之賦詞，以己之姓為韻。酒方行，而已成《鵲桥仙》雲：\"碧梧初出，桂花才吐，池上水花微謝。穿針人在合歡樓，正月露、玉盤高泻。蛛忙鵲懶，耕慵織倦，空做古今佳話。人間刚道隔年期，指天上、方才隔夜。\"元卿為之心醉，留其家半載，盡客囊橐饋赠之而歸。","sortOrder":48},
  {"id":"s_work_tddn_21_49","chapterId":"ch_work_tddn_21","text":"其後朱晦庵以使節行部至台，欲摭與正之罪，遂指其嘗與蕊為濫。系獄月餘，蕊雖備受棰楚，而一語不及唐，然猶不免受杖。移籍紹興，且复就越置獄，鞫之，久不得其情。獄吏因好言誘之曰：\"汝何不早認，亦不過杖罪。况已經斷，罪不重科，何為受此辛苦邪？\"蕊答雲：\"身為賤妓，縱是與太守有濫，科亦不至死罪。然是非真伪，豈可妄言以污士大夫，雖死不可誣也。\"其辭既堅，於是再痛杖之，仍系於獄。兩月之間，一再受杖，委頓幾死，然聲价愈騰，至彻阜陵之聽。未幾，朱公改除，而嶽霖商卿為憲，因贺朔之际，怜其病瘁，命之作詞自陳。蕊略不構思，即口占《卜算子》雲：\"不是愛風尘，似被前緣誤。花落花开自有時，總賴東君主。去也終須去，住也如何住。若得山花插滿頭，莫問奴歸處。\"即日判令從良。繼而宗室近屬，納為小婦以終身焉。《夷堅志》亦嘗略載其事而不能詳，餘蓋得之天台故家雲。","sortOrder":49},
  {"id":"s_work_tddn_21_50","chapterId":"ch_work_tddn_21","text":"○字義","sortOrder":50},
  {"id":"s_work_tddn_21_51","chapterId":"ch_work_tddn_21","text":"隙之間讀若艱，謂有容可入也。隔之間讀若諫，謂入其間而隔之也。暇之讀若閒，謂其間有容暇也。閒有防義，或借作，非正字也。《季布傳》：\"侍，果言如朱家指。\"師古曰：\"侍、謂侍於天子。謂事務之隙也。\"《劉贾傳》：\"使人招楚大司馬周殷。\"《顏註》：\"謂私求間隙而招之（《漢書）無音）。\"《史記》作去聲。《張良傳》：\"嘗從容步遊圯上（《漢書》無音）。\"《索隱》：\"，閒字也。\"《陳平傳》：\"身行杖劍亡，渡河。\"《音義》：\"、紀間反。\"","sortOrder":51},
  {"id":"s_work_tddn_21_52","chapterId":"ch_work_tddn_21","text":"○舟人稱謂有據","sortOrder":52},
  {"id":"s_work_tddn_21_53","chapterId":"ch_work_tddn_21","text":"餘生長泽國，每聞舟子呼造帆曰歡，以牵船之索曰彈（平聲）子，稱使風之帆為去聲，意謂吳諺耳。及觀唐《樂府》有詩雲：\"蒲帆猶未織，爭得一歡成。\"而鐘會呼捉船索為百丈。趙氏註雲，\"百丈者，牵船篾，內地謂之笪（音彈）。\"韓昌黎詩雲：\"無因帆江水。\"而韻書去聲內，亦有扶帆切者，是知方言俗語，皆有所據。陆放翁入蜀，聞舟人祠神，方悟杜詩長年三老攤錢之語，亦此類也。","sortOrder":53},
  {"id":"s_work_tddn_21_54","chapterId":"ch_work_tddn_21","text":"○張仲孚","sortOrder":54},
  {"id":"s_work_tddn_21_55","chapterId":"ch_work_tddn_21","text":"完顏亮败盟寇蜀，主將合喜孛堇，張仲孚副之。先是，吳氏守蜀時，专用神臂弓保险。孛堇曰：\"昔我軍皆漠北人，故短於弩射。今軍士多河南北人，何不習閱以分南人之長。\"遂擇五千人，晝夜習之。一日，設射，於石巖下張宴，以第其中否，巖皆如粉飛墜。酒酣，問仲孚曰：\"果何如？\"仲孚實秦相陰遣，雖吳氏兄弟，亦不知其謀，每欲剿其族，故金人信之不疑。仲孚欲散其謀，於是缪謂孛堇曰：\"用中國人集長兵固善，第虞一旦反噬，則恐無以製之耳。且我每佥中原兵，常製以女真，正慮此也。\"孛堇聞其說甚恐，乃漸散之。自後，和好既成，蜀備久弛，有以吳無備告堇，請劲騎數千，先事長驅而入者。仲孚為蜀危之，又謂孛堇曰：\"自四太子時，猶不得蜀，設不如意，出危道也。\"堇又為之止。","sortOrder":55},
  {"id":"s_work_tddn_21_56","chapterId":"ch_work_tddn_21","text":"其後，下秦州，取德勝，所至降附，其力為多。時王瞻叔駐綿州，總餉事，王刚中為製帥，治成都。瞻叔請遣重臣镇蜀，時虞雍公方奏采石功，遂以兵書开宣幕。虞知仲孚不忘本朝，欲顯招之，乃以王爵告命使持與之，仲孚乃径自屯所歸於虞。","sortOrder":56},
  {"id":"s_work_tddn_21_57","chapterId":"ch_work_tddn_21","text":"既而雍公舍险，出兵平地，一戰而败，丧將校七十二人。凡吳所下州郡，不能撫有。及致金人责免敵錢，故所在皆叛。而仲孚屢為畫策，亦不見用。中原之民，以為誤己，大怒，因不复信之，以至於败雲。","sortOrder":57},
  {"id":"s_work_tddn_21_58","chapterId":"ch_work_tddn_21","text":"○隱語","sortOrder":58},
  {"id":"s_work_tddn_21_59","chapterId":"ch_work_tddn_21","text":"古之所謂詞，即今之隱語，而俗所謂謎。《玉篇》謎字釋雲，隱也。人皆知其始於黃絹幼婦，而不知自漢伍舉、曼倩時已有之矣。至《鮑照集》，則有井字謎。自此雜說所載，間有可喜。今擇其佳者，著數篇於此，以資酒邊雅談雲。用字謎雲：\"一月复一月，兩月共半邊。上有可耕之田，下有長流之川。六口共一室，兩口不团圓。\"又雲：\"重山复重山，重山向下懸。明月复明月，明月兩相連。\"木玷雲：\"我本無名，因汝有名。汝有不平，吾與汝平。\"日謎雲：\"畫時圓，寫時方，寒時短，熱時長。\"又雲：\"東海有一魚，無頭亦無尾。除去脊梁骨，便是这个謎。\"染物霞頭雲：\"身居色界中，不染色界尘。一朝解繩縛，見姓自分明。\"持棋雲：\"彼亦不敢先，此亦不敢先，惟其不敢先，是以無所爭，是以能入於不死不生。\"字點雲：\"寒則重重叠叠，熱則四散分流。四个在縣，三个在州。村里不見在村里，市頭不見在市頭。\"印章雲：\"方圓大小隨人，腹里文章儒雅。有時滿面紅妆，常在風前月下。\"金刚雲：\"立不中門，行不履閾。俨然人望而畏之，斯亦不足畏也矣。\"蜘蛛雲：\"上不在天，下不在田。中心藏之，玄之又玄。\"又雲：\"自東自西，自南自北，無思不服。\"拄杖雲：\"用之則行，舍之則藏，惟我與爾。危而不持，顛而不扶，則焉用彼。\"木屐雲：\"可以托六尺之孤，可以寄百里之命。遇刚則铿爾有聲，遇柔則没齒無怨。\"蹴リ雲：\"瞻之在前，忽焉在後，樂然後笑，人不厭其笑。\"墨斗雲：\"我有一張琴，絲絃長在腹。時時馬上彈，彈盡天下曲。\"打稻〈耒加〉雲：\"天下有道則見，無道則隱。瞻之在前，忽焉在後。\"夹註書雲：\"大底不曾說小底，小底常是說大底，若要知得大底事，須去仔細問小底。\"元宵燈球雲：\"我有紅圓子，治赤白帶下，每服三五丸，臨夜茶酒下。\"日歷雲：\"都來一尺長，上面都是節。兩頭非常冷，中間非常熱。\"手指雲：\"大者兩文，小者三文，十枚共計二十八文。\"水中石雲：\"小時大，大時小。漸漸大，不見了。\"或以為小兒囟門。手巾雲：\"八尺一片，四角兩面。所識是人面，不識畜生面。\"接果雲：\"斫頭便斫頭，却不教汝死。抛却親生男，却愛過房子。\"","sortOrder":59},
  {"id":"s_work_tddn_21_60","chapterId":"ch_work_tddn_21","text":"又有以今人名藏古人名者雲：\"人人皆戴子瞻帽（仲長統），君實新來轉一官（司馬遷），門状送還王介甫（謝安石），潞公身上不曾寒（溫彦博）。\"又有以古詩賦败弓雲：\"爭帝圖王势已傾（無靶），八千兵散楚歌聲（無絃），乌江不是無船渡（無肖），羞向東吳再起兵（無面）。\"然此近俗矣。若今書會所謂謎者，尤無謂也。","sortOrder":60},
  {"id":"s_work_tddn_21_61","chapterId":"ch_work_tddn_21","text":"○趙涯","sortOrder":61},
  {"id":"s_work_tddn_21_62","chapterId":"ch_work_tddn_21","text":"理宗初郊，行事之次，適天雷電以風，黃壇燈燭皆滅無餘，百執事顛沛離次。已而風雨少止，惟子階一陪祠官，雖朝衣被雨淋漓，而俨然不動，理宗甚異之。亟遣近侍問姓名，則趙涯也。時為京局官，未幾，除監察御史。","sortOrder":62},
  {"id":"s_work_tddn_21_63","chapterId":"ch_work_tddn_21","text":"○書种文种","sortOrder":63},
  {"id":"s_work_tddn_21_64","chapterId":"ch_work_tddn_21","text":"裴度常訓其子雲：\"凡吾辈但可令文种無絕。然其間有成功，能致身萬乘之相，則天也。\"山穀雲：\"四民皆坐世業，士大夫子弟能知忠、信、孝、友，斯可矣，然不可令讀書种子斷絕。有才氣者出，便當名世矣。\"似祖裴語，特易文种為書种耳。練兼善嘗對書太息曰：\"吾老矣，非求聞者，姑下後世种子耳。\"餘家有書种堂，蓋兼取二公之說雲。","sortOrder":64},
  {"id":"s_work_tddn_21_65","chapterId":"ch_work_tddn_21","text":"○溫公重望","sortOrder":65},
  {"id":"s_work_tddn_21_66","chapterId":"ch_work_tddn_21","text":"坡公《獨樂園》詩雲：\"兒童誦君實，走卒知司馬。\"京師之貪污不才者，人皆指笑之曰：你好个司馬家。\"文潞公留守北京日，嘗遣人入遼侦事。回見遼主大宴群臣，伶人剧戲作衣冠者，見物必攫取懷之。有從其後以物朴之，雲：\"汝司馬端明邪？\"是雖夷狄亦知之，豈止兒童走卒哉！","sortOrder":66},
  {"id":"s_work_tddn_21_67","chapterId":"ch_work_tddn_21","text":"宣和間，徽宗與蔡攸辈在禁中自為優戲，上作參軍趨出。攸戲上曰：\"陛下好个神宗皇帝。\"上以杖鞭之雲：\"你也好个司馬丞相。\"是知公論在人心，有不容泯者如此。","sortOrder":67},
  {"id":"s_work_tddn_21_68","chapterId":"ch_work_tddn_21","text":"○陳孝女","sortOrder":68},
  {"id":"s_work_tddn_21_69","chapterId":"ch_work_tddn_21","text":"陳孝女，錢塘人也。父業儒，嘗受勇爵。漫遊江淮間，居胭脂嶺下，家粗給。乙亥兵火，挈家永嘉山中，悉為盜所掠，仅留一女十歲，携之丐食以歸。故居荡不复存，因寄五里塘舊仆家。聞殊勝寺設粥供，日携女子就寺丐食。凡數月，僧扣所以，頗怜之，俾留眾寮供榜疏職。時孫元帥下李知事者，東平人也，頗知書，亦寓寺旁。暇日至寺，必從容與僧談，欲謀一士為友。僧以陳為荐，一見投合如久要，馆穀加厚，其女亦得其家歡心。居數月，當丁丑仲春，女子忽謂其父雲：\"吾母墓在故居侧，數年不至矣。聞主人禁煙將為湖山遊，能乘此機，一往拜扫否？\"父以告，李欣然與俱。既至墓所，拜奠罢，李偕携酒飲旁舍。女悲泣不已，久之，勉之還，則泣告曰：\"比聞李氏今將北歸，吾父子必將從之。父老子幼，南北萬里，何日可再至吾母墓下，此所以痛也。\"言與淚俱下，父亦感痛。而女踴呼號，聲振林木，久而仆地，视之，死矣！李義之，因與墓鄰斂而於母冢之旁雲。","sortOrder":69},
  {"id":"s_work_tddn_21_70","chapterId":"ch_work_tddn_21","text":"呜呼！古有曹、饒二娥，耀史册，著為美談。今陳氏女，年甫十四，而天性至孝，抱冢泣死，视前修為無愧矣。因詳著以俟傳忠孝者。","sortOrder":70},
];

